#[derive(Clone)]
struct EvalSourceGeneration(Arc<EvalSourceGenerationMarker>);

struct EvalSourceGenerationMarker;

impl EvalSourceGeneration {
    fn fresh() -> Self {
        Self(Arc::new(EvalSourceGenerationMarker))
    }
}

impl std::fmt::Debug for EvalSourceGeneration {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str("EvalSourceGeneration(<opaque>)")
    }
}

impl PartialEq for EvalSourceGeneration {
    fn eq(&self, other: &Self) -> bool {
        Arc::ptr_eq(&self.0, &other.0)
    }
}

impl Eq for EvalSourceGeneration {}

impl std::hash::Hash for EvalSourceGeneration {
    fn hash<H: std::hash::Hasher>(&self, state: &mut H) {
        std::ptr::hash(Arc::as_ptr(&self.0), state);
    }
}

#[derive(Clone, Copy, PartialEq, Eq, Hash)]
struct EvalSourceOccurrence(usize);

impl EvalSourceOccurrence {
    fn of(expr: &EvalAstExpr) -> Self {
        Self(std::ptr::from_ref(expr).addr())
    }

    #[cfg(test)]
    fn for_test(id: usize) -> Self {
        Self(id)
    }
}

/// Independently validated Kio' evaluator input paired with the explicit
/// host-provided primitive environment under which it may reduce.
/// Cloning retains one private evaluator generation; constructing another
/// artifact, including from identical parts, creates a distinct generation.
#[derive(Debug, Clone)]
pub struct EvalArtifact {
    package: Arc<EvalPackage>,
    primitives: EvalPrimitiveEnv,
    source_generation: EvalSourceGeneration,
}

impl EvalArtifact {
    pub(crate) fn from_validated_parts(package: EvalPackage, primitives: EvalPrimitiveEnv) -> Self {
        Self {
            package: Arc::new(package),
            primitives,
            source_generation: EvalSourceGeneration::fresh(),
        }
    }

    pub fn package(&self) -> &Package<UncheckedPrime> {
        &self.package
    }

    pub fn primitives(&self) -> &EvalPrimitiveEnv {
        &self.primitives
    }

    fn source_generation(&self) -> EvalSourceGeneration {
        self.source_generation.clone()
    }

    /// Consume the prepared artifact and discard its nominal generation.
    /// Rebuilding from these parts is an independent preparation.
    pub(crate) fn into_parts(self) -> (EvalPackage, EvalPrimitiveEnv) {
        (
            Arc::try_unwrap(self.package).unwrap_or_else(|package| (*package).clone()),
            self.primitives,
        )
    }
}

impl std::ops::Deref for EvalArtifact {
    type Target = Package<UncheckedPrime>;

    fn deref(&self) -> &Self::Target {
        &self.package
    }
}

#[derive(Debug, Clone, Default, PartialEq, Eq, serde::Serialize, serde::Deserialize)]
pub struct EvalPrimitiveEnv {
    modules: BTreeMap<String, BTreeMap<String, ComptimeBuiltin>>,
}

impl EvalPrimitiveEnv {
    pub(crate) fn enable_comptime_module(&mut self, module_path: impl Into<String>) {
        let module_path = module_path.into();
        for name in crate::comptime::PUBLIC_COMPTIME_NAMES {
            self.grant(
                module_path.clone(),
                ComptimeBuiltin::from_public_name(name)
                    .expect("every public comptime name has a builtin"),
            );
        }
    }

    pub(crate) fn grant(&mut self, module_path: impl Into<String>, builtin: ComptimeBuiltin) {
        self.modules
            .entry(module_path.into())
            .or_default()
            .insert(builtin.public_name().to_owned(), builtin);
    }

    fn resolve(&self, module_path: &str, name: &str) -> Option<ComptimeBuiltin> {
        self.modules.get(module_path)?.get(name).copied()
    }

    pub(crate) fn bindings(
        &self,
    ) -> impl Iterator<Item = (&str, impl Iterator<Item = (&str, ComptimeBuiltin)>)> {
        self.modules.iter().map(|(module, bindings)| {
            (
                module.as_str(),
                bindings
                    .iter()
                    .map(|(name, builtin)| (name.as_str(), *builtin)),
            )
        })
    }
}

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct ReflectedType {
    ty: EvalRef<EvalAstType>,
}

impl ReflectedType {
    pub fn new(ty: EvalAstType, message: &str) -> Result<Self, crate::error::Error> {
        InferFreeType::new(ty, message).map(|ty| Self {
            ty: EvalRef::new(ty.into_type()),
        })
    }

    fn new_trusted(ty: EvalAstType) -> Self {
        let ty = InferFreeType::new_trusted(ty).into_type();
        Self {
            ty: EvalRef::new(ty),
        }
    }

    pub fn as_type(&self) -> &EvalAstType {
        &self.ty
    }

    pub fn into_type(self) -> EvalAstType {
        EvalRef::try_unwrap(self.ty).unwrap_or_else(|ty| (*ty).clone())
    }
}

fn refl_type_value(ty: EvalAstType) -> Value {
    Value::ReflType(ReflectedType::new_trusted(ty))
}

