#[cfg(feature = "surface")]
fn closed_projected_value(
    value: &crate::pass::typecheck_core::apply::fills::ProjectedValue,
    proof: &crate::pass::typecheck_core::apply::fills::MarkedComptimeProof,
    ctx: &EvalCtx<'_>,
) -> Option<Value> {
    if let Some(ty) = value.closed_reflected() {
        return Some(Value::ReflType(ty.clone()));
    }
    if let Some(candidate) = value.reflection_candidate(proof) {
        let ty = if candidate.identity_is_canonical {
            candidate.ty
        } else {
            let module = ctx
                .package
                .and_then(|package| package.module(&candidate.module_path))?;
            crate::pass::resolve::exported_contract_type(
                &candidate.ty,
                module,
                &candidate.binder_kinds,
            )
        };
        return ReflectedType::new(
            ty,
            "a goal-free projected type must remain infer-free when reflected",
        )
        .ok()
        .map(Value::ReflType);
    }
    value
        .closed_term()
        .cloned()
        .map(EvalRef::new)
        .map(Value::CheckedTerm)
}

