const EXACT_CALL_MEMO_MAX_ENTRIES: usize = 8192;
const EXACT_CALL_MEMO_KEY_BUDGET: usize = 96;
const EXACT_CALL_MEMO_RESULT_BUDGET: usize = 2048;

