fn write_eval_cache_frame(hasher: &mut blake3::Hasher, bytes: &[u8]) {
    hasher.update(&(bytes.len() as u64).to_le_bytes());
    hasher.update(bytes);
}

fn finish_eval_function_cache_key(
    source_generation: &EvalSourceGeneration,
    hasher: blake3::Hasher,
) -> EvalFunctionCacheKey {
    EvalFunctionCacheKey {
        source_generation: source_generation.clone(),
        digest: *hasher.finalize().as_bytes(),
    }
}

fn eval_function_cache_key_for_def(
    def: &FnDef<EvalPhase>,
    module_path: &str,
    source_generation: &EvalSourceGeneration,
) -> EvalFunctionCacheKey {
    let mut hasher = blake3::Hasher::new();
    write_eval_cache_frame(&mut hasher, b"kio-eval-top-level-function-v3");
    write_eval_cache_frame(&mut hasher, module_path.as_bytes());
    let bytes = postcard::to_allocvec(def)
        .expect("UncheckedPrime function definitions are serializable evaluator artifacts");
    write_eval_cache_frame(&mut hasher, &bytes);
    finish_eval_function_cache_key(source_generation, hasher)
}

fn eval_function_cache_key_for_lambda(
    sig: &EvalAstSignature,
    body: &EvalAstExpr,
    occurrence: EvalSourceOccurrence,
    state: &EvalCompileState<'_, '_>,
    captured_slots: &[usize],
) -> EvalFunctionCacheKey {
    let mut hasher = blake3::Hasher::new();
    write_eval_cache_frame(&mut hasher, b"kio-eval-lambda-v4");
    write_eval_cache_frame(&mut hasher, &occurrence.0.to_le_bytes());
    write_eval_cache_frame(&mut hasher, state.module_path.as_bytes());
    write_eval_cache_frame(
        &mut hasher,
        state.label_scope.as_deref().unwrap_or_default().as_bytes(),
    );
    for local in &state.locals {
        write_eval_cache_frame(&mut hasher, local.as_bytes());
    }
    for slot in captured_slots {
        write_eval_cache_frame(&mut hasher, &(*slot as u64).to_le_bytes());
    }
    let bytes = postcard::to_allocvec(&(sig, body))
        .expect("UncheckedPrime lambdas are serializable evaluator artifacts");
    write_eval_cache_frame(&mut hasher, &bytes);
    finish_eval_function_cache_key(&state.source_generation, hasher)
}

fn eval_function_cache_key_for_suffix(
    parent: &EvalFunctionCacheKey,
    suffix_group_index: usize,
) -> EvalFunctionCacheKey {
    let mut hasher = blake3::Hasher::new();
    write_eval_cache_frame(&mut hasher, b"kio-eval-function-suffix-v1");
    write_eval_cache_frame(&mut hasher, &parent.digest);
    write_eval_cache_frame(&mut hasher, &(suffix_group_index as u64).to_le_bytes());
    finish_eval_function_cache_key(&parent.source_generation, hasher)
}

#[cfg(test)]
fn eval_function_cache_key_for_test(label: &str, body: &EvalExpr) -> EvalFunctionCacheKey {
    static TEST_GENERATION: OnceLock<EvalSourceGeneration> = OnceLock::new();
    let mut hasher = blake3::Hasher::new();
    write_eval_cache_frame(&mut hasher, b"kio-eval-test-function-v1");
    write_eval_cache_frame(&mut hasher, label.as_bytes());
    write_eval_cache_frame(&mut hasher, format!("{body:?}").as_bytes());
    finish_eval_function_cache_key(
        TEST_GENERATION.get_or_init(EvalSourceGeneration::fresh),
        hasher,
    )
}

fn exact_call_memo_key(
    function: &EvalRef<EvalFunction>,
    captured: &[Value],
    args: &[Value],
) -> Option<ExactCallMemoKey> {
    if !function.memo_candidate {
        return None;
    }
    let mut budget = EXACT_CALL_MEMO_KEY_BUDGET;
    Some(ExactCallMemoKey {
        function: function.cache_key.clone(),
        captured: values_memo_keys(captured, &mut budget)?,
        args: values_memo_keys(args, &mut budget)?,
    })
}

fn values_memo_keys(values: &[Value], budget: &mut usize) -> Option<Vec<EvalValueMemoKey>> {
    values
        .iter()
        .map(|value| value_memo_key(value, budget))
        .collect()
}

fn value_memo_key(value: &Value, budget: &mut usize) -> Option<EvalValueMemoKey> {
    if let Value::ReflType(typ) = value {
        type_traversal::charge_memo_type(typ.as_type(), budget)?;
    } else {
        *budget = budget.checked_sub(1)?;
    }
    match value {
        Value::Unit => Some(EvalValueMemoKey::Unit),
        Value::Bool(value) => Some(EvalValueMemoKey::Bool(*value)),
        Value::IntAtom(digits, annotation) => Some(EvalValueMemoKey::IntAtom(
            digits.clone(),
            annotation.clone(),
        )),
        Value::FloatAtom(digits, annotation) => Some(EvalValueMemoKey::FloatAtom(
            digits.clone(),
            annotation.clone(),
        )),
        Value::StrAtom(value) => Some(EvalValueMemoKey::StrAtom(value.clone())),
        Value::ReflType(typ) => Some(EvalValueMemoKey::ReflType(TypeMemoKey::from_type(
            typ.as_type(),
        ))),
        Value::CheckedTerm(_) => None,
        #[cfg(feature = "surface")]
        Value::Projected(_) => None,
        Value::ReflTypeArity(arity) => Some(EvalValueMemoKey::ReflTypeArity(*arity)),
        Value::ReflTypeVar { name, arity } => {
            Some(EvalValueMemoKey::ReflTypeVar(name.clone(), *arity))
        }
        Value::ReflTypeName {
            segments,
            param_arities,
        } => Some(EvalValueMemoKey::ReflTypeName(
            segments.clone(),
            param_arities.clone(),
        )),
        Value::DiagnosticText(value) => Some(EvalValueMemoKey::DiagnosticText(value.clone())),
        Value::Primitive(ComptimeBuiltin::StructuralRecur) => None,
        Value::Primitive(builtin) => Some(EvalValueMemoKey::Primitive(*builtin)),
        Value::NewtypeMember(member) => Some(EvalValueMemoKey::NewtypeMember {
            constructor: member.constructor.clone(),
            kind: member.kind,
        }),
        Value::EvalClosure { .. } | Value::StructuralRecur { .. } => None,
        Value::Atom(name) => Some(EvalValueMemoKey::Atom(name.clone())),
        Value::Data(_) | Value::CaseSplit { .. } | Value::Seq { .. } | Value::Stuck(_, _) => None,
    }
}

fn exact_call_memo_result_shareable(value: &Value) -> bool {
    let mut budget = EXACT_CALL_MEMO_RESULT_BUDGET;
    value_shareable_for_exact_memo(value, &mut budget)
}

fn values_shareable_for_exact_memo(values: &[Value], budget: &mut usize) -> bool {
    values
        .iter()
        .all(|value| value_shareable_for_exact_memo(value, budget))
}

fn value_shareable_for_exact_memo(value: &Value, budget: &mut usize) -> bool {
    let Some(next_budget) = budget.checked_sub(1) else {
        return false;
    };
    *budget = next_budget;
    match value {
        Value::Unit
        | Value::Bool(_)
        | Value::IntAtom(_, _)
        | Value::FloatAtom(_, _)
        | Value::StrAtom(_)
        | Value::ReflType(_)
        | Value::ReflTypeArity(_)
        | Value::ReflTypeVar { .. }
        | Value::ReflTypeName { .. }
        | Value::DiagnosticText(_)
        | Value::NewtypeMember(_)
        | Value::Atom(_) => true,
        Value::Primitive(builtin) => *builtin != ComptimeBuiltin::StructuralRecur,
        Value::CheckedTerm(_) => false,
        #[cfg(feature = "surface")]
        Value::Projected(_) => false,
        Value::Data(data) => {
            if data.structural_recur_identity().is_some() {
                return false;
            }
            #[cfg(feature = "surface")]
            if data.is_fills_capability() {
                return false;
            }
            values_shareable_for_exact_memo(data.args(), budget)
        }
        Value::EvalClosure { .. }
        | Value::StructuralRecur { .. }
        | Value::CaseSplit { .. }
        | Value::Seq { .. }
        | Value::Stuck(_, _) => false,
    }
}

#[derive(Clone, PartialEq, Eq, Hash)]
struct StructuralRecurSite {
    source_generation: EvalSourceGeneration,
    module_path: Arc<str>,
    occurrence: EvalSourceOccurrence,
}

impl std::fmt::Debug for StructuralRecurSite {
    fn fmt(&self, formatter: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        formatter.write_str("StructuralRecurSite(<opaque>)")
    }
}

impl StructuralRecurSite {
    fn new(
        source_generation: &EvalSourceGeneration,
        module_path: &str,
        occurrence: EvalSourceOccurrence,
    ) -> Arc<Self> {
        Arc::new(Self {
            source_generation: source_generation.clone(),
            module_path: Arc::from(module_path),
            occurrence,
        })
    }

    fn public_api(source_generation: &EvalSourceGeneration) -> Arc<Self> {
        static MODULE_PATH: OnceLock<Arc<str>> = OnceLock::new();
        Arc::new(Self {
            source_generation: source_generation.clone(),
            module_path: MODULE_PATH
                .get_or_init(|| Arc::from("<public-evaluator-context>"))
                .clone(),
            occurrence: EvalSourceOccurrence(0),
        })
    }
}

