#[cfg(target_pointer_width = "64")]
const _: () = assert!(std::mem::size_of::<EvalExpr>() == 72);

enum EvalArgs {
    Empty,
    One([Value; 1]),
    Two([Value; 2]),
    Three([Value; 3]),
    Many(Vec<Value>),
}

impl EvalArgs {
    fn len(&self) -> usize {
        match self {
            Self::Empty => 0,
            Self::One(_) => 1,
            Self::Two(_) => 2,
            Self::Three(_) => 3,
            Self::Many(values) => values.len(),
        }
    }

    fn as_slice(&self) -> &[Value] {
        match self {
            Self::Empty => &[],
            Self::One(values) => values,
            Self::Two(values) => values,
            Self::Three(values) => values,
            Self::Many(values) => values,
        }
    }

    fn into_vec(self) -> Vec<Value> {
        match self {
            Self::Empty => Vec::new(),
            Self::One([one]) => vec![one],
            Self::Two([one, two]) => vec![one, two],
            Self::Three([one, two, three]) => vec![one, two, three],
            Self::Many(values) => values,
        }
    }

    fn into_product_pair_or_vec(self) -> Result<(Value, Value), Vec<Value>> {
        match self {
            Self::Two([left, right]) => Ok((left, right)),
            Self::Many(mut values) if values.len() == 2 => {
                let right = values.pop().expect("checked length");
                let left = values.pop().expect("checked length");
                Ok((left, right))
            }
            Self::One([packet]) => Ok(split_product_pair_value(packet)),
            Self::Many(mut values) if values.len() == 1 => Ok(split_product_pair_value(
                values.pop().expect("checked length"),
            )),
            other => Err(other.into_vec()),
        }
    }
}

fn split_product_pair_value(packet: Value) -> (Value, Value) {
    (
        project_product_value("__fst__", &packet),
        project_product_value("__snd__", &packet),
    )
}

enum EvalLocals<'a> {
    Borrowed(&'a [Value]),
    Owned(Vec<Value>),
}

impl<'a> EvalLocals<'a> {
    fn get(&self, slot: usize) -> Option<&Value> {
        match self {
            Self::Borrowed(values) => values.get(slot),
            Self::Owned(values) => values.get(slot),
        }
    }

    fn as_slice(&self) -> &[Value] {
        match self {
            Self::Borrowed(values) => values,
            Self::Owned(values) => values,
        }
    }

    fn push(&mut self, value: Value) {
        match self {
            Self::Borrowed(values) => {
                let mut owned = values.to_vec();
                owned.push(value);
                *self = Self::Owned(owned);
            }
            Self::Owned(values) => values.push(value),
        }
    }

    fn pop(&mut self) {
        match self {
            Self::Borrowed(_) => unreachable!("borrowed eval locals cannot be popped before push"),
            Self::Owned(values) => {
                values.pop();
            }
        }
    }
}

struct EvalSlots<'a> {
    captured: &'a [Value],
    locals: EvalLocals<'a>,
}

impl<'a> EvalSlots<'a> {
    fn root(locals: Vec<Value>) -> Self {
        Self {
            captured: &[],
            locals: EvalLocals::Owned(locals),
        }
    }

    fn closure_borrowed(captured: &'a [Value], locals: &'a [Value]) -> Self {
        Self {
            captured,
            locals: EvalLocals::Borrowed(locals),
        }
    }

    fn get(&self, slot: usize) -> Option<&Value> {
        if slot < self.captured.len() {
            self.captured.get(slot)
        } else {
            self.locals.get(slot - self.captured.len())
        }
    }

    fn push(&mut self, value: Value) {
        self.locals.push(value);
    }

    fn pop(&mut self) {
        self.locals.pop();
    }

    fn locals_slice(&self) -> &[Value] {
        self.locals.as_slice()
    }
}

#[derive(Debug, Clone)]
pub struct Env {
    frame: EvalRef<EnvFrame>,
}

#[derive(Debug)]
struct EnvFrame {
    parent: Option<Env>,
    bindings: EnvBindings,
}

#[derive(Debug)]
enum EnvBindings {
    Empty,
    One(String, Value),
}

impl Env {
    pub fn new() -> Self {
        static EMPTY_ENV: OnceLock<EvalRef<EnvFrame>> = OnceLock::new();
        Self {
            frame: EMPTY_ENV
                .get_or_init(|| {
                    EvalRef::new(EnvFrame {
                        parent: None,
                        bindings: EnvBindings::Empty,
                    })
                })
                .clone(),
        }
    }

    fn is_empty(&self) -> bool {
        self.frame.parent.is_none() && matches!(self.frame.bindings, EnvBindings::Empty)
    }

    fn flattened_bindings(&self) -> Vec<(String, Value)> {
        let mut frames = Vec::new();
        let mut env = self;
        loop {
            frames.push(&env.frame.bindings);
            let Some(parent) = &env.frame.parent else {
                break;
            };
            env = parent;
        }
        let mut out = Vec::new();
        for bindings in frames.into_iter().rev() {
            bindings.push_into(&mut out);
        }
        out
    }

    pub fn insert(&mut self, name: String, value: Value) {
        *self = Self {
            frame: EvalRef::new(EnvFrame {
                parent: Some(self.clone()),
                bindings: EnvBindings::One(name, value),
            }),
        };
    }
}

impl Default for Env {
    fn default() -> Self {
        Self::new()
    }
}

impl EnvBindings {
    fn push_into(&self, out: &mut Vec<(String, Value)>) {
        match self {
            EnvBindings::Empty => {}
            EnvBindings::One(name, value) => out.push((name.clone(), value.clone())),
        }
    }
}

/// Evaluation context: package-backed callers set a root module and
/// package so function references resolve through the module where
/// each function is defined. The flat `fn` maps remain for direct
/// evaluator tests and non-package contexts.
/// Newtype member resolution is cached per lexical owner module. Each
/// resolved value carries the declaration's canonical module/type/member
/// identity, so unrelated package declarations never participate in
/// reduction.
pub struct EvalCtx<'m> {
    pub fn_defs: FnMap<'m>,
    pub qualified_fn_defs: QualifiedFnMap<'m>,
    package: Option<&'m EvalPackage>,
    root_module: Option<&'m Module<EvalPhase>>,
    module_fn_index: Mutex<HashMap<usize, ModuleFnIndex<'m>>>,
    module_newtype_index: Mutex<HashMap<usize, ModuleNewtypeIndex>>,
    identity_alias_newtypes: OnceLock<crate::pass::resolve::IdentityAliasNewtypeIndex>,
    fn_closure_cache: SharedFnClosureCache,
    eval_function_cache: SharedEvalFunctionCache,
    type_view_cache: SharedTypeViewCache,
    exact_call_memo: SharedExactCallMemoCache,
    primitive_env: EvalPrimitiveEnv,
    /// Dotted path for flat-map eval contexts. Package-backed eval
    /// carries the current owner module path in the compile state so
    /// imported helper bodies consult their own value-at-type-slot
    /// markers. Defaults to `""` for callers that don't set it —
    /// every such caller's terms then fall through to the no-signature
    /// value-args-only behavior, the pre-existing default.
    pub module_path: String,
    pub metrics: Option<Arc<EvalMetrics>>,
    active_structural_recur_sites:
        Mutex<HashMap<std::thread::ThreadId, ActiveStructuralRecurSites>>,
    #[cfg(test)]
    structural_recur_site_lookup_work: AtomicUsize,
    structural_recur_operations:
        Mutex<HashMap<std::thread::ThreadId, StructuralRecurOperationState>>,
    public_structural_recur_site: Arc<StructuralRecurSite>,
}

impl<'m> Default for EvalCtx<'m> {
    fn default() -> Self {
        Self::new()
    }
}

impl<'m> EvalCtx<'m> {
    pub fn new() -> Self {
        let public_generation = EvalSourceGeneration::fresh();
        Self {
            fn_defs: HashMap::new(),
            qualified_fn_defs: HashMap::new(),
            package: None,
            root_module: None,
            module_fn_index: Mutex::new(HashMap::new()),
            module_newtype_index: Mutex::new(HashMap::new()),
            identity_alias_newtypes: OnceLock::new(),
            fn_closure_cache: SharedFnClosureCache::default(),
            eval_function_cache: SharedEvalFunctionCache::default(),
            type_view_cache: SharedTypeViewCache::default(),
            exact_call_memo: SharedExactCallMemoCache::default(),
            primitive_env: EvalPrimitiveEnv::default(),
            module_path: String::new(),
            metrics: None,
            active_structural_recur_sites: Mutex::new(HashMap::new()),
            #[cfg(test)]
            structural_recur_site_lookup_work: AtomicUsize::new(0),
            structural_recur_operations: Mutex::new(HashMap::new()),
            public_structural_recur_site: StructuralRecurSite::public_api(&public_generation),
        }
    }

    pub fn with_module_path(mut self, module_path: &str) -> Self {
        self.module_path = module_path.to_string();
        self
    }

    pub fn with_package(mut self, package: Option<&'m EvalPackage>) -> Self {
        self.package = package;
        self
    }

    pub fn with_root_module(mut self, module: &'m Module<EvalPhase>) -> Self {
        self.root_module = Some(module);
        self
    }

    pub fn with_metrics(mut self, metrics: Arc<EvalMetrics>) -> Self {
        self.metrics = Some(metrics);
        self
    }

    pub fn with_fn_closure_cache(mut self, cache: SharedFnClosureCache) -> Self {
        self.fn_closure_cache = cache;
        self
    }

    pub fn with_eval_function_cache(mut self, cache: SharedEvalFunctionCache) -> Self {
        self.eval_function_cache = cache;
        self
    }

    pub fn with_type_view_cache(mut self, cache: SharedTypeViewCache) -> Self {
        self.type_view_cache = cache;
        self
    }

    pub fn with_exact_call_memo_cache(mut self, cache: SharedExactCallMemoCache) -> Self {
        self.exact_call_memo = cache;
        self
    }

    pub fn with_primitive_env(mut self, primitives: EvalPrimitiveEnv) -> Self {
        self.primitive_env = primitives;
        self
    }

    pub fn with_fn_defs(mut self, fn_defs: FnMap<'m>) -> Self {
        self.fn_defs = fn_defs;
        self
    }

    pub fn with_qualified_fn_defs(mut self, qualified: QualifiedFnMap<'m>) -> Self {
        self.qualified_fn_defs = qualified;
        self
    }

    /// The package-backed evaluation context for reducing terms that
    /// live in `module` (canonical path `module_path`): the
    /// [`eval_fn_tables`] scope tables and the module / package backrefs,
    /// assembled
    /// in one place so single-shot drivers (the REPL, module-source
    /// evaluation) cannot drift from `kio test`'s equiv discharge —
    /// whose batched runner builds the same pieces once per module via
    /// the same builders. Fails only when [`ModuleEnv`] construction
    /// fails, which callers post-typecheck treat as an internal
    /// contract violation.
    ///
    /// [`ModuleEnv`]: crate::pass::typecheck_core::ModuleEnv
    pub fn for_module(
        artifact: &'m EvalArtifact,
        module: &'m Module<EvalPhase>,
        module_path: &str,
    ) -> Result<Self, crate::error::Error> {
        let package = artifact.package();
        let (fn_defs, qualified_fn_defs) = eval_fn_tables(package, module)?;
        Ok(Self::new()
            .with_fn_defs(fn_defs)
            .with_qualified_fn_defs(qualified_fn_defs)
            .with_module_path(module_path)
            .with_root_module(module)
            .with_package(Some(package))
            .with_primitive_env(artifact.primitives().clone()))
    }

    fn has_active_structural_recur_site(&self) -> bool {
        let thread_id = std::thread::current().id();
        self.active_structural_recur_sites
            .lock()
            .expect("active __structural_recur__ site stack poisoned")
            .get(&thread_id)
            .is_some_and(|state| {
                assert_eq!(
                    state.frames.is_empty(),
                    state.latest_by_site.is_empty(),
                    "active structural recursion frames and latest-site index agree on emptiness"
                );
                !state.frames.is_empty()
            })
    }

    #[cfg(test)]
    fn take_structural_recur_site_lookup_work(&self) -> usize {
        self.structural_recur_site_lookup_work
            .swap(0, Ordering::Relaxed)
    }

    #[cfg(test)]
    fn active_structural_recur_state_for_test(&self) -> Option<ActiveStructuralRecurSites> {
        let thread_id = std::thread::current().id();
        self.active_structural_recur_sites
            .lock()
            .expect("active __structural_recur__ site stack poisoned")
            .get(&thread_id)
            .cloned()
    }

    fn enter_structural_recur_operation(&self) -> StructuralRecurOperationGuard<'_, 'm> {
        let thread_id = std::thread::current().id();
        let mut operations = self
            .structural_recur_operations
            .lock()
            .expect("__structural_recur__ operation map poisoned");
        let state = operations
            .entry(thread_id)
            .or_insert(StructuralRecurOperationState {
                depth: 0,
                first_fault: None,
            });
        let root = state.depth == 0;
        state.depth += 1;
        StructuralRecurOperationGuard {
            ctx: self,
            thread_id,
            root,
            active: true,
        }
    }

    fn record_structural_recur_fault(&self, fault: &Value) {
        let thread_id = std::thread::current().id();
        let mut operations = self
            .structural_recur_operations
            .lock()
            .expect("__structural_recur__ operation map poisoned");
        let Some(state) = operations.get_mut(&thread_id) else {
            return;
        };
        if state.first_fault.is_none() {
            state.first_fault = Some(fault.clone());
        }
    }

    fn structural_recur_operation_has_fault(&self) -> bool {
        let thread_id = std::thread::current().id();
        self.structural_recur_operations
            .lock()
            .expect("__structural_recur__ operation map poisoned")
            .get(&thread_id)
            .is_some_and(|state| state.first_fault.is_some())
    }

    fn leave_structural_recur_operation(
        &self,
        thread_id: std::thread::ThreadId,
        root: bool,
    ) -> Option<Value> {
        let mut operations = self
            .structural_recur_operations
            .lock()
            .expect("__structural_recur__ operation map poisoned");
        let state = operations
            .get_mut(&thread_id)
            .expect("active __structural_recur__ operation frame");
        state.depth = state
            .depth
            .checked_sub(1)
            .expect("__structural_recur__ operation depth is positive");
        if root {
            debug_assert_eq!(state.depth, 0);
            return operations
                .remove(&thread_id)
                .and_then(|state| state.first_fault);
        }
        debug_assert!(state.depth > 0);
        None
    }

    fn enter_structural_recur_site(
        &self,
        site: &Arc<StructuralRecurSite>,
        fuel: &Value,
    ) -> Result<(usize, StructuralRecurSiteGuard<'_, 'm>), StructuralRecurSiteEntryError> {
        let thread_id = std::thread::current().id();
        let active_entry = self
            .active_structural_recur_sites
            .lock()
            .expect("active __structural_recur__ site stack poisoned")
            .get(&thread_id)
            .and_then(|state| {
                assert_eq!(
                    state.frames.is_empty(),
                    state.latest_by_site.is_empty(),
                    "active structural recursion frames and latest-site index agree on emptiness"
                );
                assert!(
                    !state.frames.is_empty(),
                    "empty structural recursion thread states are removed"
                );
                #[cfg(test)]
                self.structural_recur_site_lookup_work
                    .fetch_update(Ordering::Relaxed, Ordering::Relaxed, |work| {
                        work.checked_add(1)
                    })
                    .expect("structural recursion site lookup work overflow");
                state.latest_by_site.get(site).copied().map(|frame_number| {
                    let frame_index = frame_number
                        .get()
                        .checked_sub(1)
                        .expect("active structural recursion frame number is nonzero");
                    let frame = state
                        .frames
                        .get(frame_index)
                        .expect("latest structural recursion frame number is in bounds");
                    assert_eq!(
                        frame.site.as_ref(),
                        site.as_ref(),
                        "latest structural recursion frame maps to its exact site"
                    );
                    (frame_number, frame.root_measure, frame.measure)
                })
            });
        let (previous_same, root_measure, measure) = match active_entry {
            Some((frame_number, root_measure, current_measure)) => {
                let Some(next_measure) = fuel_measure(fuel, self) else {
                    return Err(StructuralRecurSiteEntryError::NonDecreasingReentry {
                        root_measure,
                        current_measure,
                        next_measure: None,
                    });
                };
                if next_measure >= current_measure {
                    return Err(StructuralRecurSiteEntryError::NonDecreasingReentry {
                        root_measure,
                        current_measure,
                        next_measure: Some(next_measure),
                    });
                }
                (Some(frame_number), root_measure, next_measure)
            }
            None => {
                let measure = initial_fuel_measure(fuel, self)
                    .ok_or(StructuralRecurSiteEntryError::UnmeasurableInitialFuel)?;
                (None, measure, measure)
            }
        };

        // Measuring fuel only inspects immutable evaluator values and cannot
        // invoke evaluator code. The same thread therefore cannot mutate its
        // stack between the snapshot above and this push, while releasing the
        // mutex avoids serializing independent evaluator threads.
        let mut active = self
            .active_structural_recur_sites
            .lock()
            .expect("active __structural_recur__ site stack poisoned");
        let state = active.entry(thread_id).or_default();
        assert_eq!(
            state.frames.is_empty(),
            state.latest_by_site.is_empty(),
            "active structural recursion frames and latest-site index agree on emptiness"
        );
        assert_eq!(
            state.latest_by_site.get(site).copied(),
            previous_same,
            "active structural recursion site mapping changed while measuring immutable fuel"
        );
        let frame_number = NonZeroUsize::new(
            state
                .frames
                .len()
                .checked_add(1)
                .expect("active structural recursion frame number overflow"),
        )
        .expect("active structural recursion frame number is nonzero");
        if let Some(previous) = previous_same {
            assert!(
                previous < frame_number,
                "previous same-site frame is strictly earlier"
            );
        }
        state.frames.push(ActiveStructuralRecurSite {
            site: site.clone(),
            root_measure,
            measure,
            previous_same,
        });
        assert_eq!(
            state.latest_by_site.insert(site.clone(), frame_number),
            previous_same,
            "active structural recursion site mapping matches its previous frame"
        );
        assert_eq!(
            state.frames.is_empty(),
            state.latest_by_site.is_empty(),
            "active structural recursion frames and latest-site index agree on emptiness"
        );
        Ok((
            measure,
            StructuralRecurSiteGuard {
                ctx: self,
                thread_id,
                frame_number,
            },
        ))
    }
}

/// Immutable evaluator context bound to one validated artifact generation.
///
/// This wrapper is crate-private so the shared compile/closure caches can be
/// used only while the package, primitive grants, and root resolution tables
/// remain exactly those validated for the retained artifact. Public mutable
/// [`EvalCtx`] values always compile under a fresh root generation instead.
pub(crate) struct AuthenticatedEvalCtx<'m> {
    inner: EvalCtx<'m>,
    source_generation: EvalSourceGeneration,
}

impl<'m> AuthenticatedEvalCtx<'m> {
    pub(crate) fn for_module(
        artifact: &'m EvalArtifact,
        module: &'m Module<EvalPhase>,
        module_path: &str,
    ) -> Result<Self, crate::error::Error> {
        let (fn_defs, qualified_fn_defs) = eval_fn_tables(artifact.package(), module)?;
        Ok(Self::for_module_with_fn_tables(
            artifact,
            module,
            module_path,
            fn_defs,
            qualified_fn_defs,
        ))
    }

    pub(crate) fn for_module_with_fn_tables(
        artifact: &'m EvalArtifact,
        module: &'m Module<EvalPhase>,
        module_path: &str,
        fn_defs: FnMap<'m>,
        qualified_fn_defs: QualifiedFnMap<'m>,
    ) -> Self {
        Self {
            inner: EvalCtx::new()
                .with_fn_defs(fn_defs)
                .with_qualified_fn_defs(qualified_fn_defs)
                .with_module_path(module_path)
                .with_root_module(module)
                .with_package(Some(artifact.package()))
                .with_primitive_env(artifact.primitives().clone()),
            source_generation: artifact.source_generation(),
        }
    }

    pub(crate) fn with_metrics(mut self, metrics: Arc<EvalMetrics>) -> Self {
        self.inner = self.inner.with_metrics(metrics);
        self
    }

    pub(crate) fn with_fn_closure_cache(mut self, cache: SharedFnClosureCache) -> Self {
        self.inner = self.inner.with_fn_closure_cache(cache);
        self
    }

    pub(crate) fn with_eval_function_cache(mut self, cache: SharedEvalFunctionCache) -> Self {
        self.inner = self.inner.with_eval_function_cache(cache);
        self
    }

    pub(crate) fn with_type_view_cache(mut self, cache: SharedTypeViewCache) -> Self {
        self.inner = self.inner.with_type_view_cache(cache);
        self
    }

    pub(crate) fn with_exact_call_memo_cache(mut self, cache: SharedExactCallMemoCache) -> Self {
        self.inner = self.inner.with_exact_call_memo_cache(cache);
        self
    }
}

impl<'m> std::ops::Deref for AuthenticatedEvalCtx<'m> {
    type Target = EvalCtx<'m>;

    fn deref(&self) -> &Self::Target {
        &self.inner
    }
}

struct StructuralRecurOperationGuard<'ctx, 'm> {
    ctx: &'ctx EvalCtx<'m>,
    thread_id: std::thread::ThreadId,
    root: bool,
    active: bool,
}

impl StructuralRecurOperationGuard<'_, '_> {
    fn finish(mut self, value: Value) -> Value {
        let fault = self
            .ctx
            .leave_structural_recur_operation(self.thread_id, self.root);
        self.active = false;
        if self.root {
            fault.unwrap_or(value)
        } else {
            value
        }
    }

    fn finish_checked<T>(mut self, value: T) -> Result<T, Value> {
        let fault = self
            .ctx
            .leave_structural_recur_operation(self.thread_id, self.root);
        self.active = false;
        match fault {
            Some(fault) => Err(fault),
            None => Ok(value),
        }
    }
}

impl Drop for StructuralRecurOperationGuard<'_, '_> {
    fn drop(&mut self) {
        if self.active {
            let _ = self
                .ctx
                .leave_structural_recur_operation(self.thread_id, self.root);
        }
    }
}

struct StructuralRecurSiteGuard<'ctx, 'm> {
    ctx: &'ctx EvalCtx<'m>,
    thread_id: std::thread::ThreadId,
    frame_number: NonZeroUsize,
}

#[cfg(target_pointer_width = "64")]
const _: () = assert!(std::mem::size_of::<StructuralRecurSiteGuard<'_, '_>>() == 24);

impl Drop for StructuralRecurSiteGuard<'_, '_> {
    fn drop(&mut self) {
        let mut active = self
            .ctx
            .active_structural_recur_sites
            .lock()
            .expect("active __structural_recur__ site stack poisoned");
        let empty = {
            let state = active
                .get_mut(&self.thread_id)
                .expect("active structural recursion thread state exists");
            assert_eq!(
                state.frames.len(),
                self.frame_number.get(),
                "structural recursion site guards drop in strict LIFO order"
            );
            let frame = state
                .frames
                .pop()
                .expect("active structural recursion frame exists");
            assert_eq!(
                state.latest_by_site.get(&frame.site).copied(),
                Some(self.frame_number),
                "latest structural recursion site points to the popped frame"
            );
            match frame.previous_same {
                Some(previous) => {
                    assert!(
                        previous < self.frame_number,
                        "previous same-site frame is strictly earlier"
                    );
                    let previous_index = previous
                        .get()
                        .checked_sub(1)
                        .expect("previous same-site frame number is nonzero");
                    let previous_frame = state
                        .frames
                        .get(previous_index)
                        .expect("previous same-site frame number is in bounds");
                    assert_eq!(
                        previous_frame.site.as_ref(),
                        frame.site.as_ref(),
                        "previous same-site link targets an equal structural site"
                    );
                    assert_eq!(
                        state.latest_by_site.insert(frame.site, previous),
                        Some(self.frame_number),
                        "dropping a repeated site restores its previous frame"
                    );
                }
                None => {
                    assert_eq!(
                        state.latest_by_site.remove(&frame.site),
                        Some(self.frame_number),
                        "dropping a site's last frame removes its latest mapping"
                    );
                }
            }
            let frames_empty = state.frames.is_empty();
            assert_eq!(
                frames_empty,
                state.latest_by_site.is_empty(),
                "active structural recursion frames and latest-site index agree on emptiness"
            );
            frames_empty
        };
        if empty {
            let removed = active
                .remove(&self.thread_id)
                .expect("empty structural recursion thread state exists");
            assert!(removed.frames.is_empty());
            assert!(removed.latest_by_site.is_empty());
        }
    }
}

/// Stable declaration inputs retained by the equiv cache fingerprint.
///
/// The reducer does not consult this package-wide summary. Newtype member
/// authority comes only from [`ModuleNewtypeIndex`], which is built from the
/// lexical owner's declarations and explicit imports.
#[derive(Debug, Default, Clone)]
pub struct NewtypeRegistry {
    /// Exact declaration-site projector → constructor identities.
    pub proj_ctor: HashMap<String, String>,
    /// Exact declaration-site constructor identities.
    pub ctors: std::collections::HashSet<String>,
    pub ctor_canonical: HashMap<String, String>,
    pub ctor_abi_arity: HashMap<String, usize>,
}

/// Build the cache-only newtype fingerprint from exact declaration sites.
/// No bare member spelling or import alias enters this summary.
pub fn newtype_registry_for_package(package: &EvalPackage) -> NewtypeRegistry {
    let mut registry = NewtypeRegistry::default();
    for (module_path, entry) in package.modules() {
        for item in &entry.module.items {
            crate::pass::resolve::for_each_item_declaration(item, |declaration| {
                let Some(newtype) = declaration.newtype() else {
                    return;
                };
                let constructor = format!(
                    "{module_path}::{}.{}",
                    newtype.name, newtype.constructor.name
                );
                let projector =
                    format!("{module_path}::{}.{}", newtype.name, newtype.projector.name);
                registry.proj_ctor.insert(projector, constructor.clone());
                registry.ctors.insert(constructor.clone());
                registry
                    .ctor_canonical
                    .insert(constructor.clone(), constructor.clone());
                registry.ctor_abi_arity.insert(
                    constructor,
                    Type::function_param_abi_slot_count(&newtype.payload),
                );
            });
        }
    }
    registry
}

/// Same-module fn table type for [`eval_fn_tables`], shared by every
/// package-backed evaluation driver.
pub type FnMap<'m> = HashMap<&'m str, &'m FnDef<EvalPhase>>;

/// Qualified `(alias, name)` fn table type for [`eval_fn_tables`].
pub type QualifiedFnMap<'m> = HashMap<(&'m str, &'m str), &'m FnDef<EvalPhase>>;

/// The [`FnMap`] / [`QualifiedFnMap`] pair a [`ModuleEnv`] induces:
///
/// - [`FnMap`]: same-module declarations plus selective
///   `import other/module(a, b);` imports.
/// - [`QualifiedFnMap`]: keyed by `(alias, name)`, visible fns of qualified
///   imports.
///
/// [`ModuleEnv`]: crate::pass::typecheck_core::ModuleEnv
pub fn fn_tables_from_env<'m>(
    env: &crate::pass::typecheck_core::ModuleEnv<'m, EvalPhase>,
) -> (FnMap<'m>, QualifiedFnMap<'m>) {
    let fn_defs: FnMap<'m> = env
        .fn_defs
        .iter()
        .chain(env.cross_module_fn_defs.iter())
        .map(|(k, v)| (*k, *v))
        .collect();
    let mut qualified: QualifiedFnMap<'m> = HashMap::new();
    for (alias, target_module) in &env.qualified_imports {
        for item in &target_module.items {
            if let Item::FnDef(d) = item
                && crate::pass::resolve::is_visible(&d.vis, &env.module.path)
            {
                qualified.insert((*alias, d.name.as_str()), d);
            }
        }
    }
    (fn_defs, qualified)
}

/// Fn lookup tables induced by the exact ordinary imports written into the
/// evaluator artifact. Visibility is therefore checked by `ModuleEnv`; no
/// package-wide provider scan or generated-spelling privilege participates.
pub fn eval_fn_tables<'m>(
    package: &'m EvalPackage,
    module: &'m Module<EvalPhase>,
) -> Result<(FnMap<'m>, QualifiedFnMap<'m>), crate::error::Error> {
    let package_file = package.package_file().map(|e| &e.package_file);
    let package_name = package.package_file().map(|e| e.package_name.as_str());
    let env = crate::pass::typecheck_core::ModuleEnv::build(
        module,
        package_file,
        package_name,
        Some(package),
    )?;
    Ok(fn_tables_from_env(&env))
}

/// Evaluate a value-position expression to a [`Value`].
///
/// `EvalCtx` is a public mutable embedding context, so each call is a fresh
/// evaluator root: compilation uses a root-local function cache and does not
/// reuse the context's shared compiled-function or closure cache. Values
/// returned by the call retain that root's private source-origin namespace.
pub fn eval(expr: &Expr<EvalPhase>, env: &Env, ctx: &EvalCtx<'_>) -> Value {
    eval_with_compile_scope(expr, env, ctx, EvalSourceGeneration::fresh(), false)
}

pub(crate) fn eval_authenticated(
    expr: &Expr<EvalPhase>,
    env: &Env,
    ctx: &AuthenticatedEvalCtx<'_>,
) -> Value {
    eval_with_compile_scope(expr, env, ctx, ctx.source_generation.clone(), true)
}

fn eval_with_compile_scope(
    expr: &Expr<EvalPhase>,
    env: &Env,
    ctx: &EvalCtx<'_>,
    source_generation: EvalSourceGeneration,
    share_fn_closures: bool,
) -> Value {
    let operation = ctx.enter_structural_recur_operation();
    let eval_value = || {
        let mut initial_bindings = Vec::new();
        if !env.is_empty() {
            initial_bindings = env.flattened_bindings();
        }
        let initial_names: Vec<String> = initial_bindings
            .iter()
            .map(|(name, _)| name.clone())
            .collect();
        let local_eval_function_cache = (!share_fn_closures)
            .then(|| RefCell::new(HashMap::<EvalFunctionCacheKey, EvalRef<EvalFunction>>::new()));
        let compiled = compile_eval_root_in_scope(
            expr,
            ctx,
            initial_names,
            source_generation,
            local_eval_function_cache.as_ref(),
            share_fn_closures,
        )
        .expect("Kio' evaluator expression should compile to slot IR");
        let initial_values: Vec<Value> = initial_bindings
            .into_iter()
            .map(|(_, value)| value)
            .collect();
        let mut slots = EvalSlots::root(initial_values);
        eval_compiled_expr(&compiled, &mut slots, ctx)
    };
    let value = if let Some(metrics) = ctx.metrics.as_deref() {
        let start = Instant::now();
        let value = eval_value();
        metrics.record_root_eval(start.elapsed());
        value
    } else {
        eval_value()
    };
    operation.finish(value)
}

type RootEvalFunctionCache = RefCell<HashMap<EvalFunctionCacheKey, EvalRef<EvalFunction>>>;

struct EvalCompileState<'c, 'm> {
    ctx: &'c EvalCtx<'m>,
    module: Option<&'m Module<EvalPhase>>,
    module_path: String,
    label_scope: Option<String>,
    locals: Vec<String>,
    type_binders: HashMap<String, crate::ast::Kind>,
    fn_stack: Vec<EvalFunctionCacheKey>,
    source_generation: EvalSourceGeneration,
    local_eval_function_cache: Option<&'c RootEvalFunctionCache>,
    share_fn_closures: bool,
}

impl EvalCompileState<'_, '_> {
    fn cached_eval_function(&self, key: &EvalFunctionCacheKey) -> Option<EvalRef<EvalFunction>> {
        if let Some(cache) = &self.local_eval_function_cache {
            return cache.borrow().get(key).cloned();
        }
        self.ctx
            .eval_function_cache
            .inner
            .lock()
            .expect("eval function cache lock poisoned")
            .get(key)
            .cloned()
    }

    fn cache_eval_function(&self, key: EvalFunctionCacheKey, function: EvalRef<EvalFunction>) {
        if let Some(cache) = &self.local_eval_function_cache {
            cache.borrow_mut().insert(key, function);
            return;
        }
        self.ctx
            .eval_function_cache
            .inner
            .lock()
            .expect("eval function cache lock poisoned")
            .insert(key, function);
    }
}

#[cfg(test)]
fn compile_eval_root<'m>(
    expr: &EvalAstExpr,
    ctx: &EvalCtx<'m>,
    locals: Vec<String>,
) -> Option<EvalRef<EvalExpr>> {
    let local_eval_function_cache = RefCell::new(HashMap::new());
    compile_eval_root_in_scope(
        expr,
        ctx,
        locals,
        EvalSourceGeneration::fresh(),
        Some(&local_eval_function_cache),
        false,
    )
}

fn compile_eval_root_in_scope<'c, 'm>(
    expr: &EvalAstExpr,
    ctx: &'c EvalCtx<'m>,
    locals: Vec<String>,
    source_generation: EvalSourceGeneration,
    local_eval_function_cache: Option<&'c RootEvalFunctionCache>,
    share_fn_closures: bool,
) -> Option<EvalRef<EvalExpr>> {
    let mut state = EvalCompileState {
        ctx,
        module: ctx.root_module,
        module_path: ctx
            .root_module
            .map(module_path_string)
            .unwrap_or_else(|| ctx.module_path.clone()),
        label_scope: None,
        locals,
        type_binders: HashMap::new(),
        fn_stack: Vec::new(),
        source_generation,
        local_eval_function_cache,
        share_fn_closures,
    };
    compile_eval_expr(expr, &mut state)
}

fn compile_eval_expr(
    expr: &EvalAstExpr,
    state: &mut EvalCompileState<'_, '_>,
) -> Option<EvalRef<EvalExpr>> {
    let compiled = match expr {
        crate::ast::Expr::BlockCall { ext, .. } => match *ext {},
        Expr::Unit { .. } => EvalExpr::Unit,
        Expr::BoolLit { value, .. } => EvalExpr::Bool(*value),
        Expr::IntLit {
            digits, annotation, ..
        } => EvalExpr::IntAtom(
            digits.clone(),
            literal_annotation_identity(annotation.as_ref(), state),
        ),
        Expr::FloatLit {
            digits, annotation, ..
        } => EvalExpr::FloatAtom(
            digits.clone(),
            literal_annotation_identity(annotation.as_ref(), state),
        ),
        Expr::StrLit {
            value, annotation, ..
        } if literal_is_primitive_type(
            annotation.as_ref(),
            ComptimeBuiltin::DiagnosticText,
            state,
        ) =>
        {
            EvalExpr::DiagnosticText(value.clone())
        }
        Expr::StrLit { value, .. } => EvalExpr::StrAtom(value.clone()),
        Expr::Path { segments, .. } => {
            compile_eval_path(segments, EvalSourceOccurrence::of(expr), state)?
        }
        Expr::Let {
            name, value, body, ..
        } => {
            let value = compile_eval_expr(value, state)?;
            state.locals.push(name.clone());
            let body = compile_eval_expr(body, state)?;
            state.locals.pop();
            EvalExpr::Let { value, body }
        }
        Expr::Seq { value, body, .. } => EvalExpr::Seq {
            value: compile_eval_expr(value, state)?,
            body: compile_eval_expr(body, state)?,
        },
        Expr::FnExpr {
            sig, body, meta, ..
        } => {
            let (function, captured_slots) =
                compile_eval_fn_expr(sig, body, meta.span, EvalSourceOccurrence::of(expr), state)?;
            EvalExpr::FnExpr {
                function,
                captured_slots,
                empty_closure_cache: Arc::new(OnceLock::new()),
            }
        }
        Expr::Call {
            callee, args, meta, ..
        } => {
            let reflect_start = state.ctx.metrics.as_deref().map(|_| Instant::now());
            if let Some(reflected) = compile_reflect_type_call(callee, args, state) {
                if let (Some(metrics), Some(start)) = (state.ctx.metrics.as_deref(), reflect_start)
                {
                    metrics.record_reflection_kind(ReflectionMetricKind::Other, start.elapsed());
                }
                return Some(EvalRef::new(reflected));
            }
            if let Some(core) = compile_core_intrinsic_call(callee, args, state) {
                core
            } else if let Some(direct) = compile_direct_path_call(callee, args, meta.span, state) {
                direct?
            } else {
                let callee = compile_eval_expr(callee, state)?;
                let args = compile_value_arg_exprs_without_fn(args, meta.span, state)?;
                if let Some(direct) = compile_direct_known_function_call(&callee, &args) {
                    direct
                } else {
                    EvalExpr::Call { callee, args }
                }
            }
        }
        Expr::Elaborator { ext, .. }
        | Expr::RecOrder { ext, .. }
        | Expr::RecQuote { ext, .. }
        | Expr::UserElaborator { ext, .. } => match *ext {},
        Expr::Tuple { ext, .. } => match *ext {},
        Expr::LabelValue { ext, .. } => match *ext {},
        Expr::RowLet { ext, .. } => match *ext {},
        Expr::FnPlaceholder { ext, .. } => match *ext {},
        Expr::OpChain { ext, .. } => match *ext {},
        Expr::RecCall { ext, .. } => match *ext {},
        Expr::Ufcs { ext, .. } => match *ext {},
        Expr::EnrichedTuple { ext, .. }
        | Expr::EnrichedProject { ext, .. }
        | Expr::EnrichedInject { ext, .. }
        | Expr::EnrichedMatch { ext, .. }
        | Expr::EnrichedConditional { ext, .. }
        | Expr::EnrichedRecord { ext, .. }
        | Expr::EnrichedFieldGet { ext, .. } => match *ext {},
        Expr::LowHostCall { ext, .. }
        | Expr::LowModuleCall { ext, .. }
        | Expr::LowQualifiedModuleCall { ext, .. }
        | Expr::LowQualifiedNewtypeMember { ext, .. }
        | Expr::LowNewtypeCtor { ext, .. }
        | Expr::LowNewtypeProj { ext, .. }
        | Expr::LowClosureCall { ext, .. }
        | Expr::LowIndirectCall { ext, .. }
        | Expr::LowTypeApplication { ext, .. }
        | Expr::LowAbsurdCall { ext, .. }
        | Expr::LowCpsProjectorApply { ext, .. }
        | Expr::LowBoundRef { ext, .. }
        | Expr::LowHostFnValueRef { ext, .. }
        | Expr::LowModuleFnValueRef { ext, .. } => match *ext {},
    };
    Some(EvalRef::new(compiled))
}

fn compile_eval_expr_against(
    expr: &EvalAstExpr,
    expected: Option<&EvalAstType>,
    state: &mut EvalCompileState<'_, '_>,
) -> Option<EvalRef<EvalExpr>> {
    if literal_is_primitive_type(expected, ComptimeBuiltin::DiagnosticText, state) {
        return compile_diagnostic_text_expr(expr, state);
    }
    compile_eval_expr(expr, state)
}

fn compile_diagnostic_text_expr(
    expr: &EvalAstExpr,
    state: &mut EvalCompileState<'_, '_>,
) -> Option<EvalRef<EvalExpr>> {
    match expr {
        Expr::StrLit { value, .. } => Some(EvalRef::new(EvalExpr::DiagnosticText(value.clone()))),
        _ => compile_eval_expr(expr, state),
    }
}

fn compile_direct_known_function_call(
    callee: &EvalRef<EvalExpr>,
    args: &[EvalRef<EvalExpr>],
) -> Option<EvalExpr> {
    match callee.as_ref() {
        EvalExpr::FnExpr {
            function,
            captured_slots,
            ..
        } if args.len() == function.abi_arity() => Some(EvalExpr::CallFnExpr {
            function: function.clone(),
            captured_slots: captured_slots.clone(),
            args: args.to_vec(),
        }),
        EvalExpr::FnRef { function, .. } if args.len() == function.abi_arity() => {
            Some(EvalExpr::CallFn {
                function: function.clone(),
                args: args.to_vec(),
            })
        }
        _ => None,
    }
}

enum ResolvedUnqualifiedEvalValue<'m> {
    Newtype(Arc<ResolvedNewtypeMemberValue>),
    Local(usize),
    ModuleFunction(EvalFnRef<'m>),
    FlatFunction(&'m FnDef<EvalPhase>),
    Primitive(ComptimeBuiltin),
    Atom,
}

fn resolve_unqualified_eval_value<'m>(
    segments: &[PathSegment],
    state: &EvalCompileState<'_, 'm>,
) -> Option<ResolvedUnqualifiedEvalValue<'m>> {
    let [head] = segments else {
        return None;
    };
    if let Some(member) = state
        .module
        .and_then(|module| resolve_module_newtype_member(state.ctx, module, segments))
    {
        return Some(ResolvedUnqualifiedEvalValue::Newtype(member));
    }
    let name = head.as_str();
    if let Some(slot) = state.locals.iter().rposition(|local| local == name) {
        return Some(ResolvedUnqualifiedEvalValue::Local(slot));
    }
    if let Some(function) = state
        .module
        .and_then(|module| resolve_module_fn(state.ctx, module, name))
    {
        return Some(ResolvedUnqualifiedEvalValue::ModuleFunction(function));
    }
    if let Some(def) = state.ctx.fn_defs.get(name).copied() {
        return Some(ResolvedUnqualifiedEvalValue::FlatFunction(def));
    }
    Some(
        state
            .ctx
            .primitive_env
            .resolve(&state.module_path, name)
            .map_or(
                ResolvedUnqualifiedEvalValue::Atom,
                ResolvedUnqualifiedEvalValue::Primitive,
            ),
    )
}

fn compile_eval_path(
    segments: &[PathSegment],
    occurrence: EvalSourceOccurrence,
    state: &mut EvalCompileState<'_, '_>,
) -> Option<EvalExpr> {
    if segments.len() != 1
        && let Some(member) = state
            .module
            .and_then(|module| resolve_module_newtype_member(state.ctx, module, segments))
    {
        return Some(EvalExpr::NewtypeMember(member));
    }
    match segments {
        [head] => {
            let name = head.as_str();
            match resolve_unqualified_eval_value(segments, state)? {
                ResolvedUnqualifiedEvalValue::Newtype(member) => {
                    return Some(EvalExpr::NewtypeMember(member));
                }
                ResolvedUnqualifiedEvalValue::Local(slot) => {
                    return Some(EvalExpr::Local(slot));
                }
                ResolvedUnqualifiedEvalValue::ModuleFunction(function_ref) => {
                    if let Some(function) = compile_eval_fn_ref(function_ref, state) {
                        return Some(EvalExpr::FnRef {
                            cache_key: function.cache_key.clone(),
                            function,
                            share_closure: state.share_fn_closures,
                        });
                    }
                    return Some(EvalExpr::Atom(name.to_string()));
                }
                ResolvedUnqualifiedEvalValue::FlatFunction(def) => {
                    if let Some(function) = compile_eval_fn_def(def, state) {
                        return Some(EvalExpr::FnRef {
                            cache_key: function.cache_key.clone(),
                            function,
                            share_closure: state.share_fn_closures,
                        });
                    }
                    return Some(EvalExpr::Atom(name.to_string()));
                }
                ResolvedUnqualifiedEvalValue::Primitive(builtin) => {
                    if builtin == ComptimeBuiltin::StructuralRecur {
                        return Some(EvalExpr::StructuralRecurPrimitive(
                            structural_recur_primitive_data(
                                StructuralRecurSite::new(
                                    &state.source_generation,
                                    &state.module_path,
                                    occurrence,
                                ),
                                StructuralRecurPrimitiveStage::AwaitingProof,
                            ),
                        ));
                    }
                    return Some(EvalExpr::Primitive(builtin));
                }
                ResolvedUnqualifiedEvalValue::Atom => {}
            }
            Some(EvalExpr::Atom(name.to_string()))
        }
        [alias, name] => {
            if let Some(function_ref) = state.module.and_then(|module| {
                resolve_qualified_module_fn(state.ctx, module, alias.as_str(), name.as_str())
            }) {
                if let Some(function) = compile_eval_fn_ref(function_ref, state) {
                    return Some(EvalExpr::FnRef {
                        cache_key: function.cache_key.clone(),
                        function,
                        share_closure: state.share_fn_closures,
                    });
                }
                return Some(EvalExpr::Atom(format!(
                    "{}.{}",
                    alias.as_str(),
                    name.as_str()
                )));
            }
            if let Some(def) = state
                .ctx
                .qualified_fn_defs
                .get(&(alias.as_str(), name.as_str()))
                .copied()
            {
                if let Some(function) = compile_eval_fn_def(def, state) {
                    return Some(EvalExpr::FnRef {
                        cache_key: function.cache_key.clone(),
                        function,
                        share_closure: state.share_fn_closures,
                    });
                }
                return Some(EvalExpr::Atom(format!(
                    "{}.{}",
                    alias.as_str(),
                    name.as_str()
                )));
            }
            Some(EvalExpr::Atom(format!(
                "{}.{}",
                alias.as_str(),
                name.as_str()
            )))
        }
        _ => Some(EvalExpr::Atom(
            segments
                .iter()
                .map(|segment| segment.as_str())
                .collect::<Vec<_>>()
                .join("."),
        )),
    }
}

fn compile_eval_fn_expr(
    sig: &EvalAstSignature,
    body: &EvalAstExpr,
    span: Span,
    occurrence: EvalSourceOccurrence,
    state: &mut EvalCompileState<'_, '_>,
) -> Option<(EvalRef<EvalFunction>, Arc<[usize]>)> {
    let (params, value_groups, abi_arity) = collect_value_param_layout(sig);
    let param_names = eval_param_names(&params);
    let captured_slots = capture_slots_for_fn_body(body, &param_names, &state.locals);
    let cache_key =
        eval_function_cache_key_for_lambda(sig, body, occurrence, state, &captured_slots);
    let mut nested_locals: Vec<String> = captured_slots
        .iter()
        .map(|slot| state.locals[*slot].clone())
        .collect();
    nested_locals.extend(param_names);
    let diagnostic_body = EvalRef::new(body.clone());
    let mut nested = EvalCompileState {
        ctx: state.ctx,
        module: state.module,
        module_path: state.module_path.clone(),
        label_scope: state.label_scope.clone(),
        locals: nested_locals,
        type_binders: state.type_binders.clone(),
        fn_stack: state.fn_stack.clone(),
        source_generation: state.source_generation.clone(),
        local_eval_function_cache: state.local_eval_function_cache,
        share_fn_closures: state.share_fn_closures,
    };
    for param in &sig.params {
        if let SignatureParam::Type(param) = param {
            nested
                .type_binders
                .insert(param.name.clone(), param.effective_kind());
        }
    }
    let body = compile_eval_expr(body, &mut nested);
    let body = body?;
    let label = state.ctx.metrics.as_ref().map(|_| {
        let scope = state
            .label_scope
            .as_deref()
            .map(|scope| format!("{scope}::"))
            .unwrap_or_default();
        format!(
            "{}::{}<lambda>@{}-{}",
            state.module_path, scope, span.start, span.end
        )
        .into()
    });
    let simple_body = is_simple_handler_expr(&body);
    let memo_candidate = !simple_body && is_memo_candidate_expr(&body);
    Some((
        EvalRef::new(EvalFunction {
            cache_key,
            label,
            owner_module_path: state.module_path.clone().into(),
            source_origin: EvalFunctionOrigin::Anonymous {
                enclosing: state.label_scope.clone().map(Into::into),
                span,
            },
            params,
            value_groups,
            abi_arity,
            simple_body,
            memo_candidate,
            body,
            diagnostic_body,
        }),
        captured_slots.into(),
    ))
}

fn capture_slots_for_fn_body(
    body: &EvalAstExpr,
    params: &[String],
    outer_locals: &[String],
) -> Vec<usize> {
    let mut bound = params.to_vec();
    let mut captures = Vec::new();
    collect_capture_slots(body, outer_locals, &mut bound, &mut captures);
    captures
}

fn collect_capture_slots(
    expr: &EvalAstExpr,
    outer_locals: &[String],
    bound: &mut Vec<String>,
    captures: &mut Vec<usize>,
) {
    match expr {
        crate::ast::Expr::BlockCall { ext, .. } => match *ext {},
        Expr::Path { segments, .. } => {
            let [head] = segments.as_slice() else {
                return;
            };
            let name = head.as_str();
            if bound.iter().rev().any(|local| local == name) {
                return;
            }
            if let Some(slot) = outer_locals.iter().rposition(|local| local == name)
                && !captures.contains(&slot)
            {
                captures.push(slot);
            }
        }
        Expr::Call { callee, args, .. } => {
            collect_capture_slots(callee, outer_locals, bound, captures);
            for arg in args {
                if let CallArg::Value(value) = arg {
                    collect_capture_slots(value, outer_locals, bound, captures);
                }
            }
        }
        Expr::Let {
            name, value, body, ..
        } => {
            collect_capture_slots(value, outer_locals, bound, captures);
            bound.push(name.clone());
            collect_capture_slots(body, outer_locals, bound, captures);
            bound.pop();
        }
        Expr::Seq { value, body, .. } => {
            collect_capture_slots(value, outer_locals, bound, captures);
            collect_capture_slots(body, outer_locals, bound, captures);
        }
        Expr::FnExpr { sig, body, .. } => {
            let old_len = bound.len();
            bound.extend(collect_value_param_names(&sig.params));
            collect_capture_slots(body, outer_locals, bound, captures);
            bound.truncate(old_len);
        }
        Expr::Elaborator { ext, .. }
        | Expr::RecOrder { ext, .. }
        | Expr::RecQuote { ext, .. }
        | Expr::UserElaborator { ext, .. } => match *ext {},
        Expr::Unit { .. }
        | Expr::BoolLit { .. }
        | Expr::IntLit { .. }
        | Expr::FloatLit { .. }
        | Expr::StrLit { .. } => {}
        Expr::Tuple { ext, .. } => match *ext {},
        Expr::LabelValue { ext, .. } => match *ext {},
        Expr::RowLet { ext, .. } => match *ext {},
        Expr::FnPlaceholder { ext, .. } => match *ext {},
        Expr::OpChain { ext, .. } => match *ext {},
        Expr::RecCall { ext, .. } => match *ext {},
        Expr::Ufcs { ext, .. } => match *ext {},
        Expr::EnrichedTuple { ext, .. }
        | Expr::EnrichedProject { ext, .. }
        | Expr::EnrichedInject { ext, .. }
        | Expr::EnrichedMatch { ext, .. }
        | Expr::EnrichedConditional { ext, .. }
        | Expr::EnrichedRecord { ext, .. }
        | Expr::EnrichedFieldGet { ext, .. } => match *ext {},
        Expr::LowHostCall { ext, .. }
        | Expr::LowModuleCall { ext, .. }
        | Expr::LowQualifiedModuleCall { ext, .. }
        | Expr::LowQualifiedNewtypeMember { ext, .. }
        | Expr::LowNewtypeCtor { ext, .. }
        | Expr::LowNewtypeProj { ext, .. }
        | Expr::LowClosureCall { ext, .. }
        | Expr::LowIndirectCall { ext, .. }
        | Expr::LowTypeApplication { ext, .. }
        | Expr::LowAbsurdCall { ext, .. }
        | Expr::LowCpsProjectorApply { ext, .. }
        | Expr::LowBoundRef { ext, .. }
        | Expr::LowHostFnValueRef { ext, .. }
        | Expr::LowModuleFnValueRef { ext, .. } => match *ext {},
    }
}

#[derive(Clone, Copy)]
struct EvalFnRef<'m> {
    def: &'m FnDef<EvalPhase>,
    owner: &'m Module<EvalPhase>,
}

struct ModuleFnIndex<'m> {
    own: HashMap<&'m str, EvalFnRef<'m>>,
    selective: HashMap<&'m str, EvalFnRef<'m>>,
    qualified: HashMap<(&'m str, &'m str), EvalFnRef<'m>>,
}

#[derive(Default)]
struct ModuleNewtypeIndex {
    members: HashMap<String, Option<Arc<ResolvedNewtypeMemberValue>>>,
}

fn resolve_module_newtype_member(
    ctx: &EvalCtx<'_>,
    module: &Module<EvalPhase>,
    segments: &[PathSegment],
) -> Option<Arc<ResolvedNewtypeMemberValue>> {
    let identity_aliases = ctx.identity_alias_newtypes.get_or_init(|| {
        crate::pass::resolve::IdentityAliasNewtypeIndex::build(module, ctx.package)
    });
    let module_key = module as *const Module<EvalPhase> as usize;
    let mut indexes = ctx
        .module_newtype_index
        .lock()
        .expect("eval module newtype index lock poisoned");
    let index = indexes
        .entry(module_key)
        .or_insert_with(|| build_module_newtype_index(ctx.package, module, identity_aliases));
    let display = segments
        .iter()
        .map(PathSegment::as_str)
        .collect::<Vec<_>>()
        .join(".");
    index.members.get(&display).and_then(Clone::clone)
}

fn build_module_newtype_index(
    package: Option<&EvalPackage>,
    module: &Module<EvalPhase>,
    identity_aliases: &crate::pass::resolve::IdentityAliasNewtypeIndex,
) -> ModuleNewtypeIndex {
    let mut index = ModuleNewtypeIndex::default();
    for item in &module.items {
        crate::pass::resolve::for_each_item_declaration(item, |declaration| {
            let Some(visible_type) = declaration
                .newtype()
                .map(|newtype| newtype.name.as_str())
                .or_else(|| declaration.type_alias().map(|alias| alias.name.as_str()))
            else {
                return;
            };
            insert_resolved_newtype_members(
                &mut index,
                identity_aliases,
                package,
                module,
                module,
                declaration,
                visible_type,
            );
        });
    }

    let Some(package) = package else {
        return index;
    };
    for import_ in &module.imports {
        match &import_.kind {
            ImportKind::Selective { items, from } => {
                let Some(target) = package.module(&module_import_path(from)) else {
                    continue;
                };
                for name in items.iter().filter_map(crate::ast::ImportItem::as_name) {
                    let Some(declaration) = find_module_nominal_declaration(&target.module, name)
                    else {
                        continue;
                    };
                    if !crate::pass::resolve::is_visible(&declaration.visibility(), &module.path) {
                        continue;
                    }
                    insert_resolved_newtype_members(
                        &mut index,
                        identity_aliases,
                        Some(package),
                        module,
                        &target.module,
                        declaration,
                        name,
                    );
                }
            }
            ImportKind::Qualified { path, alias, .. } => {
                let Some(target) = package.module(&module_import_path(path)) else {
                    continue;
                };
                for item in &target.module.items {
                    crate::pass::resolve::for_each_item_declaration(item, |declaration| {
                        let Some(type_name) = declaration
                            .newtype()
                            .map(|newtype| newtype.name.as_str())
                            .or_else(|| declaration.type_alias().map(|alias| alias.name.as_str()))
                        else {
                            return;
                        };
                        if !crate::pass::resolve::is_visible(
                            &declaration.visibility(),
                            &module.path,
                        ) {
                            return;
                        }
                        let visible_type = format!("{alias}.{type_name}");
                        insert_resolved_newtype_members(
                            &mut index,
                            identity_aliases,
                            Some(package),
                            module,
                            &target.module,
                            declaration,
                            &visible_type,
                        );
                    });
                }
            }
            ImportKind::Intrinsics | ImportKind::Comptime => {}
        }
    }
    index
}

fn insert_resolved_newtype_members(
    index: &mut ModuleNewtypeIndex,
    identity_aliases: &crate::pass::resolve::IdentityAliasNewtypeIndex,
    package: Option<&EvalPackage>,
    consumer: &Module<EvalPhase>,
    source_owner: &Module<EvalPhase>,
    source: crate::pass::resolve::TopLevelDeclaration<'_, EvalPhase>,
    visible_type: &str,
) {
    let Some((owner, newtype)) =
        resolve_nominal_newtype(identity_aliases, package, source_owner, source)
    else {
        return;
    };
    let visibility_consumer = (owner.path != consumer.path).then_some(consumer);
    insert_visible_newtype_members(index, owner, newtype, visible_type, visibility_consumer);
}

fn insert_visible_newtype_members(
    index: &mut ModuleNewtypeIndex,
    owner: &Module<EvalPhase>,
    newtype: &Newtype<EvalPhase>,
    visible_type: &str,
    consumer: Option<&Module<EvalPhase>>,
) {
    insert_visible_newtype_member(
        index,
        owner,
        newtype,
        visible_type,
        &newtype.constructor,
        NewtypeMemberKind::Constructor {
            payload_abi_arity: Type::function_param_abi_slot_count(&newtype.payload),
        },
        consumer,
    );
    insert_visible_newtype_member(
        index,
        owner,
        newtype,
        visible_type,
        &newtype.projector,
        NewtypeMemberKind::Projector,
        consumer,
    );
}

fn insert_visible_newtype_member(
    index: &mut ModuleNewtypeIndex,
    owner: &Module<EvalPhase>,
    newtype: &Newtype<EvalPhase>,
    visible_type: &str,
    member: &crate::ast::TypeMember<EvalPhase>,
    kind: NewtypeMemberKind,
    consumer: Option<&Module<EvalPhase>>,
) {
    if consumer
        .is_some_and(|consumer| !crate::pass::resolve::is_visible(&member.vis, &consumer.path))
    {
        return;
    }
    let display = format!("{visible_type}.{}", member.name);
    let value = Arc::new(ResolvedNewtypeMemberValue {
        constructor: NewtypeCtorIdentity {
            module_path: module_path_string(owner),
            type_name: newtype.name.clone(),
            constructor_name: newtype.constructor.name.clone(),
        },
        kind,
        member_name: member.name.clone(),
        display: display.clone(),
    });
    use std::collections::hash_map::Entry;
    match index.members.entry(display) {
        Entry::Vacant(entry) => {
            entry.insert(Some(value));
        }
        Entry::Occupied(mut entry) => match entry.get() {
            Some(existing) if existing.semantic_eq(&value) => {}
            Some(_) => {
                entry.insert(None);
            }
            None => {}
        },
    }
}

fn find_module_nominal_declaration<'m>(
    module: &'m Module<EvalPhase>,
    name: &str,
) -> Option<crate::pass::resolve::TopLevelDeclaration<'m, EvalPhase>> {
    let mut found = None;
    for item in &module.items {
        crate::pass::resolve::for_each_item_declaration(item, |declaration| {
            if declaration
                .newtype()
                .is_some_and(|newtype| newtype.name == name)
                || declaration
                    .type_alias()
                    .is_some_and(|alias| alias.name == name)
            {
                found = Some(declaration);
            }
        });
        if found.is_some() {
            break;
        }
    }
    found
}

fn resolve_nominal_newtype<'m>(
    identity_aliases: &crate::pass::resolve::IdentityAliasNewtypeIndex,
    package: Option<&'m EvalPackage>,
    source_owner: &'m Module<EvalPhase>,
    source: crate::pass::resolve::TopLevelDeclaration<'m, EvalPhase>,
) -> Option<(&'m Module<EvalPhase>, &'m Newtype<EvalPhase>)> {
    if let Some(newtype) = source.newtype() {
        return Some((source_owner, newtype));
    }
    let alias = source.type_alias()?;
    let source_module_path = module_path_string(source_owner);
    let target =
        identity_aliases.target(source_owner, package, &source_module_path, &alias.name)?;
    let owner = if target.module_path == source_module_path {
        source_owner
    } else {
        &package?.module(&target.module_path)?.module
    };
    Some((owner, target.newtype))
}

fn compile_eval_fn_ref<'m>(
    function_ref: EvalFnRef<'m>,
    state: &mut EvalCompileState<'_, 'm>,
) -> Option<EvalRef<EvalFunction>> {
    compile_eval_fn_body(function_ref.def, Some(function_ref.owner), state)
}

fn compile_eval_fn_def<'m>(
    def: &'m FnDef<EvalPhase>,
    state: &mut EvalCompileState<'_, 'm>,
) -> Option<EvalRef<EvalFunction>> {
    compile_eval_fn_body(def, state.module, state)
}

fn compile_eval_fn_body<'m>(
    def: &'m FnDef<EvalPhase>,
    owner: Option<&'m Module<EvalPhase>>,
    state: &mut EvalCompileState<'_, 'm>,
) -> Option<EvalRef<EvalFunction>> {
    let module_path = owner
        .map(module_path_string)
        .unwrap_or_else(|| state.module_path.clone());
    let owner_module_path: Arc<str> = module_path.clone().into();
    let cache_key = eval_function_cache_key_for_def(def, &module_path, &state.source_generation);
    if let Some(cached) = state.cached_eval_function(&cache_key) {
        return Some(cached);
    }
    if state.fn_stack.contains(&cache_key) {
        return None;
    }
    state.fn_stack.push(cache_key.clone());
    let (params, value_groups, abi_arity) = collect_value_param_layout(&def.sig);
    let param_names = eval_param_names(&params);
    let mut nested = EvalCompileState {
        ctx: state.ctx,
        module: owner,
        module_path,
        label_scope: Some(def.name.clone()),
        locals: param_names,
        type_binders: def
            .sig
            .params
            .iter()
            .filter_map(|param| match param {
                SignatureParam::Type(param) => Some((param.name.clone(), param.effective_kind())),
                SignatureParam::Value(_) => None,
            })
            .collect(),
        fn_stack: state.fn_stack.clone(),
        source_generation: state.source_generation.clone(),
        local_eval_function_cache: state.local_eval_function_cache,
        share_fn_closures: state.share_fn_closures,
    };
    state.fn_stack.pop();
    let body = compile_eval_expr(&def.body, &mut nested)?;
    let label = state
        .ctx
        .metrics
        .as_ref()
        .map(|_| eval_function_label(def, owner, &state.module_path));
    let simple_body = is_simple_handler_expr(&body);
    let memo_candidate = !simple_body && is_memo_candidate_expr(&body);
    let function = EvalRef::new(EvalFunction {
        cache_key: cache_key.clone(),
        label,
        owner_module_path,
        source_origin: EvalFunctionOrigin::Named {
            item: def.name.clone().into(),
        },
        params,
        value_groups,
        abi_arity,
        simple_body,
        memo_candidate,
        body,
        diagnostic_body: EvalRef::new(def.body.clone()),
    });
    state.cache_eval_function(cache_key, function.clone());
    Some(function)
}

fn eval_function_label(
    def: &FnDef<EvalPhase>,
    owner: Option<&Module<EvalPhase>>,
    fallback_module_path: &str,
) -> Arc<str> {
    let module_path = owner
        .map(module_path_string)
        .unwrap_or_else(|| fallback_module_path.to_string());
    format!("{module_path}::{}", def.name).into()
}

fn compile_core_intrinsic_call(
    callee: &EvalAstExpr,
    args: &[EvalAstCallArg],
    state: &mut EvalCompileState<'_, '_>,
) -> Option<EvalExpr> {
    let Expr::Path { segments, .. } = callee else {
        return None;
    };
    let [name] = segments.as_slice() else {
        return None;
    };
    let runtime_arity = match name.as_str() {
        "__left__" | "__right__" | "__fst__" | "__snd__" => 1,
        "__pair__" => 2,
        "__if_then_else__" | "__either__" => 3,
        _ => return None,
    };
    omitted_value_args_are_obvious(args, runtime_arity, state)?;
    match name.as_str() {
        "__left__" | "__right__" => Some(EvalExpr::CoreCtor {
            name: if name.as_str() == "__left__" {
                "__left__"
            } else {
                "__right__"
            },
            args: vec![compile_eval_expr(trailing_value_arg1(args)?, state)?],
        }),
        "__pair__" => {
            let (left, right) = trailing_value_arg2(args)?;
            Some(EvalExpr::CoreCtor {
                name: "__pair__",
                args: vec![
                    compile_eval_expr(left, state)?,
                    compile_eval_expr(right, state)?,
                ],
            })
        }
        "__fst__" | "__snd__" => Some(EvalExpr::CoreProj {
            name: if name.as_str() == "__fst__" {
                "__fst__"
            } else {
                "__snd__"
            },
            pair: compile_eval_expr(trailing_value_arg1(args)?, state)?,
        }),
        "__if_then_else__" => {
            let (condition, then_thunk, else_thunk) = trailing_value_arg3(args)?;
            let condition = compile_eval_expr(condition, state)?;
            let then_thunk = compile_eval_expr(then_thunk, state)?;
            let else_thunk = compile_eval_expr(else_thunk, state)?;
            if !is_obvious_eval_value(&then_thunk) || !is_obvious_eval_value(&else_thunk) {
                return None;
            }
            Some(EvalExpr::CoreIf {
                condition,
                then_thunk,
                else_thunk,
            })
        }
        "__either__" => {
            let (scrutinee, left, right) = trailing_value_arg3(args)?;
            let scrutinee = compile_eval_expr(scrutinee, state)?;
            let left = compile_eval_expr(left, state)?;
            let right = compile_eval_expr(right, state)?;
            if !is_obvious_eval_value(&left) || !is_obvious_eval_value(&right) {
                return None;
            }
            Some(EvalExpr::CoreEither {
                scrutinee,
                left,
                right,
            })
        }
        _ => None,
    }
}

fn compile_direct_path_call(
    callee: &EvalAstExpr,
    args: &[EvalAstCallArg],
    call_span: Span,
    state: &mut EvalCompileState<'_, '_>,
) -> Option<Option<EvalExpr>> {
    let Expr::Path { segments, .. } = callee else {
        return None;
    };
    if let Some(member) = state
        .module
        .and_then(|module| resolve_module_newtype_member(state.ctx, module, segments))
    {
        return Some(compile_direct_newtype_call(member, args, state));
    }
    match segments.as_slice() {
        [head] => {
            let name = head.as_str();
            if state
                .locals
                .iter()
                .rposition(|local| local == name)
                .is_some()
            {
                return None;
            }
            if let Some(function_ref) = state
                .module
                .and_then(|module| resolve_module_fn(state.ctx, module, name))
            {
                let def = function_ref.def;
                let args = compile_value_arg_exprs_for_fn_def(def, args, state)?;
                return Some(Some(
                    if let Some(function) = compile_eval_fn_ref(function_ref, state) {
                        compile_direct_eval_fn_call(function, args)
                    } else {
                        EvalExpr::CallAtom {
                            name: name.to_string(),
                            args,
                        }
                    },
                ));
            }
            if let Some(def) = state.ctx.fn_defs.get(name).copied() {
                let args = compile_value_arg_exprs_for_fn_def(def, args, state)?;
                return Some(Some(
                    if let Some(function) = compile_eval_fn_def(def, state) {
                        compile_direct_eval_fn_call(function, args)
                    } else {
                        EvalExpr::CallAtom {
                            name: name.to_string(),
                            args,
                        }
                    },
                ));
            }
            compile_direct_atom_call(name.to_string(), args, call_span, state).map(Some)
        }
        [alias, name] => {
            if let Some(function_ref) = state.module.and_then(|module| {
                resolve_qualified_module_fn(state.ctx, module, alias.as_str(), name.as_str())
            }) {
                let def = function_ref.def;
                let args = compile_value_arg_exprs_for_fn_def(def, args, state)?;
                return Some(Some(
                    if let Some(function) = compile_eval_fn_ref(function_ref, state) {
                        compile_direct_eval_fn_call(function, args)
                    } else {
                        EvalExpr::CallAtom {
                            name: format!("{}.{}", alias.as_str(), name.as_str()),
                            args,
                        }
                    },
                ));
            }
            if let Some(def) = state
                .ctx
                .qualified_fn_defs
                .get(&(alias.as_str(), name.as_str()))
                .copied()
            {
                let args = compile_value_arg_exprs_for_fn_def(def, args, state)?;
                return Some(Some(
                    if let Some(function) = compile_eval_fn_def(def, state) {
                        compile_direct_eval_fn_call(function, args)
                    } else {
                        EvalExpr::CallAtom {
                            name: format!("{}.{}", alias.as_str(), name.as_str()),
                            args,
                        }
                    },
                ));
            }
            compile_direct_atom_call(
                format!("{}.{}", alias.as_str(), name.as_str()),
                args,
                call_span,
                state,
            )
            .map(Some)
        }
        _ => compile_direct_atom_call(
            segments
                .iter()
                .map(|segment| segment.as_str())
                .collect::<Vec<_>>()
                .join("."),
            args,
            call_span,
            state,
        )
        .map(Some),
    }
}

fn compile_direct_newtype_call(
    member: Arc<ResolvedNewtypeMemberValue>,
    args: &[EvalAstCallArg],
    state: &mut EvalCompileState<'_, '_>,
) -> Option<EvalExpr> {
    let mut values = compile_value_arg_exprs_without_fn(args, zero_span(), state)?;
    match member.kind {
        NewtypeMemberKind::Constructor { payload_abi_arity } => {
            let payload_start = if payload_abi_arity == 0 {
                values.len()
            } else if values.len() == 1 {
                0
            } else {
                values.len().checked_sub(payload_abi_arity)?
            };
            if values[..payload_start]
                .iter()
                .any(|value| !is_obvious_eval_value(value))
            {
                return Some(EvalExpr::Call {
                    callee: EvalRef::new(EvalExpr::NewtypeMember(member)),
                    args: values,
                });
            }
            let payload_values = values.split_off(payload_start);
            let payload = match payload_values.as_slice() {
                [] => EvalRef::new(EvalExpr::Unit),
                [value] => value.clone(),
                _ => right_fold_product_eval_exprs(payload_values),
            };
            Some(EvalExpr::NewtypeCtor {
                member,
                value: payload,
            })
        }
        NewtypeMemberKind::Projector => {
            let value = values.pop()?;
            if values.iter().any(|value| !is_obvious_eval_value(value)) {
                values.push(value);
                return Some(EvalExpr::Call {
                    callee: EvalRef::new(EvalExpr::NewtypeMember(member)),
                    args: values,
                });
            }
            Some(EvalExpr::NewtypeProj { member, value })
        }
    }
}

fn compile_direct_eval_fn_call(
    function: EvalRef<EvalFunction>,
    args: Vec<EvalRef<EvalExpr>>,
) -> EvalExpr {
    // These rewrites may reorder, duplicate, or omit evaluation of an actual.
    // They are therefore legal only for expressions that already denote a
    // value. Calls and constructors remain on the ordinary CBV path.
    if args.iter().any(|arg| !is_obvious_eval_value(arg)) {
        return EvalExpr::CallFn { function, args };
    }
    if args.len() == function.abi_arity()
        && let Some((condition_slot, then_slot, else_slot)) = core_if_thunk_layout(&function)
        && let (Some(condition), Some(then_thunk), Some(else_thunk)) = (
            args.get(condition_slot).cloned(),
            args.get(then_slot).cloned(),
            args.get(else_slot).cloned(),
        )
    {
        return EvalExpr::CoreIf {
            condition,
            then_thunk,
            else_thunk,
        };
    }
    if args.len() == function.abi_arity()
        && let Some((scrutinee_slot, left_slot, right_slot)) = core_either_thunk_layout(&function)
        && let (Some(scrutinee), Some(left_thunk), Some(right_thunk)) = (
            args.get(scrutinee_slot).cloned(),
            args.get(left_slot).cloned(),
            args.get(right_slot).cloned(),
        )
    {
        return EvalExpr::CoreEitherThunk {
            scrutinee,
            left_thunk,
            right_thunk,
        };
    }
    if let Some(inlined) = inline_small_eval_function_call(&function, &args) {
        return inlined;
    }
    EvalExpr::CallFn { function, args }
}

fn inline_small_eval_function_call(
    function: &EvalFunction,
    args: &[EvalRef<EvalExpr>],
) -> Option<EvalExpr> {
    let mut budget = 32;
    inline_small_eval_function_call_with_budget(function, args, &mut budget)
}

fn inline_small_eval_function_call_with_budget(
    function: &EvalFunction,
    args: &[EvalRef<EvalExpr>],
    budget: &mut usize,
) -> Option<EvalExpr> {
    if args.iter().any(|arg| !is_obvious_eval_value(arg)) {
        return None;
    }
    let (source_args, consumed) = bind_eval_function_expr_args(function, args)?;
    if consumed != args.len() {
        return None;
    }
    inline_small_eval_expr(&function.body, &source_args, function.param_count(), budget)
}

fn is_obvious_eval_value(expr: &EvalExpr) -> bool {
    matches!(
        expr,
        EvalExpr::Unit
            | EvalExpr::Bool(_)
            | EvalExpr::IntAtom(_, _)
            | EvalExpr::FloatAtom(_, _)
            | EvalExpr::StrAtom(_)
            | EvalExpr::DiagnosticText(_)
            | EvalExpr::Primitive(_)
            | EvalExpr::StructuralRecurPrimitive(_)
            // The sole compiler-produced Const is the inert result of the
            // reflected-type constant fold. Keep that invariant explicit
            // instead of making arbitrary precomputed Values eligible for
            // erasing rewrites.
            | EvalExpr::Const(Value::ReflType(_))
            | EvalExpr::Local(_)
            | EvalExpr::Atom(_)
            | EvalExpr::FnRef { .. }
            | EvalExpr::FnExpr { .. }
            | EvalExpr::NewtypeMember(_)
    )
}

fn omitted_value_args_are_obvious(
    args: &[EvalAstCallArg],
    runtime_arity: usize,
    state: &mut EvalCompileState<'_, '_>,
) -> Option<()> {
    let omitted_count = value_arg_count(args).checked_sub(runtime_arity)?;
    for omitted in args.iter().filter_map(value_arg_expr).take(omitted_count) {
        let omitted = compile_eval_expr(omitted, state)?;
        if !is_obvious_eval_value(&omitted) {
            return None;
        }
    }
    Some(())
}

fn inline_small_eval_args(
    call_args: &[EvalRef<EvalExpr>],
    fn_args: &[EvalRef<EvalExpr>],
    param_count: usize,
    budget: &mut usize,
) -> Option<Vec<EvalRef<EvalExpr>>> {
    call_args
        .iter()
        .map(|arg| inline_small_eval_expr(arg, fn_args, param_count, budget).map(EvalRef::new))
        .collect()
}

fn inline_small_eval_expr(
    expr: &EvalExpr,
    fn_args: &[EvalRef<EvalExpr>],
    param_count: usize,
    budget: &mut usize,
) -> Option<EvalExpr> {
    *budget = budget.checked_sub(1)?;
    match expr {
        EvalExpr::Unit => Some(EvalExpr::Unit),
        EvalExpr::Bool(value) => Some(EvalExpr::Bool(*value)),
        EvalExpr::IntAtom(digits, annotation) => {
            Some(EvalExpr::IntAtom(digits.clone(), annotation.clone()))
        }
        EvalExpr::FloatAtom(digits, annotation) => {
            Some(EvalExpr::FloatAtom(digits.clone(), annotation.clone()))
        }
        EvalExpr::StrAtom(value) => Some(EvalExpr::StrAtom(value.clone())),
        EvalExpr::DiagnosticText(value) => Some(EvalExpr::DiagnosticText(value.clone())),
        EvalExpr::Primitive(builtin) => Some(EvalExpr::Primitive(*builtin)),
        EvalExpr::StructuralRecurPrimitive(site) => {
            Some(EvalExpr::StructuralRecurPrimitive(site.clone()))
        }
        EvalExpr::NewtypeMember(member) => Some(EvalExpr::NewtypeMember(member.clone())),
        EvalExpr::Const(value @ Value::ReflType(_)) => Some(EvalExpr::Const(value.clone())),
        EvalExpr::Const(_) => None,
        EvalExpr::Local(slot) if *slot < param_count => Some(fn_args[*slot].as_ref().clone()),
        EvalExpr::Local(_) => None,
        EvalExpr::Atom(name) => Some(EvalExpr::Atom(name.clone())),
        EvalExpr::CallAtom { name, args } => Some(EvalExpr::CallAtom {
            name: name.clone(),
            args: inline_small_eval_args(args, fn_args, param_count, budget)?,
        }),
        EvalExpr::CallPrimitive { builtin, args } => Some(EvalExpr::CallPrimitive {
            builtin: *builtin,
            args: inline_small_eval_args(args, fn_args, param_count, budget)?,
        }),
        EvalExpr::ProofedReflection {
            builtin,
            proof,
            direct,
        } => {
            let proof = EvalRef::new(inline_small_eval_expr(proof, fn_args, param_count, budget)?);
            if !is_obvious_eval_value(&proof) {
                return None;
            }
            Some(EvalExpr::ProofedReflection {
                builtin: *builtin,
                proof,
                direct: EvalRef::new(inline_small_eval_expr(
                    direct,
                    fn_args,
                    param_count,
                    budget,
                )?),
            })
        }
        EvalExpr::CallFn { function, args } => {
            let args = inline_small_eval_args(args, fn_args, param_count, budget)?;
            inline_small_eval_function_call_with_budget(function, &args, budget)
        }
        EvalExpr::CallFnExpr {
            function,
            captured_slots,
            args,
        } if captured_slots.is_empty() => {
            let args = inline_small_eval_args(args, fn_args, param_count, budget)?;
            inline_small_eval_function_call_with_budget(function, &args, budget)
        }
        EvalExpr::NewtypeCtor { member, value } => Some(EvalExpr::NewtypeCtor {
            member: member.clone(),
            value: EvalRef::new(inline_small_eval_expr(value, fn_args, param_count, budget)?),
        }),
        EvalExpr::NewtypeProj { member, value } => Some(EvalExpr::NewtypeProj {
            member: member.clone(),
            value: EvalRef::new(inline_small_eval_expr(value, fn_args, param_count, budget)?),
        }),
        EvalExpr::CoreCtor { name, args } => Some(EvalExpr::CoreCtor {
            name,
            args: inline_small_eval_args(args, fn_args, param_count, budget)?,
        }),
        EvalExpr::CoreProj { name, pair } => Some(EvalExpr::CoreProj {
            name,
            pair: EvalRef::new(inline_small_eval_expr(pair, fn_args, param_count, budget)?),
        }),
        EvalExpr::ReflTypeUnit => Some(EvalExpr::ReflTypeUnit),
        EvalExpr::ReflTypeBottom => Some(EvalExpr::ReflTypeBottom),
        EvalExpr::ReflTypeProduct { left, right } => Some(EvalExpr::ReflTypeProduct {
            left: EvalRef::new(inline_small_eval_expr(left, fn_args, param_count, budget)?),
            right: EvalRef::new(inline_small_eval_expr(right, fn_args, param_count, budget)?),
        }),
        EvalExpr::ReflTypeSum { left, right } => Some(EvalExpr::ReflTypeSum {
            left: EvalRef::new(inline_small_eval_expr(left, fn_args, param_count, budget)?),
            right: EvalRef::new(inline_small_eval_expr(right, fn_args, param_count, budget)?),
        }),
        EvalExpr::ReflTypeView { typ } => Some(EvalExpr::ReflTypeView {
            typ: EvalRef::new(inline_small_eval_expr(typ, fn_args, param_count, budget)?),
        }),
        EvalExpr::ReflTypeEqual { left, right } => Some(EvalExpr::ReflTypeEqual {
            left: EvalRef::new(inline_small_eval_expr(left, fn_args, param_count, budget)?),
            right: EvalRef::new(inline_small_eval_expr(right, fn_args, param_count, budget)?),
        }),
        EvalExpr::ReflTypeNameEqual { left, right } => Some(EvalExpr::ReflTypeNameEqual {
            left: EvalRef::new(inline_small_eval_expr(left, fn_args, param_count, budget)?),
            right: EvalRef::new(inline_small_eval_expr(right, fn_args, param_count, budget)?),
        }),
        EvalExpr::ReflTypeVarEqual { left, right } => Some(EvalExpr::ReflTypeVarEqual {
            left: EvalRef::new(inline_small_eval_expr(left, fn_args, param_count, budget)?),
            right: EvalRef::new(inline_small_eval_expr(right, fn_args, param_count, budget)?),
        }),
        EvalExpr::ReflTypeArityEqual { left, right } => Some(EvalExpr::ReflTypeArityEqual {
            left: EvalRef::new(inline_small_eval_expr(left, fn_args, param_count, budget)?),
            right: EvalRef::new(inline_small_eval_expr(right, fn_args, param_count, budget)?),
        }),
        EvalExpr::ReflTypeInstantiate { scheme, arg } => Some(EvalExpr::ReflTypeInstantiate {
            scheme: EvalRef::new(inline_small_eval_expr(
                scheme,
                fn_args,
                param_count,
                budget,
            )?),
            arg: EvalRef::new(inline_small_eval_expr(arg, fn_args, param_count, budget)?),
        }),
        EvalExpr::ReflTypeRootPredicate { name, typ } => Some(EvalExpr::ReflTypeRootPredicate {
            name,
            typ: EvalRef::new(inline_small_eval_expr(typ, fn_args, param_count, budget)?),
        }),
        EvalExpr::ReflTypeFold {
            name,
            typ,
            init,
            step,
        } => {
            let step = EvalRef::new(inline_small_eval_expr(step, fn_args, param_count, budget)?);
            if !is_obvious_eval_value(&step) {
                return None;
            }
            Some(EvalExpr::ReflTypeFold {
                name,
                typ: EvalRef::new(inline_small_eval_expr(typ, fn_args, param_count, budget)?),
                init: EvalRef::new(inline_small_eval_expr(init, fn_args, param_count, budget)?),
                step,
            })
        }
        EvalExpr::ReflTermType { term } => Some(EvalExpr::ReflTermType {
            term: EvalRef::new(inline_small_eval_expr(term, fn_args, param_count, budget)?),
        }),
        EvalExpr::ReflTermUnit => Some(EvalExpr::ReflTermUnit),
        EvalExpr::ReflTermCall {
            fn_type,
            fn_value,
            arg_packet,
        } => Some(EvalExpr::ReflTermCall {
            fn_type: EvalRef::new(inline_small_eval_expr(
                fn_type,
                fn_args,
                param_count,
                budget,
            )?),
            fn_value: EvalRef::new(inline_small_eval_expr(
                fn_value,
                fn_args,
                param_count,
                budget,
            )?),
            arg_packet: EvalRef::new(inline_small_eval_expr(
                arg_packet,
                fn_args,
                param_count,
                budget,
            )?),
        }),
        EvalExpr::ReflTermTypeApp { fn_value, arg } => Some(EvalExpr::ReflTermTypeApp {
            fn_value: EvalRef::new(inline_small_eval_expr(
                fn_value,
                fn_args,
                param_count,
                budget,
            )?),
            arg: EvalRef::new(inline_small_eval_expr(arg, fn_args, param_count, budget)?),
        }),
        EvalExpr::ReflIntrinsicPair { left, right } => Some(EvalExpr::ReflIntrinsicPair {
            left: EvalRef::new(inline_small_eval_expr(left, fn_args, param_count, budget)?),
            right: EvalRef::new(inline_small_eval_expr(right, fn_args, param_count, budget)?),
        }),
        EvalExpr::ReflIntrinsicProjection {
            name,
            product_type,
            value,
        } => Some(EvalExpr::ReflIntrinsicProjection {
            name,
            product_type: EvalRef::new(inline_small_eval_expr(
                product_type,
                fn_args,
                param_count,
                budget,
            )?),
            value: EvalRef::new(inline_small_eval_expr(value, fn_args, param_count, budget)?),
        }),
        EvalExpr::ReflIntrinsicInjection {
            name,
            sum_type,
            value,
        } => Some(EvalExpr::ReflIntrinsicInjection {
            name,
            sum_type: EvalRef::new(inline_small_eval_expr(
                sum_type,
                fn_args,
                param_count,
                budget,
            )?),
            value: EvalRef::new(inline_small_eval_expr(value, fn_args, param_count, budget)?),
        }),
        EvalExpr::ReflIntrinsicAbsurd {
            bottom_value,
            result_type,
        } => Some(EvalExpr::ReflIntrinsicAbsurd {
            bottom_value: EvalRef::new(inline_small_eval_expr(
                bottom_value,
                fn_args,
                param_count,
                budget,
            )?),
            result_type: EvalRef::new(inline_small_eval_expr(
                result_type,
                fn_args,
                param_count,
                budget,
            )?),
        }),
        EvalExpr::FnRef { .. }
        | EvalExpr::FnExpr { .. }
        | EvalExpr::Let { .. }
        | EvalExpr::Seq { .. }
        | EvalExpr::Call { .. }
        | EvalExpr::CallFnExpr { .. }
        | EvalExpr::CoreIf { .. }
        | EvalExpr::CoreEither { .. }
        | EvalExpr::CoreEitherThunk { .. }
        | EvalExpr::ReflTermLet { .. }
        | EvalExpr::ReflTermFn { .. }
        | EvalExpr::ReflTermTypeFn { .. }
        | EvalExpr::ReflIntrinsicEither { .. }
        | EvalExpr::ReflIntrinsicIfThenElse { .. } => None,
    }
}

fn core_if_thunk_layout(function: &EvalFunction) -> Option<(usize, usize, usize)> {
    if !function.params_are_abi_identity() || function.param_count() != 3 {
        return None;
    }
    let EvalExpr::CoreIf {
        condition,
        then_thunk,
        else_thunk,
    } = function.body.as_ref()
    else {
        return None;
    };
    let condition_slot = local_slot(condition)?;
    let then_slot = local_slot(then_thunk)?;
    let else_slot = local_slot(else_thunk)?;
    let param_count = function.param_count();
    if condition_slot >= param_count || then_slot >= param_count || else_slot >= param_count {
        return None;
    }
    Some((condition_slot, then_slot, else_slot))
}

fn core_either_thunk_layout(function: &EvalFunction) -> Option<(usize, usize, usize)> {
    if !function.params_are_abi_identity() || function.param_count() != 3 {
        return None;
    }
    let EvalExpr::CoreEither {
        scrutinee,
        left,
        right,
    } = function.body.as_ref()
    else {
        return None;
    };
    let scrutinee_slot = local_slot(scrutinee)?;
    let left_slot = core_either_thunk_branch_slot(left)?;
    let right_slot = core_either_thunk_branch_slot(right)?;
    let param_count = function.param_count();
    if scrutinee_slot >= param_count || left_slot >= param_count || right_slot >= param_count {
        return None;
    }
    Some((scrutinee_slot, left_slot, right_slot))
}

fn local_slot(expr: &EvalExpr) -> Option<usize> {
    match expr {
        EvalExpr::Local(slot) => Some(*slot),
        _ => None,
    }
}

fn core_either_thunk_branch_slot(handler: &EvalExpr) -> Option<usize> {
    let EvalExpr::FnExpr {
        function,
        captured_slots,
        ..
    } = handler
    else {
        return None;
    };
    let [captured_slot] = captured_slots.as_ref() else {
        return None;
    };
    if !function.params_are_abi_identity() || function.param_count() != 1 {
        return None;
    }
    match function.body.as_ref() {
        EvalExpr::Call { callee, args }
            if args.is_empty() && matches!(callee.as_ref(), EvalExpr::Local(0)) =>
        {
            Some(*captured_slot)
        }
        _ => None,
    }
}

fn compile_direct_atom_call(
    name: String,
    args: &[EvalAstCallArg],
    call_span: Span,
    state: &mut EvalCompileState<'_, '_>,
) -> Option<EvalExpr> {
    if let Some(builtin) = state
        .ctx
        .primitive_env
        .resolve(&state.module_path, name.as_str())
        && builtin.is_value_name()
    {
        if builtin == ComptimeBuiltin::StructuralRecur {
            return None;
        }
        if let Some(direct) = compile_direct_comptime_call(builtin, args, state) {
            return Some(direct);
        }
        return Some(EvalExpr::CallPrimitive {
            builtin,
            args: compile_value_arg_exprs_without_fn(args, call_span, state)?,
        });
    }
    let args = compile_value_arg_exprs_without_fn(args, call_span, state)?;
    Some(EvalExpr::CallAtom { name, args })
}

fn compile_direct_comptime_call(
    builtin: ComptimeBuiltin,
    args: &[EvalAstCallArg],
    state: &mut EvalCompileState<'_, '_>,
) -> Option<EvalExpr> {
    let runtime_arity = direct_comptime_runtime_arity(builtin)?;
    omitted_value_args_are_obvious(args, runtime_arity, state)?;
    #[cfg(feature = "surface")]
    let proof = if projected_capable_direct_runtime_arity(builtin)
        .is_some_and(|arity| value_arg_count(args) == arity + 1)
    {
        let proof = args.iter().find_map(|arg| match arg {
            CallArg::Value(value) => Some(value),
            CallArg::Type(_) => None,
        })?;
        Some(compile_eval_expr(proof, state)?)
    } else {
        None
    };
    #[cfg(not(feature = "surface"))]
    let proof: Option<EvalRef<EvalExpr>> = None;
    let name = builtin.public_name();
    let direct = match name {
        "__type_unit__" if value_arg_count(args) <= 1 => Some(EvalExpr::ReflTypeUnit),
        "__type_bottom__" if value_arg_count(args) <= 1 => Some(EvalExpr::ReflTypeBottom),
        "__type_product__" => {
            let (left, right) = trailing_value_arg2(args)?;
            Some(EvalExpr::ReflTypeProduct {
                left: compile_eval_expr(left, state)?,
                right: compile_eval_expr(right, state)?,
            })
        }
        "__type_sum__" => {
            let (left, right) = trailing_value_arg2(args)?;
            Some(EvalExpr::ReflTypeSum {
                left: compile_eval_expr(left, state)?,
                right: compile_eval_expr(right, state)?,
            })
        }
        "__type_view__" => Some(EvalExpr::ReflTypeView {
            typ: compile_eval_expr(trailing_value_arg1(args)?, state)?,
        }),
        "__type_equal__" => {
            let (left, right) = trailing_value_arg2(args)?;
            Some(EvalExpr::ReflTypeEqual {
                left: compile_eval_expr(left, state)?,
                right: compile_eval_expr(right, state)?,
            })
        }
        "__type_name_equal__" => {
            let (left, right) = trailing_value_arg2(args)?;
            Some(EvalExpr::ReflTypeNameEqual {
                left: compile_eval_expr(left, state)?,
                right: compile_eval_expr(right, state)?,
            })
        }
        "__type_var_equal__" => {
            let (left, right) = trailing_value_arg2(args)?;
            Some(EvalExpr::ReflTypeVarEqual {
                left: compile_eval_expr(left, state)?,
                right: compile_eval_expr(right, state)?,
            })
        }
        "__type_arity_equal__" => {
            let (left, right) = trailing_value_arg2(args)?;
            Some(EvalExpr::ReflTypeArityEqual {
                left: compile_eval_expr(left, state)?,
                right: compile_eval_expr(right, state)?,
            })
        }
        "__type_instantiate__" => {
            let (scheme, arg) = trailing_value_arg2(args)?;
            Some(EvalExpr::ReflTypeInstantiate {
                scheme: compile_eval_expr(scheme, state)?,
                arg: compile_eval_expr(arg, state)?,
            })
        }
        "__type_is_product_root__" | "__type_is_sum_root__" => {
            Some(EvalExpr::ReflTypeRootPredicate {
                name: if name == "__type_is_product_root__" {
                    "__type_is_product_root__"
                } else {
                    "__type_is_sum_root__"
                },
                typ: compile_eval_expr(trailing_value_arg1(args)?, state)?,
            })
        }
        "__type_product_spine_fold__"
        | "__type_sum_spine_fold__"
        | "__type_args_fold__"
        | "__type_function_params_fold__" => {
            let (typ, init, step) = trailing_value_arg3(args)?;
            let typ = compile_eval_expr(typ, state)?;
            let init = compile_eval_expr(init, state)?;
            let step = compile_eval_expr(step, state)?;
            if !is_obvious_eval_value(&step) {
                return None;
            }
            Some(EvalExpr::ReflTypeFold {
                name: match name {
                    "__type_product_spine_fold__" => "__type_product_spine_fold__",
                    "__type_sum_spine_fold__" => "__type_sum_spine_fold__",
                    "__type_args_fold__" => "__type_args_fold__",
                    _ => "__type_function_params_fold__",
                },
                typ,
                init,
                step,
            })
        }
        "__diagnostic_concat__" => {
            let (left, right) = trailing_value_arg2(args)?;
            Some(EvalExpr::CallPrimitive {
                builtin: ComptimeBuiltin::DiagnosticConcat,
                args: vec![
                    compile_diagnostic_text_expr(left, state)?,
                    compile_diagnostic_text_expr(right, state)?,
                ],
            })
        }
        "__elab_error__" => Some(EvalExpr::CallPrimitive {
            builtin: ComptimeBuiltin::ElabError,
            args: vec![compile_diagnostic_text_expr(
                trailing_value_arg1(args)?,
                state,
            )?],
        }),
        "__type_error__" => Some(EvalExpr::CallPrimitive {
            builtin: ComptimeBuiltin::TypeError,
            args: vec![compile_diagnostic_text_expr(
                trailing_value_arg1(args)?,
                state,
            )?],
        }),
        "__term_type__" => Some(EvalExpr::ReflTermType {
            term: compile_eval_expr(trailing_value_arg1(args)?, state)?,
        }),
        "__term_unit__" if value_arg_count(args) <= 1 => Some(EvalExpr::ReflTermUnit),
        "__term_let__" => {
            let (value_type, value, body) = trailing_value_arg3(args)?;
            let value_type = compile_eval_expr(value_type, state)?;
            let value = compile_eval_expr(value, state)?;
            let body = compile_eval_expr(body, state)?;
            if !is_obvious_eval_value(&body) {
                return None;
            }
            Some(EvalExpr::ReflTermLet {
                value_type,
                value,
                body,
            })
        }
        "__term_fn__" => {
            let (fn_type, body) = trailing_value_arg2(args)?;
            let fn_type = compile_eval_expr(fn_type, state)?;
            let body = compile_eval_expr(body, state)?;
            if !is_obvious_eval_value(&body) {
                return None;
            }
            Some(EvalExpr::ReflTermFn { fn_type, body })
        }
        "__term_call__" => {
            let (fn_type, fn_value, arg_packet) = trailing_value_arg3(args)?;
            Some(EvalExpr::ReflTermCall {
                fn_type: compile_eval_expr(fn_type, state)?,
                fn_value: compile_eval_expr(fn_value, state)?,
                arg_packet: compile_eval_expr(arg_packet, state)?,
            })
        }
        "__term_type_fn__" => {
            let (arity, body) = trailing_value_arg2(args)?;
            let arity = compile_eval_expr(arity, state)?;
            let body = compile_eval_expr(body, state)?;
            if !is_obvious_eval_value(&body) {
                return None;
            }
            Some(EvalExpr::ReflTermTypeFn { arity, body })
        }
        "__term_type_app__" => {
            let (fn_value, arg) = trailing_value_arg2(args)?;
            Some(EvalExpr::ReflTermTypeApp {
                fn_value: compile_eval_expr(fn_value, state)?,
                arg: compile_eval_expr(arg, state)?,
            })
        }
        "__intrinsic_pair__" => {
            let (left, right) = trailing_value_arg2(args)?;
            Some(EvalExpr::ReflIntrinsicPair {
                left: compile_eval_expr(left, state)?,
                right: compile_eval_expr(right, state)?,
            })
        }
        "__intrinsic_fst__" | "__intrinsic_snd__" => {
            let (product_type, value) = trailing_value_arg2(args)?;
            Some(EvalExpr::ReflIntrinsicProjection {
                name: if name == "__intrinsic_fst__" {
                    "__intrinsic_fst__"
                } else {
                    "__intrinsic_snd__"
                },
                product_type: compile_eval_expr(product_type, state)?,
                value: compile_eval_expr(value, state)?,
            })
        }
        "__intrinsic_left__" | "__intrinsic_right__" => {
            let (sum_type, value) = trailing_value_arg2(args)?;
            Some(EvalExpr::ReflIntrinsicInjection {
                name: if name == "__intrinsic_left__" {
                    "__intrinsic_left__"
                } else {
                    "__intrinsic_right__"
                },
                sum_type: compile_eval_expr(sum_type, state)?,
                value: compile_eval_expr(value, state)?,
            })
        }
        "__intrinsic_either__" => {
            let (sum_type, result_type, value, on_left, on_right) = trailing_value_arg5(args)?;
            let sum_type = compile_eval_expr(sum_type, state)?;
            let result_type = compile_eval_expr(result_type, state)?;
            let value = compile_eval_expr(value, state)?;
            let on_left = compile_eval_expr(on_left, state)?;
            let on_right = compile_eval_expr(on_right, state)?;
            if !is_obvious_eval_value(&on_left) || !is_obvious_eval_value(&on_right) {
                return None;
            }
            Some(EvalExpr::ReflIntrinsicEither {
                sum_type,
                result_type,
                value,
                on_left,
                on_right,
            })
        }
        "__intrinsic_absurd__" => {
            let (bottom_value, result_type) = trailing_value_arg2(args)?;
            Some(EvalExpr::ReflIntrinsicAbsurd {
                bottom_value: compile_eval_expr(bottom_value, state)?,
                result_type: compile_eval_expr(result_type, state)?,
            })
        }
        "__intrinsic_if_then_else__" => {
            let (result_type, condition, on_true, on_false) = trailing_value_arg4(args)?;
            let result_type = compile_eval_expr(result_type, state)?;
            let condition = compile_eval_expr(condition, state)?;
            let on_true = compile_eval_expr(on_true, state)?;
            let on_false = compile_eval_expr(on_false, state)?;
            if !is_obvious_eval_value(&on_true) || !is_obvious_eval_value(&on_false) {
                return None;
            }
            Some(EvalExpr::ReflIntrinsicIfThenElse {
                result_type,
                condition,
                on_true,
                on_false,
            })
        }
        _ => None,
    }?;
    Some(match proof {
        Some(proof) => EvalExpr::ProofedReflection {
            builtin,
            proof,
            direct: EvalRef::new(direct),
        },
        None => direct,
    })
}

fn direct_comptime_runtime_arity(builtin: ComptimeBuiltin) -> Option<usize> {
    use ComptimeBuiltin::*;
    Some(match builtin {
        TypeUnit | TypeBottom | TermUnit => 0,
        TypeView | TypeIsProductRoot | TypeIsSumRoot | ElabError | TypeError | TermType => 1,
        TypeProduct | TypeSum | TypeEqual | TypeNameEqual | TypeVarEqual | TypeArityEqual
        | TypeInstantiate | DiagnosticConcat | TermFn | TermTypeFn | TermTypeApp
        | IntrinsicPair | IntrinsicFst | IntrinsicSnd | IntrinsicLeft | IntrinsicRight
        | IntrinsicAbsurd => 2,
        TypeProductSpineFold
        | TypeSumSpineFold
        | TypeArgsFold
        | TypeFunctionParamsFold
        | TermLet
        | TermCall => 3,
        IntrinsicIfThenElse => 4,
        IntrinsicEither => 5,
        _ => return None,
    })
}

#[cfg(feature = "surface")]
fn projected_capable_direct_runtime_arity(builtin: ComptimeBuiltin) -> Option<usize> {
    use ComptimeBuiltin::*;
    Some(match builtin {
        TypeProduct | TypeSum | TypeEqual | TypeInstantiate | TermFn | TermTypeFn | TermTypeApp
        | IntrinsicPair | IntrinsicFst | IntrinsicSnd | IntrinsicLeft | IntrinsicRight
        | IntrinsicAbsurd => 2,
        TypeView | TypeIsProductRoot | TypeIsSumRoot | TermType => 1,
        TypeProductSpineFold
        | TypeSumSpineFold
        | TypeArgsFold
        | TypeFunctionParamsFold
        | TermLet
        | TermCall => 3,
        IntrinsicIfThenElse => 4,
        IntrinsicEither => 5,
        _ => return None,
    })
}

fn compile_value_arg_exprs_for_fn_def(
    def: &FnDef<EvalPhase>,
    args: &[EvalAstCallArg],
    state: &mut EvalCompileState<'_, '_>,
) -> Option<Vec<EvalRef<EvalExpr>>> {
    let value_param_count = def.sig.value_param_count();
    let type_param_count = def.sig.params.len() - value_param_count;
    let value_param_types: Vec<Option<EvalAstType>> = def
        .sig
        .params
        .iter()
        .filter_map(|param| match param {
            SignatureParam::Type(_) => None,
            SignatureParam::Value(param) => param.ty.as_ref(),
        })
        .map(|ty| Some(convert_type::<EvalPhase, EvalPhase>(ty)))
        .collect();
    let all_value_args = args.iter().all(|a| matches!(a, CallArg::Value(_)));
    if type_param_count > 0 && all_value_args && args.len() == value_param_count {
        return args
            .iter()
            .enumerate()
            .filter_map(|(index, arg)| match arg {
                CallArg::Value(v) => Some(compile_eval_expr_against(
                    v,
                    value_param_types.get(index).and_then(Option::as_ref),
                    state,
                )),
                CallArg::Type(_) => None,
            })
            .collect();
    }
    let mut out = Vec::new();
    let mut sig_iter = def.sig.params.iter();
    for arg in args {
        match sig_iter.next() {
            Some(SignatureParam::Type(_)) => continue,
            Some(SignatureParam::Value(param)) => {
                if let CallArg::Value(v) = arg {
                    let expected = param.ty.as_ref().map(convert_type::<EvalPhase, EvalPhase>);
                    out.push(compile_eval_expr_against(v, expected.as_ref(), state)?);
                }
            }
            None => {
                if let CallArg::Value(v) = arg {
                    out.push(compile_eval_expr(v, state)?);
                }
            }
        }
    }
    Some(out)
}

fn compile_value_arg_exprs_without_fn(
    args: &[EvalAstCallArg],
    _call_span: Span,
    state: &mut EvalCompileState<'_, '_>,
) -> Option<Vec<EvalRef<EvalExpr>>> {
    args.iter()
        .filter_map(|arg| match arg {
            CallArg::Value(v) => Some(compile_eval_expr(v, state)),
            CallArg::Type(_) => None,
        })
        .collect()
}

fn right_fold_product_eval_exprs(mut values: Vec<EvalRef<EvalExpr>>) -> EvalRef<EvalExpr> {
    match values.len() {
        0 => EvalRef::new(EvalExpr::Unit),
        1 => values.pop().expect("len checked"),
        _ => {
            let first = values.remove(0);
            let rest = right_fold_product_eval_exprs(values);
            EvalRef::new(EvalExpr::CoreCtor {
                name: "__pair__",
                args: vec![first, rest],
            })
        }
    }
}

fn resolve_module_fn<'m>(
    ctx: &EvalCtx<'m>,
    module: &'m Module<EvalPhase>,
    name: &str,
) -> Option<EvalFnRef<'m>> {
    let module_key = module as *const Module<EvalPhase> as usize;
    let mut indexes = ctx
        .module_fn_index
        .lock()
        .expect("eval module function index lock poisoned");
    let index = indexes
        .entry(module_key)
        .or_insert_with(|| build_module_fn_index(ctx.package, module));
    index
        .own
        .get(name)
        .copied()
        .or_else(|| index.selective.get(name).copied())
}

fn resolve_qualified_module_fn<'m>(
    ctx: &EvalCtx<'m>,
    module: &'m Module<EvalPhase>,
    alias: &str,
    name: &str,
) -> Option<EvalFnRef<'m>> {
    let module_key = module as *const Module<EvalPhase> as usize;
    let mut indexes = ctx
        .module_fn_index
        .lock()
        .expect("eval module function index lock poisoned");
    let index = indexes
        .entry(module_key)
        .or_insert_with(|| build_module_fn_index(ctx.package, module));
    index.qualified.get(&(alias, name)).copied()
}

fn build_module_fn_index<'m>(
    package: Option<&'m EvalPackage>,
    module: &'m Module<EvalPhase>,
) -> ModuleFnIndex<'m> {
    let mut index = ModuleFnIndex {
        own: HashMap::new(),
        selective: HashMap::new(),
        qualified: HashMap::new(),
    };
    for item in &module.items {
        if let Item::FnDef(def) = item {
            index
                .own
                .insert(def.name.as_str(), EvalFnRef { def, owner: module });
        }
    }
    let Some(package) = package else {
        return index;
    };
    for u in &module.imports {
        match &u.kind {
            ImportKind::Selective { items, from } => {
                let Some(target) = package.module(&module_import_path(from)) else {
                    continue;
                };
                for name in items.iter().filter_map(crate::ast::ImportItem::as_name) {
                    if let Some(def) = find_module_fn(&target.module, name) {
                        index.selective.insert(
                            name,
                            EvalFnRef {
                                def,
                                owner: &target.module,
                            },
                        );
                    }
                }
            }
            ImportKind::Qualified { path, alias, .. } => {
                let Some(target) = package.module(&module_import_path(path)) else {
                    continue;
                };
                for item in &target.module.items {
                    if let Item::FnDef(def) = item
                        && crate::pass::resolve::is_visible(&def.vis, &module.path)
                    {
                        index.qualified.insert(
                            (alias.as_str(), def.name.as_str()),
                            EvalFnRef {
                                def,
                                owner: &target.module,
                            },
                        );
                    }
                }
            }
            ImportKind::Intrinsics | ImportKind::Comptime => {}
        }
    }
    index
}

fn find_module_fn<'m>(module: &'m Module<EvalPhase>, name: &str) -> Option<&'m FnDef<EvalPhase>> {
    module.items.iter().find_map(|item| match item {
        Item::FnDef(def) if def.name == name => Some(def),
        _ => None,
    })
}

fn module_path_string<P: crate::ast::Phase>(module: &Module<P>) -> String {
    module
        .path
        .segments
        .iter()
        .map(|s| s.as_str())
        .collect::<Vec<_>>()
        .join("/")
}

// Joins with `/` to match the package module map's keys (a module's
// canonical path is `/`-separated). A `.` separator coincides for
// single-segment imports but misses every multi-segment path, e.g. a
// dependency module re-rooted under `<local>/…`.
fn module_import_path(path: &ModulePath) -> String {
    path.segments
        .iter()
        .map(|s| s.as_str())
        .collect::<Vec<_>>()
        .join("/")
}

mod execution;

fn eval_compiled_expr(expr: &EvalExpr, slots: &mut EvalSlots<'_>, ctx: &EvalCtx<'_>) -> Value {
    execution::eval(expr, slots, ctx)
}

fn try_apply_simple_compiled_handler(
    function: &EvalFunction,
    captured_slots: &[usize],
    args: &[Value],
    slots: &EvalSlots<'_>,
) -> Option<Value> {
    if !function.simple_body {
        return None;
    }
    let mut budget = 16;
    eval_simple_handler_expr(&function.body, captured_slots, args, slots, &mut budget)
}

fn is_simple_handler_expr(expr: &EvalExpr) -> bool {
    let mut budget = 16;
    is_simple_handler_expr_inner(expr, &mut budget)
}

fn is_memo_candidate_expr(expr: &EvalExpr) -> bool {
    let mut budget = 128;
    is_memo_candidate_expr_inner(expr, &mut budget)
}

fn is_memo_candidate_expr_inner(expr: &EvalExpr, budget: &mut usize) -> bool {
    let Some(next_budget) = budget.checked_sub(1) else {
        return true;
    };
    *budget = next_budget;
    match expr {
        EvalExpr::Call { .. }
        | EvalExpr::CallAtom { .. }
        | EvalExpr::CallPrimitive { .. }
        | EvalExpr::ProofedReflection { .. }
        | EvalExpr::CallFn { .. }
        | EvalExpr::CallFnExpr { .. }
        | EvalExpr::ReflTypeView { .. }
        | EvalExpr::ReflTypeEqual { .. }
        | EvalExpr::ReflTypeNameEqual { .. }
        | EvalExpr::ReflTypeVarEqual { .. }
        | EvalExpr::ReflTypeArityEqual { .. }
        | EvalExpr::ReflTypeInstantiate { .. }
        | EvalExpr::ReflTypeRootPredicate { .. }
        | EvalExpr::ReflTypeFold { .. }
        | EvalExpr::ReflTermType { .. }
        | EvalExpr::ReflTermLet { .. }
        | EvalExpr::ReflTermFn { .. }
        | EvalExpr::ReflTermCall { .. }
        | EvalExpr::ReflTermTypeFn { .. }
        | EvalExpr::ReflTermTypeApp { .. }
        | EvalExpr::ReflIntrinsicProjection { .. }
        | EvalExpr::ReflIntrinsicInjection { .. }
        | EvalExpr::ReflIntrinsicEither { .. }
        | EvalExpr::ReflIntrinsicAbsurd { .. }
        | EvalExpr::ReflIntrinsicIfThenElse { .. } => true,
        EvalExpr::Let { value, body } | EvalExpr::Seq { value, body } => {
            is_memo_candidate_expr_inner(value, budget)
                || is_memo_candidate_expr_inner(body, budget)
        }
        EvalExpr::NewtypeCtor { value, .. } | EvalExpr::NewtypeProj { value, .. } => {
            is_memo_candidate_expr_inner(value, budget)
        }
        EvalExpr::CoreCtor { args, .. } => args
            .iter()
            .any(|arg| is_memo_candidate_expr_inner(arg, budget)),
        EvalExpr::CoreProj { pair, .. } => is_memo_candidate_expr_inner(pair, budget),
        EvalExpr::CoreIf {
            condition,
            then_thunk,
            else_thunk,
        } => {
            is_memo_candidate_expr_inner(condition, budget)
                || is_memo_candidate_expr_inner(then_thunk, budget)
                || is_memo_candidate_expr_inner(else_thunk, budget)
        }
        EvalExpr::CoreEither {
            scrutinee,
            left,
            right,
        } => {
            is_memo_candidate_expr_inner(scrutinee, budget)
                || is_memo_candidate_expr_inner(left, budget)
                || is_memo_candidate_expr_inner(right, budget)
        }
        EvalExpr::CoreEitherThunk {
            scrutinee,
            left_thunk,
            right_thunk,
        } => {
            is_memo_candidate_expr_inner(scrutinee, budget)
                || is_memo_candidate_expr_inner(left_thunk, budget)
                || is_memo_candidate_expr_inner(right_thunk, budget)
        }
        EvalExpr::ReflTypeProduct { left, right } | EvalExpr::ReflTypeSum { left, right } => {
            is_memo_candidate_expr_inner(left, budget)
                || is_memo_candidate_expr_inner(right, budget)
        }
        EvalExpr::ReflTypeUnit
        | EvalExpr::ReflTypeBottom
        | EvalExpr::ReflTermUnit
        | EvalExpr::ReflIntrinsicPair { .. }
        | EvalExpr::Unit
        | EvalExpr::Bool(_)
        | EvalExpr::IntAtom(_, _)
        | EvalExpr::FloatAtom(_, _)
        | EvalExpr::StrAtom(_)
        | EvalExpr::DiagnosticText(_)
        | EvalExpr::Primitive(_)
        | EvalExpr::StructuralRecurPrimitive(_)
        | EvalExpr::NewtypeMember(_)
        | EvalExpr::Const(_)
        | EvalExpr::Local(_)
        | EvalExpr::Atom(_)
        | EvalExpr::FnRef { .. }
        | EvalExpr::FnExpr { .. } => false,
    }
}

fn is_simple_handler_expr_inner(expr: &EvalExpr, budget: &mut usize) -> bool {
    let Some(next_budget) = budget.checked_sub(1) else {
        return false;
    };
    *budget = next_budget;
    match expr {
        EvalExpr::Unit
        | EvalExpr::Bool(_)
        | EvalExpr::IntAtom(_, _)
        | EvalExpr::FloatAtom(_, _)
        | EvalExpr::StrAtom(_)
        | EvalExpr::DiagnosticText(_)
        | EvalExpr::Primitive(_)
        | EvalExpr::StructuralRecurPrimitive(_)
        | EvalExpr::NewtypeMember(_)
        | EvalExpr::Const(_)
        | EvalExpr::Local(_) => true,
        EvalExpr::NewtypeCtor { value, .. } => is_simple_handler_expr_inner(value, budget),
        EvalExpr::NewtypeProj { value, .. } => is_simple_handler_expr_inner(value, budget),
        EvalExpr::CoreCtor { args, .. } => args
            .iter()
            .all(|arg| is_simple_handler_expr_inner(arg, budget)),
        EvalExpr::CoreProj { pair, .. } => is_simple_handler_expr_inner(pair, budget),
        _ => false,
    }
}

fn eval_simple_handler_expr(
    expr: &EvalExpr,
    captured_slots: &[usize],
    args: &[Value],
    slots: &EvalSlots<'_>,
    budget: &mut usize,
) -> Option<Value> {
    *budget = budget.checked_sub(1)?;
    match expr {
        EvalExpr::Unit => Some(Value::Unit),
        EvalExpr::Bool(value) => Some(Value::Bool(*value)),
        EvalExpr::IntAtom(digits, annotation) => {
            Some(Value::IntAtom(digits.clone(), annotation.clone()))
        }
        EvalExpr::FloatAtom(digits, annotation) => {
            Some(Value::FloatAtom(digits.clone(), annotation.clone()))
        }
        EvalExpr::StrAtom(value) => Some(Value::StrAtom(value.clone())),
        EvalExpr::DiagnosticText(value) => Some(Value::DiagnosticText(value.clone())),
        EvalExpr::Primitive(builtin) => Some(Value::Primitive(*builtin)),
        EvalExpr::StructuralRecurPrimitive(primitive) => Some(Value::Data(primitive.clone())),
        EvalExpr::Const(value) => Some(value.clone()),
        EvalExpr::Local(slot) => simple_handler_local(*slot, captured_slots, args, slots),
        EvalExpr::NewtypeCtor { member, value } => Some(newtype_data_value(
            member,
            vec![eval_simple_handler_expr(
                value,
                captured_slots,
                args,
                slots,
                budget,
            )?],
        )),
        EvalExpr::NewtypeProj { member, value } => {
            let value = eval_simple_handler_expr(value, captured_slots, args, slots, budget)?;
            if let Value::Data(data) = &value
                && data.has_newtype_constructor(&member.constructor)
                && let Some(payload) = data.args().last()
            {
                return Some(payload.clone());
            }
            Some(Value::Stuck(
                EvalRef::new(Value::NewtypeMember(member.clone())),
                vec![value].into(),
            ))
        }
        EvalExpr::CoreCtor { name, args: parts } => {
            let values = parts
                .iter()
                .map(|part| eval_simple_handler_expr(part, captured_slots, args, slots, budget))
                .collect::<Option<Vec<_>>>()?;
            Some(data_value(*name, values))
        }
        EvalExpr::CoreProj { name, pair } => {
            let pair = eval_simple_handler_expr(pair, captured_slots, args, slots, budget)?;
            if let Value::Data(data) = &pair
                && data.ctor() == "__pair__"
                && data.args().len() == 2
            {
                return Some(if *name == "__fst__" {
                    data.args()[0].clone()
                } else {
                    data.args()[1].clone()
                });
            }
            Some(Value::Stuck(
                EvalRef::new(Value::Atom((*name).to_string())),
                vec![pair].into(),
            ))
        }
        _ => None,
    }
}

fn simple_handler_local(
    slot: usize,
    captured_slots: &[usize],
    args: &[Value],
    slots: &EvalSlots<'_>,
) -> Option<Value> {
    if slot < captured_slots.len() {
        slots.get(captured_slots[slot]).cloned()
    } else {
        args.get(slot - captured_slots.len()).cloned()
    }
}

fn direct_reflection_start(ctx: &EvalCtx<'_>) -> Option<Instant> {
    ctx.metrics.as_deref().map(|_| Instant::now())
}

fn record_direct_reflection_success(name: &str, ctx: &EvalCtx<'_>, start: Option<Instant>) {
    if let (Some(metrics), Some(start)) = (ctx.metrics.as_deref(), start) {
        metrics.record_reflection_name(name, start.elapsed());
    }
}

fn primitive_value(name: &str) -> Value {
    Value::Primitive(
        ComptimeBuiltin::from_public_name(name)
            .expect("direct compile-time operation has a registered primitive"),
    )
}

fn finish_direct_reflection(
    name: &str,
    result: Option<Value>,
    args: Vec<Value>,
    ctx: &EvalCtx<'_>,
    start: Option<Instant>,
) -> Value {
    if let Some(value) = result {
        record_direct_reflection_success(name, ctx, start);
        value
    } else {
        Value::Stuck(EvalRef::new(primitive_value(name)), args.into())
    }
}

fn value_arg_expr<P: crate::ast::Phase>(arg: &CallArg<P>) -> Option<&Expr<P>> {
    match arg {
        CallArg::Value(expr) => Some(expr),
        CallArg::Type(_) => None,
    }
}

type FourValueArgs<'a, P> = (&'a Expr<P>, &'a Expr<P>, &'a Expr<P>, &'a Expr<P>);

type FiveValueArgs<'a, P> = (
    &'a Expr<P>,
    &'a Expr<P>,
    &'a Expr<P>,
    &'a Expr<P>,
    &'a Expr<P>,
);

fn value_arg_count<P: crate::ast::Phase>(args: &[CallArg<P>]) -> usize {
    args.iter().filter_map(value_arg_expr).count()
}

fn trailing_value_arg1<P: crate::ast::Phase>(args: &[CallArg<P>]) -> Option<&Expr<P>> {
    args.iter().rev().find_map(value_arg_expr)
}

fn trailing_value_arg2<P: crate::ast::Phase>(args: &[CallArg<P>]) -> Option<(&Expr<P>, &Expr<P>)> {
    let mut values = args.iter().rev().filter_map(value_arg_expr);
    let second = values.next()?;
    let first = values.next()?;
    Some((first, second))
}

fn trailing_value_arg3<P: crate::ast::Phase>(
    args: &[CallArg<P>],
) -> Option<(&Expr<P>, &Expr<P>, &Expr<P>)> {
    let mut values = args.iter().rev().filter_map(value_arg_expr);
    let third = values.next()?;
    let second = values.next()?;
    let first = values.next()?;
    Some((first, second, third))
}

fn trailing_value_arg4<P: crate::ast::Phase>(args: &[CallArg<P>]) -> Option<FourValueArgs<'_, P>> {
    let mut values = args.iter().rev().filter_map(value_arg_expr);
    let fourth = values.next()?;
    let third = values.next()?;
    let second = values.next()?;
    let first = values.next()?;
    Some((first, second, third, fourth))
}

fn trailing_value_arg5<P: crate::ast::Phase>(args: &[CallArg<P>]) -> Option<FiveValueArgs<'_, P>> {
    let mut values = args.iter().rev().filter_map(value_arg_expr);
    let fifth = values.next()?;
    let fourth = values.next()?;
    let third = values.next()?;
    let second = values.next()?;
    let first = values.next()?;
    Some((first, second, third, fourth, fifth))
}

/// Monotonic source of fresh payload-atom names for symbolic
/// case-splits. The names need only be *distinct* — [`nf_eq`]'s
/// `CaseSplit` arm renames them consistently across the two compared
/// values (the same fresh-binder discipline closures use), so the raw
/// numeric value never leaks into an equivalence verdict.
static CASE_SPLIT_FRESH: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);

fn fresh_case_split_payload(tag: &str) -> String {
    let n = CASE_SPLIT_FRESH.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    format!("__case_{tag}_n{n}__")
}

/// The *value* arity of a structural-constructor intrinsic — how many
/// trailing value-args form the constructed payload (the leading args
/// are erased type-args). `None` for every non-constructor name
/// (eliminators, `__if_then_else__`, `__absurd__`, host atoms): those
/// are not constructors and don't build [`Value::Data`].
fn intrinsic_ctor_value_arity(name: &str) -> Option<usize> {
    match name {
        "__left__" | "__right__" => Some(1),
        "__pair__" => Some(2),
        _ => None,
    }
}

/// The *value* arity of a structural-eliminator intrinsic — how many
/// trailing value-args are the real operands (scrutinee + handlers, or
/// the single projection target, or condition + thunks), the leading
/// args being erased type-args. Like constructors, eliminators have no
/// fn-def signature for the call compiler to filter against, so a
/// call written with explicit type-args — `__either__(A, B, C, s, fl,
/// fr)` — reaches `apply` with the three leading type-name atoms still
/// present. (The real `kio test` path usually strips them upstream via
/// the typer's value-at-type-slot markers; a raw `eval` over an
/// explicitly-type-applied intrinsic, e.g. a unit test, does not.) The
/// ι-rule arms below match a rigid operand slice (`[scrutinee, fl, fr]`,
/// `[pair]`), which only fits once the type-args are dropped. `None` for
/// every non-eliminator name.
fn intrinsic_elim_value_arity(name: &str) -> Option<usize> {
    match name {
        "__either__" => Some(3),
        "__fst__" | "__snd__" => Some(1),
        "__if_then_else__" => Some(3),
        _ => None,
    }
}

fn grouped_reflected_type_arg(args: &[EvalAstCallArg]) -> Option<EvalAstType> {
    match args {
        [CallArg::Type(ty)] => Some(ty.clone()),
        [CallArg::Value(value)] => crate::pass::typecheck_core::expr_to_type_arg(value).ok(),
        _ => None,
    }
}

fn compile_reflect_type_call(
    callee: &EvalAstExpr,
    args: &[EvalAstCallArg],
    state: &mut EvalCompileState<'_, '_>,
) -> Option<EvalExpr> {
    let authorized = |callee: &EvalAstExpr| {
        let Expr::Path { segments, .. } = callee else {
            return false;
        };
        let [name] = segments.as_slice() else {
            return false;
        };
        state
            .ctx
            .primitive_env
            .resolve(&state.module_path, name.as_str())
            == Some(ComptimeBuiltin::ReflectType)
    };
    let (proof, ty) = if authorized(callee) {
        match args {
            [CallArg::Value(proof), CallArg::Type(ty)] => (proof, ty.clone()),
            _ => return None,
        }
    } else if let Expr::Call {
        callee: proof_callee,
        args: proof_args,
        ..
    } = callee
        && authorized(proof_callee)
        && matches!(proof_args.as_slice(), [CallArg::Value(_)])
    {
        let [CallArg::Value(proof)] = proof_args.as_slice() else {
            return None;
        };
        (proof, grouped_reflected_type_arg(args)?)
    } else {
        return None;
    };
    let proof = compile_eval_expr(proof, state)?;
    let ty = state
        .module
        .map(|owner| qualify_explicit_reflected_paths(&ty, owner, &state.type_binders))
        .unwrap_or(ty);
    let reflected = ReflectedType::new(ty, "`_` cannot be reflected at compile time")
        .ok()
        .map(Value::ReflType)?;
    let reflected = EvalExpr::Const(reflected);
    if is_obvious_eval_value(&proof) {
        Some(reflected)
    } else {
        // ReflectType's type operand is erased from runtime argument packets,
        // so declining this fold would lose information. Evaluate a computed
        // proof exactly once before returning the reflected constant instead.
        Some(EvalExpr::Let {
            value: proof,
            body: EvalRef::new(reflected),
        })
    }
}

fn zero_span() -> Span {
    Span::new(0, 0)
}

fn zero_meta() -> Meta<EvalPhase> {
    Meta::new(zero_span())
}

fn path_expr(name: &str) -> Expr<EvalPhase> {
    let span = zero_span();
    Expr::Path {
        occurrence: Default::default(),
        segments: vec![PathSegment::new(name.to_string(), span)],
        meta: Meta::new(span),
        ext: (),
    }
}

fn type_path(name: &str) -> Type<EvalPhase> {
    Type::synth_path(vec![name.to_string()], Vec::new(), zero_span())
}

fn intrinsic_expr(name: &str, args: Vec<CallArg<EvalPhase>>) -> Expr<EvalPhase> {
    crate::pass::typecheck_core::intrinsic_call(name, args, zero_span())
}

fn diagnostic_value(v: &Value) -> Option<String> {
    match v {
        Value::DiagnosticText(s) => Some(s.clone()),
        _ => None,
    }
}

fn canonical_refl_type(v: &Value, ctx: &EvalCtx<'_>) -> Option<Type<EvalPhase>> {
    let Value::ReflType(reflected) = v else {
        return None;
    };
    let _ = ctx;
    Some(type_traversal::clone_type(reflected.as_type()))
}

fn qualify_explicit_reflected_paths(
    ty: &Type<EvalPhase>,
    owner: &Module<EvalPhase>,
    binders: &HashMap<String, crate::ast::Kind>,
) -> Type<EvalPhase> {
    match ty {
        Type::Path {
            segments,
            args,
            meta,
        } => {
            let segments =
                crate::pass::resolve::qualify_type_segments_in_module(segments, owner, binders);
            let args = args
                .iter()
                .map(|arg| qualify_explicit_reflected_paths(arg, owner, binders))
                .collect();
            Type::synth_path_segments(segments, args, meta.span)
        }
        Type::Function {
            param,
            ret,
            meta,
            abi_arity,
            caps,
        } => Type::Function {
            param: Box::new(qualify_explicit_reflected_paths(param, owner, binders)),
            ret: Box::new(qualify_explicit_reflected_paths(ret, owner, binders)),
            meta: meta.clone(),
            abi_arity: *abi_arity,
            caps: *caps,
        },
        Type::Product { left, right, meta } => Type::Product {
            left: Box::new(qualify_explicit_reflected_paths(left, owner, binders)),
            right: Box::new(qualify_explicit_reflected_paths(right, owner, binders)),
            meta: meta.clone(),
        },
        Type::Sum { left, right, meta } => Type::Sum {
            left: Box::new(qualify_explicit_reflected_paths(left, owner, binders)),
            right: Box::new(qualify_explicit_reflected_paths(right, owner, binders)),
            meta: meta.clone(),
        },
        Type::Forall { param, body, meta } => {
            let mut nested_binders = binders.clone();
            nested_binders.insert(param.name.clone(), param.effective_kind());
            Type::Forall {
                param: param.clone(),
                body: Box::new(qualify_explicit_reflected_paths(
                    body,
                    owner,
                    &nested_binders,
                )),
                meta: meta.clone(),
            }
        }
        Type::Unit { .. } | Type::Bottom { .. } | Type::Infer { .. } => ty.clone(),
        Type::LabelSugar { ext, .. } => match *ext {},
        Type::Goal { ext, .. } => match *ext {},
    }
}

fn as_refl_type_ref(v: &Value) -> Option<&Type<EvalPhase>> {
    match v {
        Value::ReflType(t) => Some(t.as_type()),
        _ => None,
    }
}

fn as_checked_term(v: &Value) -> Option<EvalRef<CheckedTerm>> {
    match v {
        Value::CheckedTerm(term) => Some(term.clone()),
        _ => None,
    }
}

fn as_checked_term_ref(v: &Value) -> Option<&CheckedTerm> {
    match v {
        Value::CheckedTerm(term) => Some(term.as_ref()),
        _ => None,
    }
}

fn into_checked_term(v: Value) -> Option<CheckedTerm> {
    match v {
        Value::CheckedTerm(term) => {
            Some(EvalRef::try_unwrap(term).unwrap_or_else(|term| (*term).clone()))
        }
        _ => None,
    }
}

fn as_refl_type_arity(v: &Value) -> Option<usize> {
    match v {
        Value::ReflTypeArity(n) => Some(*n),
        _ => None,
    }
}

fn value_pair(left: Value, right: Value) -> Value {
    data_value("__pair__", vec![left, right])
}

pub(crate) fn right_fold_product_values(mut values: Vec<Value>) -> Value {
    match values.len() {
        0 => Value::Unit,
        1 => values.pop().expect("len checked"),
        _ => {
            let first = values.remove(0);
            value_pair(first, right_fold_product_values(values))
        }
    }
}

fn value_pair3(a: Value, b: Value, c: Value) -> Value {
    value_pair(a, value_pair(b, c))
}

fn value_sum_inject(branch: usize, total: usize, payload: Value) -> Value {
    debug_assert!(branch < total);
    if total <= 1 {
        return payload;
    }
    if branch == 0 {
        data_value("__left__", vec![payload])
    } else {
        data_value(
            "__right__",
            vec![value_sum_inject(branch - 1, total - 1, payload)],
        )
    }
}

fn predicate_value(ok: bool) -> Value {
    Value::Bool(ok)
}

fn type_instantiate_ok(ty: Type<EvalPhase>) -> Value {
    value_sum_inject(0, 2, refl_type_value(ty))
}

fn type_instantiate_err(message: impl Into<String>) -> Value {
    value_sum_inject(1, 2, Value::DiagnosticText(message.into()))
}

fn type_instantiate_value(
    scheme: Type<EvalPhase>,
    arg: Type<EvalPhase>,
    ctx: &EvalCtx<'_>,
) -> Value {
    let unfolded = unfold_canonical_refl_type(&scheme, ctx);
    let Type::Forall { param, body, .. } = unfolded else {
        return type_instantiate_err(format!(
            "__type_instantiate__ expected a forall type, got `{}`",
            crate::pass::typecheck_core::display_type(&scheme)
        ));
    };
    if param.effective_kind().arity() > 0 && !matches!(arg, Type::Path { .. }) {
        return type_instantiate_err(format!(
            "__type_instantiate__ cannot substitute structural type `{}` for higher-kinded binder `{}`",
            crate::pass::typecheck_core::display_type(&arg),
            param.name
        ));
    }
    let subst = HashMap::from([(param.name, arg)]);
    type_instantiate_ok(subst_type(&body, &subst))
}

fn eval_refl_type_free_bare_heads(ty: &Type<EvalPhase>) -> HashSet<String> {
    enum Work<'a> {
        Type(&'a Type<EvalPhase>),
        LeaveBinder(&'a str),
    }

    let mut bound = HashMap::<&str, usize>::new();
    let mut free = HashSet::new();
    let mut pending = vec![Work::Type(ty)];
    while let Some(work) = pending.pop() {
        match work {
            Work::LeaveBinder(name) => {
                let remove = {
                    let count = bound
                        .get_mut(name)
                        .expect("a reflected binder was pushed before it was popped");
                    *count -= 1;
                    *count == 0
                };
                if remove {
                    bound.remove(name);
                }
            }
            Work::Type(ty) => match ty {
                Type::Path { segments, args, .. } => {
                    if let [name] = segments.as_slice()
                        && !bound.contains_key(name.as_str())
                    {
                        free.insert(name.name.clone());
                    }
                    pending.extend(args.iter().rev().map(Work::Type));
                }
                Type::Function { param, ret, .. } => {
                    pending.push(Work::Type(ret));
                    pending.push(Work::Type(param));
                }
                Type::Product { left, right, .. } | Type::Sum { left, right, .. } => {
                    pending.push(Work::Type(right));
                    pending.push(Work::Type(left));
                }
                Type::Forall { param, body, .. } => {
                    *bound.entry(param.name.as_str()).or_default() += 1;
                    pending.push(Work::LeaveBinder(param.name.as_str()));
                    pending.push(Work::Type(body));
                }
                Type::Unit { .. } | Type::Bottom { .. } => {}
                Type::Infer { .. } => unreachable!(
                    "compile-time reflected types are validated as inference-free before evaluation"
                ),
                Type::LabelSugar { ext, .. } => match *ext {},
                Type::Goal { ext, .. } => match *ext {},
            },
        }
    }
    free
}

fn compact_refl_type_display(ty: &Type<EvalPhase>, ctx: &EvalCtx<'_>) -> String {
    let Some(root) = ctx.root_module else {
        return crate::pass::typecheck_core::display_reflected_type(ty);
    };
    let compact = crate::pass::typecheck_core::compact_source_type_spelling_with_bound(
        ty,
        root,
        &eval_refl_type_free_bare_heads(ty),
    );
    crate::pass::typecheck_core::display_reflected_type(&compact)
}

fn expand_eval_canonical_alias_refs(ty: &Type<EvalPhase>, ctx: &EvalCtx<'_>) -> Type<EvalPhase> {
    // Evaluator types are validated canonical artifacts: nominal heads are
    // module-qualified before reflection, while a remaining free bare head is
    // a rigid occurrence. Preserve that phase authority explicitly so adding
    // a same-spelled alias to the root module cannot retarget an existing
    // reflected binder.
    let binders = eval_refl_type_free_bare_heads(ty);
    crate::pass::typecheck_core::materialize_aliases_in_scope(
        ty,
        ctx.root_module,
        ctx.package,
        Some(&binders),
        true,
    )
}

fn unfold_canonical_refl_type(ty: &Type<EvalPhase>, ctx: &EvalCtx<'_>) -> Type<EvalPhase> {
    let start = ctx.metrics.as_deref().map(|_| Instant::now());
    let out = expand_eval_canonical_alias_refs(ty, ctx);
    if let (Some(metrics), Some(start)) = (ctx.metrics.as_deref(), start) {
        metrics.record_type_unfold(start.elapsed());
    }
    out
}

fn canonical_refl_type_equiv(
    left: &Type<EvalPhase>,
    right: &Type<EvalPhase>,
    ctx: &EvalCtx<'_>,
) -> bool {
    if left == right {
        return true;
    }
    let start = ctx.metrics.as_deref().map(|_| Instant::now());
    let left = expand_eval_canonical_alias_refs(left, ctx);
    let right = expand_eval_canonical_alias_refs(right, ctx);
    let out = type_equiv_without_aliases(&left, &right);
    if let (Some(metrics), Some(start)) = (ctx.metrics.as_deref(), start) {
        metrics.record_type_equiv(start.elapsed());
    }
    out
}

fn type_equiv_without_aliases(left: &Type<EvalPhase>, right: &Type<EvalPhase>) -> bool {
    let local: HashMap<&str, crate::pass::typecheck_core::AliasDef<'_, EvalPhase>> = HashMap::new();
    let cross_module: HashMap<&str, crate::pass::typecheck_core::AliasDef<'_, EvalPhase>> =
        HashMap::new();
    let ctx = AliasCtx {
        local: &local,
        cross_module: &cross_module,
        type_interner: None,
        source_module: None,
        package: None,
        binder_locals: None,
    };
    type_equiv(left, right, &ctx)
}

fn type_arity_of_type(ty: &Type<EvalPhase>, ctx: &EvalCtx<'_>) -> usize {
    match unfold_canonical_refl_type(ty, ctx) {
        Type::Forall { param, .. } => param.effective_kind().arity(),
        _ => 0,
    }
}

fn product_spine(ty: &Type<EvalPhase>, ctx: &EvalCtx<'_>) -> Vec<Type<EvalPhase>> {
    match unfold_canonical_refl_type(ty, ctx) {
        Type::Product { left, right, .. } => {
            let mut out = vec![*left];
            out.extend(product_spine(&right, ctx));
            out
        }
        other => vec![other],
    }
}

fn sum_spine(ty: &Type<EvalPhase>, ctx: &EvalCtx<'_>) -> Vec<Type<EvalPhase>> {
    match unfold_canonical_refl_type(ty, ctx) {
        Type::Sum { left, right, .. } => {
            let mut out = vec![*left];
            out.extend(sum_spine(&right, ctx));
            out
        }
        other => vec![other],
    }
}

fn type_args(ty: &Type<EvalPhase>, ctx: &EvalCtx<'_>) -> Vec<Type<EvalPhase>> {
    match unfold_canonical_refl_type(ty, ctx) {
        Type::Path { args, .. } => args,
        _ => Vec::new(),
    }
}

fn split_canonical_function_params(
    ty: &Type<EvalPhase>,
    ctx: &EvalCtx<'_>,
) -> Option<(Vec<Type<EvalPhase>>, Type<EvalPhase>)> {
    let unfolded = unfold_canonical_refl_type(ty, ctx);
    let Type::Function {
        param,
        ret,
        abi_arity,
        ..
    } = unfolded
    else {
        return None;
    };
    if abi_arity == 0 {
        return Some((Vec::new(), *ret));
    }
    let params = split_product_prefix(&param, abi_arity, ctx)?;
    Some((params, *ret))
}

fn split_product_prefix(
    ty: &Type<EvalPhase>,
    n: usize,
    ctx: &EvalCtx<'_>,
) -> Option<Vec<Type<EvalPhase>>> {
    if n == 0 {
        return Some(Vec::new());
    }
    let mut out = Vec::with_capacity(n);
    let mut cur = ty.clone();
    for i in 0..n {
        if i + 1 == n {
            out.push(unfold_canonical_refl_type(&cur, ctx));
            return Some(out);
        }
        let unfolded = unfold_canonical_refl_type(&cur, ctx);
        match unfolded {
            Type::Product { left, right, .. } => {
                out.push(*left);
                cur = *right;
            }
            _ => return None,
        }
    }
    Some(out)
}

fn right_fold_product_type(types: &[Type<EvalPhase>]) -> Type<EvalPhase> {
    match types {
        [] => Type::Unit { meta: zero_meta() },
        [one] => one.clone(),
        [first, rest @ ..] => Type::Product {
            left: Box::new(first.clone()),
            right: Box::new(right_fold_product_type(rest)),
            meta: zero_meta(),
        },
    }
}

fn package_host_types<'m>(ctx: &EvalCtx<'m>) -> Vec<(&'m str, &'m HostType<EvalPhase>)> {
    // Host types are ordinary module declarations now; scan every
    // module in the package for `host type` items. Each is paired with
    // its declaring module path so a reflected (now module-qualified)
    // host-type reference matches by *identity*, not by bare name — two
    // structurally-identical host types from different modules (a
    // consumer's `String` and a dependency's re-rooted `String`) stay
    // distinct.
    let Some(package) = ctx.package else {
        return Vec::new();
    };
    let mut out = Vec::new();
    for (module_path, entry) in package.modules() {
        for item in &entry.module.items {
            if let Item::HostType(host_type) = item {
                out.push((module_path, host_type));
            }
        }
    }
    out
}

/// Whether a reflected type path `segments` denotes the host type
/// `name` declared in module `module_path`. The input is canonical before
/// this predicate runs, so host identity is the exact full path; a bare path
/// is a type variable rather than a same-leaf host-type fallback.
fn host_type_path_matches(segments: &[PathSegment], module_path: &str, name: &str) -> bool {
    let actual: Vec<&str> = segments.iter().map(|s| s.as_str()).collect();
    let mut expected: Vec<&str> = if module_path.is_empty() {
        Vec::new()
    } else {
        module_path.split('/').collect()
    };
    expected.push(name);
    actual == expected
}

/// Build the applied type `mod/.../Name(args)` of a host type, spelled
/// with its **declaring-module-qualified** head so it matches the
/// qualified host spelling reflection now produces for the value /
/// goal / source types. `host_module_path`
/// is the host type's declaring module (`""` for a package-root host type),
/// `/`-split into leading segments.
fn host_type_application(
    host_module_path: &str,
    host_type: &HostType<EvalPhase>,
    args: Vec<Type<EvalPhase>>,
) -> Type<EvalPhase> {
    let mut segments: Vec<String> = if host_module_path.is_empty() {
        Vec::new()
    } else {
        host_module_path.split('/').map(str::to_owned).collect()
    };
    segments.push(host_type.name.clone());
    Type::synth_path(segments, args, zero_span())
}

fn host_type_param_paths(host_type: &HostType<EvalPhase>) -> Vec<Type<EvalPhase>> {
    host_type
        .type_params
        .iter()
        .map(|param| type_path(&param.name))
        .collect()
}

fn host_converter_type(
    host_module_path: &str,
    host_type: &HostType<EvalPhase>,
    string_ty: Type<EvalPhase>,
) -> Type<EvalPhase> {
    let host_value_ty = host_type_application(
        host_module_path,
        host_type,
        host_type_param_paths(host_type),
    );
    let mut ty = Type::synth_function(vec![host_value_ty], string_ty, zero_span());
    for param in host_type.type_params.iter().rev() {
        ty = Type::Forall {
            param: TypeParam {
                name: param.name.clone(),
                span: zero_span(),
                kind: param.kind.clone(),
            },
            body: Box::new(ty),
            meta: zero_meta(),
        };
    }
    ty
}

fn source_mentions_host_type(
    ty: &Type<EvalPhase>,
    host_module_path: &str,
    host_type: &HostType<EvalPhase>,
    ctx: &EvalCtx<'_>,
) -> bool {
    match unfold_canonical_refl_type(ty, ctx) {
        Type::Product { left, right, .. } | Type::Sum { left, right, .. } => {
            source_mentions_host_type(&left, host_module_path, host_type, ctx)
                || source_mentions_host_type(&right, host_module_path, host_type, ctx)
        }
        Type::Path { segments, args, .. } => {
            host_type_path_matches(&segments, host_module_path, &host_type.name)
                && args.len() == host_type.type_params.len()
        }
        Type::Unit { .. }
        | Type::Bottom { .. }
        | Type::Function { .. }
        | Type::Forall { .. }
        | Type::LabelSugar { .. }
        | Type::Infer { .. } => false,
        Type::Goal { ext, .. } => match ext {},
    }
}

fn source_host_types<'m>(
    source_ty: &Type<EvalPhase>,
    ctx: &EvalCtx<'m>,
) -> Vec<(&'m str, &'m HostType<EvalPhase>)> {
    package_host_types(ctx)
        .into_iter()
        .filter(|(module_path, host_type)| {
            source_mentions_host_type(source_ty, module_path, host_type, ctx)
        })
        .collect()
}

fn host_converter_product_type(
    string_ty: Type<EvalPhase>,
    source_ty: &Type<EvalPhase>,
    ctx: &EvalCtx<'_>,
) -> Type<EvalPhase> {
    let converters: Vec<_> = source_host_types(source_ty, ctx)
        .into_iter()
        .map(|(module_path, host_type)| {
            host_converter_type(module_path, host_type, string_ty.clone())
        })
        .collect();
    right_fold_product_type(&converters)
}

/// A host-type match: the matched type's index in the candidate
/// slice, the matched [`HostType`] itself, and the reflected
/// type-arguments the matching `Type::Path` supplied.
type HostTypeMatch<'m> = (usize, &'m HostType<EvalPhase>, Vec<Type<EvalPhase>>);

fn match_host_type<'m>(
    ty: &Type<EvalPhase>,
    host_types: &[(&'m str, &'m HostType<EvalPhase>)],
    ctx: &EvalCtx<'_>,
) -> Option<HostTypeMatch<'m>> {
    let unfolded = unfold_canonical_refl_type(ty, ctx);
    let Type::Path { segments, args, .. } = unfolded else {
        return None;
    };
    host_types
        .iter()
        .copied()
        .enumerate()
        .find_map(|(index, (module_path, host_type))| {
            (host_type_path_matches(&segments, module_path, &host_type.name)
                && host_type.type_params.len() == args.len())
            .then_some((index, host_type, args.clone()))
        })
}

fn match_package_host_type<'m>(
    ty: &Type<EvalPhase>,
    ctx: &EvalCtx<'m>,
) -> Option<HostTypeMatch<'m>> {
    match_host_type(ty, &package_host_types(ctx), ctx)
}

fn checked_product_projection(
    intrinsic: &str,
    left_ty: Type<EvalPhase>,
    right_ty: Type<EvalPhase>,
    value: EvalRef<CheckedTerm>,
) -> EvalRef<CheckedTerm> {
    let result_ty = if intrinsic == "__fst__" {
        left_ty.clone()
    } else {
        right_ty.clone()
    };
    EvalRef::new(CheckedTerm::from_node(
        CheckedTermNode::IntrinsicProjection {
            intrinsic: intrinsic.to_owned(),
            left_ty,
            right_ty,
            value,
        },
        result_ty,
    ))
}

fn project_right_fold_product_slot(
    value: EvalRef<CheckedTerm>,
    slot_tys: &[Type<EvalPhase>],
    index: usize,
) -> Option<EvalRef<CheckedTerm>> {
    match slot_tys {
        [] => None,
        [_] => (index == 0).then_some(value),
        [first, rest @ ..] => {
            let rest_ty = right_fold_product_type(rest);
            if index == 0 {
                Some(checked_product_projection(
                    "__fst__",
                    first.clone(),
                    rest_ty,
                    value,
                ))
            } else {
                let snd = checked_product_projection("__snd__", first.clone(), rest_ty, value);
                project_right_fold_product_slot(snd, rest, index - 1)
            }
        }
    }
}

fn apply_host_converter_type_args(
    mut converter: EvalRef<CheckedTerm>,
    args: &[Type<EvalPhase>],
    ctx: &EvalCtx<'_>,
) -> Option<EvalRef<CheckedTerm>> {
    for arg in args {
        let Type::Forall { param, body, .. } = unfold_canonical_refl_type(converter.ty(), ctx)
        else {
            return None;
        };
        let result_ty = subst_type(&body, &HashMap::from([(param.name, arg.clone())]));
        converter = EvalRef::new(CheckedTerm::from_node(
            CheckedTermNode::TermTypeApp {
                fn_value: converter,
                arg: arg.clone(),
            },
            result_ty,
        ));
    }
    Some(converter)
}

fn reflection_term_host_convert_value(
    string_ty: &Value,
    source_ty: &Value,
    converters: &Value,
    value: &Value,
    ctx: &EvalCtx<'_>,
) -> Option<Value> {
    let string_ty = canonical_refl_type(string_ty, ctx)?;
    let source_ty = canonical_refl_type(source_ty, ctx)?;
    let converters = as_checked_term(converters)?;
    let value = as_checked_term(value)?;
    let host_types = source_host_types(&source_ty, ctx);
    let converter_tys: Vec<_> = host_types
        .iter()
        .copied()
        .map(|(module_path, host_type)| {
            host_converter_type(module_path, host_type, string_ty.clone())
        })
        .collect();
    let converter_product_ty = right_fold_product_type(&converter_tys);
    if !checked_type_equiv(&converters, &converter_product_ty, ctx) {
        return None;
    }
    let (index, host_type, args) = match_host_type(value.ty(), &host_types, ctx)?;
    let host_value_ty = host_type_application(host_types[index].0, host_type, args.clone());
    if !checked_type_equiv(&value, &host_value_ty, ctx) {
        return None;
    }
    let converter = project_right_fold_product_slot(converters, &converter_tys, index)?;
    let converter = apply_host_converter_type_args(converter, &args, ctx)?;
    let fn_ty = converter.clone_type();
    let (params, ret_ty) = split_canonical_function_params(&fn_ty, ctx)?;
    if params.len() != 1
        || !canonical_refl_type_equiv(&params[0], &host_value_ty, ctx)
        || !canonical_refl_type_equiv(&ret_ty, &string_ty, ctx)
    {
        return None;
    }
    Some(checked_term_node_value(
        CheckedTermNode::TermCall {
            fn_value: converter,
            params,
            arg_packet: value,
        },
        string_ty,
    ))
}

fn function_param_types(ty: &Type<EvalPhase>, ctx: &EvalCtx<'_>) -> Vec<Type<EvalPhase>> {
    // Owner-qualify host heads (through each alias's declaring module)
    // before splitting, so a param's host type stays consistent with the
    // goal under deep cross-package decomposition.
    let qualified = unfold_canonical_refl_type(ty, ctx);
    split_canonical_function_params(&qualified, ctx)
        .map(|(params, _)| params)
        .unwrap_or_default()
}

fn type_view_value(ty: &Type<EvalPhase>, ctx: &EvalCtx<'_>) -> Option<Value> {
    let key = TypeViewCacheKey {
        ty: TypeMemoKey::from_type(ty),
    };
    if let Some(cached) = ctx
        .type_view_cache
        .inner
        .lock()
        .expect("type-view cache lock poisoned")
        .get(&key)
        .cloned()
    {
        return cached;
    }
    let value = type_view_value_uncached(ty, ctx);
    ctx.type_view_cache
        .inner
        .lock()
        .expect("type-view cache lock poisoned")
        .insert(key, value.clone());
    value
}

fn type_view_value_uncached(ty: &Type<EvalPhase>, ctx: &EvalCtx<'_>) -> Option<Value> {
    // Qualify host-type heads before the view is destructured, so the
    // per-component `refl_type_value` recursions (and the leaf
    // `ReflTypeName`) carry the same self-identifying host spelling the
    // elaborator-call goal type does — keeping deep `derive!` subgoal
    // reflections consistent with the goal.
    let ty = unfold_canonical_refl_type(ty, ctx);
    Some(match ty {
        Type::Unit { .. } => value_sum_inject(0, 8, Value::Unit),
        Type::Bottom { .. } => value_sum_inject(1, 8, Value::Unit),
        Type::Product { left, right, .. } => value_sum_inject(
            2,
            8,
            value_pair(refl_type_value(*left), refl_type_value(*right)),
        ),
        Type::Sum { left, right, .. } => value_sum_inject(
            3,
            8,
            value_pair(refl_type_value(*left), refl_type_value(*right)),
        ),
        Type::Function {
            param,
            ret,
            abi_arity,
            ..
        } => value_sum_inject(
            4,
            8,
            value_pair3(
                refl_type_value(*param),
                Value::ReflTypeArity(abi_arity),
                refl_type_value(*ret),
            ),
        ),
        Type::Forall { param, body, .. } => {
            let arity = param.effective_kind().arity();
            value_sum_inject(
                5,
                8,
                value_pair3(
                    Value::ReflTypeVar {
                        name: param.name,
                        arity,
                    },
                    Value::ReflTypeArity(arity),
                    refl_type_value(*body),
                ),
            )
        }
        Type::Path { segments, args, .. } => value_sum_inject(
            7,
            8,
            Value::ReflTypeName {
                segments: segments.into_iter().map(|s| s.name).collect(),
                param_arities: args
                    .iter()
                    .map(|arg| type_arity_of_type(arg, ctx))
                    .collect(),
            },
        ),
        Type::LabelSugar { ext, .. } => match ext {},
        Type::Infer { .. } => return None,
        Type::Goal { ext, .. } => match ext {},
    })
}

#[cfg(feature = "surface")]
fn projected_type_view_value(
    view: crate::pass::typecheck_core::apply::fills::ProjectedTypeView,
) -> Value {
    use crate::pass::typecheck_core::apply::fills::ProjectedTypeView;
    match view {
        ProjectedTypeView::Unit => value_sum_inject(0, 8, Value::Unit),
        ProjectedTypeView::Bottom => value_sum_inject(1, 8, Value::Unit),
        ProjectedTypeView::Product { left, right } => value_sum_inject(
            2,
            8,
            value_pair(projected_value(left), projected_value(right)),
        ),
        ProjectedTypeView::Sum { left, right } => value_sum_inject(
            3,
            8,
            value_pair(projected_value(left), projected_value(right)),
        ),
        ProjectedTypeView::Function {
            param,
            abi_arity,
            ret,
        } => value_sum_inject(
            4,
            8,
            value_pair3(
                projected_value(param),
                Value::ReflTypeArity(abi_arity),
                projected_value(ret),
            ),
        ),
        ProjectedTypeView::Forall { name, arity, body } => value_sum_inject(
            5,
            8,
            value_pair3(
                Value::ReflTypeVar { name, arity },
                Value::ReflTypeArity(arity),
                projected_value(body),
            ),
        ),
        ProjectedTypeView::TypeVar { name, arity } => {
            value_sum_inject(6, 8, Value::ReflTypeVar { name, arity })
        }
        ProjectedTypeView::TypeName {
            segments,
            param_arities,
        } => value_sum_inject(
            7,
            8,
            Value::ReflTypeName {
                segments,
                param_arities,
            },
        ),
    }
}

#[cfg(feature = "surface")]
fn projected_spine(
    proof: &crate::pass::typecheck_core::apply::fills::MarkedComptimeProof,
    root: &crate::pass::typecheck_core::apply::fills::ProjectedValue,
    product: bool,
) -> Result<Vec<crate::pass::typecheck_core::apply::fills::ProjectedValue>, crate::error::Error> {
    use crate::pass::typecheck_core::apply::fills::{ProjectedTypeView, projected_type_view};
    let mut cursor = root.clone();
    let mut items = Vec::new();
    loop {
        match (product, projected_type_view(proof, &cursor)?) {
            (true, ProjectedTypeView::Product { left, right })
            | (false, ProjectedTypeView::Sum { left, right }) => {
                items.push(left);
                cursor = right;
            }
            _ => {
                items.push(cursor);
                return Ok(items);
            }
        }
    }
}

#[cfg(feature = "surface")]
fn projected_function_params(
    proof: &crate::pass::typecheck_core::apply::fills::MarkedComptimeProof,
    root: &crate::pass::typecheck_core::apply::fills::ProjectedValue,
) -> Result<Vec<crate::pass::typecheck_core::apply::fills::ProjectedValue>, crate::error::Error> {
    use crate::pass::typecheck_core::apply::fills::{ProjectedTypeView, projected_type_view};
    let ProjectedTypeView::Function {
        mut param,
        abi_arity,
        ..
    } = projected_type_view(proof, root)?
    else {
        return Ok(Vec::new());
    };
    if abi_arity == 0 {
        return Ok(Vec::new());
    }
    let mut params = Vec::with_capacity(abi_arity);
    for index in 0..abi_arity {
        if index + 1 == abi_arity {
            params.push(param);
            return Ok(params);
        }
        let ProjectedTypeView::Product { left, right } = projected_type_view(proof, &param)? else {
            return Err(crate::error::Error::elaborator(
                zero_span(),
                "a projected function ABI arity exceeded its exact product parameter spine",
            ));
        };
        params.push(left);
        param = right;
    }
    unreachable!("a nonzero projected function ABI arity completed without its last parameter")
}

fn fresh_checked_term_name(prefix: &str) -> String {
    static CHECKED_TERM_FRESH: std::sync::atomic::AtomicU64 = std::sync::atomic::AtomicU64::new(0);
    let n = CHECKED_TERM_FRESH.fetch_add(1, std::sync::atomic::Ordering::Relaxed);
    format!("_ct_{prefix}_n{n}")
}

pub(crate) fn fresh_checked_term_value_name(prefix: &str) -> String {
    let name = fresh_checked_term_name(prefix);
    format!("_{name}__")
}

fn checked_product_packet(terms: &[EvalRef<CheckedTerm>]) -> EvalRef<CheckedTerm> {
    match terms {
        [] => EvalRef::new(CheckedTerm::new(
            Expr::Unit {
                occurrence: Default::default(),
                meta: zero_meta(),
            },
            Type::Unit { meta: zero_meta() },
        )),
        [one] => one.clone(),
        [first, rest @ ..] => {
            let right = checked_product_packet(rest);
            EvalRef::new(CheckedTerm::from_node(
                CheckedTermNode::IntrinsicPair {
                    left: first.clone(),
                    right: right.clone(),
                },
                Type::Product {
                    left: Box::new(first.clone_type()),
                    right: Box::new(right.clone_type()),
                    meta: zero_meta(),
                },
            ))
        }
    }
}

#[cfg(feature = "surface")]
fn projected_checked_product_packet(
    proof: &crate::pass::typecheck_core::apply::fills::MarkedComptimeProof,
    terms: &[crate::pass::typecheck_core::apply::fills::ProjectedValue],
) -> Option<Value> {
    match terms {
        [] => Some(reflection_term_unit_value()),
        [one] => Some(projected_value(one.clone())),
        [first, rest @ ..] => {
            let left = projected_value(first.clone());
            let right = projected_checked_product_packet(proof, rest)?;
            crate::pass::typecheck_core::apply::fills::projected_intrinsic_pair(
                proof, &left, &right,
            )
            .ok()
            .map(projected_value)
        }
    }
}

fn project_packet(packet: EvalAstExpr, params: &[EvalAstType]) -> Vec<EvalAstExpr> {
    let mut packet = EvalRef::new(packet);
    let mut out = Vec::with_capacity(params.len());
    for (index, first) in params.iter().enumerate() {
        if index + 1 == params.len() {
            out.push(
                packet
                    .into_inner()
                    .expect("a projected packet is uniquely owned"),
            );
            return out;
        }
        let rest_ty = right_fold_product_type(&params[index + 1..]);
        out.push(intrinsic_expr(
            "__fst__",
            vec![
                CallArg::Type(first.clone()),
                CallArg::Type(rest_ty.clone()),
                CallArg::Value(checked_traversal::clone_expr(&packet)),
            ],
        ));
        packet = EvalRef::new(intrinsic_expr(
            "__snd__",
            vec![
                CallArg::Type(first.clone()),
                CallArg::Type(rest_ty),
                CallArg::Value(
                    packet
                        .into_inner()
                        .expect("a projected packet is uniquely owned"),
                ),
            ],
        ));
    }
    out
}

fn checked_term_value(expr: Expr<EvalPhase>, ty: Type<EvalPhase>) -> Value {
    Value::CheckedTerm(EvalRef::new(CheckedTerm::new(expr, ty)))
}

fn checked_term_local_value(name: String, ty: Type<EvalPhase>) -> Value {
    checked_term_node_value(CheckedTermNode::Local { name }, ty)
}

fn checked_term_node_value(node: CheckedTermNode, ty: Type<EvalPhase>) -> Value {
    Value::CheckedTerm(EvalRef::new(CheckedTerm::from_node(node, ty)))
}

fn checked_type_equiv(term: &CheckedTerm, expected: &Type<EvalPhase>, ctx: &EvalCtx<'_>) -> bool {
    canonical_refl_type_equiv(term.ty(), expected, ctx)
}

fn checked_term_type_fn(param: TypeParam, body: EvalRef<CheckedTerm>) -> CheckedTerm {
    let forall_ty = Type::Forall {
        param: param.clone(),
        body: Box::new(body.clone_type()),
        meta: zero_meta(),
    };
    // FIXME(shared-syntax): Shared Kio/Kio' expression syntax cannot directly
    // construct the bare pure `forall A. body` value, so this already-applied
    // Unit redex represents it without leaving a value-call layer. Replace the
    // redex if the shared syntax itself provides a direct constructor.
    let unit_ty = Type::Unit { meta: zero_meta() };
    let fn_value = EvalRef::new(CheckedTerm::from_node(
        CheckedTermNode::TermFn {
            sig: Signature::from_parts(
                vec![SignatureParam::Type(param)],
                vec![
                    crate::ast::SignatureGroupKind::Value { len: 0 },
                    crate::ast::SignatureGroupKind::Type { len: 1 },
                ],
            ),
            body,
        },
        Type::Function {
            param: Box::new(unit_ty),
            ret: Box::new(forall_ty.clone()),
            meta: zero_meta(),
            abi_arity: 0,
            caps: (),
        },
    ));
    CheckedTerm::from_node(
        CheckedTermNode::TermCall {
            fn_value,
            params: Vec::new(),
            arg_packet: checked_product_packet(&[]),
        },
        forall_ty,
    )
}

fn reflection_term_call_value_owned(
    fn_type: Value,
    fn_value: Value,
    arg_packet: Value,
    ctx: &EvalCtx<'_>,
) -> Result<Value, Vec<Value>> {
    let Some(fn_type_ty) = canonical_refl_type(&fn_type, ctx) else {
        return Err(vec![fn_type, fn_value, arg_packet]);
    };
    let Some((params, ret_ty)) = split_canonical_function_params(&fn_type_ty, ctx) else {
        return Err(vec![fn_type, fn_value, arg_packet]);
    };
    let Some(fn_value_term) = as_checked_term_ref(&fn_value) else {
        return Err(vec![fn_type, fn_value, arg_packet]);
    };
    let Some(arg_packet_term) = as_checked_term_ref(&arg_packet) else {
        return Err(vec![fn_type, fn_value, arg_packet]);
    };
    let packet_ty = right_fold_product_type(&params);
    if !checked_type_equiv(fn_value_term, &fn_type_ty, ctx)
        || !checked_type_equiv(arg_packet_term, &packet_ty, ctx)
    {
        return Err(vec![fn_type, fn_value, arg_packet]);
    }
    let fn_value = EvalRef::new(
        into_checked_term(fn_value).expect("checked-term value matched before consuming"),
    );
    let arg_packet = EvalRef::new(
        into_checked_term(arg_packet).expect("checked-term value matched before consuming"),
    );
    Ok(checked_term_node_value(
        CheckedTermNode::TermCall {
            fn_value,
            params,
            arg_packet,
        },
        ret_ty,
    ))
}

fn reflection_term_type_app_value_owned(
    fn_value: Value,
    arg: Value,
    ctx: &EvalCtx<'_>,
) -> Result<Value, Vec<Value>> {
    let Some(fn_value_term) = as_checked_term_ref(&fn_value) else {
        return Err(vec![fn_value, arg]);
    };
    let Type::Forall { param, body, .. } = unfold_canonical_refl_type(fn_value_term.ty(), ctx)
    else {
        return Err(vec![fn_value, arg]);
    };
    let Some(arg_ty) = canonical_refl_type(&arg, ctx) else {
        return Err(vec![fn_value, arg]);
    };
    let result_ty = subst_type(&body, &HashMap::from([(param.name, arg_ty.clone())]));
    let fn_value = EvalRef::new(
        into_checked_term(fn_value).expect("checked-term value matched before consuming"),
    );
    Ok(checked_term_node_value(
        CheckedTermNode::TermTypeApp {
            fn_value,
            arg: arg_ty,
        },
        result_ty,
    ))
}

fn is_reflection_proof(value: &Value) -> bool {
    if matches!(value, Value::Primitive(ComptimeBuiltin::ComptimeProof)) {
        return true;
    }
    #[cfg(feature = "surface")]
    if marked_comptime_proof_from_value(value).is_some() {
        return true;
    }
    false
}

fn reflection_runtime_args(builtin: ComptimeBuiltin, args: &[Value]) -> &[Value] {
    if builtin == ComptimeBuiltin::Fill {
        return args;
    }
    let args = match args.first() {
        Some(value) if is_reflection_proof(value) => &args[1..],
        _ => args,
    };
    match builtin {
        builtin if builtin.is_fold() && args.len() == 4 => &args[1..],
        ComptimeBuiltin::StructuralRecur if args.len() == 6 => &args[3..],
        _ => args,
    }
}

fn structural_recur_runtime_operands(args: &[Value]) -> Option<[Value; 3]> {
    match args {
        [fuel, input, step] => Some([fuel.clone(), input.clone(), step.clone()]),
        [packet] => {
            // The helper has one product-domain value layer. Like an ordinary
            // function binder, one value is the complete right-folded packet;
            // within-layer partial application is not a Kio operation.
            let input_and_step = project_product_value("__snd__", packet);
            Some([
                project_product_value("__fst__", packet),
                project_product_value("__fst__", &input_and_step),
                project_product_value("__snd__", &input_and_step),
            ])
        }
        _ => None,
    }
}

fn public_structural_recur_runtime_operands(args: &[Value]) -> Option<[Value; 3]> {
    structural_recur_runtime_operands(reflection_runtime_args(
        ComptimeBuiltin::StructuralRecur,
        args,
    ))
}

#[cfg(feature = "surface")]
enum ProjectedBuiltinClass {
    Helper(crate::pass::typecheck_core::apply::fills::ProjectedHelperClass),
    Fill,
    Specialize,
}

#[cfg(feature = "surface")]
fn projected_builtin_class(builtin: ComptimeBuiltin) -> ProjectedBuiltinClass {
    use crate::pass::typecheck_core::apply::fills::ProjectedHelperClass;
    use ComptimeBuiltin::*;
    let helper = match builtin {
        Fill => return ProjectedBuiltinClass::Fill,
        TermSpecialize => return ProjectedBuiltinClass::Specialize,
        ComptimeProof
        | Type
        | CheckedTerm
        | TypeVar
        | TypeName
        | TypeArity
        | DiagnosticText
        | ComptimeBool
        | ComptimeStr
        | FillCtx
        | TypeNameEqual
        | TypeVarEqual
        | TypeArityFn
        | TypeVarArity
        | TypeArityZero
        | TypeAritySucc
        | TypeArityEqual
        | TypeArityFold
        | TypeNameParamAritiesFold
        | TypeNameDisplay
        | TypeVarDisplay
        | TypeArityDisplay
        | DiagnosticConcat
        | ElabError
        | TypeError
        | StructuralRecur => ProjectedHelperClass::ContextInsensitive,
        TypeIsHost | TypeHostConverters | TypeEqual | TypeDisplay | TypeShortName
        | TermHostConvert => ProjectedHelperClass::GoalFreeOnly,
        ReflectType
        | TypeView
        | TypeIsProductRoot
        | TypeIsSumRoot
        | TypeUnit
        | TypeBottom
        | TypeProduct
        | TypeSum
        | TypeArrow
        | TypeForall
        | TypeVarFn
        | TypeNameType
        | TypeApply
        | TypeInstantiate
        | TypeProductSpineFold
        | TypeSumSpineFold
        | TypeArgsFold
        | TypeFunctionParamsFold
        | TermType
        | TermLet
        | TermFn
        | TermCall
        | TermTypeFn
        | TermTypeApp
        | TermUnit
        | IntrinsicPair
        | IntrinsicFst
        | IntrinsicSnd
        | IntrinsicLeft
        | IntrinsicRight
        | IntrinsicEither
        | IntrinsicAbsurd
        | IntrinsicIfThenElse => ProjectedHelperClass::FocusStructural,
    };
    ProjectedBuiltinClass::Helper(helper)
}

#[cfg(feature = "surface")]
fn close_authenticated_projected_args(
    args: &[Value],
    proof: &crate::pass::typecheck_core::apply::fills::MarkedComptimeProof,
    ctx: &EvalCtx<'_>,
) -> Option<Vec<Value>> {
    args.iter()
        .map(|arg| match arg {
            Value::Projected(projected) => projected
                .matches_proof(proof)
                .then(|| closed_projected_value(projected, proof, ctx))
                .flatten(),
            arg => Some(arg.clone()),
        })
        .collect()
}

#[derive(Clone, Copy)]
enum FuelMeasureMode {
    Initial,
    Recursive,
}

fn fuel_measure(value: &Value, ctx: &EvalCtx<'_>) -> Option<usize> {
    fuel_measure_with_mode(value, ctx, FuelMeasureMode::Recursive)
}

fn initial_fuel_measure(value: &Value, ctx: &EvalCtx<'_>) -> Option<usize> {
    fuel_measure_with_mode(value, ctx, FuelMeasureMode::Initial)
}

fn fuel_measure_with_mode(
    value: &Value,
    ctx: &EvalCtx<'_>,
    mode: FuelMeasureMode,
) -> Option<usize> {
    let mut total = 0usize;
    let mut pending = vec![(value, false)];
    while let Some((value, nested_in_data)) = pending.pop() {
        let measure = match value {
            Value::Unit
            | Value::Bool(_)
            | Value::IntAtom(_, _)
            | Value::FloatAtom(_, _)
            | Value::StrAtom(_)
            | Value::CheckedTerm(_)
            | Value::DiagnosticText(_)
            | Value::ReflTypeVar { .. }
            | Value::ReflTypeName { .. } => 1,
            Value::ReflType(reflected) => refl_type_measure(reflected.as_type(), ctx)?,
            Value::ReflTypeArity(arity) => arity.checked_add(1)?,
            Value::Data(data) => {
                if data.structural_recur_identity().is_some() {
                    return None;
                }
                #[cfg(feature = "surface")]
                if data.is_fills_capability() {
                    return None;
                }
                pending.extend(data.args().iter().rev().map(|arg| (arg, true)));
                1
            }
            Value::EvalClosure { .. }
            | Value::StructuralRecur { .. }
            | Value::Primitive(_)
            | Value::NewtypeMember(_)
            | Value::Atom(_)
            | Value::CaseSplit { .. }
            | Value::Seq { .. }
            | Value::Stuck(_, _) => return None,
            #[cfg(feature = "surface")]
            Value::Projected(projected) => {
                if nested_in_data {
                    projected.initial_structural_measure()?
                } else {
                    match mode {
                        FuelMeasureMode::Initial => projected.initial_structural_measure()?,
                        FuelMeasureMode::Recursive => projected.structural_measure()?,
                    }
                }
            }
        };
        total = total.checked_add(measure)?;
    }
    Some(total)
}

fn refl_type_measure(typ: &Type<EvalPhase>, ctx: &EvalCtx<'_>) -> Option<usize> {
    let start = ctx.metrics.as_deref().map(|_| Instant::now());
    let binders = eval_refl_type_free_bare_heads(typ);
    let out = crate::pass::typecheck_core::measure_materialized_aliases_in_scope(
        typ,
        ctx.root_module,
        ctx.package,
        Some(&binders),
        true,
    );
    if let (Some(metrics), Some(start)) = (ctx.metrics.as_deref(), start) {
        metrics.record_type_unfold(start.elapsed());
    }
    out
}

fn structural_recur_fault(value: Value, ctx: &EvalCtx<'_>) -> Value {
    ctx.record_structural_recur_fault(&value);
    value
}

fn reflection_term_type_value(term: &Value, ctx: &EvalCtx<'_>) -> Option<Value> {
    // Checked-term types are canonical semantic types. Preserve that mode:
    // reading them as source spellings would reinterpret a module-qualified
    // head through the consumer's same-named import alias.
    let ty = as_checked_term(term)?.clone_type();
    Some(refl_type_value(unfold_canonical_refl_type(&ty, ctx)))
}

fn reflection_term_unit_value() -> Value {
    checked_term_value(
        Expr::Unit {
            occurrence: Default::default(),
            meta: zero_meta(),
        },
        Type::Unit { meta: zero_meta() },
    )
}

fn reflection_error_value(kind: CheckedTermErrorKind, message: &Value) -> Option<Value> {
    Some(checked_term_node_value(
        CheckedTermNode::ElabError {
            kind,
            message: diagnostic_value(message)?,
        },
        Type::Unit { meta: zero_meta() },
    ))
}

fn reflection_intrinsic_pair_value(left: &Value, right: &Value) -> Option<Value> {
    let left = as_checked_term(left)?;
    let right = as_checked_term(right)?;
    let left_ty = left.clone_type();
    let right_ty = right.clone_type();
    Some(checked_term_node_value(
        CheckedTermNode::IntrinsicPair { left, right },
        Type::Product {
            left: Box::new(left_ty),
            right: Box::new(right_ty),
            meta: zero_meta(),
        },
    ))
}

fn reflection_intrinsic_pair_value_owned(left: Value, right: Value) -> Result<Value, Vec<Value>> {
    if !matches!(left, Value::CheckedTerm(_)) || !matches!(right, Value::CheckedTerm(_)) {
        return Err(vec![left, right]);
    }
    let left =
        EvalRef::new(into_checked_term(left).expect("checked-term value matched before consuming"));
    let right = EvalRef::new(
        into_checked_term(right).expect("checked-term value matched before consuming"),
    );
    let left_ty = left.clone_type();
    let right_ty = right.clone_type();
    Ok(checked_term_node_value(
        CheckedTermNode::IntrinsicPair { left, right },
        Type::Product {
            left: Box::new(left_ty),
            right: Box::new(right_ty),
            meta: zero_meta(),
        },
    ))
}

fn reflection_intrinsic_projection_value(
    name: &str,
    product_type: &Value,
    value: &Value,
    ctx: &EvalCtx<'_>,
) -> Option<Value> {
    let product_type = canonical_refl_type(product_type, ctx)?;
    let Type::Product { left, right, .. } = unfold_canonical_refl_type(&product_type, ctx) else {
        return None;
    };
    let value = as_checked_term(value)?;
    if !checked_type_equiv(&value, &product_type, ctx) {
        return None;
    }
    let intrinsic = if name == "__intrinsic_fst__" {
        "__fst__"
    } else {
        "__snd__"
    };
    let result_ty = if name == "__intrinsic_fst__" {
        (*left).clone()
    } else {
        (*right).clone()
    };
    Some(checked_term_node_value(
        CheckedTermNode::IntrinsicProjection {
            intrinsic: intrinsic.to_owned(),
            left_ty: (*left).clone(),
            right_ty: (*right).clone(),
            value,
        },
        result_ty,
    ))
}

fn reflection_intrinsic_projection_value_owned(
    name: &str,
    product_type: Value,
    value: Value,
    ctx: &EvalCtx<'_>,
) -> Result<Value, Vec<Value>> {
    let Some(product_type_ty) = canonical_refl_type(&product_type, ctx) else {
        return Err(vec![product_type, value]);
    };
    let Type::Product { left, right, .. } = unfold_canonical_refl_type(&product_type_ty, ctx)
    else {
        return Err(vec![product_type, value]);
    };
    let Some(value_term) = as_checked_term_ref(&value) else {
        return Err(vec![product_type, value]);
    };
    if !checked_type_equiv(value_term, &product_type_ty, ctx) {
        return Err(vec![product_type, value]);
    }
    let intrinsic = if name == "__intrinsic_fst__" {
        "__fst__"
    } else {
        "__snd__"
    };
    let result_ty = if name == "__intrinsic_fst__" {
        (*left).clone()
    } else {
        (*right).clone()
    };
    let value = EvalRef::new(
        into_checked_term(value).expect("checked-term value matched before consuming"),
    );
    Ok(checked_term_node_value(
        CheckedTermNode::IntrinsicProjection {
            intrinsic: intrinsic.to_owned(),
            left_ty: (*left).clone(),
            right_ty: (*right).clone(),
            value,
        },
        result_ty,
    ))
}

fn reflection_intrinsic_injection_value(
    name: &str,
    sum_type: &Value,
    value: &Value,
    ctx: &EvalCtx<'_>,
) -> Option<Value> {
    let sum_type = canonical_refl_type(sum_type, ctx)?;
    let Type::Sum { left, right, .. } = unfold_canonical_refl_type(&sum_type, ctx) else {
        return None;
    };
    let value = as_checked_term(value)?;
    let intrinsic = if name == "__intrinsic_left__" {
        if !checked_type_equiv(&value, &left, ctx) {
            return None;
        }
        "__left__"
    } else {
        if !checked_type_equiv(&value, &right, ctx) {
            return None;
        }
        "__right__"
    };
    Some(checked_term_node_value(
        CheckedTermNode::IntrinsicInjection {
            intrinsic: intrinsic.to_owned(),
            left_ty: (*left).clone(),
            right_ty: (*right).clone(),
            value,
        },
        sum_type,
    ))
}

fn reflection_intrinsic_injection_value_owned(
    name: &str,
    sum_type: Value,
    value: Value,
    ctx: &EvalCtx<'_>,
) -> Result<Value, Vec<Value>> {
    let Some(sum_type_ty) = canonical_refl_type(&sum_type, ctx) else {
        return Err(vec![sum_type, value]);
    };
    let Type::Sum { left, right, .. } = unfold_canonical_refl_type(&sum_type_ty, ctx) else {
        return Err(vec![sum_type, value]);
    };
    let Some(value_term) = as_checked_term_ref(&value) else {
        return Err(vec![sum_type, value]);
    };
    let intrinsic = if name == "__intrinsic_left__" {
        if !checked_type_equiv(value_term, &left, ctx) {
            return Err(vec![sum_type, value]);
        }
        "__left__"
    } else {
        if !checked_type_equiv(value_term, &right, ctx) {
            return Err(vec![sum_type, value]);
        }
        "__right__"
    };
    let value = EvalRef::new(
        into_checked_term(value).expect("checked-term value matched before consuming"),
    );
    Ok(checked_term_node_value(
        CheckedTermNode::IntrinsicInjection {
            intrinsic: intrinsic.to_owned(),
            left_ty: (*left).clone(),
            right_ty: (*right).clone(),
            value,
        },
        sum_type_ty,
    ))
}

fn reflection_intrinsic_absurd_value_owned(
    bottom_value: Value,
    result_type: Value,
    ctx: &EvalCtx<'_>,
) -> Result<Value, Vec<Value>> {
    let Some(bottom_ref) = as_checked_term_ref(&bottom_value) else {
        return Err(vec![bottom_value, result_type]);
    };
    if !checked_type_equiv(bottom_ref, &Type::Bottom { meta: zero_meta() }, ctx) {
        return Err(vec![bottom_value, result_type]);
    }
    let Some(result_type_ty) = canonical_refl_type(&result_type, ctx) else {
        return Err(vec![bottom_value, result_type]);
    };
    let bottom_value = EvalRef::new(
        into_checked_term(bottom_value).expect("checked-term value matched before consuming"),
    );
    Ok(checked_term_node_value(
        CheckedTermNode::IntrinsicAbsurd {
            result_ty: result_type_ty.clone(),
            bottom_value,
        },
        result_type_ty,
    ))
}

fn specialization_nominal_kind(
    segments: &[PathSegment],
    ctx: &EvalCtx<'_>,
) -> Option<crate::ast::Kind> {
    fn declaration_kind(
        declaration: crate::pass::resolve::TopLevelDeclaration<'_, EvalPhase>,
        name: &str,
    ) -> Option<crate::ast::Kind> {
        let params = if let Some(newtype) = declaration.newtype().filter(|item| item.name == name) {
            &newtype.type_params
        } else if let Some(host) = declaration.host_type().filter(|item| item.name == name) {
            &host.type_params
        } else {
            return None;
        };
        Some(
            params
                .iter()
                .rev()
                .fold(crate::ast::Kind::Star, |kind, param| {
                    crate::ast::Kind::Arrow(Box::new(param.effective_kind()), Box::new(kind))
                }),
        )
    }

    let (name, module_segments) = segments.split_last()?;
    let in_module = |module: &Module<EvalPhase>| {
        (module.path.segments.as_slice() == module_segments)
            .then(|| {
                let mut kind = None;
                for item in &module.items {
                    crate::pass::resolve::for_each_item_declaration(item, |declaration| {
                        if kind.is_none() {
                            kind = declaration_kind(declaration, name.as_str());
                        }
                    });
                    if kind.is_some() {
                        break;
                    }
                }
                kind
            })
            .flatten()
    };
    if let Some(package) = ctx.package {
        for (_, entry) in package.modules() {
            if let Some(kind) = in_module(&entry.module) {
                return Some(kind);
            }
        }
    }
    ctx.root_module.and_then(in_module)
}

fn specialization_nominal_kinds(
    pattern: &Type<EvalPhase>,
    target: &Type<EvalPhase>,
    params: &[TypeParam],
    ctx: &EvalCtx<'_>,
) -> Result<HashMap<Vec<String>, crate::ast::Kind>, String> {
    fn collect(
        ty: &Type<EvalPhase>,
        bound: &mut HashMap<String, usize>,
        kinds: &mut HashMap<Vec<String>, crate::ast::Kind>,
        ctx: &EvalCtx<'_>,
    ) -> Result<(), String> {
        match ty {
            Type::Unit { .. } | Type::Bottom { .. } => Ok(()),
            Type::Function { param, ret, .. } => {
                collect(param, bound, kinds, ctx)?;
                collect(ret, bound, kinds, ctx)
            }
            Type::Product { left, right, .. } | Type::Sum { left, right, .. } => {
                collect(left, bound, kinds, ctx)?;
                collect(right, bound, kinds, ctx)
            }
            Type::Forall { param, body, .. } => {
                *bound.entry(param.name.clone()).or_default() += 1;
                let result = collect(body, bound, kinds, ctx);
                let count = bound
                    .get_mut(&param.name)
                    .expect("specialization binder stack lost its top entry");
                *count -= 1;
                if *count == 0 {
                    bound.remove(&param.name);
                }
                result
            }
            Type::Path { segments, args, .. } => {
                for arg in args {
                    collect(arg, bound, kinds, ctx)?;
                }
                if segments.len() == 1 && bound.contains_key(segments[0].as_str()) {
                    return Ok(());
                }
                let key = segments
                    .iter()
                    .map(|segment| segment.name.clone())
                    .collect::<Vec<_>>();
                let kind = specialization_nominal_kind(segments, ctx).ok_or_else(|| {
                    format!(
                        "__term_specialize__ could not resolve canonical type head `{}`",
                        key.join(".")
                    )
                })?;
                match kinds.entry(key) {
                    std::collections::hash_map::Entry::Vacant(entry) => {
                        entry.insert(kind);
                    }
                    std::collections::hash_map::Entry::Occupied(entry) => {
                        if entry.get() != &kind {
                            return Err(
                                "__term_specialize__ observed conflicting nominal kinds".to_owned()
                            );
                        }
                    }
                }
                Ok(())
            }
            Type::Infer { ext, .. } => match *ext {},
            Type::Goal { ext, .. } => match *ext {},
            Type::LabelSugar { ext, .. } => match *ext {},
        }
    }

    let mut kinds = HashMap::new();
    let mut pattern_bound = HashMap::new();
    for param in params {
        *pattern_bound.entry(param.name.clone()).or_default() += 1;
    }
    collect(pattern, &mut pattern_bound, &mut kinds, ctx)?;
    collect(target, &mut HashMap::new(), &mut kinds, ctx)?;
    Ok(kinds)
}

fn term_specialize_value(
    term: &Value,
    pattern: &Value,
    target: &Value,
    ctx: &EvalCtx<'_>,
) -> Option<Value> {
    let term = as_checked_term(term)?;
    let term_type = unfold_canonical_refl_type(term.ty(), ctx);
    let pattern = unfold_canonical_refl_type(as_refl_type_ref(pattern)?, ctx);
    let target = unfold_canonical_refl_type(as_refl_type_ref(target)?, ctx);
    let mut params = Vec::new();
    let mut cursor = &term_type;
    while let Type::Forall { param, body, .. } = cursor {
        params.push(param.clone());
        cursor = body;
    }
    let nominal_kinds = match specialization_nominal_kinds(&pattern, &target, &params, ctx) {
        Ok(kinds) => kinds,
        Err(message) => {
            return Some(value_sum_inject(2, 3, Value::DiagnosticText(message)));
        }
    };
    let specialization_ctx =
        crate::pass::typecheck_core::IsolatedSpecializationContext::from_canonical_nominal_head_kinds(
            nominal_kinds,
        );
    let pattern = crate::pass::typecheck_core::InternedType::fresh_canonical(convert_type::<
        EvalPhase,
        crate::ast::Lowered,
    >(&pattern));
    let target = crate::pass::typecheck_core::InternedType::fresh_canonical(convert_type::<
        EvalPhase,
        crate::ast::Lowered,
    >(&target));
    let outcome = crate::pass::typecheck_core::solve_canonical_specialization_by_name(
        &params,
        &pattern,
        &target,
        zero_span(),
        &specialization_ctx,
    );
    match outcome {
        Ok(crate::pass::typecheck_core::IsolatedSpecialization::NoMatch) => {
            Some(value_sum_inject(1, 3, Value::Unit))
        }
        Ok(crate::pass::typecheck_core::IsolatedSpecialization::Matched(arguments)) => {
            let mut specialized = Value::CheckedTerm(term);
            for argument in arguments {
                let argument = refl_type_value(convert_type::<crate::ast::Lowered, EvalPhase>(
                    argument.as_type(),
                ));
                specialized = reflection_term_type_app_value_owned(specialized, argument, ctx)
                    .unwrap_or_else(|_| {
                        unreachable!(
                            "the shared specialization solver produced an inapplicable type argument"
                        )
                    });
            }
            Some(value_sum_inject(0, 3, specialized))
        }
        Err(error) => Some(value_sum_inject(
            2,
            3,
            Value::DiagnosticText(error.diagnostic().message.clone()),
        )),
    }
}

fn reflect_leaf(builtin: ComptimeBuiltin, args: &[Value], ctx: &EvalCtx<'_>) -> Option<Value> {
    #[cfg(feature = "surface")]
    if args.iter().any(|arg| matches!(arg, Value::Projected(_))) {
        match projected_builtin_class(builtin) {
            ProjectedBuiltinClass::Fill => {}
            ProjectedBuiltinClass::Specialize => {
                let proof = marked_comptime_proof_from_value(args.first()?)?;
                let [term, pattern, target] = reflection_runtime_args(builtin, args) else {
                    return None;
                };
                let term = projected_value_from_value(term)?;
                let outcome = crate::pass::typecheck_core::apply::fills::specialize_projected_term(
                    proof, term, pattern, target,
                )
                .ok()?;
                use crate::pass::typecheck_core::apply::fills::ProjectedSpecializationOutcome;
                return Some(match outcome {
                    ProjectedSpecializationOutcome::Matched(term) => {
                        value_sum_inject(0, 3, projected_value(term))
                    }
                    ProjectedSpecializationOutcome::NoMatch => value_sum_inject(1, 3, Value::Unit),
                    ProjectedSpecializationOutcome::Diagnostic(message) => {
                        value_sum_inject(2, 3, Value::DiagnosticText(message))
                    }
                });
            }
            ProjectedBuiltinClass::Helper(class) => {
                let proof = marked_comptime_proof_from_value(args.first()?)?;
                if class
                    == crate::pass::typecheck_core::apply::fills::ProjectedHelperClass::FocusStructural
                {
                    let runtime_args = reflection_runtime_args(builtin, args);
                    match (builtin, runtime_args) {
                        (ComptimeBuiltin::TermType, [term]) => {
                            let term = projected_value_from_value(term)?;
                            let ty =
                                crate::pass::typecheck_core::apply::fills::projected_term_type(
                                    proof, term,
                                )
                                .ok()?;
                            return Some(projected_value(ty));
                        }
                        (ComptimeBuiltin::TypeView, [ty]) => {
                            let ty = projected_value_from_value(ty)?;
                            let view =
                                crate::pass::typecheck_core::apply::fills::projected_type_view(
                                    proof, ty,
                                )
                                .ok()?;
                            return Some(projected_type_view_value(view));
                        }
                        (ComptimeBuiltin::TypeIsProductRoot, [ty])
                        | (ComptimeBuiltin::TypeIsSumRoot, [ty]) => {
                            let ty = projected_value_from_value(ty)?;
                            let view =
                                crate::pass::typecheck_core::apply::fills::projected_type_view(
                                    proof, ty,
                                )
                                .ok()?;
                            let matches = match builtin {
                                ComptimeBuiltin::TypeIsProductRoot => matches!(
                                    view,
                                    crate::pass::typecheck_core::apply::fills::ProjectedTypeView::Product { .. }
                                ),
                                ComptimeBuiltin::TypeIsSumRoot => matches!(
                                    view,
                                    crate::pass::typecheck_core::apply::fills::ProjectedTypeView::Sum { .. }
                                ),
                                _ => unreachable!("projected root predicate dispatch changed builtin"),
                            };
                            return Some(predicate_value(matches));
                        }
                        (
                            ComptimeBuiltin::TypeProduct | ComptimeBuiltin::TypeSum,
                            [left, right],
                        ) => {
                            let ty = match builtin {
                                ComptimeBuiltin::TypeProduct => crate::pass::typecheck_core::apply::fills::projected_type_product(
                                    proof, left, right,
                                ),
                                ComptimeBuiltin::TypeSum => crate::pass::typecheck_core::apply::fills::projected_type_sum(
                                    proof, left, right,
                                ),
                                _ => unreachable!("projected binary type dispatch changed builtin"),
                            }
                            .ok()?;
                            return Some(projected_value(ty));
                        }
                        (ComptimeBuiltin::TypeArrow, [params, arity, result]) => {
                            let arity = as_refl_type_arity(arity)?;
                            let arrow =
                                crate::pass::typecheck_core::apply::fills::projected_type_arrow(
                                    proof, params, arity, result,
                                )
                                .ok()?;
                            return Some(projected_value(arrow));
                        }
                        (ComptimeBuiltin::TypeApply, [head, argument]) => {
                            let applied =
                                crate::pass::typecheck_core::apply::fills::projected_type_apply(
                                    proof, head, argument,
                                )
                                .ok()??;
                            return Some(projected_value(applied));
                        }
                        (ComptimeBuiltin::TypeInstantiate, [scheme, argument]) => {
                            let instantiated = crate::pass::typecheck_core::apply::fills::projected_type_instantiate(
                                proof,
                                scheme,
                                argument,
                            )
                            .ok()?;
                            use crate::pass::typecheck_core::apply::fills::ProjectedTypeInstantiationOutcome;
                            return Some(match instantiated {
                                ProjectedTypeInstantiationOutcome::Instantiated(ty) => {
                                    value_sum_inject(0, 2, projected_value(ty))
                                }
                                ProjectedTypeInstantiationOutcome::Diagnostic(message) => {
                                    value_sum_inject(
                                        1,
                                        2,
                                        Value::DiagnosticText(message),
                                    )
                                }
                            });
                        }
                        (ComptimeBuiltin::TermTypeApp, [term, argument]) => {
                            let applied = crate::pass::typecheck_core::apply::fills::projected_term_type_app(
                                proof,
                                term,
                                argument,
                            )
                            .ok()?;
                            return Some(projected_value(applied));
                        }
                        (
                            ComptimeBuiltin::TermCall,
                            [function_type, function, argument],
                        ) => {
                            let call =
                                crate::pass::typecheck_core::apply::fills::projected_term_call(
                                    proof,
                                    function_type,
                                    function,
                                    argument,
                                )
                                .ok()?;
                            return Some(projected_value(call));
                        }
                        (ComptimeBuiltin::IntrinsicAbsurd, [bottom, result_type]) => {
                            let absurd = crate::pass::typecheck_core::apply::fills::projected_intrinsic_absurd(
                                proof,
                                bottom,
                                result_type,
                            )
                            .ok()?;
                            return Some(projected_value(absurd));
                        }
                        (ComptimeBuiltin::IntrinsicPair, [left, right]) => {
                            let pair = crate::pass::typecheck_core::apply::fills::projected_intrinsic_pair(
                                proof, left, right,
                            )
                            .ok()?;
                            return Some(projected_value(pair));
                        }
                        (
                            ComptimeBuiltin::IntrinsicFst | ComptimeBuiltin::IntrinsicSnd,
                            [product_type, value],
                        ) => {
                            let projection = crate::pass::typecheck_core::apply::fills::projected_intrinsic_product_projection(
                                proof,
                                product_type,
                                value,
                                builtin == ComptimeBuiltin::IntrinsicFst,
                            )
                            .ok()?;
                            return Some(projected_value(projection));
                        }
                        (
                            ComptimeBuiltin::IntrinsicLeft | ComptimeBuiltin::IntrinsicRight,
                            [sum_type, value],
                        ) => {
                            let injection = crate::pass::typecheck_core::apply::fills::projected_intrinsic_injection(
                                proof,
                                sum_type,
                                value,
                                builtin == ComptimeBuiltin::IntrinsicLeft,
                            )
                            .ok()?;
                            return Some(projected_value(injection));
                        }
                        _ => {}
                    }
                    // A focus-structural helper must retain projected identity;
                    // only the explicit GoalFreeOnly class may close a handle.
                    return None;
                }
            }
        }
    }
    let name = builtin.public_name();
    let args = reflection_runtime_args(builtin, args);
    match (name, args) {
        #[cfg(feature = "surface")]
        ("__fill__", [proof, context, destination, candidate]) => {
            let proof = marked_comptime_proof_from_value(proof)?;
            let context = fill_context_from_value(context)?;
            let destination = projected_value_from_value(destination)?;
            if !destination.authenticates_fill_destination(proof) {
                return None;
            }
            match candidate {
                Value::ReflType(_) => {}
                Value::Projected(candidate)
                    if candidate.is_type() && candidate.matches_proof(proof) => {}
                _ => return None,
            }
            Some(fill_context_value(context.append(
                proof,
                projected_value(destination.clone()),
                candidate.clone(),
            )?))
        }
        ("__type_unit__", []) => Some(refl_type_value(Type::Unit { meta: zero_meta() })),
        ("__type_bottom__", []) => Some(refl_type_value(Type::Bottom { meta: zero_meta() })),
        ("__type_product__", [left, right]) => Some(refl_type_value(Type::Product {
            left: Box::new(canonical_refl_type(left, ctx)?),
            right: Box::new(canonical_refl_type(right, ctx)?),
            meta: zero_meta(),
        })),
        ("__type_sum__", [left, right]) => Some(refl_type_value(Type::Sum {
            left: Box::new(canonical_refl_type(left, ctx)?),
            right: Box::new(canonical_refl_type(right, ctx)?),
            meta: zero_meta(),
        })),
        ("__type_arrow__", [params, arity, result]) => {
            let abi_arity = as_refl_type_arity(arity)?;
            let param = canonical_refl_type(params, ctx)?;
            Some(refl_type_value(Type::Function {
                param: Box::new(param),
                ret: Box::new(canonical_refl_type(result, ctx)?),
                meta: zero_meta(),
                abi_arity,
                caps: (),
            }))
        }
        ("__type_var__", [Value::ReflTypeVar { name, .. }]) => {
            Some(refl_type_value(type_path(name)))
        }
        ("__type_name_type__", [Value::ReflTypeName { segments, .. }]) => Some(refl_type_value(
            Type::synth_path(segments.clone(), Vec::new(), zero_span()),
        )),
        ("__type_apply__", [head, arg]) => {
            let mut head_ty = canonical_refl_type(head, ctx)?;
            if let Type::Path { args, .. } = &mut head_ty {
                args.push(canonical_refl_type(arg, ctx)?);
            }
            Some(refl_type_value(head_ty))
        }
        ("__type_view__", [typ]) => type_view_value(&canonical_refl_type(typ, ctx)?, ctx),
        ("__type_is_host__", [typ]) => Some(predicate_value(
            match_package_host_type(&canonical_refl_type(typ, ctx)?, ctx).is_some(),
        )),
        ("__type_host_converters__", [string_ty, source_ty]) => {
            let source_ty = canonical_refl_type(source_ty, ctx)?;
            Some(refl_type_value(host_converter_product_type(
                canonical_refl_type(string_ty, ctx)?,
                &source_ty,
                ctx,
            )))
        }
        ("__type_equal__", [left, right]) => {
            let left = canonical_refl_type(left, ctx)?;
            let right = canonical_refl_type(right, ctx)?;
            Some(predicate_value(canonical_refl_type_equiv(
                &left, &right, ctx,
            )))
        }
        ("__type_instantiate__", [scheme, arg]) => Some(type_instantiate_value(
            canonical_refl_type(scheme, ctx)?,
            canonical_refl_type(arg, ctx)?,
            ctx,
        )),
        ("__type_name_equal__", [left, right]) => Some(predicate_value(match (left, right) {
            (
                Value::ReflTypeName {
                    segments: left_segments,
                    param_arities: left_arities,
                },
                Value::ReflTypeName {
                    segments: right_segments,
                    param_arities: right_arities,
                },
            ) => left_segments == right_segments && left_arities == right_arities,
            _ => return None,
        })),
        ("__type_var_equal__", [left, right]) => Some(predicate_value(match (left, right) {
            (
                Value::ReflTypeVar {
                    name: left_name,
                    arity: left_arity,
                },
                Value::ReflTypeVar {
                    name: right_name,
                    arity: right_arity,
                },
            ) => left_name == right_name && left_arity == right_arity,
            _ => return None,
        })),
        ("__type_is_product_root__", [typ]) => Some(predicate_value(matches!(
            unfold_canonical_refl_type(&canonical_refl_type(typ, ctx)?, ctx),
            Type::Product { .. }
        ))),
        ("__type_is_sum_root__", [typ]) => Some(predicate_value(matches!(
            unfold_canonical_refl_type(&canonical_refl_type(typ, ctx)?, ctx),
            Type::Sum { .. }
        ))),
        ("__type_arity__", [typ]) => Some(Value::ReflTypeArity(type_arity_of_type(
            &canonical_refl_type(typ, ctx)?,
            ctx,
        ))),
        ("__type_var_arity__", [Value::ReflTypeVar { arity, .. }]) => {
            Some(Value::ReflTypeArity(*arity))
        }
        ("__type_arity_zero__", []) => Some(Value::ReflTypeArity(0)),
        ("__type_arity_succ__", [prev]) => {
            Some(Value::ReflTypeArity(as_refl_type_arity(prev)? + 1))
        }
        ("__type_arity_equal__", [left, right]) => Some(predicate_value(
            as_refl_type_arity(left)? == as_refl_type_arity(right)?,
        )),
        ("__type_display__", [typ]) => Some(Value::DiagnosticText(
            crate::pass::typecheck_core::display_reflected_type(as_refl_type_ref(typ)?),
        )),
        ("__type_short_name__", [typ]) => Some(Value::DiagnosticText(compact_refl_type_display(
            as_refl_type_ref(typ)?,
            ctx,
        ))),
        ("__type_name_display__", [Value::ReflTypeName { segments, .. }]) => {
            Some(Value::DiagnosticText(
                crate::pass::typecheck_core::display_reflected_type_name(segments),
            ))
        }
        ("__type_var_display__", [Value::ReflTypeVar { name, .. }]) => {
            Some(Value::DiagnosticText(name.clone()))
        }
        ("__type_arity_display__", [arity]) => Some(Value::DiagnosticText(
            as_refl_type_arity(arity)?.to_string(),
        )),
        ("__diagnostic_concat__", [left, right]) => Some(Value::DiagnosticText(format!(
            "{}{}",
            diagnostic_value(left)?,
            diagnostic_value(right)?
        ))),
        ("__elab_error__", [message]) => {
            reflection_error_value(CheckedTermErrorKind::Elaborator, message)
        }
        ("__type_error__", [message]) => {
            reflection_error_value(CheckedTermErrorKind::Type, message)
        }
        ("__term_type__", [term]) => reflection_term_type_value(term, ctx),
        ("__term_specialize__", [term, pattern, target]) => {
            term_specialize_value(term, pattern, target, ctx)
        }
        ("__term_call__", [fn_type, fn_value, arg_packet]) => {
            let fn_type = canonical_refl_type(fn_type, ctx)?;
            let (params, ret_ty) = split_canonical_function_params(&fn_type, ctx)?;
            let fn_value = as_checked_term(fn_value)?;
            let arg_packet = as_checked_term(arg_packet)?;
            let packet_ty = right_fold_product_type(&params);
            if !checked_type_equiv(&fn_value, &fn_type, ctx)
                || !checked_type_equiv(&arg_packet, &packet_ty, ctx)
            {
                return None;
            }
            Some(checked_term_node_value(
                CheckedTermNode::TermCall {
                    fn_value,
                    params,
                    arg_packet,
                },
                ret_ty,
            ))
        }
        ("__term_type_app__", [fn_value, arg]) => {
            let fn_value = as_checked_term(fn_value)?;
            let Type::Forall { param, body, .. } = unfold_canonical_refl_type(fn_value.ty(), ctx)
            else {
                return None;
            };
            let arg = canonical_refl_type(arg, ctx)?;
            let result_ty = subst_type(&body, &HashMap::from([(param.name, arg.clone())]));
            Some(checked_term_node_value(
                CheckedTermNode::TermTypeApp { fn_value, arg },
                result_ty,
            ))
        }
        ("__term_unit__", []) => Some(reflection_term_unit_value()),
        ("__term_host_convert__", [string_ty, source_ty, converters, value]) => {
            reflection_term_host_convert_value(string_ty, source_ty, converters, value, ctx)
        }
        ("__intrinsic_pair__", [left, right]) => reflection_intrinsic_pair_value(left, right),
        ("__intrinsic_fst__", [product_type, value])
        | ("__intrinsic_snd__", [product_type, value]) => {
            reflection_intrinsic_projection_value(name, product_type, value, ctx)
        }
        ("__intrinsic_left__", [sum_type, value]) | ("__intrinsic_right__", [sum_type, value]) => {
            reflection_intrinsic_injection_value(name, sum_type, value, ctx)
        }
        ("__intrinsic_absurd__", [bottom_value, result_type]) => {
            let bottom_value = as_checked_term(bottom_value)?;
            if !checked_type_equiv(&bottom_value, &Type::Bottom { meta: zero_meta() }, ctx) {
                return None;
            }
            let result_type = canonical_refl_type(result_type, ctx)?;
            Some(checked_term_node_value(
                CheckedTermNode::IntrinsicAbsurd {
                    result_ty: result_type.clone(),
                    bottom_value,
                },
                result_type,
            ))
        }
        _ => None,
    }
}

/// Apply an evaluator value. A public plain `StructuralRecur` primitive gains
/// its private synthetic origin only when this call completes its runtime
/// saturation; the destination `ctx` therefore owns that origin even when a
/// proof-prefix partial value was created elsewhere.
pub fn apply(callee: Value, args: Vec<Value>, ctx: &EvalCtx<'_>) -> Value {
    let operation = ctx.enter_structural_recur_operation();
    operation.finish(apply_args(callee, EvalArgs::Many(args), ctx))
}

fn apply_args(callee: Value, args: EvalArgs, ctx: &EvalCtx<'_>) -> Value {
    execution::apply(callee, args, ctx)
}

fn apply_atom_leaf(atom: AtomCallee<'_>, mut args: Vec<Value>) -> Value {
    let name = atom.as_str();
    if args.is_empty() {
        return atom.into_value();
    }
    // ── Constructors build `Value::Data` ────────────────────────────
    //
    // A saturated core constructor application is a residual normal form
    // (specs/formal/equiv.md § 3). Each constructor carries leading *erased*
    // type-args (the expr-first parse keeps a bare type name as a
    // `CallArg::Value`; the call compiler can only drop them with a
    // fn-def signature or a value-at-type-slot marker). So the value payload is the *trailing*
    // N value-args, where N is the constructor's value arity. Anything
    // ahead of the payload is an erased type-arg and is dropped here.
    if let Some(arity) = intrinsic_ctor_value_arity(name)
        && args.len() >= arity
    {
        let payload = args.split_off(args.len() - arity);
        return data_value(name, payload);
    }
    // ── Drop an eliminator's leading erased type-args ───────────────
    //
    // `__either__` / `__fst__` / `__snd__` / `__if_then_else__` have no
    // fn-def signature for the call compiler to filter against, so a
    // call with explicit type-args — `__either__(A, B, C, s, fl, fr)` —
    // can reach here with the leading type-name atoms still in `args`. The
    // ι-rule arms below match a rigid operand slice (`[scrutinee, fl,
    // fr]`, `[pair]`), which only fits once the type-args are gone. Keep
    // just the trailing N value-operands, where N is the eliminator's
    // value arity (constructors were handled above; this is the dual).
    if let Some(arity) = intrinsic_elim_value_arity(name)
        && args.len() > arity
    {
        args = args.split_off(args.len() - arity);
    }
    // ── ι-Fst / ι-Snd (specs/formal/equiv.md § 2.1) ─────────────────
    //
    //   __fst__(__pair__(a, b))  →  a
    //   __snd__(__pair__(a, b))  →  b
    if (name == "__fst__" || name == "__snd__")
        && let [Value::Data(data)] = args.as_slice()
        && data.ctor() == "__pair__"
        && data.args().len() == 2
    {
        let want_fst = name == "__fst__";
        let snd = data.args()[1].clone();
        let fst = data.args()[0].clone();
        return if want_fst { fst } else { snd };
    }
    Value::Stuck(EvalRef::new(atom.into_value()), args.into())
}

fn can_bind_eval_function_args(function: &EvalFunction, args: &[Value]) -> bool {
    bind_eval_function_group_args(function, 0, 0, args, function.value_groups.len()).is_some()
}

fn bind_eval_function_expr_args(
    function: &EvalFunction,
    args: &[EvalRef<EvalExpr>],
) -> Option<(Vec<EvalRef<EvalExpr>>, usize)> {
    bind_eval_function_group_expr_args(function, 0, 0, args)
}

fn bind_eval_function_group_expr_args(
    function: &EvalFunction,
    group_index: usize,
    arg_index: usize,
    args: &[EvalRef<EvalExpr>],
) -> Option<(Vec<EvalRef<EvalExpr>>, usize)> {
    let Some(group) = function.value_groups.get(group_index) else {
        return Some((Vec::new(), arg_index));
    };
    let params = &function.params[group.param_start..group.param_start + group.param_count];
    let mut best: Option<(Vec<EvalRef<EvalExpr>>, usize)> = None;
    for (group_locals, next_arg_index) in
        eval_group_expr_binding_candidates(params, group, arg_index, args)
    {
        if let Some((tail_locals, consumed)) =
            bind_eval_function_group_expr_args(function, group_index + 1, next_arg_index, args)
        {
            let mut locals = group_locals;
            locals.extend(tail_locals);
            if best
                .as_ref()
                .is_none_or(|(_, best_consumed)| consumed > *best_consumed)
            {
                best = Some((locals, consumed));
            }
        }
    }
    best
}

fn eval_group_expr_binding_candidates(
    params: &[EvalParam],
    group: &EvalParamGroup,
    arg_index: usize,
    args: &[EvalRef<EvalExpr>],
) -> Vec<(Vec<EvalRef<EvalExpr>>, usize)> {
    let mut out = Vec::new();
    if group.abi_arity == 0 {
        // Expr twin of eval_group_binding_candidates' zero-slot arm:
        // the group claims the unit-packet argument position
        // unconditionally; a single unit-typed param binds the actual
        // argument expression (β-Lam), a nullary group binds nothing.
        // No argument, no candidate — binding stops at the boundary.
        if let Some(arg) = args.get(arg_index) {
            let locals = if group.param_count == 1 {
                vec![arg.clone()]
            } else {
                Vec::new()
            };
            out.push((locals, arg_index + 1));
        }
        return out;
    }
    let has_flattened_group = arg_index + group.abi_arity <= args.len();
    if has_flattened_group {
        out.push((
            bind_eval_params_abi_exprs(params, &args[arg_index..arg_index + group.abi_arity]),
            arg_index + group.abi_arity,
        ));
    }
    if !has_flattened_group
        && group.abi_arity > 1
        && let Some(packet) = args.get(arg_index)
    {
        out.push((
            bind_eval_params_packet_expr(params, group, packet.clone()),
            arg_index + 1,
        ));
    }
    out
}

fn bind_eval_params_abi_exprs(
    params: &[EvalParam],
    slots: &[EvalRef<EvalExpr>],
) -> Vec<EvalRef<EvalExpr>> {
    let mut locals = Vec::with_capacity(params.len());
    let mut next = 0usize;
    for param in params {
        match param.abi_arity {
            0 => locals.push(EvalRef::new(EvalExpr::Unit)),
            1 => {
                locals.push(
                    slots
                        .get(next)
                        .expect("eval function ABI expr slot available")
                        .clone(),
                );
                next += 1;
            }
            arity => {
                let end = next + arity;
                locals.push(right_fold_product_eval_exprs(
                    slots
                        .get(next..end)
                        .expect("eval function ABI expr slot run available")
                        .to_vec(),
                ));
                next = end;
            }
        }
    }
    locals
}

fn bind_eval_params_packet_expr(
    params: &[EvalParam],
    group: &EvalParamGroup,
    packet: EvalRef<EvalExpr>,
) -> Vec<EvalRef<EvalExpr>> {
    if group.param_count == 1 {
        return vec![packet];
    }
    let slots = split_product_packet_expr_slots(packet, group.abi_arity);
    bind_eval_params_abi_exprs(params, &slots)
}

fn split_product_packet_expr_slots(
    packet: EvalRef<EvalExpr>,
    slot_count: usize,
) -> Vec<EvalRef<EvalExpr>> {
    match slot_count {
        0 => Vec::new(),
        1 => vec![packet],
        _ => {
            let mut out = Vec::with_capacity(slot_count);
            let mut current = packet;
            for index in 0..slot_count {
                if index + 1 == slot_count {
                    out.push(current);
                    break;
                } else {
                    out.push(EvalRef::new(EvalExpr::CoreProj {
                        name: "__fst__",
                        pair: current.clone(),
                    }));
                    current = EvalRef::new(EvalExpr::CoreProj {
                        name: "__snd__",
                        pair: current,
                    });
                }
            }
            out
        }
    }
}

fn bind_eval_function_group_args(
    function: &EvalFunction,
    group_index: usize,
    arg_index: usize,
    args: &[Value],
    end_group: usize,
) -> Option<(Vec<Value>, usize)> {
    if group_index >= end_group {
        return Some((Vec::new(), arg_index));
    }
    let Some(group) = function.value_groups.get(group_index) else {
        return Some((Vec::new(), arg_index));
    };
    let params = &function.params[group.param_start..group.param_start + group.param_count];
    let mut best: Option<(Vec<Value>, usize)> = None;
    for (group_locals, next_arg_index) in
        eval_group_binding_candidates(params, group, arg_index, args)
    {
        if let Some((tail_locals, consumed)) = bind_eval_function_group_args(
            function,
            group_index + 1,
            next_arg_index,
            args,
            end_group,
        ) {
            let mut locals = group_locals;
            locals.extend(tail_locals);
            if best
                .as_ref()
                .is_none_or(|(_, best_consumed)| consumed > *best_consumed)
            {
                best = Some((locals, consumed));
            }
        }
    }
    best
}

fn eval_group_binding_candidates(
    params: &[EvalParam],
    group: &EvalParamGroup,
    arg_index: usize,
    args: &[Value],
) -> Vec<(Vec<Value>, usize)> {
    let mut out = Vec::new();
    if group.abi_arity == 0 {
        // A zero-slot group is one unit-typed param or a nullary group
        // (see collect_value_param_layout); either way its type has
        // unit domain, and the call's argument position holds the unit
        // packet whatever its value shape — `f()` and `f(())` both pass
        // the unit product (specs/language.md § Function types), and an
        // opaque or stuck unit-typed packet is equally legal. The group
        // therefore claims the position unconditionally instead of
        // leaking the packet into a leftover application onto the
        // body's value (the `()(x)` residual specs/formal/equiv.md § 3
        // rules out). With a param, β-Lam (§ 2.1) binds the actual
        // value, so a stuck action the body returns is not erased to
        // `()`; a nullary group has no binder — β-Lam at zero binders
        // discards the packet by substitution, and binding it would
        // mint a phantom local that shifts the body's let slots.
        // Without an argument there is no candidate: β-Lam reduces one
        // λ-layer per application (curry layers are distinct), so
        // binding stops at the group boundary and the caller suspends
        // the remaining groups as a closure.
        if let Some(arg) = args.get(arg_index) {
            let locals = if group.param_count == 1 {
                vec![arg.clone()]
            } else {
                Vec::new()
            };
            out.push((locals, arg_index + 1));
        }
        return out;
    }
    let has_flattened_group = arg_index + group.abi_arity <= args.len();
    if has_flattened_group {
        out.push((
            bind_eval_params_abi_slots(params, &args[arg_index..arg_index + group.abi_arity]),
            arg_index + group.abi_arity,
        ));
    }
    if !has_flattened_group
        && group.abi_arity > 1
        && let Some(packet) = args.get(arg_index)
    {
        out.push((
            bind_eval_params_packet(params, group, packet.clone()),
            arg_index + 1,
        ));
    }
    out
}

fn bind_eval_function_abi_slots(function: &EvalFunction, slots: &[Value]) -> Vec<Value> {
    bind_eval_params_abi_slots(&function.params, slots)
}

fn bind_eval_params_abi_slots(params: &[EvalParam], slots: &[Value]) -> Vec<Value> {
    let mut locals = Vec::with_capacity(params.len());
    let mut next = 0usize;
    for param in params {
        match param.abi_arity {
            0 => locals.push(Value::Unit),
            1 => {
                locals.push(
                    slots
                        .get(next)
                        .expect("eval function ABI slot available")
                        .clone(),
                );
                next += 1;
            }
            arity => {
                let end = next + arity;
                locals.push(right_fold_product_values(
                    slots
                        .get(next..end)
                        .expect("eval function ABI slot run available")
                        .to_vec(),
                ));
                next = end;
            }
        }
    }
    locals
}

fn bind_eval_params_packet(
    params: &[EvalParam],
    group: &EvalParamGroup,
    packet: Value,
) -> Vec<Value> {
    if group.param_count == 1 {
        return vec![packet];
    }
    let slots = split_product_packet_slots(packet, group.abi_arity);
    bind_eval_params_abi_slots(params, &slots)
}

fn split_product_packet_slots(packet: Value, slot_count: usize) -> Vec<Value> {
    match slot_count {
        0 => Vec::new(),
        1 => vec![packet],
        _ => {
            let mut out = Vec::with_capacity(slot_count);
            let mut current = packet;
            for index in 0..slot_count {
                if index + 1 == slot_count {
                    out.push(current);
                    break;
                } else {
                    out.push(project_product_value("__fst__", &current));
                    current = project_product_value("__snd__", &current);
                }
            }
            out
        }
    }
}

fn project_product_value(name: &'static str, pair: &Value) -> Value {
    if let Value::Data(data) = pair
        && data.ctor() == "__pair__"
        && data.args().len() == 2
    {
        return if name == "__fst__" {
            data.args()[0].clone()
        } else {
            data.args()[1].clone()
        };
    }
    Value::Stuck(
        EvalRef::new(Value::Atom(name.to_string())),
        vec![pair.clone()].into(),
    )
}

/// Whether a full ABI-slot argument list saturates every value group,
/// so slot-exact binding coincides with per-group β. False only when a
/// multi-group function contains a zero-slot group: that group consumes
/// an argument position without a slot, so slot-count equality no
/// longer means every layer received its argument.
fn abi_slots_saturate_groups(function: &EvalFunction) -> bool {
    function.value_groups.len() <= 1
        || function
            .value_groups
            .iter()
            .all(|group| group.abi_arity > 0)
}

fn lookup_exact_call_memo(
    function: &EvalRef<EvalFunction>,
    captured: &[Value],
    args: &[Value],
    ctx: &EvalCtx<'_>,
) -> Result<Option<ExactCallMemoKey>, Value> {
    // A cached result cannot replace work performed while a recursion origin
    // is active, and a fault already recorded by this operation cannot be
    // hidden by a later cache hit.
    let memo_key = if !function.memo_candidate
        || ctx.has_active_structural_recur_site()
        || ctx.structural_recur_operation_has_fault()
    {
        None
    } else {
        exact_call_memo_key(function, captured, args)
    };
    if function.memo_candidate
        && memo_key.is_none()
        && let Some(metrics) = ctx.metrics.as_deref()
    {
        metrics.record_exact_call_memo_key_skip();
    }
    if let Some(key) = memo_key.as_ref()
        && let Some(value) = ctx
            .exact_call_memo
            .inner
            .lock()
            .expect("exact call memo lock poisoned")
            .get(key)
            .cloned()
    {
        if let Some(metrics) = ctx.metrics.as_deref() {
            metrics.record_exact_call_memo_hit();
        }
        return Err(value);
    }
    if memo_key.is_some()
        && let Some(metrics) = ctx.metrics.as_deref()
    {
        metrics.record_exact_call_memo_miss();
    }
    Ok(memo_key)
}

fn insert_exact_call_memo(ctx: &EvalCtx<'_>, key: Option<ExactCallMemoKey>, value: Value) {
    let Some(key) = key else {
        return;
    };
    // The body may have executed and then discarded a totality failure while
    // producing an otherwise shareable result. The operation retains that
    // first fault until its public boundary, so never cache the apparent
    // success.
    if ctx.has_active_structural_recur_site() || ctx.structural_recur_operation_has_fault() {
        return;
    }
    if !exact_call_memo_result_shareable(&value) {
        return;
    }
    let mut memo = ctx
        .exact_call_memo
        .inner
        .lock()
        .expect("exact call memo lock poisoned");
    if memo.len() < EXACT_CALL_MEMO_MAX_ENTRIES {
        memo.insert(key, value);
        if let Some(metrics) = ctx.metrics.as_deref() {
            metrics.record_exact_call_memo_store();
        }
    }
}

fn suspend_eval_function_suffix(
    function: &EvalRef<EvalFunction>,
    captured: &[Value],
    prefix_locals: Vec<Value>,
    suffix_group_index: usize,
    ctx: &EvalCtx<'_>,
) -> Value {
    let suffix_param_start = function.value_groups[suffix_group_index].param_start;
    let params: Arc<[EvalParam]> = function.params[suffix_param_start..].to_vec().into();
    let value_groups: Arc<[EvalParamGroup]> = function.value_groups[suffix_group_index..]
        .iter()
        .map(|group| EvalParamGroup {
            param_start: group.param_start - suffix_param_start,
            param_count: group.param_count,
            abi_arity: group.abi_arity,
        })
        .collect::<Vec<_>>()
        .into();
    let abi_arity = value_groups.iter().map(|group| group.abi_arity).sum();
    // The body is unchanged: its slots expect the original captures,
    // then every param in order. Appending the bound prefix to the
    // captures keeps that layout — prefix params resolve as captures,
    // suffix params as the forcing call's locals.
    let mut suspended_captured = captured.to_vec();
    suspended_captured.extend(prefix_locals);
    if let Some(metrics) = ctx.metrics.as_deref() {
        metrics.record_closure_build();
        metrics.record_capture_vec(suspended_captured.len());
    }
    Value::EvalClosure {
        function: EvalRef::new(EvalFunction {
            cache_key: eval_function_cache_key_for_suffix(&function.cache_key, suffix_group_index),
            label: function.label.clone(),
            owner_module_path: function.owner_module_path.clone(),
            source_origin: function.source_origin.clone(),
            params,
            value_groups,
            abi_arity,
            simple_body: function.simple_body,
            memo_candidate: function.memo_candidate,
            body: function.body.clone(),
            diagnostic_body: function.diagnostic_body.clone(),
        }),
        captured: suspended_captured.into(),
    }
}

fn apply_newtype_member(member: Arc<ResolvedNewtypeMemberValue>, mut args: Vec<Value>) -> Value {
    match member.kind {
        NewtypeMemberKind::Constructor { payload_abi_arity } => {
            let payload = if payload_abi_arity == 0 && args.is_empty() {
                Value::Unit
            } else if args.len() == 1 {
                args.pop().expect("one argument")
            } else if args.len() >= payload_abi_arity {
                let payload_slots = args.split_off(args.len() - payload_abi_arity);
                right_fold_product_values(payload_slots)
            } else {
                return Value::Stuck(EvalRef::new(Value::NewtypeMember(member)), args.into());
            };
            newtype_data_value(&member, vec![payload])
        }
        NewtypeMemberKind::Projector => {
            if let Some(Value::Data(data)) = args.last()
                && data.has_newtype_constructor(&member.constructor)
                && let Some(payload) = data.args().last()
            {
                return payload.clone();
            }
            Value::Stuck(EvalRef::new(Value::NewtypeMember(member)), args.into())
        }
    }
}

fn collect_value_param_names<P: crate::ast::Phase>(params: &[SignatureParam<P>]) -> Vec<String> {
    params
        .iter()
        .filter_map(|p| match p {
            SignatureParam::Type(_) => None,
            SignatureParam::Value(vp) => Some(vp.name.clone()),
        })
        .collect()
}

fn collect_value_param_layout<P: crate::ast::Phase>(
    sig: &Signature<P>,
) -> (Arc<[EvalParam]>, Arc<[EvalParamGroup]>, usize) {
    let mut params = Vec::new();
    let mut value_groups = Vec::new();
    let mut total_abi_arity = 0usize;
    for group in sig.canonical_groups() {
        let SignatureGroupRef::Value(group_params) = group else {
            continue;
        };
        let group_start = params.len();
        let single_value_param = group_params.len() == 1;
        let mut group_abi_arity = 0usize;
        for param in group_params {
            let SignatureParam::Value(param) = param else {
                unreachable!("SignatureGroupRef::Value contains only value params")
            };
            let abi_arity = if single_value_param {
                match param.ty.as_ref() {
                    Some(Type::Unit { .. }) => 0,
                    Some(_) | None => 1,
                }
            } else {
                1
            };
            group_abi_arity += abi_arity;
            params.push(EvalParam {
                name: param.name.clone(),
                abi_arity,
            });
        }
        total_abi_arity += group_abi_arity;
        value_groups.push(EvalParamGroup {
            param_start: group_start,
            param_count: params.len() - group_start,
            abi_arity: group_abi_arity,
        });
    }
    (params.into(), value_groups.into(), total_abi_arity)
}

fn eval_param_names(params: &[EvalParam]) -> Vec<String> {
    params.iter().map(|param| param.name.clone()).collect()
}

/// The canonical host-type path of a literal's optional `(Type)` annotation,
/// for the literal atom's identity. A bare literal — or an annotation with
/// type arguments — yields `None`.
fn literal_annotation_name<P: crate::ast::Phase>(annotation: Option<&Type<P>>) -> Option<String> {
    match annotation {
        Some(Type::Path { segments, args, .. }) if !segments.is_empty() && args.is_empty() => Some(
            segments
                .iter()
                .map(PathSegment::as_str)
                .collect::<Vec<_>>()
                .join("."),
        ),
        _ => None,
    }
}

fn literal_annotation_identity(
    annotation: Option<&EvalAstType>,
    state: &EvalCompileState<'_, '_>,
) -> Option<String> {
    let annotation = match annotation {
        Some(Type::Path {
            segments,
            args,
            meta,
        }) if segments.len() == 1 && args.is_empty() => {
            let segments = state.module.map_or_else(
                || segments.clone(),
                |module| {
                    crate::pass::resolve::qualify_type_segments_in_module(
                        segments,
                        module,
                        &state.type_binders,
                    )
                },
            );
            Some(Type::synth_path_segments(segments, Vec::new(), meta.span))
        }
        Some(annotation) => Some(annotation.clone()),
        None => None,
    };
    literal_annotation_name(annotation.as_ref())
}

fn literal_is_primitive_type(
    typ: Option<&EvalAstType>,
    builtin: ComptimeBuiltin,
    state: &EvalCompileState<'_, '_>,
) -> bool {
    matches!(
        typ,
        Some(Type::Path { segments, args, .. })
            if segments.len() == 1
                && args.is_empty()
                && state
                    .ctx
                    .primitive_env
                    .resolve(&state.module_path, segments[0].as_str()) == Some(builtin)
    )
}

// =========================================================================
// NF equality (alpha + eta)
// =========================================================================

/// Check whether two `Value`s are equal up to alpha-equivalence on
/// closures and eta-equivalence (`λx. f(x) ≡ f` when `x` is not free
/// in `f`). Structural elsewhere.
pub fn nf_eq(a: &Value, b: &Value, ctx: &EvalCtx<'_>) -> bool {
    if structural_recur_stuck_message(a, ctx).is_some()
        || structural_recur_stuck_message(b, ctx).is_some()
    {
        return false;
    };
    let operation = ctx.enter_structural_recur_operation();
    let out = measured_nf_eq_in_operation(a, b, ctx);
    operation.finish_checked(out).unwrap_or(false)
}

fn nf_eq_in_operation(a: &Value, b: &Value, ctx: &EvalCtx<'_>) -> bool {
    execution::compare(a, b, ctx)
}

fn measured_nf_eq_in_operation(a: &Value, b: &Value, ctx: &EvalCtx<'_>) -> bool {
    let Some(metrics) = ctx.metrics.as_deref() else {
        return nf_eq_in_operation(a, b, ctx);
    };
    let start = Instant::now();
    let out = nf_eq_in_operation(a, b, ctx);
    metrics.record_nf_eq(start.elapsed());
    out
}

pub(crate) fn nf_eq_checked(a: &Value, b: &Value, ctx: &EvalCtx<'_>) -> Result<bool, Value> {
    if structural_recur_stuck_message(a, ctx).is_some() {
        return Err(a.clone());
    }
    if structural_recur_stuck_message(b, ctx).is_some() {
        return Err(b.clone());
    }
    let operation = ctx.enter_structural_recur_operation();
    operation.finish_checked(measured_nf_eq_in_operation(a, b, ctx))
}

/// Whether `v` is the trivial re-injection `__mk_<side>__(payload)` of
/// the named payload atom — i.e. `Data { ctor, [Atom(payload)] }`. Used
/// by sum-η to recognize an identity case-split.
fn is_reinjection(v: &Value, ctor: &str, payload: &str) -> bool {
    matches!(v, Value::Data(data)
        if data.ctor() == ctor
            && data.args().len() == 1
            && matches!(&data.args()[0], Value::Atom(a) if a == payload))
}

/// If `v` is a stuck projection `proj_name(.., base)` (an opaque
/// `__fst__` / `__snd__` applied to type-args then a single base
/// value), return the projected base. The base is the *last* argument;
/// any leading args are erased type-names.
fn stuck_projection_base<'v>(v: &'v Value, proj_name: &str) -> Option<&'v Value> {
    if let Value::Stuck(callee, args) = v
        && let Value::Atom(name) = &**callee
        && name == proj_name
    {
        args.last()
    } else {
        None
    }
}

fn atom_eq_under(
    a: &str,
    b: &str,
    a_renaming: &HashMap<String, String>,
    b_renaming: &HashMap<String, String>,
) -> bool {
    let a_canon = a_renaming.get(a).map(|s| s.as_str()).unwrap_or(a);
    let b_canon = b_renaming.get(b).map(|s| s.as_str()).unwrap_or(b);
    a_canon == b_canon
}

fn restore_renaming(renaming: &mut HashMap<String, String>, name: &str, prior: Option<String>) {
    if let Some(prior) = prior {
        renaming.insert(name.to_owned(), prior);
    } else {
        renaming.remove(name);
    }
}

fn fresh_opaque_packet(prefix: &str, width: usize, fresh: &mut usize) -> Value {
    debug_assert!(width > 0);
    let start = *fresh;
    *fresh += width;
    let mut packet = Value::Atom(format!("{prefix}{}", start + width - 1));
    for index in (start..start + width - 1).rev() {
        packet = value_pair(Value::Atom(format!("{prefix}{index}")), packet);
    }
    packet
}

fn closure_partition_width(value: &Value) -> Option<usize> {
    match value {
        // This is the first group's source partition width, not its
        // semantic arity. Closure-vs-closure comparison uses the maximum
        // width to build one shared product packet. Eta comparison retains
        // the closure's own flattened probe so applying the non-closure side
        // preserves the existing application skeleton. A zero-slot group
        // still has one opaque unit-domain position.
        Value::EvalClosure { function, .. } => {
            Some(function.value_groups.first().map_or(0, |group| {
                if group.abi_arity == 0 {
                    1
                } else {
                    group.param_count
                }
            }))
        }
        _ => None,
    }
}

// =========================================================================
// Pretty-printing for diagnostics
// =========================================================================

/// Render a [`Value`] as a human-readable string for diagnostic
/// output. Pure ground values (`Unit`, `Bool`, literal atoms, string
/// atoms) print as their source form; `Stuck` applications render as
/// `callee(arg, …)`; closures print as source-shaped Kio' expressions.
pub fn value_to_string(v: &Value) -> String {
    ValueRenderer {
        newtype_type_heads: None,
        render_closure_origins: false,
    }
    .render(v)
}

/// Render a residual value in the scope of `module` for the REPL.
///
/// Evaluator values preserve the declaration identity of newtype
/// constructors and projectors. A residual can originate in an inlined
/// function from another module, where its source-local import alias has no
/// meaning in the REPL's current module. Re-spell those exact identities
/// through the current scope and introduce ordinary qualified imports only
/// when the scope has no spelling for their owner module.
#[cfg(any(feature = "repl-core", test))]
pub(crate) fn value_to_repl_string<P>(v: &Value, module: &Module<P>) -> String
where
    P: crate::pass::resolve::ResolvePhase,
{
    let mut scan = ReplReferenceScan::default();
    scan_repl_value(v, &[], &mut scan);

    let current_module = module_path_string(module);
    let mut requalifier = crate::pass::typecheck_core::PrimeTypeRequalifier::new(module);
    let mut newtype_type_heads = BTreeMap::new();
    for (owner, type_name) in &scan.referenced_newtypes {
        let forbidden = scan.forbidden_for_owner(owner);
        let can_use_unqualified = !forbidden.contains(type_name)
            && (owner == &current_module
                || module.imports.iter().any(|import_| {
                    matches!(
                        &import_.kind,
                        ImportKind::Selective { items, from }
                            if module_import_path(from) == *owner
                                && items
                                    .iter()
                                    .filter_map(crate::ast::ImportItem::as_name)
                                    .any(|name| name == *type_name)
                    )
                }));
        let head = if can_use_unqualified {
            type_name.clone()
        } else {
            format!(
                "{}.{}",
                requalifier.ensure_module_import_avoiding(owner, &forbidden),
                type_name
            )
        };
        newtype_type_heads.insert((owner.clone(), type_name.clone()), head);
    }

    let expression = ValueRenderer {
        newtype_type_heads: Some(&newtype_type_heads),
        render_closure_origins: true,
    }
    .render(v);
    let imports = requalifier.take_imports();
    if imports.is_empty() {
        expression
    } else {
        let prelude = imports
            .iter()
            .map(crate::pretty::pretty_import)
            .collect::<Vec<_>>()
            .join("\n");
        format!("{prelude}\n\n{expression}")
    }
}

#[cfg(any(feature = "repl-core", test))]
#[derive(Default)]
struct ReplReferenceScan {
    referenced_newtypes: BTreeSet<(String, String)>,
    forbidden_by_owner: BTreeMap<String, BTreeSet<String>>,
    atom_heads: BTreeSet<String>,
}

#[cfg(any(feature = "repl-core", test))]
impl ReplReferenceScan {
    fn record_newtype<'a>(
        &mut self,
        identity: &NewtypeCtorIdentity,
        bound: impl Iterator<Item = &'a String>,
    ) {
        self.referenced_newtypes
            .insert((identity.module_path.clone(), identity.type_name.clone()));
        self.forbidden_by_owner
            .entry(identity.module_path.clone())
            .or_default()
            .extend(bound.cloned());
    }

    fn record_atom(&mut self, name: &str) {
        if let Some(head) = name.split('.').next()
            && !head.is_empty()
        {
            self.atom_heads.insert(head.to_owned());
        }
    }

    fn forbidden_for_owner(&self, owner: &str) -> BTreeSet<String> {
        let mut forbidden = self.atom_heads.clone();
        if let Some(scoped) = self.forbidden_by_owner.get(owner) {
            forbidden.extend(scoped.iter().cloned());
        }
        forbidden
    }
}

#[cfg(any(feature = "repl-core", test))]
fn scan_repl_value(v: &Value, enclosing_bound: &[String], scan: &mut ReplReferenceScan) {
    match v {
        Value::NewtypeMember(member) => {
            scan.record_newtype(&member.constructor, enclosing_bound.iter());
        }
        Value::Data(data) => {
            if data.structural_recur_identity().is_some() {
                return;
            }
            if let DataConstructorIdentity::Newtype(identity) = &data.identity {
                scan.record_newtype(identity, enclosing_bound.iter());
            }
            for arg in data.args() {
                scan_repl_value(arg, enclosing_bound, scan);
            }
        }
        Value::CaseSplit {
            scrutinee,
            left_payload,
            left,
            right_payload,
            right,
        } => {
            scan_repl_value(scrutinee, enclosing_bound, scan);
            let mut left_bound = enclosing_bound.to_vec();
            left_bound.push(left_payload.clone());
            scan_repl_value(left, &left_bound, scan);
            let mut right_bound = enclosing_bound.to_vec();
            right_bound.push(right_payload.clone());
            scan_repl_value(right, &right_bound, scan);
        }
        Value::Seq { value, body } => {
            scan_repl_value(value, enclosing_bound, scan);
            scan_repl_value(body, enclosing_bound, scan);
        }
        Value::Stuck(callee, args) => {
            scan_repl_value(callee, enclosing_bound, scan);
            for arg in args.iter() {
                scan_repl_value(arg, enclosing_bound, scan);
            }
        }
        Value::Atom(name) => scan.record_atom(name),
        #[cfg(feature = "surface")]
        Value::Projected(_) => {}
        Value::Unit
        | Value::Bool(_)
        | Value::IntAtom(_, _)
        | Value::FloatAtom(_, _)
        | Value::StrAtom(_)
        | Value::ReflType(_)
        | Value::CheckedTerm(_)
        | Value::ReflTypeArity(_)
        | Value::ReflTypeVar { .. }
        | Value::ReflTypeName { .. }
        | Value::DiagnosticText(_)
        | Value::Primitive(_)
        | Value::EvalClosure { .. }
        | Value::StructuralRecur { .. } => {}
    }
}

struct ValueRenderer<'a> {
    newtype_type_heads: Option<&'a BTreeMap<(String, String), String>>,
    render_closure_origins: bool,
}

impl ValueRenderer<'_> {
    fn render(&self, v: &Value) -> String {
        match v {
            Value::Unit => "()".to_string(),
            Value::Bool(true) => ".t".to_string(),
            Value::Bool(false) => ".f".to_string(),
            Value::IntAtom(d, ann) | Value::FloatAtom(d, ann) => match ann {
                Some(t) => format!("{d}({})", t.rsplit('.').next().unwrap_or(t)),
                None => d.clone(),
            },
            Value::StrAtom(s) => format!("{s:?}"),
            Value::DiagnosticText(s) => format!("{s:?}"),
            Value::ReflType(t) => format!(
                "<type {}>",
                crate::pass::typecheck_core::display_type(t.as_type())
            ),
            Value::CheckedTerm(_) => "<checked_term>".to_string(),
            #[cfg(feature = "surface")]
            Value::Projected(projected) => if projected.is_type() {
                "<projected-type>"
            } else {
                "<projected-checked-term>"
            }
            .to_string(),
            Value::ReflTypeArity(n) => format!("<arity {n}>"),
            Value::ReflTypeVar { name, arity } => format!("<type-var {name}/{arity}>"),
            Value::ReflTypeName {
                segments,
                param_arities,
            } => format!("<type-name {} {:?}>", segments.join("."), param_arities),
            Value::StructuralRecur { .. } => "<comptime-recur>".to_string(),
            Value::Primitive(builtin) => builtin.public_name().to_string(),
            Value::NewtypeMember(member) => self.newtype_head(&member.constructor).map_or_else(
                || member.display.clone(),
                |head| format!("{head}.{}", member.member_name),
            ),
            Value::Atom(name) => name.clone(),
            Value::Data(data) => {
                if let Some(identity) = data.structural_recur_identity() {
                    return match identity {
                        StructuralRecurDataIdentity::Primitive { .. } => {
                            ComptimeBuiltin::StructuralRecur.public_name().to_owned()
                        }
                        StructuralRecurDataIdentity::InitialRejected => {
                            "<structural-recur-initial-rejected>".to_owned()
                        }
                        StructuralRecurDataIdentity::SiteRejected { .. } => {
                            "<structural-recur-origin-rejected>".to_owned()
                        }
                    };
                }
                let ctor = match &data.identity {
                    DataConstructorIdentity::Newtype(identity) => {
                        self.newtype_head(identity).map_or_else(
                            || data.ctor().to_owned(),
                            |head| format!("{head}.{}", identity.constructor_name),
                        )
                    }
                    DataConstructorIdentity::Core(_) => data.ctor().to_owned(),
                    DataConstructorIdentity::StructuralRecur(_) => {
                        unreachable!("structural-recursion evaluator data renders opaquely")
                    }
                    #[cfg(feature = "surface")]
                    DataConstructorIdentity::MarkedComptimeProof(_) => {
                        "<marked-comptime-proof>".to_owned()
                    }
                    #[cfg(feature = "surface")]
                    DataConstructorIdentity::FillContext(_) => "<fill-context>".to_owned(),
                };
                let arg_strs: Vec<String> =
                    data.args().iter().map(|arg| self.render(arg)).collect();
                format!("{ctor}({})", arg_strs.join(", "))
            }
            Value::CaseSplit {
                scrutinee,
                left_payload,
                left,
                right_payload,
                right,
            } => format!(
                "case {} {{ left({left_payload}) -> {}, right({right_payload}) -> {} }}",
                self.render(scrutinee),
                self.render(left),
                self.render(right),
            ),
            Value::Seq { value, body } => {
                format!("{}; {}", self.render(value), self.render(body))
            }
            Value::Stuck(c, args) => {
                let arg_strs: Vec<String> = args.iter().map(|arg| self.render(arg)).collect();
                format!("{}({})", self.render(c), arg_strs.join(", "))
            }
            Value::EvalClosure { function, .. } => {
                if self.render_closure_origins {
                    render_closure_origin(function)
                } else {
                    render_closure_source(function)
                }
            }
        }
    }

    fn newtype_head(&self, identity: &NewtypeCtorIdentity) -> Option<&str> {
        self.newtype_type_heads?
            .get(&(identity.module_path.clone(), identity.type_name.clone()))
            .map(String::as_str)
    }
}

fn render_closure_source(function: &EvalFunction) -> String {
    let params = function
        .params
        .iter()
        .map(|param| param.name.as_str())
        .collect::<Vec<_>>()
        .join(", ");
    format!(
        ".({params}) {{ {} }}",
        render_eval_expr(&function.diagnostic_body)
    )
}

fn render_eval_expr(expr: &EvalAstExpr) -> String {
    match expr {
        crate::ast::Expr::BlockCall { ext, .. } => match *ext {},
        Expr::Unit { .. } => "()".to_string(),
        Expr::BoolLit { value: true, .. } => ".t".to_string(),
        Expr::BoolLit { value: false, .. } => ".f".to_string(),
        Expr::IntLit { digits, .. } | Expr::FloatLit { digits, .. } => digits.clone(),
        Expr::StrLit { value, .. } => format!("{value:?}"),
        Expr::Path { segments, .. } => segments.join("."),
        Expr::Call { callee, args, .. } => {
            let args = args
                .iter()
                .filter_map(|arg| match arg {
                    CallArg::Value(value) => Some(render_eval_expr(value)),
                    CallArg::Type(_) => None,
                })
                .collect::<Vec<_>>()
                .join(", ");
            format!("{}({args})", render_eval_expr(callee))
        }
        Expr::Let {
            name, value, body, ..
        } => format!(
            "let {name} = {}; {}",
            render_eval_expr(value),
            render_eval_expr(body)
        ),
        Expr::Seq { value, body, .. } => {
            format!("{}; {}", render_eval_expr(value), render_eval_expr(body))
        }
        Expr::FnExpr { sig, body, .. } => {
            let params = collect_value_param_names(&sig.params).join(", ");
            format!(".({params}) {{ {} }}", render_eval_expr(body))
        }
        Expr::Elaborator { ext, .. }
        | Expr::RecOrder { ext, .. }
        | Expr::RecQuote { ext, .. }
        | Expr::UserElaborator { ext, .. }
        | Expr::Tuple { ext, .. }
        | Expr::LabelValue { ext, .. }
        | Expr::RowLet { ext, .. }
        | Expr::FnPlaceholder { ext, .. }
        | Expr::OpChain { ext, .. }
        | Expr::RecCall { ext, .. }
        | Expr::Ufcs { ext, .. }
        | Expr::EnrichedTuple { ext, .. }
        | Expr::EnrichedProject { ext, .. }
        | Expr::EnrichedInject { ext, .. }
        | Expr::EnrichedMatch { ext, .. }
        | Expr::EnrichedConditional { ext, .. }
        | Expr::EnrichedRecord { ext, .. }
        | Expr::EnrichedFieldGet { ext, .. }
        | Expr::LowHostCall { ext, .. }
        | Expr::LowModuleCall { ext, .. }
        | Expr::LowQualifiedModuleCall { ext, .. }
        | Expr::LowQualifiedNewtypeMember { ext, .. }
        | Expr::LowNewtypeCtor { ext, .. }
        | Expr::LowNewtypeProj { ext, .. }
        | Expr::LowClosureCall { ext, .. }
        | Expr::LowIndirectCall { ext, .. }
        | Expr::LowTypeApplication { ext, .. }
        | Expr::LowAbsurdCall { ext, .. }
        | Expr::LowCpsProjectorApply { ext, .. }
        | Expr::LowBoundRef { ext, .. }
        | Expr::LowHostFnValueRef { ext, .. }
        | Expr::LowModuleFnValueRef { ext, .. } => match *ext {},
    }
}

fn render_closure_origin(function: &EvalFunction) -> String {
    let owner = if function.owner_module_path.is_empty() {
        String::new()
    } else {
        format!("{}.", function.owner_module_path)
    };
    let identity = match &function.source_origin {
        EvalFunctionOrigin::Named { item } => format!("{owner}{item}"),
        EvalFunctionOrigin::Anonymous { enclosing, span } => {
            let enclosing = enclosing
                .as_deref()
                .map_or_else(String::new, |name| format!("{name}::"));
            format!("{owner}{enclosing}<fn@{}-{}>", span.start, span.end)
        }
    };
    let params = function
        .value_groups
        .iter()
        .map(|group| {
            let names = function.params[group.param_start..group.param_start + group.param_count]
                .iter()
                .map(|param| param.name.as_str())
                .collect::<Vec<_>>()
                .join(", ");
            format!("({names})")
        })
        .collect::<String>();
    format!("<closure {identity}{params}>")
}

pub fn structural_recur_stuck_message(value: &Value, ctx: &EvalCtx<'_>) -> Option<String> {
    // Totality failures are represented internally as fault values, so a deep
    // but finite evaluation may wrap one in many ordinary value constructors.
    // Scan iteratively:
    // an arbitrary recursion cap could silently reclassify that failure, while
    // pointer deduplication keeps shared residual subgraphs proportional to the
    // represented values and edges.
    let mut pending = vec![value];
    let mut visited = HashSet::<*const Value>::new();
    while let Some(value) = pending.pop() {
        if !visited.insert(value as *const Value) {
            continue;
        }
        match value {
            Value::Stuck(callee, args) => {
                if let Value::StructuralRecur {
                    root_measure,
                    current_measure,
                    ..
                } = callee.as_ref()
                {
                    return Some(structural_recur_recursive_stuck_message(
                        *root_measure,
                        *current_measure,
                        args,
                        ctx,
                    ));
                }
                pending.extend(args.iter().rev());
                pending.push(callee.as_ref());
            }
            Value::Data(data) => match data.structural_recur_identity() {
                Some(StructuralRecurDataIdentity::Primitive { .. }) => {}
                Some(StructuralRecurDataIdentity::InitialRejected) => {
                    return Some(
                        "`__structural_recur__` got stuck because its initial fuel has no structural compile-time measure"
                            .to_string(),
                    );
                }
                Some(StructuralRecurDataIdentity::SiteRejected {
                    root_measure,
                    current_measure,
                    next_measure,
                    ..
                }) => {
                    return Some(structural_recur_site_reentry_stuck_message(
                        *root_measure,
                        *current_measure,
                        *next_measure,
                    ));
                }
                None => pending.extend(data.args().iter().rev()),
            },
            Value::CaseSplit {
                scrutinee,
                left,
                right,
                ..
            } => {
                pending.push(right.as_ref());
                pending.push(left.as_ref());
                pending.push(scrutinee.as_ref());
            }
            Value::Seq { value, body } => {
                pending.push(body.as_ref());
                pending.push(value.as_ref());
            }
            _ => {}
        }
    }
    None
}

fn structural_recur_site_reentry_stuck_message(
    root_measure: usize,
    current_measure: usize,
    next_measure: Option<usize>,
) -> String {
    let Some(next_measure) = next_measure else {
        return format!(
            "`__structural_recur__` got stuck because a same helper origin re-entry used fuel with no recursive structural measure (root={root_measure}, current={current_measure}, next=unmeasurable)"
        );
    };
    format!(
        "`__structural_recur__` got stuck because a same helper origin re-entry did not descend from the current fuel measure (root={root_measure}, current={current_measure}, next={next_measure})"
    )
}

fn structural_recur_recursive_stuck_message(
    root_measure: usize,
    current_measure: usize,
    args: &[Value],
    ctx: &EvalCtx<'_>,
) -> String {
    if !matches!(args.len(), 1 | 2) {
        let next = match args.first() {
            Some(fuel) => fuel_measure(fuel, ctx)
                .map_or_else(|| "unmeasurable".to_string(), |measure| measure.to_string()),
            None => "missing".to_string(),
        };
        return format!(
            "`__structural_recur__` got stuck because a recursive call did not provide one product packet or two flattened arguments (root={root_measure}, current={current_measure}, next={next})"
        );
    }
    let next_fuel = if let [packet] = args {
        project_product_value("__fst__", packet)
    } else {
        args[0].clone()
    };
    let Some(next_measure) = fuel_measure(&next_fuel, ctx) else {
        return format!(
            "`__structural_recur__` got stuck because a recursive call used fuel with no structural compile-time measure (root={root_measure}, current={current_measure}, next=unmeasurable)"
        );
    };
    if next_measure < current_measure && next_measure >= root_measure {
        return format!(
            "`__structural_recur__` got stuck because a recursive call did not stay below the root fuel measure (root={root_measure}, current={current_measure}, next={next_measure})"
        );
    }
    format!(
        "`__structural_recur__` got stuck because a recursive call did not descend from the current fuel measure (root={root_measure}, current={current_measure}, next={next_measure})"
    )
}

