    #[test]
    fn checked_signature_instantiation_preserves_empty_value_group() {
        let sig =
            Signature::<EvalPhase>::from_groups(vec![
                crate::ast::SignatureGroup::Value(Vec::new()),
            ]);
        let mut canonicalizer = CheckedTermNameCanonicalizer::default();
        let sig = canonicalizer.signature(&sig, &mut Vec::new(), &mut Vec::new());
        assert_eq!(
            sig.groups,
            vec![crate::ast::SignatureGroupKind::Value { len: 0 }]
        );
        let mut no_types = |_ty: &Type<EvalPhase>| -> Type<PrePrime> {
            unreachable!("an empty signature has no parameter types")
        };

        let instantiated = instantiate_checked_signature(&sig, zero_span(), &mut no_types);

        assert!(instantiated.params.is_empty());
        assert_eq!(
            instantiated.groups,
            vec![crate::ast::SignatureGroupKind::Value { len: 0 }]
        );
    }

    struct TestEquiv {
        sig: Signature<UncheckedPrime>,
        terms: Vec<Expr<UncheckedPrime>>,
    }

    struct TestEvalModule {
        module: crate::ast::Module<UncheckedPrime>,
        equivs: Vec<TestEquiv>,
    }

    impl std::ops::Deref for TestEvalModule {
        type Target = crate::ast::Module<UncheckedPrime>;

        fn deref(&self) -> &Self::Target {
            &self.module
        }
    }

    fn parse_module(src: &str) -> TestEvalModule {
        use std::path::PathBuf;
        let surface = crate::pass::parser::parse(src).expect("parse");
        let desugared = crate::pass::desugar::desugar_module(surface).expect("desugar");
        let path = PathBuf::from("test.kio");
        let (mut lowered, _) =
            crate::pass::label_elab::elaborate_package(vec![(path, desugared)], None)
                .expect("label_elab");
        let module = lowered.pop().expect("at least one module").1;
        let module_path = module
            .path
            .segments
            .iter()
            .map(PathSegment::as_str)
            .collect::<Vec<_>>()
            .join("/");
        let elaborations = Elaborations::new();
        let equivs = module
            .items
            .iter()
            .filter_map(|item| match item {
                Item::Equiv(equiv, _) => Some(TestEquiv {
                    sig: crate::pass::substitute::substitute_signature_for_eval(
                        &equiv.sig,
                        &elaborations,
                        &module_path,
                        None,
                        Some(&module),
                    ),
                    terms: equiv
                        .terms
                        .iter()
                        .map(|term| {
                            crate::pass::substitute::substitute_expr_for_eval(
                                &term.body,
                                &elaborations,
                                &module_path,
                                None,
                                Some(&module),
                            )
                        })
                        .collect(),
                }),
                _ => None,
            })
            .collect();
        let module = crate::pass::substitute::substitute_module_for_eval(
            &module,
            &elaborations,
            &module_path,
            None,
        );
        TestEvalModule { module, equivs }
    }

    fn parse_module_with_bodies<const N: usize>(
        src: &str,
        bodies: [&str; N],
    ) -> (TestEvalModule, [Expr<UncheckedPrime>; N]) {
        assert!(
            !src.contains("fixture_body"),
            "fixture helper name collision"
        );
        let mut augmented = src.to_owned();
        for (index, body) in bodies.iter().enumerate() {
            augmented.push_str(&format!("\nfn fixture_body{index}() -> . {{ {body} }}"));
        }
        let mut module = parse_module(&augmented);
        let mut extracted = Vec::with_capacity(N);
        for index in (0..N).rev() {
            let expected = format!("fixture_body{index}");
            let Some(Item::FnDef(def)) = module.module.items.pop() else {
                panic!("appended fixture function missing: {expected}");
            };
            assert_eq!(def.name, expected, "appended fixture identity changed");
            extracted.push(def.body);
        }
        extracted.reverse();
        (
            module,
            extracted
                .try_into()
                .unwrap_or_else(|_| unreachable!("extracted fixture body count changed")),
        )
    }

