    #[test]
    fn host_type_path_matches_distinguishes_same_name_across_modules() {
        let seg = |n: &str| PathSegment::synth(n, zero_span());
        // Exact module-qualified match.
        assert!(host_type_path_matches(
            &[seg("testapi"), seg("String")],
            "testapi",
            "String"
        ));
        // Two distinct multi-segment paths must NOT conflate — the
        // open-world fix: a dependency's re-rooted `elab/testapi.String`
        // is a different host type from the consumer's `testapi.String`,
        // even though both are `role(str)`.
        assert!(!host_type_path_matches(
            &[seg("elab"), seg("testapi"), seg("String")],
            "testapi",
            "String"
        ));
        assert!(!host_type_path_matches(
            &[seg("testapi"), seg("String")],
            "elab/testapi",
            "String"
        ));
        // Canonical matching never treats a bare type variable as a
        // same-leaf host type.
        assert!(!host_type_path_matches(
            &[seg("String")],
            "testapi",
            "String"
        ));
        assert!(host_type_path_matches(
            &[seg("elab"), seg("testapi"), seg("String")],
            "elab/testapi",
            "String"
        ));
        // A different leaf name never matches.
        assert!(!host_type_path_matches(
            &[seg("testapi"), seg("Int")],
            "testapi",
            "String"
        ));
    }

    fn equiv_terms(m: &TestEvalModule) -> Vec<&Expr<EvalPhase>> {
        m.equivs.first().expect("equiv item").terms.iter().collect()
    }

    fn fn_def_map(m: &crate::ast::Module<EvalPhase>) -> HashMap<&str, &FnDef<EvalPhase>> {
        let mut out = HashMap::new();
        for item in &m.items {
            if let Item::FnDef(d) = item {
                out.insert(d.name.as_str(), d);
            }
        }
        out
    }

    #[test]
    fn evaluator_function_cache_key_retains_nominal_generation_and_content() {
        fn hash_writes(value: &impl std::hash::Hash) -> Vec<u8> {
            #[derive(Default)]
            struct RecordingHasher(Vec<u8>);

            impl std::hash::Hasher for RecordingHasher {
                fn finish(&self) -> u64 {
                    0
                }

                fn write(&mut self, bytes: &[u8]) {
                    self.0.extend_from_slice(bytes);
                }
            }

            let mut hasher = RecordingHasher::default();
            value.hash(&mut hasher);
            hasher.0
        }

        let first = parse_module("module same; fn f(x: .) -> . { x }");
        let rebuilt = parse_module("module same; fn f(x: .) -> . { x }");
        let changed = parse_module("module same; fn f(x: .) -> . { () }");
        let first_defs = fn_def_map(&first);
        let rebuilt_defs = fn_def_map(&rebuilt);
        let changed_defs = fn_def_map(&changed);

        let first_generation = EvalSourceGeneration::fresh();
        let rebuilt_generation = EvalSourceGeneration::fresh();
        let first_key = eval_function_cache_key_for_def(first_defs["f"], "same", &first_generation);
        let same_generation_key =
            eval_function_cache_key_for_def(rebuilt_defs["f"], "same", &first_generation);
        let rebuilt_key =
            eval_function_cache_key_for_def(rebuilt_defs["f"], "same", &rebuilt_generation);
        let changed_key =
            eval_function_cache_key_for_def(changed_defs["f"], "same", &first_generation);

        assert_eq!(first_key, same_generation_key);
        assert_ne!(first_key, rebuilt_key);
        assert_ne!(first_key, changed_key);
        let first_hash = hash_writes(&first_key);
        assert!(!first_hash.is_empty());
        assert_eq!(first_hash, hash_writes(&same_generation_key));
        assert_ne!(first_hash, hash_writes(&rebuilt_key));

        let exact_key = |function: EvalFunctionCacheKey| ExactCallMemoKey {
            function,
            captured: Vec::new(),
            args: vec![EvalValueMemoKey::Unit],
        };
        assert_eq!(
            hash_writes(&exact_key(first_key.clone())),
            hash_writes(&exact_key(same_generation_key.clone()))
        );
        assert_ne!(
            hash_writes(&exact_key(first_key.clone())),
            hash_writes(&exact_key(rebuilt_key.clone()))
        );
        assert_eq!(exact_key(first_key.clone()), exact_key(same_generation_key));
        assert_ne!(exact_key(first_key), exact_key(rebuilt_key));
    }

    #[test]
    fn distinct_raw_helper_nodes_with_identical_spans_keep_distinct_origins() {
        let span = zero_span();
        let expr = Expr::Seq {
            occurrence: Default::default(),
            value: Box::new(path_expr("__structural_recur__")),
            body: Box::new(path_expr("__structural_recur__")),
            meta: Meta::new(span),
        };
        let ctx = test_primitive_ctx(&[ComptimeBuiltin::StructuralRecur]);
        let compiled = compile_eval_root(&expr, &ctx, Vec::new()).expect("compile helper pair");
        let EvalExpr::Seq { value, body } = compiled.as_ref() else {
            panic!("helper pair did not retain its sequence shape");
        };
        let site = |expr: &EvalExpr| {
            let EvalExpr::StructuralRecurPrimitive(data) = expr else {
                panic!("expected a source-origin helper token, got {expr:?}");
            };
            let Some(StructuralRecurDataIdentity::Primitive { site, .. }) =
                data.structural_recur_identity()
            else {
                panic!("helper token lost its private source origin");
            };
            site.clone()
        };
        let left = site(value);
        let right = site(body);
        assert_ne!(left, right, "distinct AST nodes shared an origin by span");

        let fuel = refl_type_value(Type::Unit { meta: zero_meta() });
        let (_left_measure, left_guard) = ctx
            .enter_structural_recur_site(&left, &fuel)
            .expect("first helper origin");
        let (_right_measure, right_guard) = ctx
            .enter_structural_recur_site(&right, &fuel)
            .expect("an equal measure at a distinct helper node is independent");
        drop(right_guard);
        drop(left_guard);
    }

    #[test]
    fn distinct_raw_lambda_nodes_with_identical_spans_keep_distinct_cache_keys() {
        let module = parse_module("module x; equiv sample { .(value: .) { value }; () }");
        let lambda = equiv_terms(&module)[0].clone();
        let expr = Expr::Seq {
            occurrence: Default::default(),
            value: Box::new(lambda.clone()),
            body: Box::new(lambda),
            meta: zero_meta(),
        };
        let compiled = compile_eval_root(&expr, &EvalCtx::new(), Vec::new())
            .expect("compile same-span lambda pair");
        let EvalExpr::Seq { value, body } = compiled.as_ref() else {
            panic!("lambda pair did not retain its sequence shape");
        };
        let cache_key = |expr: &EvalExpr| {
            let EvalExpr::FnExpr { function, .. } = expr else {
                panic!("expected a compiled lambda, got {expr:?}");
            };
            function.cache_key.clone()
        };

        assert_ne!(
            cache_key(value),
            cache_key(body),
            "distinct same-span lambda nodes shared one compiled-function cache identity"
        );
    }

    #[test]
    fn artifact_generation_namespaces_source_origins_across_env_and_higher_order_use() {
        let source =
            "module x; import __comptime__; fn held(value: .) -> . { __structural_recur__ }";
        let artifact = lowered_package(&[("x.kio", source)]);
        let cloned = artifact.clone();
        let rebuilt = lowered_package(&[("x.kio", source)]);
        assert!(Arc::ptr_eq(&artifact.package, &cloned.package));
        assert!(!Arc::ptr_eq(&artifact.package, &rebuilt.package));
        assert_eq!(artifact.source_generation(), cloned.source_generation());
        assert_ne!(artifact.source_generation(), rebuilt.source_generation());

        let module = &artifact.module("x").expect("artifact module").module;
        let cloned_module = &cloned.module("x").expect("cloned module").module;
        let rebuilt_module = &rebuilt.module("x").expect("rebuilt module").module;
        let ctx = AuthenticatedEvalCtx::for_module(&artifact, module, "x")
            .expect("authenticated artifact context");
        let cloned_ctx = AuthenticatedEvalCtx::for_module(&cloned, cloned_module, "x")
            .expect("authenticated cloned context");
        let rebuilt_ctx = AuthenticatedEvalCtx::for_module(&rebuilt, rebuilt_module, "x")
            .expect("authenticated rebuilt context");
        let helper_expr = path_expr("__structural_recur__");
        let token = eval_authenticated(&helper_expr, &Env::new(), &ctx);
        let cloned_token = eval_authenticated(&helper_expr, &Env::new(), &cloned_ctx);
        let rebuilt_token = eval_authenticated(&helper_expr, &Env::new(), &rebuilt_ctx);
        let token_site = structural_recur_primitive_site(&token).expect("source token");
        assert_ne!(
            ctx.public_structural_recur_site.as_ref(),
            token_site.as_ref()
        );
        assert_eq!(
            structural_recur_primitive_site(&cloned_token),
            Some(token_site)
        );
        assert_ne!(
            structural_recur_primitive_site(&rebuilt_token),
            Some(token_site)
        );

        let raw_ctx = EvalCtx::for_module(&artifact, module, "x")
            .expect("public package context remains deauthenticated");
        let raw_first = eval(&helper_expr, &Env::new(), &raw_ctx);
        let raw_second = eval(&helper_expr, &Env::new(), &raw_ctx);
        assert_ne!(
            structural_recur_primitive_site(&raw_first),
            structural_recur_primitive_site(&raw_second)
        );
        assert_ne!(
            structural_recur_primitive_site(&raw_first),
            Some(token_site)
        );

        let forward = Value::EvalClosure {
            function: test_eval_function(&["value"], EvalExpr::Local(0)),
            captured: Vec::<Value>::new().into(),
        };
        let step = Value::EvalClosure {
            function: test_eval_function(&["recur", "fuel", "input"], EvalExpr::Local(2)),
            captured: Vec::<Value>::new().into(),
        };
        let fuel = refl_type_value(Type::Unit { meta: zero_meta() });
        let indirect_call = Expr::synth_call(
            Expr::synth_call(
                Expr::synth_call(
                    path_expr("forward"),
                    vec![CallArg::Value(path_expr("helper"))],
                    zero_span(),
                ),
                vec![CallArg::Value(path_expr("proof"))],
                zero_span(),
            ),
            vec![
                CallArg::Value(path_expr("fuel")),
                CallArg::Value(path_expr("input")),
                CallArg::Value(path_expr("step")),
            ],
            zero_span(),
        );
        let evaluate_nested = |helper: Value| {
            let mut env = Env::new();
            env.insert("forward".to_owned(), forward.clone());
            env.insert("helper".to_owned(), helper);
            env.insert("proof".to_owned(), Value::Atom("opaque-proof".to_owned()));
            env.insert("fuel".to_owned(), fuel.clone());
            env.insert("input".to_owned(), Value::Unit);
            env.insert("step".to_owned(), step.clone());
            let (_measure, active) = ctx
                .enter_structural_recur_site(token_site, &fuel)
                .expect("destination source origin");
            let result = eval_authenticated(&indirect_call, &env, &ctx);
            drop(active);
            result
        };

        let same_generation = evaluate_nested(cloned_token);
        assert_eq!(
            structural_recur_stuck_message(&same_generation, &ctx),
            Some(
                "`__structural_recur__` got stuck because a same helper origin re-entry did not descend from the current fuel measure (root=1, current=1, next=1)"
                    .to_owned()
            )
        );
        assert!(matches!(evaluate_nested(rebuilt_token), Value::Unit));
    }

    #[test]
    fn authenticated_generation_partitions_shared_caches_while_public_roots_stay_local() {
        let source =
            "module x; import __comptime__; fn held(value: .) -> . { __structural_recur__ }";
        let artifact = lowered_package(&[("x.kio", source)]);
        let cloned = artifact.clone();
        let rebuilt = lowered_package(&[("x.kio", source)]);
        let module = &artifact.module("x").expect("artifact module").module;
        let cloned_module = &cloned.module("x").expect("cloned module").module;
        let rebuilt_module = &rebuilt.module("x").expect("rebuilt module").module;
        let eval_functions = SharedEvalFunctionCache::default();
        let closures = SharedFnClosureCache::default();
        let ctx = AuthenticatedEvalCtx::for_module(&artifact, module, "x")
            .expect("artifact context")
            .with_eval_function_cache(eval_functions.clone())
            .with_fn_closure_cache(closures.clone());
        let cloned_ctx = AuthenticatedEvalCtx::for_module(&cloned, cloned_module, "x")
            .expect("cloned context")
            .with_eval_function_cache(eval_functions.clone())
            .with_fn_closure_cache(closures.clone());
        let rebuilt_ctx = AuthenticatedEvalCtx::for_module(&rebuilt, rebuilt_module, "x")
            .expect("rebuilt context")
            .with_eval_function_cache(eval_functions.clone())
            .with_fn_closure_cache(closures.clone());
        let held = path_expr("held");

        let first = eval_authenticated(&held, &Env::new(), &ctx);
        let same_generation = eval_authenticated(&held, &Env::new(), &cloned_ctx);
        let (
            Value::EvalClosure {
                function: first_fn, ..
            },
            Value::EvalClosure {
                function: cloned_fn,
                ..
            },
        ) = (&first, &same_generation)
        else {
            panic!("held must evaluate to closures")
        };
        assert!(EvalRef::ptr_eq(first_fn, cloned_fn));
        assert_eq!(
            eval_functions.inner.lock().expect("function cache").len(),
            1
        );
        assert_eq!(closures.inner.lock().expect("closure cache").len(), 1);

        let independently_rebuilt = eval_authenticated(&held, &Env::new(), &rebuilt_ctx);
        let Value::EvalClosure {
            function: rebuilt_fn,
            ..
        } = &independently_rebuilt
        else {
            panic!("rebuilt held must evaluate to a closure")
        };
        assert!(!EvalRef::ptr_eq(first_fn, rebuilt_fn));
        assert_eq!(
            eval_functions.inner.lock().expect("function cache").len(),
            2
        );
        assert_eq!(closures.inner.lock().expect("closure cache").len(), 2);

        let raw_functions = SharedEvalFunctionCache::default();
        let raw_closures = SharedFnClosureCache::default();
        let raw_ctx = EvalCtx::for_module(&artifact, module, "x")
            .expect("public package context")
            .with_eval_function_cache(raw_functions.clone())
            .with_fn_closure_cache(raw_closures.clone());
        let raw_first = eval(&held, &Env::new(), &raw_ctx);
        let raw_second = eval(&held, &Env::new(), &raw_ctx);
        let (
            Value::EvalClosure {
                function: raw_first_fn,
                ..
            },
            Value::EvalClosure {
                function: raw_second_fn,
                ..
            },
        ) = (&raw_first, &raw_second)
        else {
            panic!("public roots must evaluate held to closures")
        };
        assert!(!EvalRef::ptr_eq(raw_first_fn, raw_second_fn));
        assert!(
            raw_functions
                .inner
                .lock()
                .expect("raw function cache")
                .is_empty()
        );
        assert!(
            raw_closures
                .inner
                .lock()
                .expect("raw closure cache")
                .is_empty()
        );
    }

    #[test]
    fn authenticated_compile_and_closure_caches_preserve_cold_warm_and_shared_results() {
        let artifact = lowered_package(&[("x.kio", "module x; fn held(value: .) -> . { value }")]);
        let same_generation = artifact.clone();
        let module = &artifact.module("x").expect("artifact module").module;
        let same_generation_module = &same_generation
            .module("x")
            .expect("same-generation module")
            .module;
        let eval_functions = SharedEvalFunctionCache::default();
        let closures = SharedFnClosureCache::default();
        let metrics = Arc::new(EvalMetrics::default());
        let ctx = AuthenticatedEvalCtx::for_module(&artifact, module, "x")
            .expect("artifact context")
            .with_metrics(metrics.clone())
            .with_eval_function_cache(eval_functions.clone())
            .with_fn_closure_cache(closures.clone());
        let same_generation_ctx =
            AuthenticatedEvalCtx::for_module(&same_generation, same_generation_module, "x")
                .expect("same-generation context")
                .with_metrics(metrics.clone())
                .with_eval_function_cache(eval_functions.clone())
                .with_fn_closure_cache(closures.clone());
        let held = path_expr("held");

        let cold = eval_authenticated(&held, &Env::new(), &ctx);
        let warm = eval_authenticated(&held, &Env::new(), &ctx);
        let shared = eval_authenticated(&held, &Env::new(), &same_generation_ctx);
        let (
            Value::EvalClosure {
                function: cold_fn,
                captured: cold_captured,
            },
            Value::EvalClosure {
                function: warm_fn,
                captured: warm_captured,
            },
            Value::EvalClosure {
                function: shared_fn,
                captured: shared_captured,
            },
        ) = (&cold, &warm, &shared)
        else {
            panic!("held must evaluate to a closure in every cache state")
        };
        assert!(EvalRef::ptr_eq(cold_fn, warm_fn));
        assert!(EvalRef::ptr_eq(cold_fn, shared_fn));
        assert!(EvalRef::ptr_eq(cold_captured, warm_captured));
        assert!(EvalRef::ptr_eq(cold_captured, shared_captured));
        let cached_function = {
            let functions = eval_functions.inner.lock().expect("function cache");
            assert_eq!(functions.len(), 1);
            functions
                .values()
                .next()
                .cloned()
                .expect("one cached function")
        };
        assert!(EvalRef::ptr_eq(&cached_function, cold_fn));
        assert_eq!(closures.inner.lock().expect("closure cache").len(), 1);
        assert_eq!(metrics.snapshot().closure_builds, 1);

        let cold_result = apply(cold, vec![Value::Unit], &ctx);
        let warm_result = apply(warm, vec![Value::Unit], &ctx);
        let shared_result = apply(shared, vec![Value::Unit], &same_generation_ctx);
        let comparison_ctx = EvalCtx::new();
        assert!(nf_eq(&cold_result, &warm_result, &comparison_ctx));
        assert!(nf_eq(&cold_result, &shared_result, &comparison_ctx));
        assert!(matches!(cold_result, Value::Unit));
    }

    #[test]
    fn artifact_generation_prevents_primitive_grant_cache_transport_in_both_warm_orders() {
        let authorized_source =
            "module x; import __comptime__; fn held(value: .) -> . { __structural_recur__ }";
        let unauthorized_source =
            "module x;                      fn held(value: .) -> . { __structural_recur__ }";
        assert_eq!(
            authorized_source.find("fn held"),
            unauthorized_source.find("fn held"),
            "the primitive grant must change without moving the cached definition"
        );
        let authorized = lowered_package(&[("x.kio", authorized_source)]);
        let unauthorized = lowered_package(&[("x.kio", unauthorized_source)]);
        let shared_generation = EvalSourceGeneration::fresh();
        let authorized_defs = fn_def_map(&authorized.module("x").expect("x module").module);
        let unauthorized_defs = fn_def_map(&unauthorized.module("x").expect("x module").module);
        assert_eq!(
            eval_function_cache_key_for_def(authorized_defs["held"], "x", &shared_generation),
            eval_function_cache_key_for_def(unauthorized_defs["held"], "x", &shared_generation),
            "only the nominal artifact generation partitions these identical definitions"
        );
        let evaluate = |artifact: &EvalArtifact,
                        eval_functions: SharedEvalFunctionCache,
                        closures: SharedFnClosureCache| {
            let module = &artifact.module("x").expect("x module").module;
            let ctx = AuthenticatedEvalCtx::for_module(artifact, module, "x")
                .expect("artifact context")
                .with_eval_function_cache(eval_functions)
                .with_fn_closure_cache(closures);
            let held = eval_authenticated(&path_expr("held"), &Env::new(), &ctx);
            apply(held, vec![Value::Unit], &ctx)
        };

        for authorized_first in [true, false] {
            let eval_functions = SharedEvalFunctionCache::default();
            let closures = SharedFnClosureCache::default();
            let (first_artifact, second_artifact) = if authorized_first {
                (&authorized, &unauthorized)
            } else {
                (&unauthorized, &authorized)
            };
            let first = evaluate(first_artifact, eval_functions.clone(), closures.clone());
            let second = evaluate(second_artifact, eval_functions.clone(), closures.clone());
            let (authorized_value, unauthorized_value) = if authorized_first {
                (first, second)
            } else {
                (second, first)
            };
            assert!(structural_recur_primitive_site(&authorized_value).is_some());
            assert!(matches!(
                unauthorized_value,
                Value::Atom(name) if name == "__structural_recur__"
            ));
            assert_eq!(
                eval_functions.inner.lock().expect("function cache").len(),
                2
            );
            assert_eq!(closures.inner.lock().expect("closure cache").len(), 2);
        }

        let lambda_module = parse_module(
            "module x; import __comptime__; equiv cache { \
             .(fuel: .) { \
               __structural_recur__(proof, fuel, (), .(recur: ., current: ., input: .) { input }) \
             }; \
             .(fuel: .) { \
               let ignored = __structural_recur__(proof, fuel, (), .(recur: ., current: ., input: .) { input }); \
               () \
             } \
             }",
        );
        let lambda_terms = equiv_terms(&lambda_module);
        let successful_lambda = lambda_terms[0].clone();
        let rejecting_discarded_lambda = lambda_terms[1].clone();
        let evaluate_lambda =
            |artifact: &EvalArtifact,
             lambda: &Expr<EvalPhase>,
             fuel: Value,
             exact_call_memo: SharedExactCallMemoCache| {
                let module = &artifact.module("x").expect("x module").module;
                let ctx = AuthenticatedEvalCtx::for_module(artifact, module, "x")
                    .expect("artifact context")
                    .with_exact_call_memo_cache(exact_call_memo);
                let closure = eval_authenticated(lambda, &Env::new(), &ctx);
                let Value::EvalClosure { function, .. } = &closure else {
                    panic!("lambda must evaluate to a closure")
                };
                assert!(function.memo_candidate);
                apply(closure, vec![fuel], &ctx)
            };

        let authorized_first_memo = SharedExactCallMemoCache::default();
        let measurable_fuel = refl_type_value(Type::Unit { meta: zero_meta() });
        assert!(matches!(
            evaluate_lambda(
                &authorized,
                &successful_lambda,
                measurable_fuel.clone(),
                authorized_first_memo.clone(),
            ),
            Value::Unit
        ));
        assert!(matches!(
            evaluate_lambda(
                &unauthorized,
                &successful_lambda,
                measurable_fuel,
                authorized_first_memo,
            ),
            Value::Stuck(_, _)
        ));

        let unauthorized_first_memo = SharedExactCallMemoCache::default();
        let opaque_fuel = Value::Atom("opaque-fuel".to_owned());
        assert!(matches!(
            evaluate_lambda(
                &unauthorized,
                &rejecting_discarded_lambda,
                opaque_fuel.clone(),
                unauthorized_first_memo.clone(),
            ),
            Value::Unit
        ));
        let rejected = evaluate_lambda(
            &authorized,
            &rejecting_discarded_lambda,
            opaque_fuel,
            unauthorized_first_memo,
        );
        assert_eq!(
            structural_recur_stuck_message(&rejected, &EvalCtx::new()),
            Some(
                "`__structural_recur__` got stuck because its initial fuel has no structural compile-time measure"
                    .to_owned()
            )
        );
    }

    #[test]
    fn artifact_generation_partitions_transitively_changed_imported_callees() {
        let first = lowered_package(&[
            (
                "provider.kio",
                "module provider; pub fn leaf(value: .) -> . { () }",
            ),
            (
                "consumer.kio",
                "module consumer; import provider(leaf); fn top(value: .) -> . { leaf(value) }",
            ),
        ]);
        let changed = lowered_package(&[
            (
                "provider.kio",
                "module provider; pub fn leaf(value: .) -> . { .t }",
            ),
            (
                "consumer.kio",
                "module consumer; import provider(leaf); fn top(value: .) -> . { leaf(value) }",
            ),
        ]);
        let eval_functions = SharedEvalFunctionCache::default();
        let closures = SharedFnClosureCache::default();
        let evaluate = |artifact: &EvalArtifact| {
            let module = &artifact.module("consumer").expect("consumer module").module;
            let ctx = AuthenticatedEvalCtx::for_module(artifact, module, "consumer")
                .expect("consumer context")
                .with_eval_function_cache(eval_functions.clone())
                .with_fn_closure_cache(closures.clone());
            let top = eval_authenticated(&path_expr("top"), &Env::new(), &ctx);
            apply(top, vec![Value::Unit], &ctx)
        };

        assert!(matches!(evaluate(&first), Value::Unit));
        assert!(matches!(evaluate(&changed), Value::Bool(true)));
        assert_eq!(
            eval_functions.inner.lock().expect("function cache").len(),
            4,
            "both top and its imported callee must be generation-partitioned"
        );
    }

    fn value_param(name: &str) -> SignatureParam<EvalPhase> {
        SignatureParam::Value(Param {
            name: name.to_string(),
            ty: None,
            pattern: Default::default(),
            meta: zero_meta(),
        })
    }

    pub(super) fn test_eval_function(params: &[&str], body: EvalExpr) -> EvalRef<EvalFunction> {
        let params: Arc<[EvalParam]> = params
            .iter()
            .map(|param| EvalParam {
                name: (*param).to_string(),
                abi_arity: 1,
            })
            .collect::<Vec<_>>()
            .into();
        let value_groups: Arc<[EvalParamGroup]> = if params.is_empty() {
            Vec::new().into()
        } else {
            vec![EvalParamGroup {
                param_start: 0,
                param_count: params.len(),
                abi_arity: params.len(),
            }]
            .into()
        };
        let abi_arity = params.len();
        let simple_body = is_simple_handler_expr(&body);
        let memo_candidate = !simple_body && is_memo_candidate_expr(&body);
        EvalRef::new(EvalFunction {
            cache_key: eval_function_cache_key_for_test("test::<fn>", &body),
            label: Some("test::<fn>".into()),
            owner_module_path: "test".into(),
            source_origin: EvalFunctionOrigin::Anonymous {
                enclosing: None,
                span: zero_span(),
            },
            params,
            value_groups,
            abi_arity,
            simple_body,
            memo_candidate,
            body: EvalRef::new(body),
            diagnostic_body: test_source_unit(),
        })
    }

    #[test]
    fn execution_stack_preserves_capture_views_and_let_extent() {
        let leaf = test_eval_function(&["arg"], EvalExpr::Local(0));
        let middle = test_eval_function(
            &["arg"],
            EvalExpr::Let {
                value: EvalRef::new(EvalExpr::Bool(false)),
                body: EvalRef::new(EvalExpr::CallFnExpr {
                    function: leaf,
                    captured_slots: vec![0].into(),
                    args: vec![EvalRef::new(EvalExpr::Local(1))],
                }),
            },
        );
        let expr = EvalExpr::CallFnExpr {
            function: middle,
            captured_slots: vec![0].into(),
            args: vec![EvalRef::new(EvalExpr::Bool(false))],
        };
        let metrics = Arc::new(EvalMetrics::default());
        let ctx = EvalCtx::new().with_metrics(metrics.clone());
        let mut slots = EvalSlots::root(vec![Value::Bool(true)]);
        let mut storage = execution::StorageMetrics::default();
        let value = execution::eval_with_storage(&expr, &mut slots, &ctx, &mut storage);

        assert!(matches!(value, Value::Bool(true)));
        assert!(matches!(slots.locals_slice(), [Value::Bool(true)]));
        assert_eq!(storage.activation_pushes, 2, "{storage:?}");
        assert_eq!(storage.activation_peak, 2, "{storage:?}");
        assert_eq!(storage.local_promotions, 1, "{storage:?}");
        assert_eq!(storage.local_copies, 1, "{storage:?}");
        assert_eq!(metrics.snapshot().capture_vec_builds, 0);
        assert_eq!(metrics.snapshot().capture_vec_values, 0);

        for (name, body, args, expected_promotions) in [
            (
                "argument",
                EvalExpr::CallFnExpr {
                    function: test_eval_function(&[], EvalExpr::Local(0)),
                    captured_slots: vec![0].into(),
                    args: Vec::new(),
                },
                vec![EvalRef::new(EvalExpr::Atom("argument".into()))],
                0,
            ),
            (
                "let-local",
                EvalExpr::Let {
                    value: EvalRef::new(EvalExpr::Atom("let-local".into())),
                    body: EvalRef::new(EvalExpr::CallFnExpr {
                        function: test_eval_function(&[], EvalExpr::Local(0)),
                        captured_slots: vec![1].into(),
                        args: Vec::new(),
                    }),
                },
                vec![EvalRef::new(EvalExpr::Atom("argument".into()))],
                1,
            ),
        ] {
            let expr = EvalExpr::CallFn {
                function: test_eval_function(&["arg"], body),
                args,
            };
            let metrics = Arc::new(EvalMetrics::default());
            let ctx = EvalCtx::new().with_metrics(metrics.clone());
            let mut storage = execution::StorageMetrics::default();
            let value = execution::eval_with_storage(&expr, &mut slots, &ctx, &mut storage);
            assert!(
                matches!(&value, Value::Atom(actual) if actual == name),
                "{value:?}"
            );
            assert!(matches!(slots.locals_slice(), [Value::Bool(true)]));
            assert_eq!(storage.activation_pushes, 2, "{storage:?}");
            assert_eq!(storage.local_promotions, expected_promotions, "{storage:?}");
            assert_eq!(storage.local_copies, expected_promotions, "{storage:?}");
            assert_eq!(metrics.snapshot().capture_vec_builds, 0);
            assert_eq!(metrics.snapshot().capture_vec_values, 0);
        }

        let leaf = test_eval_function(&[], EvalExpr::Local(0));
        let forward = test_eval_function(
            &[],
            EvalExpr::CallFnExpr {
                function: leaf,
                captured_slots: vec![0].into(),
                args: Vec::new(),
            },
        );
        let owner = test_eval_function(
            &[],
            EvalExpr::CallFnExpr {
                function: forward,
                captured_slots: vec![1].into(),
                args: Vec::new(),
            },
        );
        let expr = EvalExpr::CallFnExpr {
            function: owner,
            captured_slots: vec![2, 0].into(),
            args: Vec::new(),
        };
        let mut slots = EvalSlots::root(vec![
            Value::Atom("selected".into()),
            Value::Unit,
            Value::Atom("other".into()),
        ]);
        let metrics = Arc::new(EvalMetrics::default());
        let ctx = EvalCtx::new().with_metrics(metrics.clone());
        let mut storage = execution::StorageMetrics::default();
        let value = execution::eval_with_storage(&expr, &mut slots, &ctx, &mut storage);
        assert!(
            matches!(&value, Value::Atom(name) if name == "selected"),
            "{value:?}"
        );
        assert!(
            matches!(slots.locals_slice(), [Value::Atom(first), Value::Unit, Value::Atom(last)]
            if first == "selected" && last == "other")
        );
        assert_eq!(storage.activation_pushes, 3, "{storage:?}");
        assert_eq!(storage.activation_peak, 3, "{storage:?}");
        assert_eq!(metrics.snapshot().capture_vec_builds, 1);
        assert_eq!(metrics.snapshot().capture_vec_values, 2);
    }

    #[test]
    fn execution_stack_preserves_nonunit_sequences_and_ordered_arguments() {
        let function = test_eval_function(
            &["first", "second", "third"],
            EvalExpr::Seq {
                value: EvalRef::new(EvalExpr::Local(0)),
                body: EvalRef::new(EvalExpr::Seq {
                    value: EvalRef::new(EvalExpr::Local(1)),
                    body: EvalRef::new(EvalExpr::Local(2)),
                }),
            },
        );
        let expr = EvalExpr::CallFn {
            function,
            args: vec![
                EvalRef::new(EvalExpr::Atom("first-action".into())),
                EvalRef::new(EvalExpr::Atom("second-action".into())),
                EvalRef::new(EvalExpr::Unit),
            ],
        };
        let mut storage = execution::StorageMetrics::default();
        let value = execution::eval_with_storage(
            &expr,
            &mut EvalSlots::root(Vec::new()),
            &EvalCtx::new(),
            &mut storage,
        );
        let Value::Seq { value: first, body } = value else {
            panic!("first sequence")
        };
        let Value::Seq {
            value: second,
            body,
        } = body.as_ref()
        else {
            panic!("second sequence")
        };
        assert!(matches!(first.as_ref(), Value::Atom(name) if name == "first-action"));
        assert!(matches!(second.as_ref(), Value::Atom(name) if name == "second-action"));
        assert!(matches!(body.as_ref(), Value::Unit));
        assert_eq!(storage.activation_pushes, 1, "{storage:?}");
        assert_eq!(storage.record_growths, 0, "{storage:?}");
        assert_eq!(storage.frame_growths, 0, "{storage:?}");
        assert_eq!(storage.value_pushes, 5, "{storage:?}");
        assert_eq!(storage.value_peak, 5, "{storage:?}");
        assert_eq!(storage.value_growths, 1, "{storage:?}");
    }

    #[test]
    fn execution_stack_counts_retained_arguments_at_the_inline_value_boundary() {
        for (params, expected_peak, expected_growths) in [
            (&["first", "last"][..], 3, 0),
            (&["first", "middle", "last"][..], 4, 1),
        ] {
            let function = test_eval_function(
                params,
                EvalExpr::Seq {
                    value: EvalRef::new(EvalExpr::Local(0)),
                    body: EvalRef::new(EvalExpr::Local(params.len() - 1)),
                },
            );
            let expr = EvalExpr::CallFn {
                function,
                args: (0..params.len())
                    .map(|index| {
                        EvalRef::new(if index == 0 {
                            EvalExpr::Atom("first-action".into())
                        } else {
                            EvalExpr::Unit
                        })
                    })
                    .collect(),
            };
            let mut storage = execution::StorageMetrics::default();
            let value = execution::eval_with_storage(
                &expr,
                &mut EvalSlots::root(Vec::new()),
                &EvalCtx::new(),
                &mut storage,
            );
            let Value::Seq { value, body } = value else {
                panic!("non-unit first argument retains its sequence")
            };
            assert!(matches!(value.as_ref(), Value::Atom(name) if name == "first-action"));
            assert!(matches!(body.as_ref(), Value::Unit));
            assert_eq!(storage.activation_pushes, 1, "{storage:?}");
            assert_eq!(storage.value_pushes, expected_peak, "{storage:?}");
            assert_eq!(storage.value_peak, expected_peak, "{storage:?}");
            assert_eq!(storage.value_growths, expected_growths, "{storage:?}");
        }
    }

    #[test]
    fn execution_stack_pending_lets_scale_with_live_work() {
        for depth in [4096, 8192] {
            let mut retained = vec![EvalRef::new(EvalExpr::Local(0))];
            for _ in 0..depth {
                let body = retained.last().expect("initial body").clone();
                retained.push(EvalRef::new(EvalExpr::Let {
                    value: EvalRef::new(EvalExpr::Unit),
                    body,
                }));
            }
            let mut storage = execution::StorageMetrics::default();
            let mut slots = EvalSlots::root(vec![Value::Bool(true)]);
            let value = execution::eval_with_storage(
                retained.last().expect("retained body"),
                &mut slots,
                &EvalCtx::new(),
                &mut storage,
            );
            assert!(matches!(value, Value::Bool(true)));
            assert!(matches!(slots.locals_slice(), [Value::Bool(true)]));
            assert_eq!(storage.frame_peak, depth, "{storage:?}");
            assert_eq!(storage.frame_pushes, 2 * depth, "{storage:?}");
            assert_eq!(storage.activation_pushes, 0, "{storage:?}");
            assert_eq!(storage.value_pushes, 0, "{storage:?}");
            // Each child still has its separately retained owner when its parent drops.
            while retained.pop().is_some() {}
        }
    }

    #[test]
    fn execution_stack_discards_computed_unit_before_residual_sequence() {
        let function = test_eval_function(
            &["arg"],
            EvalExpr::Let {
                value: EvalRef::new(EvalExpr::Const(Value::Unit)),
                body: EvalRef::new(EvalExpr::Local(1)),
            },
        );
        let expr = EvalExpr::Seq {
            value: EvalRef::new(EvalExpr::CallFn {
                function,
                args: vec![EvalRef::new(EvalExpr::Const(Value::Bool(false)))],
            }),
            body: EvalRef::new(EvalExpr::Seq {
                value: EvalRef::new(EvalExpr::Atom("pending-action".into())),
                body: EvalRef::new(EvalExpr::Const(Value::Bool(true))),
            }),
        };
        let metrics = Arc::new(EvalMetrics::default());
        let ctx = EvalCtx::new().with_metrics(metrics.clone());
        let mut storage = execution::StorageMetrics::default();
        let value = execution::eval_with_storage(
            &expr,
            &mut EvalSlots::root(Vec::new()),
            &ctx,
            &mut storage,
        );
        let Value::Seq { value, body } = value else {
            panic!("the opaque action remains sequenced")
        };
        assert!(matches!(value.as_ref(), Value::Atom(name) if name == "pending-action"));
        assert!(matches!(body.as_ref(), Value::Bool(true)));
        assert_eq!(storage.value_peak, 1, "{storage:?}");
        assert_eq!(storage.local_promotions, 1, "{storage:?}");
        assert_eq!(metrics.snapshot().apply_fn_calls, 1);
        assert_eq!(metrics.snapshot().expr_visits, 9);
    }

    fn test_source_unit() -> EvalRef<EvalAstExpr> {
        EvalRef::new(Expr::Unit {
            occurrence: Default::default(),
            meta: Meta::new(zero_span()),
        })
    }

    #[derive(Debug, Clone, Copy, PartialEq, Eq)]
    enum ComptimeEvalSurface {
        TypeOnly,
        ReflectType,
        DirectType,
        DirectDiagnostic,
        DirectTerm,
        StructuralRecur,
        GenericOnly,
    }

    fn comptime_eval_surface(builtin: ComptimeBuiltin) -> ComptimeEvalSurface {
        match builtin {
            ComptimeBuiltin::ComptimeProof
            | ComptimeBuiltin::Type
            | ComptimeBuiltin::CheckedTerm
            | ComptimeBuiltin::TypeVar
            | ComptimeBuiltin::TypeName
            | ComptimeBuiltin::TypeArity
            | ComptimeBuiltin::DiagnosticText
            | ComptimeBuiltin::ComptimeBool
            | ComptimeBuiltin::ComptimeStr
            | ComptimeBuiltin::FillCtx => ComptimeEvalSurface::TypeOnly,
            ComptimeBuiltin::ReflectType => ComptimeEvalSurface::ReflectType,
            ComptimeBuiltin::TypeView
            | ComptimeBuiltin::TypeEqual
            | ComptimeBuiltin::TypeNameEqual
            | ComptimeBuiltin::TypeVarEqual
            | ComptimeBuiltin::TypeIsProductRoot
            | ComptimeBuiltin::TypeIsSumRoot
            | ComptimeBuiltin::TypeUnit
            | ComptimeBuiltin::TypeBottom
            | ComptimeBuiltin::TypeProduct
            | ComptimeBuiltin::TypeSum
            | ComptimeBuiltin::TypeInstantiate
            | ComptimeBuiltin::TypeArityEqual
            | ComptimeBuiltin::TypeProductSpineFold
            | ComptimeBuiltin::TypeSumSpineFold
            | ComptimeBuiltin::TypeArgsFold
            | ComptimeBuiltin::TypeFunctionParamsFold => ComptimeEvalSurface::DirectType,
            ComptimeBuiltin::DiagnosticConcat
            | ComptimeBuiltin::ElabError
            | ComptimeBuiltin::TypeError => ComptimeEvalSurface::DirectDiagnostic,
            ComptimeBuiltin::TermType
            | ComptimeBuiltin::TermLet
            | ComptimeBuiltin::TermFn
            | ComptimeBuiltin::TermCall
            | ComptimeBuiltin::TermTypeFn
            | ComptimeBuiltin::TermTypeApp
            | ComptimeBuiltin::TermUnit
            | ComptimeBuiltin::IntrinsicPair
            | ComptimeBuiltin::IntrinsicFst
            | ComptimeBuiltin::IntrinsicSnd
            | ComptimeBuiltin::IntrinsicLeft
            | ComptimeBuiltin::IntrinsicRight
            | ComptimeBuiltin::IntrinsicEither
            | ComptimeBuiltin::IntrinsicAbsurd
            | ComptimeBuiltin::IntrinsicIfThenElse => ComptimeEvalSurface::DirectTerm,
            ComptimeBuiltin::StructuralRecur => ComptimeEvalSurface::StructuralRecur,
            ComptimeBuiltin::TypeIsHost
            | ComptimeBuiltin::TypeHostConverters
            | ComptimeBuiltin::TypeArrow
            | ComptimeBuiltin::TypeForall
            | ComptimeBuiltin::TypeVarFn
            | ComptimeBuiltin::TypeNameType
            | ComptimeBuiltin::TypeApply
            | ComptimeBuiltin::TypeArityFn
            | ComptimeBuiltin::TypeVarArity
            | ComptimeBuiltin::TypeArityZero
            | ComptimeBuiltin::TypeAritySucc
            | ComptimeBuiltin::TypeArityFold
            | ComptimeBuiltin::TypeNameParamAritiesFold
            | ComptimeBuiltin::TypeDisplay
            | ComptimeBuiltin::TypeShortName
            | ComptimeBuiltin::TypeNameDisplay
            | ComptimeBuiltin::TypeVarDisplay
            | ComptimeBuiltin::TypeArityDisplay
            | ComptimeBuiltin::TermHostConvert
            | ComptimeBuiltin::Fill
            | ComptimeBuiltin::TermSpecialize => ComptimeEvalSurface::GenericOnly,
        }
    }

    #[test]
    fn comptime_builtin_eval_surface_catalog_is_exhaustive() {
        let mut names = HashSet::new();
        let mut builtins = HashSet::new();
        for name in PUBLIC_COMPTIME_NAMES {
            assert!(names.insert(*name), "duplicate compile-time name `{name}`");
            let builtin = ComptimeBuiltin::from_public_name(name)
                .unwrap_or_else(|| panic!("compile-time name `{name}` has no builtin"));
            assert_eq!(builtin.public_name(), *name);
            assert!(
                builtins.insert(builtin),
                "multiple compile-time names map to {builtin:?}"
            );
            let _ = comptime_eval_surface(builtin);
        }
        assert_eq!(builtins.len(), PUBLIC_COMPTIME_NAMES.len());
    }

    struct DirectTypeCase {
        builtin: ComptimeBuiltin,
        valid_args: Vec<Value>,
        invalid_args: Option<Vec<Value>>,
    }

    struct DirectComptimeCase {
        builtin: ComptimeBuiltin,
        valid_args: Vec<Value>,
        invalid_args: Option<Vec<Value>>,
    }

    fn direct_type_cases() -> Vec<DirectTypeCase> {
        let unit = Type::Unit { meta: zero_meta() };
        let bottom = Type::Bottom { meta: zero_meta() };
        let product = Type::Product {
            left: Box::new(unit.clone()),
            right: Box::new(bottom.clone()),
            meta: zero_meta(),
        };
        let sum = Type::Sum {
            left: Box::new(unit.clone()),
            right: Box::new(bottom.clone()),
            meta: zero_meta(),
        };
        let applied = Type::synth_path(
            vec!["Applied".to_string()],
            vec![unit.clone(), bottom.clone()],
            zero_span(),
        );
        let function = Type::Function {
            param: Box::new(product.clone()),
            ret: Box::new(unit.clone()),
            meta: zero_meta(),
            abi_arity: 2,
            caps: (),
        };
        let scheme = Type::Forall {
            param: TypeParam {
                name: "A".to_string(),
                span: zero_span(),
                kind: None,
            },
            body: Box::new(type_path("A")),
            meta: zero_meta(),
        };
        let type_name = || Value::ReflTypeName {
            segments: vec!["Box".to_string()],
            param_arities: vec![0],
        };
        let type_var = || Value::ReflTypeVar {
            name: "A".to_string(),
            arity: 0,
        };
        let fold_step = || Value::EvalClosure {
            function: test_eval_function(&["acc", "item"], EvalExpr::Local(0)),
            captured: Vec::<Value>::new().into(),
        };
        let reflected_unit = || refl_type_value(unit.clone());
        let reflected_bottom = || refl_type_value(bottom.clone());
        let invalid_binary_type_args = || vec![Value::Unit, reflected_bottom()];
        let fold_args = |typ: Type<EvalPhase>| vec![refl_type_value(typ), Value::Unit, fold_step()];
        let invalid_fold_args = || vec![Value::Unit, Value::Unit, fold_step()];

        vec![
            DirectTypeCase {
                builtin: ComptimeBuiltin::TypeUnit,
                valid_args: Vec::new(),
                invalid_args: None,
            },
            DirectTypeCase {
                builtin: ComptimeBuiltin::TypeBottom,
                valid_args: Vec::new(),
                invalid_args: None,
            },
            DirectTypeCase {
                builtin: ComptimeBuiltin::TypeProduct,
                valid_args: vec![reflected_unit(), reflected_bottom()],
                invalid_args: Some(invalid_binary_type_args()),
            },
            DirectTypeCase {
                builtin: ComptimeBuiltin::TypeSum,
                valid_args: vec![reflected_unit(), reflected_bottom()],
                invalid_args: Some(invalid_binary_type_args()),
            },
            DirectTypeCase {
                builtin: ComptimeBuiltin::TypeView,
                valid_args: vec![reflected_unit()],
                invalid_args: Some(vec![Value::Unit]),
            },
            DirectTypeCase {
                builtin: ComptimeBuiltin::TypeEqual,
                valid_args: vec![reflected_unit(), reflected_unit()],
                invalid_args: Some(vec![Value::Unit, reflected_unit()]),
            },
            DirectTypeCase {
                builtin: ComptimeBuiltin::TypeNameEqual,
                valid_args: vec![type_name(), type_name()],
                invalid_args: Some(vec![Value::Unit, type_name()]),
            },
            DirectTypeCase {
                builtin: ComptimeBuiltin::TypeVarEqual,
                valid_args: vec![type_var(), type_var()],
                invalid_args: Some(vec![Value::Unit, type_var()]),
            },
            DirectTypeCase {
                builtin: ComptimeBuiltin::TypeArityEqual,
                valid_args: vec![Value::ReflTypeArity(2), Value::ReflTypeArity(2)],
                invalid_args: Some(vec![Value::Unit, Value::ReflTypeArity(2)]),
            },
            DirectTypeCase {
                builtin: ComptimeBuiltin::TypeInstantiate,
                valid_args: vec![refl_type_value(scheme), reflected_unit()],
                invalid_args: Some(vec![Value::Unit, reflected_unit()]),
            },
            DirectTypeCase {
                builtin: ComptimeBuiltin::TypeIsProductRoot,
                valid_args: vec![refl_type_value(product.clone())],
                invalid_args: Some(vec![Value::Unit]),
            },
            DirectTypeCase {
                builtin: ComptimeBuiltin::TypeIsSumRoot,
                valid_args: vec![refl_type_value(sum.clone())],
                invalid_args: Some(vec![Value::Unit]),
            },
            DirectTypeCase {
                builtin: ComptimeBuiltin::TypeProductSpineFold,
                valid_args: fold_args(product),
                invalid_args: Some(invalid_fold_args()),
            },
            DirectTypeCase {
                builtin: ComptimeBuiltin::TypeSumSpineFold,
                valid_args: fold_args(sum),
                invalid_args: Some(invalid_fold_args()),
            },
            DirectTypeCase {
                builtin: ComptimeBuiltin::TypeArgsFold,
                valid_args: fold_args(applied),
                invalid_args: Some(invalid_fold_args()),
            },
            DirectTypeCase {
                builtin: ComptimeBuiltin::TypeFunctionParamsFold,
                valid_args: fold_args(function),
                invalid_args: Some(invalid_fold_args()),
            },
        ]
    }

    fn direct_diagnostic_cases() -> Vec<DirectComptimeCase> {
        let text = |value: &str| Value::DiagnosticText(value.to_string());
        vec![
            DirectComptimeCase {
                builtin: ComptimeBuiltin::DiagnosticConcat,
                valid_args: vec![text("left"), text("right")],
                invalid_args: Some(vec![Value::Unit, text("right")]),
            },
            DirectComptimeCase {
                builtin: ComptimeBuiltin::ElabError,
                valid_args: vec![text("elaboration failed")],
                invalid_args: Some(vec![Value::Unit]),
            },
            DirectComptimeCase {
                builtin: ComptimeBuiltin::TypeError,
                valid_args: vec![text("type failed")],
                invalid_args: Some(vec![Value::Unit]),
            },
        ]
    }

    fn direct_term_cases() -> Vec<DirectComptimeCase> {
        let unit = Type::Unit { meta: zero_meta() };
        let bottom = Type::Bottom { meta: zero_meta() };
        let product = Type::Product {
            left: Box::new(unit.clone()),
            right: Box::new(bottom.clone()),
            meta: zero_meta(),
        };
        let sum = Type::Sum {
            left: Box::new(unit.clone()),
            right: Box::new(bottom.clone()),
            meta: zero_meta(),
        };
        let fn_param = type_path("Payload");
        let fn_type = Type::Function {
            param: Box::new(fn_param.clone()),
            ret: Box::new(fn_param.clone()),
            meta: zero_meta(),
            abi_arity: Type::function_param_abi_slot_count(&fn_param),
            caps: (),
        };
        let call_fn_type = Type::Function {
            param: Box::new(product.clone()),
            ret: Box::new(unit.clone()),
            meta: zero_meta(),
            abi_arity: Type::function_param_abi_slot_count(&product),
            caps: (),
        };
        let forall_type = Type::Forall {
            param: TypeParam {
                name: "A".to_string(),
                span: zero_span(),
                kind: None,
            },
            body: Box::new(type_path("A")),
            meta: zero_meta(),
        };
        let checked = |ty: Type<EvalPhase>| {
            checked_term_value(
                Expr::Unit {
                    occurrence: Default::default(),
                    meta: zero_meta(),
                },
                ty,
            )
        };
        let unary_identity_handler = || Value::EvalClosure {
            function: test_eval_function(&["value"], EvalExpr::Local(0)),
            captured: Vec::<Value>::new().into(),
        };
        let unary_unit_handler = || Value::EvalClosure {
            function: test_eval_function(&["value"], EvalExpr::ReflTermUnit),
            captured: Vec::<Value>::new().into(),
        };
        let nullary_checked_handler = |name: &str| Value::EvalClosure {
            function: test_eval_function(&[], EvalExpr::Local(0)),
            captured: vec![checked_term_value(path_expr(name), unit.clone())].into(),
        };

        vec![
            DirectComptimeCase {
                builtin: ComptimeBuiltin::TermType,
                valid_args: vec![checked(unit.clone())],
                invalid_args: Some(vec![Value::Unit]),
            },
            DirectComptimeCase {
                builtin: ComptimeBuiltin::TermLet,
                valid_args: vec![
                    refl_type_value(unit.clone()),
                    checked(unit.clone()),
                    unary_identity_handler(),
                ],
                invalid_args: Some(vec![
                    Value::Unit,
                    checked(unit.clone()),
                    unary_identity_handler(),
                ]),
            },
            DirectComptimeCase {
                builtin: ComptimeBuiltin::TermFn,
                valid_args: vec![refl_type_value(fn_type), unary_identity_handler()],
                invalid_args: Some(vec![Value::Unit, unary_identity_handler()]),
            },
            DirectComptimeCase {
                builtin: ComptimeBuiltin::TermCall,
                valid_args: vec![
                    refl_type_value(call_fn_type.clone()),
                    checked_term_value(path_expr("callable"), call_fn_type),
                    checked(product.clone()),
                ],
                invalid_args: Some(vec![
                    Value::Unit,
                    checked(unit.clone()),
                    checked(product.clone()),
                ]),
            },
            DirectComptimeCase {
                builtin: ComptimeBuiltin::TermTypeFn,
                valid_args: vec![Value::ReflTypeArity(0), unary_unit_handler()],
                invalid_args: Some(vec![Value::Unit, unary_unit_handler()]),
            },
            DirectComptimeCase {
                builtin: ComptimeBuiltin::TermTypeApp,
                valid_args: vec![
                    checked_term_value(path_expr("polymorphic"), forall_type),
                    refl_type_value(unit.clone()),
                ],
                invalid_args: Some(vec![Value::Unit, refl_type_value(unit.clone())]),
            },
            DirectComptimeCase {
                builtin: ComptimeBuiltin::TermUnit,
                valid_args: Vec::new(),
                invalid_args: None,
            },
            DirectComptimeCase {
                builtin: ComptimeBuiltin::IntrinsicPair,
                valid_args: vec![checked(unit.clone()), checked(bottom.clone())],
                invalid_args: Some(vec![Value::Unit, checked(bottom.clone())]),
            },
            DirectComptimeCase {
                builtin: ComptimeBuiltin::IntrinsicFst,
                valid_args: vec![refl_type_value(product.clone()), checked(product.clone())],
                invalid_args: Some(vec![Value::Unit, checked(product.clone())]),
            },
            DirectComptimeCase {
                builtin: ComptimeBuiltin::IntrinsicSnd,
                valid_args: vec![refl_type_value(product.clone()), checked(product.clone())],
                invalid_args: Some(vec![Value::Unit, checked(product.clone())]),
            },
            DirectComptimeCase {
                builtin: ComptimeBuiltin::IntrinsicLeft,
                valid_args: vec![refl_type_value(sum.clone()), checked(unit.clone())],
                invalid_args: Some(vec![Value::Unit, checked(unit.clone())]),
            },
            DirectComptimeCase {
                builtin: ComptimeBuiltin::IntrinsicRight,
                valid_args: vec![refl_type_value(sum.clone()), checked(bottom.clone())],
                invalid_args: Some(vec![Value::Unit, checked(bottom.clone())]),
            },
            DirectComptimeCase {
                builtin: ComptimeBuiltin::IntrinsicEither,
                valid_args: vec![
                    refl_type_value(sum.clone()),
                    refl_type_value(unit.clone()),
                    checked(sum),
                    unary_identity_handler(),
                    unary_unit_handler(),
                ],
                invalid_args: Some(vec![
                    Value::Unit,
                    refl_type_value(unit.clone()),
                    checked(unit.clone()),
                    unary_identity_handler(),
                    unary_unit_handler(),
                ]),
            },
            DirectComptimeCase {
                builtin: ComptimeBuiltin::IntrinsicAbsurd,
                valid_args: vec![checked(bottom), refl_type_value(unit.clone())],
                invalid_args: Some(vec![Value::Unit, refl_type_value(unit.clone())]),
            },
            DirectComptimeCase {
                builtin: ComptimeBuiltin::IntrinsicIfThenElse,
                valid_args: vec![
                    refl_type_value(unit.clone()),
                    checked(unit.clone()),
                    nullary_checked_handler("true_branch"),
                    nullary_checked_handler("false_branch"),
                ],
                invalid_args: Some(vec![
                    Value::Unit,
                    checked(unit.clone()),
                    nullary_checked_handler("true_branch"),
                    nullary_checked_handler("false_branch"),
                ]),
            },
        ]
    }

    #[test]
    fn direct_comptime_runtime_arity_matches_every_specialized_fixture() {
        for (builtin, arity) in direct_type_cases()
            .into_iter()
            .map(|case| (case.builtin, case.valid_args.len()))
            .chain(
                direct_diagnostic_cases()
                    .into_iter()
                    .map(|case| (case.builtin, case.valid_args.len())),
            )
            .chain(
                direct_term_cases()
                    .into_iter()
                    .map(|case| (case.builtin, case.valid_args.len())),
            )
        {
            assert_eq!(
                direct_comptime_runtime_arity(builtin),
                Some(arity),
                "{}",
                builtin.public_name()
            );
        }
    }

    fn eval_direct_comptime_call_args(
        builtin: ComptimeBuiltin,
        call_args: Vec<CallArg<EvalPhase>>,
        env: &Env,
        _elaborations: &Elaborations,
    ) -> (Value, EvalMetricsSnapshot) {
        let metrics = Arc::new(EvalMetrics::default());
        let mut primitive_env = EvalPrimitiveEnv::default();
        primitive_env.grant("", builtin);
        let ctx = EvalCtx::new()
            .with_primitive_env(primitive_env)
            .with_metrics(metrics.clone());
        let expr = Expr::synth_call(path_expr(builtin.public_name()), call_args, zero_span());
        let value = eval(&expr, env, &ctx);
        (value, metrics.snapshot())
    }

    fn eval_direct_comptime_builtin(
        builtin: ComptimeBuiltin,
        args: &[Value],
        elaborations: &Elaborations,
    ) -> (Value, EvalMetricsSnapshot) {
        let mut env = Env::new();
        let call_args = args
            .iter()
            .enumerate()
            .map(|(index, value)| {
                let name = format!("arg{index}");
                env.insert(name.clone(), value.clone());
                CallArg::Value(path_expr(&name))
            })
            .collect();
        eval_direct_comptime_call_args(builtin, call_args, &env, elaborations)
    }

    fn eval_direct_diagnostic_builtin(
        builtin: ComptimeBuiltin,
        args: &[Value],
        elaborations: &Elaborations,
    ) -> (Value, EvalMetricsSnapshot) {
        let call_args = args
            .iter()
            .map(|value| {
                let Value::DiagnosticText(value) = value else {
                    panic!("valid direct diagnostic fixture must be diagnostic text")
                };
                CallArg::Value(Expr::StrLit {
                    occurrence: Default::default(),
                    value: value.clone(),
                    annotation: None,
                    meta: zero_meta(),
                })
            })
            .collect();
        eval_direct_comptime_call_args(builtin, call_args, &Env::new(), elaborations)
    }

    fn apply_comptime_builtin(
        builtin: ComptimeBuiltin,
        args: Vec<Value>,
    ) -> (Value, EvalMetricsSnapshot) {
        let metrics = Arc::new(EvalMetrics::default());
        let ctx = EvalCtx::new().with_metrics(metrics.clone());
        let value = apply(Value::Primitive(builtin), args, &ctx);
        (value, metrics.snapshot())
    }

    fn assert_builtin_stuck(value: &Value, builtin: ComptimeBuiltin) {
        assert!(
            matches!(value, Value::Stuck(callee, _)
                if matches!(callee.as_ref(), Value::Primitive(actual)
                    if *actual == builtin)),
            "{} must stay as its own residual, got {value:?}",
            builtin.public_name()
        );
    }

    fn canonicalize_checked_term_result(value: &Value) -> Value {
        match value {
            Value::CheckedTerm(term) => {
                Value::CheckedTerm(EvalRef::new(term.canonicalize_generated_names()))
            }
            value => value.clone(),
        }
    }

    fn assert_expected_diagnostic_result(builtin: ComptimeBuiltin, value: &Value) {
        match builtin {
            ComptimeBuiltin::DiagnosticConcat => {
                assert!(
                    matches!(value, Value::DiagnosticText(message) if message == "leftright"),
                    "diagnostic concat produced {value:?}"
                );
            }
            ComptimeBuiltin::ElabError | ComptimeBuiltin::TypeError => {
                let Value::CheckedTerm(term) = value else {
                    panic!("{} must produce a checked error", builtin.public_name())
                };
                let expected_kind = if builtin == ComptimeBuiltin::ElabError {
                    CheckedTermErrorKind::Elaborator
                } else {
                    CheckedTermErrorKind::Type
                };
                let expected_message = if builtin == ComptimeBuiltin::ElabError {
                    "elaboration failed"
                } else {
                    "type failed"
                };
                assert_eq!(
                    term.checked_error(),
                    Some((expected_kind, expected_message)),
                    "{}",
                    builtin.public_name()
                );
            }
            _ => unreachable!("non-diagnostic builtin in diagnostic table"),
        }
    }

    fn assert_direct_term_fixture_result(builtin: ComptimeBuiltin, value: &Value) {
        let Value::CheckedTerm(term) = value else {
            return;
        };
        match (builtin, term.node.as_ref()) {
            (ComptimeBuiltin::TermLet, CheckedTermNode::TermLet { name, body, .. }) => assert!(
                matches!(body.node.as_ref(), CheckedTermNode::Local { name: body_name }
                    if body_name == name),
                "term-let handler did not return its generated binder"
            ),
            (ComptimeBuiltin::TermFn, CheckedTermNode::TermFn { sig, body }) => {
                let Some(SignatureParam::Value(param)) = sig.params.first() else {
                    panic!("term-fn fixture lost its value parameter")
                };
                assert!(
                    matches!(body.node.as_ref(), CheckedTermNode::Local { name }
                        if name == &param.name),
                    "term-fn handler did not return its generated packet"
                );
            }
            (
                ComptimeBuiltin::IntrinsicEither,
                CheckedTermNode::IntrinsicEither {
                    left_name,
                    left_body,
                    right_body,
                    ..
                },
            ) => {
                assert!(
                    matches!(left_body.node.as_ref(), CheckedTermNode::Local { name }
                        if name == left_name),
                    "either left handler did not return its payload"
                );
                assert!(
                    matches!(
                        right_body.node.as_ref(),
                        CheckedTermNode::Raw(Expr::Unit { .. })
                    ),
                    "either right handler did not return the constant unit term"
                );
            }
            (
                ComptimeBuiltin::IntrinsicIfThenElse,
                CheckedTermNode::IntrinsicIfThenElse {
                    true_body,
                    false_body,
                    ..
                },
            ) => {
                let raw_path_is = |term: &CheckedTerm, expected: &str| {
                    matches!(term.node.as_ref(), CheckedTermNode::Raw(Expr::Path { segments, .. })
                        if matches!(segments.as_slice(), [segment] if segment.as_str() == expected))
                };
                assert!(
                    raw_path_is(true_body, "true_branch"),
                    "if true handler result was swapped or lost"
                );
                assert!(
                    raw_path_is(false_body, "false_branch"),
                    "if false handler result was swapped or lost"
                );
            }
            (ComptimeBuiltin::TermLet, _)
            | (ComptimeBuiltin::TermFn, _)
            | (ComptimeBuiltin::IntrinsicEither, _)
            | (ComptimeBuiltin::IntrinsicIfThenElse, _) => {
                panic!(
                    "{} produced the wrong checked-term node",
                    builtin.public_name()
                )
            }
            _ => {}
        }
    }

    #[test]
    fn comptime_builtin_direct_type_reflection_matches_generic_dispatch_table() {
        let cases = direct_type_cases();
        let covered: HashSet<_> = cases.iter().map(|case| case.builtin).collect();
        let expected: HashSet<_> = PUBLIC_COMPTIME_NAMES
            .iter()
            .filter_map(|name| ComptimeBuiltin::from_public_name(name))
            .filter(|builtin| comptime_eval_surface(*builtin) == ComptimeEvalSurface::DirectType)
            .collect();
        assert_eq!(covered, expected, "direct type-reflection table drifted");

        let elaborations = empty_elaborations();
        let eq_ctx = EvalCtx::new();
        for case in cases {
            let name = case.builtin.public_name();
            let (direct, direct_metrics) =
                eval_direct_comptime_builtin(case.builtin, &case.valid_args, &elaborations);
            let (generic, generic_metrics) =
                apply_comptime_builtin(case.builtin, case.valid_args.clone());
            assert_eq!(direct_metrics.apply_atom_calls, 0, "direct `{name}`");
            assert_eq!(direct_metrics.reflection_calls, 1, "direct `{name}`");
            assert_eq!(generic_metrics.apply_atom_calls, 0, "generic `{name}`");
            assert_eq!(generic_metrics.reflection_calls, 1, "generic `{name}`");
            assert!(
                nf_eq(&direct, &generic, &eq_ctx),
                "direct/generic `{name}` mismatch: {direct:?} vs {generic:?}"
            );

            let Some(invalid_args) = case.invalid_args else {
                continue;
            };
            let (direct, direct_metrics) =
                eval_direct_comptime_builtin(case.builtin, &invalid_args, &elaborations);
            let (generic, generic_metrics) = apply_comptime_builtin(case.builtin, invalid_args);
            assert_eq!(
                direct_metrics.apply_atom_calls, 0,
                "direct invalid `{name}`"
            );
            assert_eq!(
                direct_metrics.reflection_calls, 0,
                "direct invalid `{name}`"
            );
            assert_eq!(
                generic_metrics.apply_atom_calls, 0,
                "generic invalid `{name}`"
            );
            assert_eq!(
                generic_metrics.reflection_calls, 0,
                "generic invalid `{name}`"
            );
            assert_builtin_stuck(&direct, case.builtin);
            assert_builtin_stuck(&generic, case.builtin);
            assert!(
                nf_eq(&direct, &generic, &eq_ctx),
                "direct/generic invalid `{name}` mismatch: {direct:?} vs {generic:?}"
            );
        }
    }

    #[test]
    fn comptime_builtin_direct_diagnostic_matches_generic_dispatch_table() {
        let cases = direct_diagnostic_cases();
        let covered: HashSet<_> = cases.iter().map(|case| case.builtin).collect();
        let expected: HashSet<_> = PUBLIC_COMPTIME_NAMES
            .iter()
            .filter_map(|name| ComptimeBuiltin::from_public_name(name))
            .filter(|builtin| {
                comptime_eval_surface(*builtin) == ComptimeEvalSurface::DirectDiagnostic
            })
            .collect();
        assert_eq!(covered, expected, "direct diagnostic table drifted");

        let elaborations = empty_elaborations();
        let eq_ctx = EvalCtx::new();
        for case in cases {
            let name = case.builtin.public_name();
            let invalid_args = case
                .invalid_args
                .expect("every diagnostic builtin has a value operand");
            assert_eq!(
                invalid_args.len(),
                case.valid_args.len(),
                "invalid `{name}` row must preserve arity"
            );

            let (direct, direct_metrics) =
                eval_direct_diagnostic_builtin(case.builtin, &case.valid_args, &elaborations);
            let (generic, generic_metrics) = apply_comptime_builtin(case.builtin, case.valid_args);
            assert_eq!(direct_metrics.root_eval_calls, 1, "direct `{name}`");
            assert!(direct_metrics.expr_visits > 0, "direct `{name}`");
            assert_eq!(direct_metrics.apply_atom_calls, 1, "direct `{name}`");
            assert_eq!(direct_metrics.reflection_calls, 1, "direct `{name}`");
            assert_eq!(generic_metrics.root_eval_calls, 0, "generic `{name}`");
            assert_eq!(generic_metrics.expr_visits, 0, "generic `{name}`");
            assert_eq!(generic_metrics.apply_atom_calls, 0, "generic `{name}`");
            assert_eq!(generic_metrics.reflection_calls, 1, "generic `{name}`");
            assert!(
                matches!(direct, Value::DiagnosticText(_) | Value::CheckedTerm(_)),
                "valid `{name}` row got {direct:?}"
            );
            assert_expected_diagnostic_result(case.builtin, &direct);
            assert!(
                nf_eq(
                    &canonicalize_checked_term_result(&direct),
                    &canonicalize_checked_term_result(&generic),
                    &eq_ctx,
                ),
                "direct/generic `{name}` mismatch: {direct:?} vs {generic:?}"
            );

            let (direct, direct_metrics) =
                eval_direct_comptime_builtin(case.builtin, &invalid_args, &elaborations);
            let (generic, generic_metrics) = apply_comptime_builtin(case.builtin, invalid_args);
            assert_eq!(direct_metrics.root_eval_calls, 1, "direct invalid `{name}`");
            assert!(direct_metrics.expr_visits > 0, "direct invalid `{name}`");
            assert_eq!(
                direct_metrics.apply_atom_calls, 1,
                "direct invalid `{name}`"
            );
            assert_eq!(
                direct_metrics.reflection_calls, 0,
                "direct invalid `{name}`"
            );
            assert_eq!(
                generic_metrics.root_eval_calls, 0,
                "generic invalid `{name}`"
            );
            assert_eq!(generic_metrics.expr_visits, 0, "generic invalid `{name}`");
            assert_eq!(
                generic_metrics.apply_atom_calls, 0,
                "generic invalid `{name}`"
            );
            assert_eq!(
                generic_metrics.reflection_calls, 0,
                "generic invalid `{name}`"
            );
            assert_builtin_stuck(&direct, case.builtin);
            assert_builtin_stuck(&generic, case.builtin);
            assert!(
                nf_eq(&direct, &generic, &eq_ctx),
                "direct/generic invalid `{name}` mismatch: {direct:?} vs {generic:?}"
            );
        }
    }

    #[test]
    fn comptime_builtin_direct_term_matches_generic_dispatch_table() {
        let cases = direct_term_cases();
        let covered: HashSet<_> = cases.iter().map(|case| case.builtin).collect();
        let expected: HashSet<_> = PUBLIC_COMPTIME_NAMES
            .iter()
            .filter_map(|name| ComptimeBuiltin::from_public_name(name))
            .filter(|builtin| comptime_eval_surface(*builtin) == ComptimeEvalSurface::DirectTerm)
            .collect();
        assert_eq!(covered, expected, "direct term table drifted");

        let elaborations = empty_elaborations();
        let eq_ctx = EvalCtx::new();
        for case in cases {
            let name = case.builtin.public_name();
            if let Some(invalid_args) = &case.invalid_args {
                assert_eq!(
                    invalid_args.len(),
                    case.valid_args.len(),
                    "invalid `{name}` row must preserve arity"
                );
            } else {
                assert_eq!(case.builtin, ComptimeBuiltin::TermUnit);
                assert!(case.valid_args.is_empty());
            }

            let (direct, direct_metrics) =
                eval_direct_comptime_builtin(case.builtin, &case.valid_args, &elaborations);
            let (generic, generic_metrics) =
                apply_comptime_builtin(case.builtin, case.valid_args.clone());
            assert_eq!(direct_metrics.root_eval_calls, 1, "direct `{name}`");
            assert_eq!(direct_metrics.apply_atom_calls, 0, "direct `{name}`");
            assert!(direct_metrics.reflection_calls > 0, "direct `{name}`");
            assert_eq!(generic_metrics.root_eval_calls, 0, "generic `{name}`");
            assert_eq!(generic_metrics.apply_atom_calls, 0, "generic `{name}`");
            assert_eq!(
                direct_metrics.reflection_calls, generic_metrics.reflection_calls,
                "reflection work differs for `{name}`"
            );
            assert!(
                if case.builtin == ComptimeBuiltin::TermType {
                    matches!(direct, Value::ReflType(_))
                } else {
                    matches!(direct, Value::CheckedTerm(_))
                },
                "valid `{name}` row got {direct:?}"
            );
            assert_direct_term_fixture_result(case.builtin, &direct);
            assert!(
                nf_eq(
                    &canonicalize_checked_term_result(&direct),
                    &canonicalize_checked_term_result(&generic),
                    &eq_ctx,
                ),
                "direct/generic `{name}` mismatch: {direct:?} vs {generic:?}"
            );

            let Some(invalid_args) = case.invalid_args else {
                continue;
            };
            let (direct, direct_metrics) =
                eval_direct_comptime_builtin(case.builtin, &invalid_args, &elaborations);
            let (generic, generic_metrics) = apply_comptime_builtin(case.builtin, invalid_args);
            assert_eq!(direct_metrics.root_eval_calls, 1, "direct invalid `{name}`");
            assert_eq!(
                direct_metrics.apply_atom_calls, 0,
                "direct invalid `{name}`"
            );
            assert_eq!(
                direct_metrics.reflection_calls, 0,
                "direct invalid `{name}`"
            );
            assert_eq!(
                generic_metrics.root_eval_calls, 0,
                "generic invalid `{name}`"
            );
            assert_eq!(
                generic_metrics.apply_atom_calls, 0,
                "generic invalid `{name}`"
            );
            assert_eq!(
                generic_metrics.reflection_calls, 0,
                "generic invalid `{name}`"
            );
            assert_builtin_stuck(&direct, case.builtin);
            assert_builtin_stuck(&generic, case.builtin);
            assert!(
                nf_eq(&direct, &generic, &eq_ctx),
                "direct/generic invalid `{name}` mismatch: {direct:?} vs {generic:?}"
            );
        }
    }

    #[cfg(feature = "surface")]
    struct GenericOnlyCase {
        builtin: ComptimeBuiltin,
        valid_args: Vec<Value>,
        invalid_args: Option<Vec<Value>>,
    }

    #[cfg(feature = "surface")]
    #[test]
    fn comptime_builtin_generic_only_inventory_is_exact() {
        let package = lowered_package(&[(
            "generic.kio",
            "module generic; \
             host type Text role(str); \
             host type Host; \
             host type Box[A]; \
             type Folded[A][**F] = A;",
        )]);
        package
            .resolve_imports()
            .expect("resolve generic fixture uses");
        let module = &package.module("generic").expect("generic module").module;
        let fixture_ctx = EvalCtx::new()
            .with_package(Some(&package))
            .with_root_module(module);

        let unit = || Type::Unit { meta: zero_meta() };
        let bottom = || Type::Bottom { meta: zero_meta() };
        let nominal = |name: &str, args| {
            Type::synth_path(
                vec!["generic".to_owned(), name.to_owned()],
                args,
                zero_span(),
            )
        };
        let text_ty = nominal("Text", Vec::new());
        let host_ty = nominal("Host", Vec::new());
        let box_head_ty = nominal("Box", Vec::new());
        let box_unit_ty = nominal("Box", vec![unit()]);
        let converter_ty = host_converter_product_type(text_ty.clone(), &host_ty, &fixture_ctx);
        let converter_term = checked_term_value(path_expr("convert_host"), converter_ty.clone());
        let host_term = checked_term_value(path_expr("host_value"), host_ty.clone());

        let unary_fold_step = || Value::EvalClosure {
            function: test_eval_function(
                &["acc"],
                EvalExpr::CoreCtor {
                    name: "__pair__",
                    args: vec![
                        EvalRef::new(EvalExpr::Local(0)),
                        EvalRef::new(EvalExpr::Unit),
                    ],
                },
            ),
            captured: Vec::<Value>::new().into(),
        };
        let binary_fold_step = || Value::EvalClosure {
            function: test_eval_function(
                &["acc", "item"],
                EvalExpr::CoreCtor {
                    name: "__pair__",
                    args: vec![
                        EvalRef::new(EvalExpr::Local(0)),
                        EvalRef::new(EvalExpr::Local(1)),
                    ],
                },
            ),
            captured: Vec::<Value>::new().into(),
        };
        let reflected = |ty| refl_type_value(ty);
        let type_var = || Value::ReflTypeVar {
            name: "T".to_owned(),
            arity: 2,
        };
        let box_name = || Value::ReflTypeName {
            segments: vec!["generic".to_owned(), "Box".to_owned()],
            param_arities: vec![0],
        };
        let fold_name = || Value::ReflTypeName {
            segments: vec!["generic".to_owned(), "Folded".to_owned()],
            param_arities: vec![0, 2],
        };
        let display_ty = Type::Function {
            param: Box::new(host_ty.clone()),
            ret: Box::new(text_ty.clone()),
            meta: zero_meta(),
            abi_arity: 1,
            caps: (),
        };
        let arity_ty = Type::Forall {
            param: TypeParam {
                name: "F".to_owned(),
                span: zero_span(),
                kind: Some(crate::ast::Kind::arrow_chain(2)),
            },
            body: Box::new(unit()),
            meta: zero_meta(),
        };
        let specialized_pattern = type_path("A");
        let specialized_ty = Type::Forall {
            param: TypeParam {
                name: "A".to_owned(),
                span: zero_span(),
                kind: None,
            },
            body: Box::new(specialized_pattern.clone()),
            meta: zero_meta(),
        };
        let specialized_term = checked_term_value(path_expr("poly"), specialized_ty);

        let (fill_proof, empty_fills) = fresh_fills_capability_values();
        let fill_destination = projected_value(
            crate::pass::typecheck_core::apply::fills::focused_type_for_test(
                marked_comptime_proof_from_value(&fill_proof)
                    .expect("fresh Fill proof must authenticate"),
                ReflectedType::new_trusted(unit()),
            ),
        );
        let fill_candidate = reflected(unit());

        let cases = vec![
            GenericOnlyCase {
                builtin: ComptimeBuiltin::TypeIsHost,
                valid_args: vec![reflected(host_ty.clone())],
                invalid_args: Some(vec![Value::Unit]),
            },
            GenericOnlyCase {
                builtin: ComptimeBuiltin::TypeHostConverters,
                valid_args: vec![reflected(text_ty.clone()), reflected(host_ty.clone())],
                invalid_args: Some(vec![Value::Unit, reflected(host_ty.clone())]),
            },
            GenericOnlyCase {
                builtin: ComptimeBuiltin::TypeArrow,
                valid_args: vec![
                    reflected(unit()),
                    Value::ReflTypeArity(1),
                    reflected(bottom()),
                ],
                invalid_args: Some(vec![
                    Value::Unit,
                    Value::ReflTypeArity(1),
                    reflected(bottom()),
                ]),
            },
            GenericOnlyCase {
                builtin: ComptimeBuiltin::TypeForall,
                valid_args: vec![
                    Value::ReflTypeArity(2),
                    Value::Primitive(ComptimeBuiltin::TypeVarFn),
                ],
                invalid_args: Some(vec![
                    Value::Unit,
                    Value::Primitive(ComptimeBuiltin::TypeVarFn),
                ]),
            },
            GenericOnlyCase {
                builtin: ComptimeBuiltin::TypeVarFn,
                valid_args: vec![type_var()],
                invalid_args: Some(vec![Value::Unit]),
            },
            GenericOnlyCase {
                builtin: ComptimeBuiltin::TypeNameType,
                valid_args: vec![box_name()],
                invalid_args: Some(vec![Value::Unit]),
            },
            GenericOnlyCase {
                builtin: ComptimeBuiltin::TypeApply,
                valid_args: vec![reflected(box_head_ty.clone()), reflected(unit())],
                invalid_args: Some(vec![Value::Unit, reflected(unit())]),
            },
            GenericOnlyCase {
                builtin: ComptimeBuiltin::TypeArityFn,
                valid_args: vec![reflected(arity_ty)],
                invalid_args: Some(vec![Value::Unit]),
            },
            GenericOnlyCase {
                builtin: ComptimeBuiltin::TypeVarArity,
                valid_args: vec![type_var()],
                invalid_args: Some(vec![Value::Unit]),
            },
            GenericOnlyCase {
                builtin: ComptimeBuiltin::TypeArityZero,
                valid_args: Vec::new(),
                invalid_args: None,
            },
            GenericOnlyCase {
                builtin: ComptimeBuiltin::TypeAritySucc,
                valid_args: vec![Value::ReflTypeArity(2)],
                invalid_args: Some(vec![Value::Unit]),
            },
            GenericOnlyCase {
                builtin: ComptimeBuiltin::TypeArityFold,
                valid_args: vec![
                    Value::ReflTypeArity(3),
                    Value::Atom("arity_init".to_owned()),
                    unary_fold_step(),
                ],
                invalid_args: Some(vec![
                    Value::Unit,
                    Value::Atom("arity_init".to_owned()),
                    unary_fold_step(),
                ]),
            },
            GenericOnlyCase {
                builtin: ComptimeBuiltin::TypeNameParamAritiesFold,
                valid_args: vec![
                    fold_name(),
                    Value::Atom("name_init".to_owned()),
                    binary_fold_step(),
                ],
                invalid_args: Some(vec![
                    Value::Unit,
                    Value::Atom("name_init".to_owned()),
                    binary_fold_step(),
                ]),
            },
            GenericOnlyCase {
                builtin: ComptimeBuiltin::TypeDisplay,
                valid_args: vec![reflected(display_ty.clone())],
                invalid_args: Some(vec![Value::Unit]),
            },
            GenericOnlyCase {
                builtin: ComptimeBuiltin::TypeShortName,
                valid_args: vec![reflected(display_ty)],
                invalid_args: Some(vec![Value::Unit]),
            },
            GenericOnlyCase {
                builtin: ComptimeBuiltin::TypeNameDisplay,
                valid_args: vec![box_name()],
                invalid_args: Some(vec![Value::Unit]),
            },
            GenericOnlyCase {
                builtin: ComptimeBuiltin::TypeVarDisplay,
                valid_args: vec![type_var()],
                invalid_args: Some(vec![Value::Unit]),
            },
            GenericOnlyCase {
                builtin: ComptimeBuiltin::TypeArityDisplay,
                valid_args: vec![Value::ReflTypeArity(2)],
                invalid_args: Some(vec![Value::Unit]),
            },
            GenericOnlyCase {
                builtin: ComptimeBuiltin::TermHostConvert,
                valid_args: vec![
                    reflected(text_ty.clone()),
                    reflected(host_ty.clone()),
                    converter_term.clone(),
                    host_term.clone(),
                ],
                invalid_args: Some(vec![
                    Value::Unit,
                    reflected(host_ty.clone()),
                    converter_term,
                    host_term,
                ]),
            },
            GenericOnlyCase {
                builtin: ComptimeBuiltin::Fill,
                valid_args: vec![
                    fill_proof.clone(),
                    empty_fills.clone(),
                    fill_destination,
                    fill_candidate.clone(),
                ],
                invalid_args: Some(vec![
                    fill_proof,
                    empty_fills,
                    fill_candidate.clone(),
                    fill_candidate,
                ]),
            },
            GenericOnlyCase {
                builtin: ComptimeBuiltin::TermSpecialize,
                valid_args: vec![
                    specialized_term,
                    reflected(specialized_pattern),
                    reflected(unit()),
                ],
                invalid_args: Some(vec![
                    Value::Unit,
                    reflected(type_path("A")),
                    reflected(unit()),
                ]),
            },
        ];

        let expected: HashSet<_> = PUBLIC_COMPTIME_NAMES
            .iter()
            .filter_map(|name| ComptimeBuiltin::from_public_name(name))
            .filter(|builtin| comptime_eval_surface(*builtin) == ComptimeEvalSurface::GenericOnly)
            .collect();
        let mut covered = HashSet::new();
        for case in &cases {
            assert!(
                covered.insert(case.builtin),
                "duplicate GenericOnly fixture for {}",
                case.builtin.public_name()
            );
        }
        assert_eq!(
            covered, expected,
            "GenericOnly fixture table drifted from the public builtin inventory"
        );

        let run = |builtin, args: Vec<Value>| {
            let metrics = Arc::new(EvalMetrics::default());
            let ctx = EvalCtx::new()
                .with_package(Some(&package))
                .with_root_module(module)
                .with_metrics(metrics.clone());
            let expr = EvalExpr::CallPrimitive {
                builtin,
                args: args
                    .into_iter()
                    .map(|value| EvalRef::new(EvalExpr::Const(value)))
                    .collect(),
            };
            let value = eval_compiled_expr(&expr, &mut EvalSlots::root(Vec::new()), &ctx);
            (value, metrics.snapshot())
        };

        for case in cases {
            let name = case.builtin.public_name();
            if let Some(invalid_args) = &case.invalid_args {
                assert_eq!(
                    invalid_args.len(),
                    case.valid_args.len(),
                    "invalid `{name}` fixture changed call arity"
                );
            } else {
                assert_eq!(case.builtin, ComptimeBuiltin::TypeArityZero);
                assert!(case.valid_args.is_empty());
            }

            let (valid, valid_metrics) = run(case.builtin, case.valid_args);
            assert_eq!(valid_metrics.root_eval_calls, 0, "valid `{name}`");
            assert!(valid_metrics.apply_atom_calls > 0, "valid `{name}`");
            assert!(valid_metrics.reflection_calls > 0, "valid `{name}`");
            assert_generic_only_fixture_result(
                case.builtin,
                &valid,
                &fixture_ctx,
                &converter_ty,
                &box_unit_ty,
                &host_ty,
                &text_ty,
            );

            let Some(invalid_args) = case.invalid_args else {
                continue;
            };
            let invalid_arity = invalid_args.len();
            let (invalid, invalid_metrics) = run(case.builtin, invalid_args);
            assert_eq!(invalid_metrics.root_eval_calls, 0, "invalid `{name}`");
            assert_eq!(invalid_metrics.apply_atom_calls, 1, "invalid `{name}`");
            assert_eq!(invalid_metrics.reflection_calls, 0, "invalid `{name}`");
            assert_builtin_stuck(&invalid, case.builtin);
            assert!(
                matches!(&invalid, Value::Stuck(_, args) if args.len() == invalid_arity),
                "invalid `{name}` residual changed operand count: {invalid:?}"
            );
        }
    }

    #[cfg(feature = "surface")]
    fn assert_generic_only_fixture_result(
        builtin: ComptimeBuiltin,
        value: &Value,
        ctx: &EvalCtx<'_>,
        converter_ty: &Type<EvalPhase>,
        box_unit_ty: &Type<EvalPhase>,
        host_ty: &Type<EvalPhase>,
        text_ty: &Type<EvalPhase>,
    ) {
        match builtin {
            ComptimeBuiltin::TypeIsHost => {
                assert!(matches!(value, Value::Bool(true)), "{value:?}")
            }
            ComptimeBuiltin::TypeHostConverters => assert!(
                matches!(as_refl_type_ref(value), Some(ty)
                    if canonical_refl_type_equiv(ty, converter_ty, ctx)),
                "{value:?}"
            ),
            ComptimeBuiltin::TypeArrow => assert!(
                matches!(as_refl_type_ref(value), Some(Type::Function {
                    param,
                    ret,
                    abi_arity: 1,
                    ..
                }) if matches!(param.as_ref(), Type::Unit { .. })
                    && matches!(ret.as_ref(), Type::Bottom { .. })),
                "{value:?}"
            ),
            ComptimeBuiltin::TypeForall => assert!(
                matches!(as_refl_type_ref(value), Some(Type::Forall { param, body, .. })
                    if param.effective_kind().arity() == 2
                        && matches!(body.as_ref(), Type::Path { segments, args, .. }
                            if matches!(segments.as_slice(), [segment]
                                if segment.as_str() == param.name.as_str())
                                && args.is_empty())),
                "{value:?}"
            ),
            ComptimeBuiltin::TypeVarFn => assert!(
                matches!(as_refl_type_ref(value), Some(Type::Path { segments, args, .. })
                    if matches!(segments.as_slice(), [segment] if segment.as_str() == "T")
                        && args.is_empty()),
                "{value:?}"
            ),
            ComptimeBuiltin::TypeNameType => assert!(
                matches!(as_refl_type_ref(value), Some(Type::Path { segments, args, .. })
                    if segments.iter().map(PathSegment::as_str).eq(["generic", "Box"])
                        && args.is_empty()),
                "{value:?}"
            ),
            ComptimeBuiltin::TypeApply => assert!(
                matches!(as_refl_type_ref(value), Some(ty)
                    if canonical_refl_type_equiv(ty, box_unit_ty, ctx)),
                "{value:?}"
            ),
            ComptimeBuiltin::TypeArityFn | ComptimeBuiltin::TypeVarArity => {
                assert_eq!(as_refl_type_arity(value), Some(2), "{value:?}")
            }
            ComptimeBuiltin::TypeArityZero => {
                assert_eq!(as_refl_type_arity(value), Some(0), "{value:?}")
            }
            ComptimeBuiltin::TypeAritySucc => {
                assert_eq!(as_refl_type_arity(value), Some(3), "{value:?}")
            }
            ComptimeBuiltin::TypeArityFold => {
                let mut cursor = value;
                for _ in 0..3 {
                    let Value::Data(pair) = cursor else {
                        panic!("arity fold step did not fire three times: {value:?}")
                    };
                    assert_eq!(pair.ctor(), "__pair__");
                    let [next, Value::Unit] = pair.args() else {
                        panic!("arity fold step produced the wrong packet: {value:?}")
                    };
                    cursor = next;
                }
                assert!(
                    matches!(cursor, Value::Atom(name) if name == "arity_init"),
                    "arity fold lost its initial accumulator: {value:?}"
                );
            }
            ComptimeBuiltin::TypeNameParamAritiesFold => {
                let Value::Data(outer) = value else {
                    panic!("type-name arity fold did not run: {value:?}")
                };
                assert_eq!(outer.ctor(), "__pair__");
                let [inner, Value::ReflTypeArity(2)] = outer.args() else {
                    panic!("type-name arity fold lost its second item: {value:?}")
                };
                let Value::Data(inner) = inner else {
                    panic!("type-name arity fold ran fewer than two steps: {value:?}")
                };
                assert_eq!(inner.ctor(), "__pair__");
                assert!(matches!(
                    inner.args(),
                    [Value::Atom(name), Value::ReflTypeArity(0)] if name == "name_init"
                ));
            }
            ComptimeBuiltin::TypeDisplay | ComptimeBuiltin::TypeShortName => assert!(
                matches!(value, Value::DiagnosticText(text) if !text.is_empty()),
                "{value:?}"
            ),
            ComptimeBuiltin::TypeNameDisplay => assert!(
                matches!(value, Value::DiagnosticText(text) if text == "generic.Box"),
                "{value:?}"
            ),
            ComptimeBuiltin::TypeVarDisplay => assert!(
                matches!(value, Value::DiagnosticText(text) if text == "T"),
                "{value:?}"
            ),
            ComptimeBuiltin::TypeArityDisplay => assert!(
                matches!(value, Value::DiagnosticText(text) if text == "2"),
                "{value:?}"
            ),
            ComptimeBuiltin::TermHostConvert => {
                let Value::CheckedTerm(term) = value else {
                    panic!("host conversion did not produce a checked term: {value:?}")
                };
                assert!(canonical_refl_type_equiv(term.ty(), text_ty, ctx));
                let CheckedTermNode::TermCall {
                    fn_value,
                    params,
                    arg_packet,
                } = term.node.as_ref()
                else {
                    panic!("host conversion did not produce a checked call: {term:?}")
                };
                assert_eq!(params.len(), 1);
                assert!(canonical_refl_type_equiv(&params[0], host_ty, ctx));
                assert!(canonical_refl_type_equiv(fn_value.ty(), converter_ty, ctx));
                assert!(canonical_refl_type_equiv(arg_packet.ty(), host_ty, ctx));
            }
            ComptimeBuiltin::Fill => {
                let context = fill_context_from_value(value)
                    .unwrap_or_else(|| panic!("Fill did not produce a Fill context: {value:?}"));
                assert_eq!(context.relations_in_source_order().len(), 1);
            }
            ComptimeBuiltin::TermSpecialize => {
                let Value::Data(success) = value else {
                    panic!("term specialization did not return a sum: {value:?}")
                };
                assert_eq!(success.ctor(), "__left__");
                let [Value::CheckedTerm(term)] = success.args() else {
                    panic!("term specialization success lost its checked term: {value:?}")
                };
                assert!(matches!(term.ty(), Type::Unit { .. }));
                assert!(matches!(
                    term.node.as_ref(),
                    CheckedTermNode::TermTypeApp {
                        arg: Type::Unit { .. },
                        ..
                    }
                ));
            }
            _ => unreachable!("non-GenericOnly builtin in GenericOnly result assertion"),
        }
    }

