    #[test]
    fn compiled_core_if_producer_requires_obvious_branch_values() {
        let thunk = |value| Expr::FnExpr {
            occurrence: Default::default(),
            sig: Signature::new(Vec::new()),
            ret_ty: None,
            body: Box::new(Expr::BoolLit {
                occurrence: Default::default(),
                value,
                annotation: None,
                meta: zero_meta(),
            }),
            meta: zero_meta(),
            caps: (),
        };
        for computed_branch in [None, Some(0), Some(1)] {
            for condition in [false, true] {
                let mut branches = [thunk(true), thunk(false)];
                if let Some(index) = computed_branch {
                    branches[index] = Expr::Seq {
                        occurrence: Default::default(),
                        value: Box::new(Expr::Unit {
                            occurrence: Default::default(),
                            meta: zero_meta(),
                        }),
                        body: Box::new(branches[index].clone()),
                        meta: zero_meta(),
                    };
                }
                let [then_branch, else_branch] = branches;
                let expr = Expr::synth_call(
                    path_expr("__if_then_else__"),
                    vec![
                        CallArg::Value(Expr::BoolLit {
                            occurrence: Default::default(),
                            value: condition,
                            annotation: None,
                            meta: zero_meta(),
                        }),
                        CallArg::Value(then_branch),
                        CallArg::Value(else_branch),
                    ],
                    zero_span(),
                );
                let ctx = EvalCtx::new();
                let compiled = compile_eval_root(&expr, &ctx, Vec::new()).expect("compiled if");
                assert_eq!(
                    matches!(compiled.as_ref(), EvalExpr::CoreIf { .. }),
                    computed_branch.is_none(),
                    "computed branch: {computed_branch:?}"
                );
                let value = eval_compiled_expr(&compiled, &mut EvalSlots::root(Vec::new()), &ctx);
                assert!(matches!(value, Value::Bool(actual) if actual == condition));
            }
        }
    }

