    #[test]
    fn erasing_rewrites_accept_only_evaluator_values() {
        assert!(is_obvious_eval_value(&EvalExpr::Unit));
        assert!(is_obvious_eval_value(&EvalExpr::Local(0)));
        assert!(is_obvious_eval_value(&EvalExpr::FnRef {
            cache_key: eval_function_cache_key_for_test("test::value", &EvalExpr::Unit),
            function: test_eval_function(&[], EvalExpr::Unit),
            share_closure: true,
        }));
        assert!(is_obvious_eval_value(&EvalExpr::Const(refl_type_value(
            Type::Unit { meta: zero_meta() }
        ))));
        assert!(!is_obvious_eval_value(&EvalExpr::Const(data_value(
            "__left__",
            vec![Value::Unit]
        ))));
        assert!(!is_obvious_eval_value(&EvalExpr::CoreCtor {
            name: "__left__",
            args: vec![EvalRef::new(EvalExpr::Unit)],
        }));
        assert!(!is_obvious_eval_value(&EvalExpr::Call {
            callee: EvalRef::new(EvalExpr::Atom("computed".to_string())),
            args: Vec::new(),
        }));

        let wrapper = test_eval_function(
            &["condition", "on_true", "on_false"],
            EvalExpr::CoreIf {
                condition: EvalRef::new(EvalExpr::Local(0)),
                then_thunk: EvalRef::new(EvalExpr::Local(1)),
                else_thunk: EvalRef::new(EvalExpr::Local(2)),
            },
        );
        let call = compile_direct_eval_fn_call(
            wrapper,
            vec![
                EvalRef::new(EvalExpr::Bool(true)),
                test_zero_arg_thunk("true"),
                EvalRef::new(EvalExpr::Call {
                    callee: EvalRef::new(EvalExpr::Atom("computed".to_string())),
                    args: Vec::new(),
                }),
            ],
        );
        assert!(matches!(call, EvalExpr::CallFn { .. }));
    }

    #[test]
    fn inliner_rechecks_proof_and_fold_handlers_after_substitution() {
        let computed = EvalRef::new(EvalExpr::Call {
            callee: EvalRef::new(EvalExpr::Atom("computed".to_string())),
            args: Vec::new(),
        });
        let mut budget = 16;
        let proofed = EvalExpr::ProofedReflection {
            builtin: ComptimeBuiltin::TypeView,
            proof: EvalRef::new(EvalExpr::Local(0)),
            direct: EvalRef::new(EvalExpr::ReflTypeUnit),
        };
        assert!(
            inline_small_eval_expr(&proofed, std::slice::from_ref(&computed), 1, &mut budget)
                .is_none()
        );

        let mut budget = 16;
        let fold = EvalExpr::ReflTypeFold {
            name: "__type_args_fold__",
            typ: EvalRef::new(EvalExpr::ReflTypeUnit),
            init: EvalRef::new(EvalExpr::Unit),
            step: EvalRef::new(EvalExpr::Local(0)),
        };
        assert!(inline_small_eval_expr(&fold, &[computed], 1, &mut budget).is_none());
    }

    #[test]
    fn recursive_inliner_preserves_a_computed_actual() {
        let ignore = test_eval_function(&["ignored"], EvalExpr::Unit);
        let outer = test_eval_function(
            &[],
            EvalExpr::CallFn {
                function: ignore,
                args: vec![EvalRef::new(EvalExpr::CallPrimitive {
                    builtin: ComptimeBuiltin::TypeUnit,
                    args: Vec::new(),
                })],
            },
        );

        // The outer zero-argument call may begin inlining, but the recursive
        // attempt to inline `ignore(computed())` must retain the call so its
        // call-by-value actual is still evaluated.
        let compiled = compile_direct_eval_fn_call(outer, Vec::new());
        assert!(matches!(compiled, EvalExpr::CallFn { .. }));

        let metrics = Arc::new(EvalMetrics::default());
        let ctx = EvalCtx::new().with_metrics(metrics.clone());
        let mut slots = EvalSlots::root(Vec::new());
        assert!(matches!(
            eval_compiled_expr(&compiled, &mut slots, &ctx),
            Value::Unit
        ));
        assert_eq!(metrics.snapshot().apply_atom_calls, 1);
    }

    #[test]
    fn lazy_direct_specializations_decline_computed_handlers() {
        let module = parse_module(
            "module x; import __comptime__; \
             fn reject(proof: .) -> . { \
               __structural_recur__(proof, __type_unit__(), (), \
                 .(recur, fuel, input) { recur(fuel, input) }) \
             } \
             fn handler(value: .) -> . { value } \
             fn thunk() -> . { () } \
             equiv keep { (); () }",
        );
        let ctx = test_primitive_ctx_for(
            "x",
            &[
                ComptimeBuiltin::StructuralRecur,
                ComptimeBuiltin::TypeUnit,
                ComptimeBuiltin::TypeArgsFold,
                ComptimeBuiltin::TermLet,
                ComptimeBuiltin::TermFn,
                ComptimeBuiltin::TermTypeFn,
                ComptimeBuiltin::IntrinsicEither,
                ComptimeBuiltin::IntrinsicIfThenElse,
            ],
        )
        .with_root_module(&module)
        .with_fn_defs(fn_def_map(&module));
        let reject = || {
            CallArg::Value(Expr::synth_call(
                path_expr("reject"),
                vec![CallArg::Value(Expr::Unit {
                    occurrence: Default::default(),
                    meta: zero_meta(),
                })],
                zero_span(),
            ))
        };
        let unit = || {
            CallArg::Value(Expr::Unit {
                occurrence: Default::default(),
                meta: zero_meta(),
            })
        };
        let handler = || CallArg::Value(path_expr("handler"));
        let thunk = || CallArg::Value(path_expr("thunk"));
        let calls = vec![
            (
                "empty type-argument fold step",
                Expr::synth_call(
                    path_expr("__type_args_fold__"),
                    vec![unit(), unit(), reject()],
                    zero_span(),
                ),
            ),
            (
                "term-let body",
                Expr::synth_call(
                    path_expr("__term_let__"),
                    vec![unit(), unit(), reject()],
                    zero_span(),
                ),
            ),
            (
                "term-fn body",
                Expr::synth_call(
                    path_expr("__term_fn__"),
                    vec![unit(), reject()],
                    zero_span(),
                ),
            ),
            (
                "term-type-fn body",
                Expr::synth_call(
                    path_expr("__term_type_fn__"),
                    vec![unit(), reject()],
                    zero_span(),
                ),
            ),
            (
                "reflected either handler",
                Expr::synth_call(
                    path_expr("__intrinsic_either__"),
                    vec![unit(), unit(), unit(), handler(), reject()],
                    zero_span(),
                ),
            ),
            (
                "reflected conditional thunk",
                Expr::synth_call(
                    path_expr("__intrinsic_if_then_else__"),
                    vec![unit(), unit(), thunk(), reject()],
                    zero_span(),
                ),
            ),
            (
                "core conditional thunk",
                Expr::synth_call(
                    path_expr("__if_then_else__"),
                    vec![
                        CallArg::Value(Expr::BoolLit {
                            occurrence: Default::default(),
                            value: true,
                            annotation: None,
                            meta: zero_meta(),
                        }),
                        thunk(),
                        reject(),
                    ],
                    zero_span(),
                ),
            ),
            (
                "core either handler",
                Expr::synth_call(
                    path_expr("__either__"),
                    vec![unit(), handler(), reject()],
                    zero_span(),
                ),
            ),
        ];

        for (label, call) in calls {
            let compiled = compile_eval_root(&call, &ctx, Vec::new())
                .unwrap_or_else(|| panic!("compile {label}"));
            assert!(
                matches!(
                    compiled.as_ref(),
                    EvalExpr::CallPrimitive { .. }
                        | EvalExpr::CallAtom { .. }
                        | EvalExpr::Call { .. }
                ),
                "{label} retained an erasing direct specialization: {compiled:?}"
            );
            let fault = eval(&call, &Env::new(), &ctx);
            assert_eq!(
                structural_recur_stuck_message(&fault, &ctx),
                Some(
                    "`__structural_recur__` got stuck because a recursive call did not descend from the current fuel measure (root=1, current=1, next=1)"
                        .to_string()
                ),
                "{label}: {fault:?}"
            );
        }
    }

