    #[test]
    fn forced_call_fn_matches_inlined_small_application() {
        let function = test_eval_function(
            &["payload"],
            EvalExpr::CoreCtor {
                name: "__right__",
                args: vec![EvalRef::new(EvalExpr::Local(0))],
            },
        );
        let args = vec![EvalRef::new(EvalExpr::Unit)];
        let forced = EvalExpr::CallFn {
            function: function.clone(),
            args: args.clone(),
        };
        let inlined = compile_direct_eval_fn_call(function, args);
        assert!(matches!(&forced, EvalExpr::CallFn { .. }));
        assert!(matches!(
            &inlined,
            EvalExpr::CoreCtor { name, .. } if *name == "__right__"
        ));

        let forced_metrics = Arc::new(EvalMetrics::default());
        let forced_ctx = EvalCtx::new().with_metrics(forced_metrics.clone());
        let forced_value =
            eval_compiled_expr(&forced, &mut EvalSlots::root(Vec::new()), &forced_ctx);
        let inlined_metrics = Arc::new(EvalMetrics::default());
        let inlined_ctx = EvalCtx::new().with_metrics(inlined_metrics.clone());
        let inlined_value =
            eval_compiled_expr(&inlined, &mut EvalSlots::root(Vec::new()), &inlined_ctx);

        assert!(nf_eq(&forced_value, &inlined_value, &EvalCtx::new()));
        assert_eq!(forced_metrics.snapshot().apply_fn_calls, 1);
        assert_eq!(inlined_metrics.snapshot().apply_fn_calls, 0);
    }

    #[test]
    fn simple_compiled_handler_matches_ordinary_closure_application() {
        let handler = EvalExpr::FnExpr {
            function: test_eval_function(
                &["payload"],
                EvalExpr::CoreCtor {
                    name: "__left__",
                    args: vec![EvalRef::new(EvalExpr::Local(0))],
                },
            ),
            captured_slots: Vec::new().into(),
            empty_closure_cache: Arc::new(OnceLock::new()),
        };
        let shortcut_metrics = Arc::new(EvalMetrics::default());
        let shortcut_ctx = EvalCtx::new().with_metrics(shortcut_metrics.clone());
        let shortcut_value = execution::eval_handler(
            &handler,
            EvalArgs::One([Value::Unit]),
            &mut EvalSlots::root(Vec::new()),
            &shortcut_ctx,
        );
        let shortcut_snapshot = shortcut_metrics.snapshot();
        assert_eq!(shortcut_snapshot.apply_fn_calls, 0, "{shortcut_snapshot:?}");
        assert_eq!(shortcut_snapshot.closure_builds, 0, "{shortcut_snapshot:?}");

        let closure_metrics = Arc::new(EvalMetrics::default());
        let closure_ctx = EvalCtx::new().with_metrics(closure_metrics.clone());
        let closure = eval_compiled_expr(&handler, &mut EvalSlots::root(Vec::new()), &closure_ctx);
        let closure_value = apply_args(closure, EvalArgs::One([Value::Unit]), &closure_ctx);
        let closure_snapshot = closure_metrics.snapshot();
        assert_eq!(closure_snapshot.apply_fn_calls, 1, "{closure_snapshot:?}");
        assert_eq!(closure_snapshot.closure_builds, 1, "{closure_snapshot:?}");

        assert!(nf_eq(&shortcut_value, &closure_value, &EvalCtx::new()));
    }

    #[test]
    fn eval_metrics_enabled_obeys_process_environment() {
        const CHILD: &str = "KIO_DEBUG_EVAL_METRICS_CHILD";
        if let Ok(case) = std::env::var(CHILD) {
            let expected = match case.as_str() {
                "absent" | "disabled" => false,
                "generic" | "dedicated" => true,
                _ => panic!("unknown metrics admission case: {case}"),
            };
            let metrics = EvalMetrics::enabled();
            assert_eq!(metrics.is_some(), expected, "{case}");
            if let Some(metrics) = metrics {
                let ctx = EvalCtx::new().with_metrics(metrics.clone());
                assert!(matches!(
                    eval(
                        &Expr::Unit {
                            occurrence: Default::default(),
                            meta: zero_meta()
                        },
                        &Env::new(),
                        &ctx
                    ),
                    Value::Unit
                ));
                assert_eq!(metrics.snapshot().root_eval_calls, 1);
            }
            println!("metrics-admission-complete:{case}");
            return;
        }
        for case in ["absent", "disabled", "generic", "dedicated"] {
            let mut child = std::process::Command::new(std::env::current_exe().unwrap());
            child
                .args([
                    "--exact",
                    "normalization::tests::eval_metrics_enabled_obeys_process_environment",
                    "--nocapture",
                ])
                .env_remove("KIO_DEBUG_TIMING")
                .env_remove("KIO_DEBUG_EVAL_TIMING")
                .env(CHILD, case);
            match case {
                "absent" => {}
                "disabled" => {
                    child
                        .env("KIO_DEBUG_TIMING", "0")
                        .env("KIO_DEBUG_EVAL_TIMING", "0");
                }
                "generic" => {
                    child.env("KIO_DEBUG_TIMING", "eval");
                }
                "dedicated" => {
                    child.env("KIO_DEBUG_EVAL_TIMING", "1");
                }
                _ => unreachable!(),
            }
            let output = child.output().unwrap();
            let stdout = String::from_utf8_lossy(&output.stdout);
            let stderr = String::from_utf8_lossy(&output.stderr);
            assert!(output.status.success(), "{case}: {stdout}\n{stderr}");
            let sentinel = format!("metrics-admission-complete:{case}");
            assert!(
                stdout.lines().any(|line| line == sentinel),
                "{case}: {stdout}"
            );
        }
    }

    #[test]
    fn eval_metrics_record_closure_application() {
        let metrics = std::sync::Arc::new(EvalMetrics::default());
        let ctx = EvalCtx::new().with_metrics(metrics.clone());
        let expr = Expr::synth_call(
            Expr::FnExpr {
                occurrence: Default::default(),
                sig: Signature::new(vec![value_param("x")]),
                ret_ty: None,
                body: Box::new(path_expr("x")),
                meta: zero_meta(),
                caps: (),
            },
            vec![CallArg::Value(Expr::Unit {
                occurrence: Default::default(),
                meta: zero_meta(),
            })],
            zero_span(),
        );

        let value = eval(&expr, &Env::new(), &ctx);

        assert!(matches!(value, Value::Unit));
        let snapshot = metrics.snapshot();
        assert_eq!(snapshot.root_eval_calls, 1);
        assert!(snapshot.expr_visits >= 3, "{snapshot:?}");
        assert_eq!(snapshot.apply_calls, 1);
        assert_eq!(snapshot.apply_fn_calls, 1);
        assert_eq!(snapshot.apply_generic_calls, 0);
        assert_eq!(snapshot.closure_apply_calls, 0);
        assert_eq!(snapshot.env_clones, 0);
        assert_eq!(snapshot.closure_builds, 0);
        assert_eq!(snapshot.function_hotspots.len(), 1);
        assert_eq!(snapshot.function_hotspots[0].calls, 1);
    }

