    #[test]
    fn direct_structural_recur_outer_continuation_survives_top_level_helper_loop() {
        let m = parse_module(
            "module x; import __comptime__; \
             fn walk(outer_recur: (Type & .) -> ., parent: Type) -> . { \
               __structural_recur__( \
                 proof, \
                 __type_product__(__type_unit__(), __type_unit__()), \
                 (), \
                 .(inner_recur, inner_fuel, inner_input) { \
                   __if_then_else__( \
                     __type_equal__(inner_fuel, __type_unit__()), \
                     .() { outer_recur(parent, ()) }, \
                     .() { \
                       __either__(., ., . | ., outer_recur(__type_unit__(), ()), \
                         .(left_done) { inner_recur(__type_unit__(), ()) }, \
                         .(left_err) { left_err }) \
                     }) \
                 }) \
             } \
             equiv cache { \
               __either__(., ., ., \
                 __structural_recur__( \
                   proof, \
                   __type_product__( \
                     __type_unit__(), \
                     __type_product__(__type_unit__(), __type_product__(__type_unit__(), __type_unit__()))), \
                   (), \
                   .(outer_recur, outer_fuel, outer_input) { \
                     __if_then_else__(__type_equal__(outer_fuel, __type_unit__()), \
                       .() { __left__(., ., ()) }, \
                       .() { \
                         __if_then_else__( \
                           __type_equal__(outer_fuel, __type_product__(__type_unit__(), __type_unit__())), \
                           .() { __left__(., ., ()) }, \
                           .() { \
                             walk(outer_recur, __type_product__(__type_unit__(), __type_unit__())) \
                           }) \
                       }) \
                   }), \
                 .(ok) { () }, \
                 .(err) { err }); \
               () \
             }",
        );
        let ctx = test_primitive_ctx_for(
            "x",
            &[
                ComptimeBuiltin::StructuralRecur,
                ComptimeBuiltin::TypeProduct,
                ComptimeBuiltin::TypeUnit,
                ComptimeBuiltin::TypeEqual,
            ],
        )
        .with_root_module(&m);

        let values = eval_each(&equiv_terms(&m), &ctx);

        let (a, b) = first_two(&values);
        assert!(nf_eq(a, b, &ctx), "NFs were {a:?} vs {b:?}");
    }

    #[test]
    fn eval_metrics_direct_either_handler_skips_closure_build() {
        let metrics = std::sync::Arc::new(EvalMetrics::default());
        let ctx = EvalCtx::new().with_metrics(metrics.clone());
        let expr = Expr::synth_call(
            path_expr("__either__"),
            vec![
                CallArg::Value(path_expr("A")),
                CallArg::Value(path_expr("B")),
                CallArg::Value(path_expr("C")),
                CallArg::Value(Expr::synth_call(
                    path_expr("__left__"),
                    vec![
                        CallArg::Value(path_expr("A")),
                        CallArg::Value(path_expr("B")),
                        CallArg::Value(Expr::Unit {
                            occurrence: Default::default(),
                            meta: zero_meta(),
                        }),
                    ],
                    zero_span(),
                )),
                CallArg::Value(Expr::FnExpr {
                    occurrence: Default::default(),
                    sig: Signature::new(vec![value_param("l")]),
                    ret_ty: None,
                    body: Box::new(path_expr("l")),
                    meta: zero_meta(),
                    caps: (),
                }),
                CallArg::Value(Expr::FnExpr {
                    occurrence: Default::default(),
                    sig: Signature::new(vec![value_param("r")]),
                    ret_ty: None,
                    body: Box::new(path_expr("r")),
                    meta: zero_meta(),
                    caps: (),
                }),
            ],
            zero_span(),
        );

        let value = eval(&expr, &Env::new(), &ctx);

        assert!(matches!(value, Value::Unit));
        let snapshot = metrics.snapshot();
        assert_eq!(snapshot.apply_fn_calls, 0);
        assert_eq!(snapshot.apply_generic_calls, 0);
        assert_eq!(snapshot.closure_apply_calls, 0);
        assert_eq!(snapshot.closure_builds, 0);
    }

    #[test]
    fn exact_fn_ref_handler_uses_exact_call_memo() {
        let function = test_eval_function(
            &["typ"],
            EvalExpr::ReflTypeEqual {
                left: EvalRef::new(EvalExpr::Local(0)),
                right: EvalRef::new(EvalExpr::ReflTypeUnit),
            },
        );
        assert!(!function.simple_body);
        assert!(function.memo_candidate);
        let arg = refl_type_value(Type::Unit { meta: zero_meta() });
        let oracle = eval_compiled_expr(
            &function.body,
            &mut EvalSlots::closure_borrowed(&[], EvalArgs::One([arg.clone()]).as_slice()),
            &EvalCtx::new(),
        );
        assert!(matches!(oracle, Value::Bool(true)));
        let handler = EvalExpr::FnRef {
            cache_key: function.cache_key.clone(),
            function,
            share_closure: true,
        };
        let metrics = EvalMetrics::collect();
        let ctx = EvalCtx::new().with_metrics(metrics.clone());
        for expected_hits in [0, 1] {
            let value = execution::eval_handler(
                &handler,
                EvalArgs::One([arg.clone()]),
                &mut EvalSlots::root(Vec::new()),
                &ctx,
            );
            assert!(matches!(value, Value::Bool(true)));
            let snapshot = metrics.snapshot();
            assert_eq!(snapshot.exact_call_memo_misses, 1, "{snapshot:?}");
            assert_eq!(snapshot.exact_call_memo_stores, 1, "{snapshot:?}");
            assert_eq!(snapshot.exact_call_memo_hits, expected_hits, "{snapshot:?}");
            assert_eq!(snapshot.apply_fn_calls, 1, "{snapshot:?}");
        }
    }

    #[test]
    fn exact_compiled_handler_with_contiguous_captures_borrows_frame() {
        let metrics = std::sync::Arc::new(EvalMetrics::default());
        let ctx = EvalCtx::new().with_metrics(metrics.clone());
        let handler = EvalExpr::FnExpr {
            function: test_eval_function(
                &[],
                EvalExpr::CallAtom {
                    name: "use".to_string(),
                    args: vec![
                        EvalRef::new(EvalExpr::Local(0)),
                        EvalRef::new(EvalExpr::Local(1)),
                    ],
                },
            ),
            captured_slots: vec![0, 1].into(),
            empty_closure_cache: Arc::new(OnceLock::new()),
        };
        let mut slots = EvalSlots::root(vec![
            Value::Atom("left".to_string()),
            Value::Atom("right".to_string()),
        ]);

        let value = execution::eval_handler(&handler, EvalArgs::Empty, &mut slots, &ctx);

        let Value::Stuck(callee, args) = value else {
            panic!("expected stuck call");
        };
        assert!(matches!(callee.as_ref(), Value::Atom(name) if name == "use"));
        assert_eq!(args.len(), 2);
        assert!(matches!(&args[0], Value::Atom(name) if name == "left"));
        assert!(matches!(&args[1], Value::Atom(name) if name == "right"));
        let snapshot = metrics.snapshot();
        assert_eq!(snapshot.apply_fn_calls, 1);
        assert_eq!(snapshot.capture_vec_builds, 0);
        assert_eq!(snapshot.capture_vec_values, 0);
    }

