    #[test]
    fn proofed_compiled_term_type_fn_retries_a_projected_callback() {
        let ctx = EvalCtx::new();
        let (raw_proof, fills, template) =
            crate::pass::typecheck_core::apply::fills::specialization_term_for_test();
        let (proof, _fills) = fills_capability_values(raw_proof, fills);
        let specialized = apply(
            Value::Primitive(ComptimeBuiltin::TermSpecialize),
            vec![
                proof.clone(),
                projected_value(template),
                refl_type_value(Type::synth_path(
                    vec!["A".to_owned()],
                    Vec::new(),
                    zero_span(),
                )),
                refl_type_value(Type::Unit { meta: zero_meta() }),
            ],
            &ctx,
        );
        let Value::Data(success) = specialized else {
            panic!("specialization did not return a sum: {specialized:?}")
        };
        let [Value::Projected(unit_recipe)] = success.args() else {
            panic!("specialization did not return a projected recipe: {success:?}")
        };
        let body = Value::EvalClosure {
            function: test_eval_function(&["ignored"], EvalExpr::Local(0)),
            captured: vec![Value::Projected(unit_recipe.clone())].into(),
        };
        let expr = EvalExpr::ProofedReflection {
            builtin: ComptimeBuiltin::TermTypeFn,
            proof: EvalRef::new(EvalExpr::Const(proof)),
            direct: EvalRef::new(EvalExpr::ReflTermTypeFn {
                arity: EvalRef::new(EvalExpr::Const(Value::ReflTypeArity(0))),
                body: EvalRef::new(EvalExpr::Const(body)),
            }),
        };
        let mut slots = EvalSlots::root(Vec::new());

        let value = eval_compiled_expr(&expr, &mut slots, &ctx);

        assert!(
            matches!(value, Value::Projected(_)),
            "compiled callback-only projected __term_type_fn__ stayed residual: {value:?}"
        );
    }

    #[test]
    fn direct_type_view_cache_preserves_cold_warm_and_shared_results() {
        let metrics = Arc::new(EvalMetrics::default());
        let cache = SharedTypeViewCache::default();
        let local_ctx = EvalCtx::new()
            .with_metrics(metrics.clone())
            .with_type_view_cache(cache.clone());
        let shared_ctx = EvalCtx::new()
            .with_metrics(metrics.clone())
            .with_type_view_cache(cache.clone());
        let unit = Type::Unit { meta: zero_meta() };
        let product = Type::Product {
            left: Box::new(unit.clone()),
            right: Box::new(unit),
            meta: zero_meta(),
        };
        let expr = EvalExpr::ReflTypeView {
            typ: EvalRef::new(EvalExpr::Const(refl_type_value(product))),
        };

        let cold = eval_compiled_expr(&expr, &mut EvalSlots::root(Vec::new()), &local_ctx);
        assert_eq!(cache.inner.lock().expect("type-view cache").len(), 1);
        let warm = eval_compiled_expr(&expr, &mut EvalSlots::root(Vec::new()), &local_ctx);
        let shared = eval_compiled_expr(&expr, &mut EvalSlots::root(Vec::new()), &shared_ctx);
        let (Value::Data(cold_data), Value::Data(warm_data), Value::Data(shared_data)) =
            (&cold, &warm, &shared)
        else {
            panic!("type view must return concrete sum data in every cache state")
        };
        assert!(EvalRef::ptr_eq(cold_data, warm_data));
        assert!(EvalRef::ptr_eq(cold_data, shared_data));
        assert!(nf_eq(&cold, &warm, &EvalCtx::new()));
        assert!(nf_eq(&cold, &shared, &EvalCtx::new()));
        assert_eq!(cache.inner.lock().expect("type-view cache").len(), 1);

        let snapshot = metrics.snapshot();
        assert_eq!(snapshot.reflection_calls, 3, "{snapshot:?}");
        assert_eq!(snapshot.reflection_type_view_calls, 3, "{snapshot:?}");
        assert_eq!(snapshot.apply_atom_calls, 0, "{snapshot:?}");
    }

