    #[test]
    fn exact_call_memo_skips_checked_terms() {
        let metrics = std::sync::Arc::new(EvalMetrics::default());
        let ctx = EvalCtx::new().with_metrics(metrics.clone());
        let checked = Value::CheckedTerm(EvalRef::new(CheckedTerm::new(
            Expr::Unit {
                occurrence: Default::default(),
                meta: zero_meta(),
            },
            Type::Unit { meta: zero_meta() },
        )));
        let arg_function = test_eval_function(
            &["value"],
            EvalExpr::ReflTypeEqual {
                left: EvalRef::new(EvalExpr::ReflTypeUnit),
                right: EvalRef::new(EvalExpr::ReflTypeUnit),
            },
        );

        let first = apply_args(
            Value::EvalClosure {
                function: arg_function.clone(),
                captured: Vec::new().into(),
            },
            EvalArgs::One([checked.clone()]),
            &ctx,
        );
        let second = apply_args(
            Value::EvalClosure {
                function: arg_function.clone(),
                captured: Vec::new().into(),
            },
            EvalArgs::One([checked.clone()]),
            &ctx,
        );

        assert!(matches!(first, Value::Bool(true)));
        assert!(matches!(second, Value::Bool(true)));
        let snapshot = metrics.snapshot();
        assert_eq!(snapshot.exact_call_memo_hits, 0, "{snapshot:?}");
        assert_eq!(snapshot.exact_call_memo_misses, 0, "{snapshot:?}");
        assert_eq!(snapshot.exact_call_memo_stores, 0, "{snapshot:?}");
        assert_eq!(snapshot.exact_call_memo_key_skips, 2, "{snapshot:?}");

        let result_metrics = std::sync::Arc::new(EvalMetrics::default());
        let result_ctx = EvalCtx::new().with_metrics(result_metrics.clone());
        let result_function = test_eval_function(
            &[],
            EvalExpr::Let {
                value: EvalRef::new(EvalExpr::ReflTypeEqual {
                    left: EvalRef::new(EvalExpr::ReflTypeUnit),
                    right: EvalRef::new(EvalExpr::ReflTypeUnit),
                }),
                body: EvalRef::new(EvalExpr::Const(checked)),
            },
        );

        let first = apply_args(
            Value::EvalClosure {
                function: result_function.clone(),
                captured: Vec::new().into(),
            },
            EvalArgs::Empty,
            &result_ctx,
        );
        let second = apply_args(
            Value::EvalClosure {
                function: result_function.clone(),
                captured: Vec::new().into(),
            },
            EvalArgs::Empty,
            &result_ctx,
        );

        assert!(matches!(first, Value::CheckedTerm(_)));
        assert!(matches!(second, Value::CheckedTerm(_)));
        let snapshot = result_metrics.snapshot();
        assert_eq!(snapshot.exact_call_memo_hits, 0, "{snapshot:?}");
        assert_eq!(snapshot.exact_call_memo_misses, 2, "{snapshot:?}");
        assert_eq!(snapshot.exact_call_memo_stores, 0, "{snapshot:?}");
        assert_eq!(snapshot.exact_call_memo_key_skips, 0, "{snapshot:?}");
    }

    #[test]
    fn exact_call_memo_matches_uncached_local_warm_and_shared_results() {
        let function = test_eval_function(
            &["typ"],
            EvalExpr::ReflTypeEqual {
                left: EvalRef::new(EvalExpr::Local(0)),
                right: EvalRef::new(EvalExpr::ReflTypeUnit),
            },
        );
        let arg = refl_type_value(Type::Unit { meta: zero_meta() });
        assert!(function.memo_candidate);

        let oracle = eval_compiled_expr(
            &function.body,
            &mut EvalSlots::closure_borrowed(&[], EvalArgs::One([arg.clone()]).as_slice()),
            &EvalCtx::new(),
        );

        let local_metrics = Arc::new(EvalMetrics::default());
        let local_ctx = EvalCtx::new().with_metrics(local_metrics.clone());
        let local_cold = apply_args(
            Value::EvalClosure {
                function: function.clone(),
                captured: Vec::new().into(),
            },
            EvalArgs::One([arg.clone()]),
            &local_ctx,
        );
        let local_cold_snapshot = local_metrics.snapshot();
        assert_eq!(local_cold_snapshot.exact_call_memo_misses, 1);
        assert_eq!(local_cold_snapshot.exact_call_memo_stores, 1);
        assert_eq!(local_cold_snapshot.exact_call_memo_hits, 0);
        assert_eq!(local_cold_snapshot.exact_call_memo_key_skips, 0);
        assert_eq!(local_cold_snapshot.apply_fn_calls, 1);
        let local_warm = apply_args(
            Value::EvalClosure {
                function: function.clone(),
                captured: Vec::new().into(),
            },
            EvalArgs::One([arg.clone()]),
            &local_ctx,
        );
        let local_warm_snapshot = local_metrics.snapshot();
        assert_eq!(local_warm_snapshot.exact_call_memo_misses, 1);
        assert_eq!(local_warm_snapshot.exact_call_memo_stores, 1);
        assert_eq!(local_warm_snapshot.exact_call_memo_hits, 1);
        assert_eq!(local_warm_snapshot.exact_call_memo_key_skips, 0);
        assert_eq!(local_warm_snapshot.apply_fn_calls, 1);
        assert_eq!(
            local_ctx
                .exact_call_memo
                .inner
                .lock()
                .expect("local exact-call memo")
                .len(),
            1
        );

        let shared_cache = SharedExactCallMemoCache::default();
        let shared_cold_metrics = Arc::new(EvalMetrics::default());
        let shared_cold_ctx = EvalCtx::new()
            .with_metrics(shared_cold_metrics.clone())
            .with_exact_call_memo_cache(shared_cache.clone());
        let shared_hit_metrics = Arc::new(EvalMetrics::default());
        let shared_hit_ctx = EvalCtx::new()
            .with_metrics(shared_hit_metrics.clone())
            .with_exact_call_memo_cache(shared_cache.clone());
        let shared_cold = apply_args(
            Value::EvalClosure {
                function: function.clone(),
                captured: Vec::new().into(),
            },
            EvalArgs::One([arg.clone()]),
            &shared_cold_ctx,
        );
        let shared_hit = apply_args(
            Value::EvalClosure {
                function: function.clone(),
                captured: Vec::new().into(),
            },
            EvalArgs::One([arg]),
            &shared_hit_ctx,
        );

        let shared_cold_snapshot = shared_cold_metrics.snapshot();
        assert_eq!(shared_cold_snapshot.exact_call_memo_misses, 1);
        assert_eq!(shared_cold_snapshot.exact_call_memo_stores, 1);
        assert_eq!(shared_cold_snapshot.exact_call_memo_hits, 0);
        assert_eq!(shared_cold_snapshot.exact_call_memo_key_skips, 0);
        assert_eq!(shared_cold_snapshot.apply_fn_calls, 1);
        let shared_hit_snapshot = shared_hit_metrics.snapshot();
        assert_eq!(shared_hit_snapshot.exact_call_memo_misses, 0);
        assert_eq!(shared_hit_snapshot.exact_call_memo_stores, 0);
        assert_eq!(shared_hit_snapshot.exact_call_memo_hits, 1);
        assert_eq!(shared_hit_snapshot.exact_call_memo_key_skips, 0);
        assert_eq!(shared_hit_snapshot.apply_fn_calls, 0);
        assert_eq!(
            shared_cache
                .inner
                .lock()
                .expect("shared exact-call memo")
                .len(),
            1
        );

        let comparison_ctx = EvalCtx::new();
        for value in [&local_cold, &local_warm, &shared_cold, &shared_hit] {
            assert!(nf_eq(&oracle, value, &comparison_ctx));
        }
        assert!(matches!(oracle, Value::Bool(true)));
    }

    #[test]
    fn eval_metrics_direct_reflection_type_fold_skips_atom_dispatch_and_closure_builds() {
        let metrics = std::sync::Arc::new(EvalMetrics::default());
        let ctx = EvalCtx::new().with_metrics(metrics.clone());
        let unit_ty = Type::Unit { meta: zero_meta() };
        let product_ty = Type::Product {
            left: Box::new(unit_ty.clone()),
            right: Box::new(unit_ty),
            meta: zero_meta(),
        };
        let expr = EvalExpr::ReflTypeFold {
            name: "__type_product_spine_fold__",
            typ: EvalRef::new(EvalExpr::Const(refl_type_value(product_ty))),
            init: EvalRef::new(EvalExpr::ReflTypeBottom),
            step: EvalRef::new(EvalExpr::FnExpr {
                function: test_eval_function(&["acc", "item"], EvalExpr::Local(1)),
                captured_slots: Vec::new().into(),
                empty_closure_cache: Arc::new(OnceLock::new()),
            }),
        };
        let mut slots = EvalSlots::root(Vec::new());

        let value = eval_compiled_expr(&expr, &mut slots, &ctx);

        assert!(matches!(as_refl_type_ref(&value), Some(Type::Unit { .. })));
        let snapshot = metrics.snapshot();
        assert_eq!(snapshot.apply_atom_calls, 0, "{snapshot:?}");
        assert_eq!(snapshot.apply_fn_calls, 0, "{snapshot:?}");
        assert_eq!(snapshot.reflection_type_fold_calls, 1);
        assert_eq!(snapshot.closure_builds, 0, "{snapshot:?}");
    }

