    fn eval_each(terms: &[&Expr<EvalPhase>], ctx: &EvalCtx<'_>) -> Vec<Value> {
        let env = Env::new();
        terms.iter().map(|e| eval(e, &env, ctx)).collect()
    }

    fn first_two(values: &[Value]) -> (&Value, &Value) {
        (&values[0], &values[1])
    }

    #[test]
    fn unit_terms_equal() {
        let m = parse_module("module x; equiv u { (); () }");
        let ctx = EvalCtx::new();
        let v = eval_each(&equiv_terms(&m), &ctx);
        let (a, b) = first_two(&v);
        assert!(nf_eq(a, b, &ctx), "NFs were {a:?} vs {b:?}");
    }

