    #[test]
    fn absurd_over_stuck_bottom_call_stays_structural() {
        // specs/formal/equiv.md § 2.3: bottom elimination has no
        // reduction rule, so the opaque bottom-producing call remains
        // observable below the `__absurd__` residual.
        let m = parse_module(
            "module x; import __intrinsics__; \
             equiv opaque_absurd { \
               __absurd__(never_a(x)); \
               __absurd__(never_a(x)); \
               __absurd__(never_b(x)) }",
        );
        let ctx = EvalCtx::new();
        let values = eval_each(&equiv_terms(&m), &ctx);
        let [same_left, same_right, changed] = values.as_slice() else {
            panic!("expected three residuals, got {values:?}");
        };
        let Value::Stuck(callee, args) = same_left else {
            panic!("expected a stuck __absurd__, got {same_left:?}");
        };
        assert!(matches!(&**callee, Value::Atom(name) if name == "__absurd__"));
        assert!(
            matches!(args.as_slice(), [Value::Stuck(bottom_callee, bottom_args)]
                if matches!(&**bottom_callee, Value::Atom(name) if name == "never_a")
                    && matches!(bottom_args.as_slice(), [Value::Atom(name)] if name == "x")),
            "expected __absurd__(never_a(x)), got {same_left:?}"
        );
        assert!(
            nf_eq(same_left, same_right, &ctx),
            "identical opaque bottom structure must compare equal"
        );
        assert!(
            !nf_eq(same_left, changed, &ctx),
            "a different bottom-producing host call must remain observable"
        );
    }

    #[test]
    fn partial_application_residualizes() {
        // A 2-param closure given 1 arg should residualize as Stuck.
        // Two such residuals built from alpha-equivalent closures
        // compare equal.
        let m =
            parse_module("module x; equiv partial { (.(x, y) { y })(()); (.(a, b) { b })(()) }");
        let ctx = EvalCtx::new();
        let v = eval_each(&equiv_terms(&m), &ctx);
        let (a, b) = first_two(&v);
        match a {
            Value::Stuck(_, args) => assert_eq!(args.len(), 1),
            _ => panic!("expected Stuck for partial app, got {a:?}"),
        }
        assert!(nf_eq(a, b, &ctx), "NFs were {a:?} vs {b:?}");
    }

