    #[test]
    fn if_then_else_true_selects_then_arm() {
        // ι-IfTrue (specs/formal/equiv.md § 2.2): a literal `.t`
        // condition reduces `__if_then_else__(_, t, e)` to `t(())`.
        // Both arms branch on `.t`, so both reduce to the then-arm
        // `f()` regardless of the (discarded) else arm.
        let m = parse_module(
            "module x; import __intrinsics__; \
             equiv if_t { \
               __if_then_else__(.t, .() { f() }, .() { g() }); \
               __if_then_else__(.t, .() { f() }, .() { h() }) }",
        );
        let ctx = EvalCtx::new();
        let v = eval_each(&equiv_terms(&m), &ctx);
        let (a, b) = first_two(&v);
        assert!(nf_eq(a, b, &ctx), "NFs were {a:?} vs {b:?}");
    }

    #[test]
    fn if_then_else_false_selects_else_arm() {
        // ι-IfFalse: a literal `.f` condition reduces to `e(())`.
        let m = parse_module(
            "module x; import __intrinsics__; \
             equiv if_f { \
               __if_then_else__(.f, .() { g() }, .() { f() }); \
               __if_then_else__(.f, .() { h() }, .() { f() }) }",
        );
        let ctx = EvalCtx::new();
        let v = eval_each(&equiv_terms(&m), &ctx);
        let (a, b) = first_two(&v);
        assert!(nf_eq(a, b, &ctx), "NFs were {a:?} vs {b:?}");
    }

    #[test]
    fn if_then_else_stuck_application_condition_is_structural() {
        // specs/formal/equiv.md § 2.2: a non-literal condition must
        // retain the condition and both handlers as structural residuals.
        let m = parse_module(
            "module x; import __intrinsics__; \
             equiv if_stuck { \
               __if_then_else__(condition(x), .() { f() }, .() { g() }); \
               __if_then_else__(condition(x), .() { f() }, .() { g() }); \
               __if_then_else__(condition(x), .() { f() }, .() { h() }) }",
        );
        let ctx = EvalCtx::new();
        let v = eval_each(&equiv_terms(&m), &ctx);
        let [same_left, same_right, changed] = v.as_slice() else {
            panic!("expected three residuals, got {v:?}");
        };
        let Value::Stuck(callee, args) = same_left else {
            panic!("expected a stuck __if_then_else__, got {same_left:?}");
        };
        assert!(
            matches!(&**callee, Value::Atom(name) if name == "__if_then_else__"),
            "expected the __if_then_else__ residual head, got {callee:?}"
        );
        let [condition_value, then_handler, else_handler] = args.as_slice() else {
            panic!("expected condition and two handlers, got {args:?}");
        };
        assert!(
            matches!(condition_value, Value::Stuck(source, source_args)
                if matches!(&**source, Value::Atom(name) if name == "condition")
                    && matches!(source_args.as_slice(), [Value::Atom(name)] if name == "x")),
            "expected the nested condition(x) residual, got {condition_value:?}"
        );
        assert!(
            matches!(then_handler, Value::EvalClosure { .. })
                && matches!(else_handler, Value::EvalClosure { .. }),
            "expected both handlers to remain closures, got {args:?}"
        );
        assert!(
            nf_eq(same_left, same_right, &ctx),
            "identical stuck conditionals must compare equal: {same_left:?} vs {same_right:?}"
        );

        let Value::Stuck(changed_callee, changed_args) = changed else {
            panic!("expected a stuck __if_then_else__, got {changed:?}");
        };
        assert!(matches!(&**changed_callee, Value::Atom(name) if name == "__if_then_else__"));
        let [changed_condition, changed_then, changed_else] = changed_args.as_slice() else {
            panic!("expected condition and two handlers, got {changed_args:?}");
        };
        assert!(nf_eq(condition_value, changed_condition, &ctx));
        assert!(nf_eq(then_handler, changed_then, &ctx));
        assert!(!nf_eq(else_handler, changed_else, &ctx));
        assert!(
            !nf_eq(same_left, changed, &ctx),
            "changing one handler must change the residual"
        );
    }

    #[test]
    fn iota_left_either_selects_left_handler() {
        // ι-LeftEither (specs/formal/equiv.md § 2.1): the sum
        // eliminator applied to a known left injection selects the
        // left handler. `__either__(__left__(a), fl, fr) → fl(a)`,
        // so both arms reduce to `f(a)` regardless of the (discarded)
        // right handler.
        let m = parse_module(
            "module x; import __intrinsics__; \
             equiv il { \
               __either__(__left__(a), .(l) { f(l) }, .(r) { g(r) }); \
               f(a) }",
        );
        let ctx = EvalCtx::new();
        let v = eval_each(&equiv_terms(&m), &ctx);
        let (a, b) = first_two(&v);
        assert!(nf_eq(a, b, &ctx), "NFs were {a:?} vs {b:?}");
    }

    #[test]
    fn iota_right_either_selects_right_handler() {
        // ι-RightEither: a known right injection selects the right
        // handler.
        let m = parse_module(
            "module x; import __intrinsics__; \
             equiv ir { \
               __either__(__right__(b), .(l) { g(l) }, .(r) { f(r) }); \
               f(b) }",
        );
        let ctx = EvalCtx::new();
        let v = eval_each(&equiv_terms(&m), &ctx);
        let (a, b) = first_two(&v);
        assert!(nf_eq(a, b, &ctx), "NFs were {a:?} vs {b:?}");
    }

    #[test]
    fn iota_either_stuck_scrutinee_symbolically_splits() {
        // specs/formal/equiv.md § 2.6: a genuine application residual
        // retains both possible branches in a symbolic case split.
        let m = parse_module(
            "module x; import __intrinsics__; \
             equiv ie { \
               __either__(source(x), .(l) { f(l) }, .(r) { g(r) }); \
               __either__(source(x), .(l) { g(l) }, .(r) { f(r) }) }",
        );
        let ctx = EvalCtx::new();
        let v = eval_each(&equiv_terms(&m), &ctx);
        let (a, b) = first_two(&v);
        for value in [a, b] {
            match value {
                Value::CaseSplit { scrutinee, .. } => assert!(
                    matches!(&**scrutinee, Value::Stuck(callee, args)
                        if matches!(&**callee, Value::Atom(name) if name == "source")
                            && matches!(args.as_slice(), [Value::Atom(name)] if name == "x")),
                    "expected a case split over source(x), got {scrutinee:?}"
                ),
                other => panic!("expected Value::CaseSplit, got {other:?}"),
            }
        }
        assert!(!nf_eq(a, b, &ctx), "expected unequal, got {a:?} == {b:?}");
    }

    #[test]
    fn iota_fst_snd_select_pair_components() {
        // ι-Fst / ι-Snd: a projection over a known pair selects the
        // matching component. `__fst__(__pair__(a, b)) → a`,
        // `__snd__(__pair__(a, b)) → b`.
        let m_fst = parse_module(
            "module x; import __intrinsics__; \
             equiv pf { __fst__(__pair__(a, b)); a }",
        );
        let m_snd = parse_module(
            "module x; import __intrinsics__; \
             equiv ps { __snd__(__pair__(a, b)); b }",
        );
        let ctx = EvalCtx::new();
        for m in [&m_fst, &m_snd] {
            let v = eval_each(&equiv_terms(m), &ctx);
            let (a, b) = first_two(&v);
            assert!(nf_eq(a, b, &ctx), "NFs were {a:?} vs {b:?}");
        }
    }

    #[test]
    fn iota_newtype_unwraps_constructor() {
        // ι-Newtype (specs/formal/equiv.md § 2.1): a newtype projector
        // applied to the matching constructor's wrap unwraps it. The
        // `labels { wrap[A]: A }` block mints newtype `Wrap` with
        // constructor `mk` and projector `get`; lexical resolution gives
        // both members the same declaration identity, so
        // `Wrap.get(Wrap.mk(x)) → x`. `parse_module` runs
        // label lowering, so the `Item::Newtype` is present to
        // expose. Use explicit Kio' newtype members here: surface
        // label construction has already been removed at the evaluator
        // boundary.
        let m = parse_module(
            "module x; \
             labels { wrap[A]: A }; \
             equiv nt { Wrap.get(A, Wrap.mk(A, x)); x }",
        );
        let ctx = EvalCtx::new()
            .with_fn_defs(fn_def_map(&m))
            .with_root_module(&m);
        let v = eval_each(&equiv_terms(&m), &ctx);
        let (a, b) = first_two(&v);
        assert!(nf_eq(a, b, &ctx), "NFs were {a:?} vs {b:?}");
    }

    #[test]
    fn iota_newtype_unregistered_projector_stays_stuck() {
        // Without a lexical newtype-member declaration, a projector-shaped
        // path is just an opaque atom — the rule must not fire on an unknown
        // pairing. `wrap(mk_wrap(x))` with no member scope stays a residual,
        // distinct from the bare `x`.
        let m = parse_module(
            "module x; import __intrinsics__; \
             equiv nt_stuck { Wrap.wrap(Wrap.mk_wrap(x)); x }",
        );
        let ctx = EvalCtx::new(); // no registry
        let v = eval_each(&equiv_terms(&m), &ctx);
        let (a, b) = first_two(&v);
        assert!(!nf_eq(a, b, &ctx), "expected unequal, got {a:?} == {b:?}");
    }

    #[test]
    fn lexical_newtype_members_keep_exact_declaration_identity() {
        let pkg = lowered_package(&[
            (
                "a.kio",
                "module a; pub newtype Wrap[A] : A { pub constructor mk; pub projector get; };",
            ),
            (
                "b.kio",
                "module b; pub newtype Wrap[A] : A { pub constructor mk; pub projector get; };",
            ),
            (
                "consumer.kio",
                "module consumer; import a as n; fn keep() -> . { () }",
            ),
            (
                "selective.kio",
                "module selective; import a(Wrap); fn keep() -> . { () }",
            ),
        ]);
        let a = &pkg.module("a").expect("module a").module;
        let b = &pkg.module("b").expect("module b").module;
        let consumer = &pkg.module("consumer").expect("consumer").module;
        let selective = &pkg.module("selective").expect("selective").module;
        let path = |parts: &[&str]| {
            parts
                .iter()
                .map(|part| PathSegment::synth((*part).to_owned(), zero_span()))
                .collect::<Vec<_>>()
        };
        let a_ctx = EvalCtx::for_module(&pkg, a, "a").expect("a context");
        let b_ctx = EvalCtx::for_module(&pkg, b, "b").expect("b context");
        let consumer_ctx =
            EvalCtx::for_module(&pkg, consumer, "consumer").expect("consumer context");

        let a_ctor =
            resolve_module_newtype_member(&a_ctx, a, &path(&["Wrap", "mk"])).expect("a.Wrap.mk");
        let b_ctor =
            resolve_module_newtype_member(&b_ctx, b, &path(&["Wrap", "mk"])).expect("b.Wrap.mk");
        let imported =
            resolve_module_newtype_member(&consumer_ctx, consumer, &path(&["n", "Wrap", "mk"]))
                .expect("qualified a.Wrap.mk");

        assert!(!a_ctor.semantic_eq(&b_ctor));
        assert!(a_ctor.semantic_eq(&imported));
        assert_eq!(a_ctor.display, "Wrap.mk");
        assert_eq!(imported.display, "n.Wrap.mk");
        assert!(resolve_module_newtype_member(&a_ctx, a, &path(&["mk"])).is_none());

        let a_data = apply(Value::NewtypeMember(a_ctor), vec![Value::Unit], &a_ctx);
        let b_data = apply(Value::NewtypeMember(b_ctor), vec![Value::Unit], &b_ctx);
        assert!(!nf_eq(&a_data, &b_data, &a_ctx));
        assert_eq!(value_to_string(&a_data), "Wrap.mk(())");
        assert_eq!(value_to_string(&b_data), "Wrap.mk(())");
        assert_eq!(value_to_repl_string(&a_data, a), "Wrap.mk(())");
        assert_eq!(value_to_repl_string(&a_data, consumer), "n.Wrap.mk(())");
        assert_eq!(value_to_repl_string(&a_data, selective), "Wrap.mk(())");
    }

    #[test]
    fn repl_rendering_requalifies_distinct_newtype_owners_without_alias_collisions() {
        let pkg = lowered_package(&[
            (
                "a/one.kio",
                "module a/one; pub newtype Wrap : . { pub constructor mk; pub projector get; };",
            ),
            (
                "b/two.kio",
                "module b/two; pub newtype Wrap : . { pub constructor mk; pub projector get; };",
            ),
            (
                "left.kio",
                "module left; import a/one as _q0; fn keep() -> . { () }",
            ),
            (
                "right.kio",
                "module right; import b/two as _q0; fn keep() -> . { () }",
            ),
            ("occupied.kio", "module occupied; fn keep() -> . { () }"),
            (
                "consumer.kio",
                "module consumer; import occupied as _q1; fn _q0() -> . { () }",
            ),
        ]);
        let left = &pkg.module("left").expect("left module").module;
        let right = &pkg.module("right").expect("right module").module;
        let consumer = &pkg.module("consumer").expect("consumer module").module;
        let path = |parts: &[&str]| {
            parts
                .iter()
                .map(|part| PathSegment::synth((*part).to_owned(), zero_span()))
                .collect::<Vec<_>>()
        };
        let left_ctx = EvalCtx::for_module(&pkg, left, "left").expect("left context");
        let right_ctx = EvalCtx::for_module(&pkg, right, "right").expect("right context");

        let left_ctor =
            resolve_module_newtype_member(&left_ctx, left, &path(&["_q0", "Wrap", "mk"]))
                .expect("left imported constructor");
        let right_projector =
            resolve_module_newtype_member(&right_ctx, right, &path(&["_q0", "Wrap", "get"]))
                .expect("right imported projector");
        let residual = data_value(
            "__pair__",
            vec![
                apply(
                    Value::NewtypeMember(left_ctor),
                    vec![Value::Unit],
                    &left_ctx,
                ),
                Value::NewtypeMember(right_projector),
            ],
        );

        assert_eq!(
            value_to_string(&residual),
            "__pair__(_q0.Wrap.mk(()), _q0.Wrap.get)"
        );
        assert_eq!(
            value_to_repl_string(&residual, consumer),
            "import a/one as _q2;\nimport b/two as _q3;\n\n__pair__(_q2.Wrap.mk(()), _q3.Wrap.get)"
        );
    }

    #[test]
    fn repl_rendering_avoids_residual_atom_heads_when_allocating_imports() {
        let pkg = lowered_package(&[
            (
                "inner/a.kio",
                "module inner/a; pub newtype Wrap : . { pub constructor mk; pub projector get; };",
            ),
            ("consumer.kio", "module consumer; fn keep() -> . { () }"),
        ]);
        let inner = &pkg.module("inner/a").expect("inner/a module").module;
        let consumer = &pkg.module("consumer").expect("consumer module").module;
        let ctx = EvalCtx::for_module(&pkg, inner, "inner/a").expect("inner/a context");
        let path = ["Wrap", "mk"]
            .into_iter()
            .map(|part| PathSegment::synth(part.to_owned(), zero_span()))
            .collect::<Vec<_>>();
        let ctor = resolve_module_newtype_member(&ctx, inner, &path).expect("inner/a.Wrap.mk");
        let wrapped = apply(Value::NewtypeMember(ctor), vec![Value::Unit], &ctx);
        let residual = data_value("__pair__", vec![Value::Atom("_q0".to_owned()), wrapped]);

        assert_eq!(
            value_to_repl_string(&residual, consumer),
            "import inner/a as _q1;\n\n__pair__(_q0, _q1.Wrap.mk(()))"
        );
    }

    #[test]
    fn repl_rendering_names_named_closures_and_suffix_parameters() {
        let pkg = lowered_package(&[
            (
                "provider.kio",
                "module provider; pub pure fn wrap(x: .)(y: .) -> . { x; y }",
            ),
            (
                "consumer.kio",
                "module consumer; import provider as p; fn expose() -> . { p.wrap }",
            ),
        ]);
        let consumer = &pkg.module("consumer").expect("consumer").module;
        let expose = find_module_fn(consumer, "expose").expect("expose fn");
        let ctx = EvalCtx::for_module(&pkg, consumer, "consumer").expect("consumer context");
        let closure = eval(&expose.body, &Env::new(), &ctx);

        assert_eq!(
            value_to_repl_string(&closure, consumer),
            "<closure provider.wrap(x)(y)>"
        );

        let suffix = apply(closure, vec![Value::Unit], &ctx);
        assert_eq!(
            value_to_repl_string(&suffix, consumer),
            "<closure provider.wrap(y)>"
        );
    }

    #[test]
    fn repl_rendering_names_anonymous_closures_by_owner_and_source_span() {
        let pkg = lowered_package(&[
            (
                "provider.kio",
                "module provider; pub pure fn make() -> . -> . { .(z: .) -> . { z } }",
            ),
            (
                "consumer.kio",
                "module consumer; import provider as p; fn expose() -> . { p.make() }",
            ),
        ]);
        let provider = &pkg.module("provider").expect("provider").module;
        let make = find_module_fn(provider, "make").expect("make fn");
        let Expr::FnExpr { meta, .. } = &make.body else {
            panic!("make body should be a lambda");
        };
        let consumer = &pkg.module("consumer").expect("consumer").module;
        let expose = find_module_fn(consumer, "expose").expect("expose fn");
        let ctx = EvalCtx::for_module(&pkg, consumer, "consumer").expect("consumer context");
        let closure = eval(&expose.body, &Env::new(), &ctx);
        let expected = format!(
            "<closure provider.make::<fn@{}-{}>(z)>",
            meta.span.start, meta.span.end
        );

        assert_eq!(value_to_repl_string(&closure, consumer), expected);
    }

    #[test]
    fn repl_rendering_preserves_private_saturated_and_residual_newtype_members() {
        let pkg = lowered_package(&[
            (
                "secret.kio",
                "module secret; \
                 newtype Hidden[A, B, C] : A & B & C { constructor mk; projector get; };",
            ),
            ("consumer.kio", "module consumer; fn keep() -> . { () }"),
        ]);
        let secret = &pkg.module("secret").expect("secret").module;
        let consumer = &pkg.module("consumer").expect("consumer").module;
        let ctx = EvalCtx::for_module(&pkg, secret, "secret").expect("secret context");
        let path = |parts: &[&str]| {
            parts
                .iter()
                .map(|part| PathSegment::synth((*part).to_owned(), zero_span()))
                .collect::<Vec<_>>()
        };
        let ctor = resolve_module_newtype_member(&ctx, secret, &path(&["Hidden", "mk"]))
            .expect("private constructor");
        let projector = resolve_module_newtype_member(&ctx, secret, &path(&["Hidden", "get"]))
            .expect("private projector");
        let saturated = apply(
            Value::NewtypeMember(ctor.clone()),
            vec![
                Value::Atom("left".to_owned()),
                Value::Atom("middle".to_owned()),
                Value::Atom("right".to_owned()),
            ],
            &ctx,
        );
        let partial = apply(
            Value::NewtypeMember(ctor),
            vec![
                Value::Atom("partial_left".to_owned()),
                Value::Atom("partial_right".to_owned()),
            ],
            &ctx,
        );
        let residual_projector = apply(
            Value::NewtypeMember(projector),
            vec![Value::Atom("opaque".to_owned())],
            &ctx,
        );
        assert!(matches!(saturated, Value::Data(_)));
        assert!(matches!(partial, Value::Stuck(_, _)));
        assert!(matches!(residual_projector, Value::Stuck(_, _)));
        let residual = data_value(
            "__pair__",
            vec![
                saturated,
                data_value("__pair__", vec![partial, residual_projector]),
            ],
        );

        assert_eq!(
            value_to_repl_string(&residual, consumer),
            "import secret as _q0;\n\n\
             __pair__(_q0.Hidden.mk(__pair__(left, __pair__(middle, right))), __pair__(_q0.Hidden.mk(partial_left, partial_right), _q0.Hidden.get(opaque)))"
        );
    }

    #[test]
    fn newtype_member_values_apply_higher_order() {
        let (mut m, [body]) = parse_module_with_bodies(
            "module a; \
             newtype Wrap[A] : A { pub constructor mk; pub projector get; }; \
             equiv members { Wrap.mk; Wrap.get } \
             equiv applied { \
                 (); \
                 x \
             }",
            ["let ctor = Wrap.mk; let proj = Wrap.get; proj(A, ctor(A, x))"],
        );
        m.equivs[1].terms[0] = body;
        let ctx = EvalCtx::new().with_root_module(&m);
        let mut equivs = m.equivs.iter();
        let members = eval_each(
            &equivs
                .next()
                .expect("members equiv")
                .terms
                .iter()
                .collect::<Vec<_>>(),
            &ctx,
        );
        let payload = Value::Atom("payload".to_owned());
        let wrapped = apply(members[0].clone(), vec![payload.clone()], &ctx);
        let unwrapped = apply(members[1].clone(), vec![wrapped], &ctx);

        assert!(matches!(unwrapped, Value::Atom(name) if name == "payload"));

        let applied = equivs.next().expect("applied equiv");
        let values = applied
            .terms
            .iter()
            .map(|term| eval(term, &Env::new(), &ctx))
            .collect::<Vec<_>>();
        assert!(nf_eq(&values[0], &values[1], &ctx));
    }

    #[test]
    fn imported_newtype_members_follow_selective_and_member_visibility() {
        let pkg = lowered_package(&[
            (
                "provider.kio",
                "module provider; \
                 rec { \
                   pub newtype Wrap[A] : A & Peer(A) { pub constructor mk; pub projector get; }; \
                   newtype Peer[A] : Wrap(A) { constructor make_peer; projector un_peer; }; \
                 } \
                 pub type Alias[A] = Wrap(A); \
                 pub newtype Hidden[A] : A { constructor mk; projector get; };",
            ),
            (
                "consumer.kio",
                "module consumer; \
                 import provider(Wrap, Alias, Hidden); \
                 import provider as p; \
                 fn keep() -> . { () }",
            ),
        ]);
        let provider = &pkg.module("provider").expect("provider").module;
        let consumer = &pkg.module("consumer").expect("consumer").module;
        let path = |parts: &[&str]| {
            parts
                .iter()
                .map(|part| PathSegment::synth((*part).to_owned(), zero_span()))
                .collect::<Vec<_>>()
        };
        let provider_ctx =
            EvalCtx::for_module(&pkg, provider, "provider").expect("provider context");
        let consumer_ctx =
            EvalCtx::for_module(&pkg, consumer, "consumer").expect("consumer context");

        let local = resolve_module_newtype_member(&provider_ctx, provider, &path(&["Wrap", "mk"]))
            .expect("provider Wrap.mk");
        let selective =
            resolve_module_newtype_member(&consumer_ctx, consumer, &path(&["Wrap", "mk"]))
                .expect("selective Wrap.mk");
        let qualified =
            resolve_module_newtype_member(&consumer_ctx, consumer, &path(&["p", "Wrap", "mk"]))
                .expect("qualified p.Wrap.mk");
        assert!(local.semantic_eq(&selective));
        assert!(local.semantic_eq(&qualified));
        let selective_alias =
            resolve_module_newtype_member(&consumer_ctx, consumer, &path(&["Alias", "mk"]))
                .expect("selective Alias.mk");
        let qualified_alias =
            resolve_module_newtype_member(&consumer_ctx, consumer, &path(&["p", "Alias", "get"]))
                .expect("qualified p.Alias.get");
        assert!(local.semantic_eq(&selective_alias));
        let local_projector =
            resolve_module_newtype_member(&provider_ctx, provider, &path(&["Wrap", "get"]))
                .expect("provider Wrap.get");
        assert!(local_projector.semantic_eq(&qualified_alias));

        assert!(
            resolve_module_newtype_member(&consumer_ctx, consumer, &path(&["Hidden", "mk"]),)
                .is_none()
        );
        assert!(
            resolve_module_newtype_member(&consumer_ctx, consumer, &path(&["p", "Hidden", "get"]),)
                .is_none()
        );
    }

    #[test]
    fn imported_helper_resolves_newtypes_in_its_definition_module() {
        let pkg = lowered_package(&[
            (
                "provider.kio",
                "module provider; \
                 pub newtype Wrap[A] : A { pub constructor mk; pub projector get; }; \
                 pub fn wrap[A](x: A) -> Wrap(A) { Wrap.mk(A, x) }",
            ),
            (
                "consumer.kio",
                "module consumer; \
                 import provider as p; \
                 newtype Wrap[A] : A { constructor mk; projector get; }; \
                 fn run[A](x: A) -> A { p.Wrap.get(A, p.wrap(A, x)) }",
            ),
        ]);
        let consumer = &pkg.module("consumer").expect("consumer").module;
        let run = find_module_fn(consumer, "run").expect("run fn");
        let ctx = EvalCtx::for_module(&pkg, consumer, "consumer").expect("consumer context");
        let mut env = Env::new();
        env.insert("x".to_owned(), Value::Atom("payload".to_owned()));

        let value = eval(&run.body, &env, &ctx);
        assert!(
            matches!(&value, Value::Atom(name) if name == "payload"),
            "helper body resolved its newtype in the caller module: {value:?}"
        );
    }

    // =====================================================================
    // `Value::Data` construction + case-reduction over the full
    // `__intrinsics__` vocabulary, exercised against the REAL EvalPhase
    // shape: constructors carry LEADING erased type-args
    // (`__pair__(A, B, x, y)`, `__left__(A, B, x)`). A type-arg-
    // free spelling cannot distinguish a correct trailing-N extraction
    // from a no-op, so every construction test feeds explicit type-args
    // and asserts the built `Value::Data` payload directly.
    // =====================================================================

    /// Evaluate a single-expr equiv arm to a `Value`, with
    /// `__intrinsics__` in scope. Returns the first arm's NF.
    fn eval_one(src_body: &str) -> Value {
        let m = parse_module(&format!(
            "module x; import __intrinsics__; equiv probe {{ {src_body}; () }}"
        ));
        let ctx = EvalCtx::new();
        eval(equiv_terms(&m)[0], &Env::new(), &ctx)
    }

    #[test]
    fn mk_left_builds_data_dropping_leading_type_args() {
        // `__left__(A, B, x)` — two leading erased type-args, one
        // value payload. Builds `Data { "__left__", [X] }`.
        let v = eval_one("__left__(A, B, x)");
        match v {
            Value::Data(data) => {
                assert_eq!(data.ctor(), "__left__");
                assert_eq!(
                    data.args().len(),
                    1,
                    "type-args must be dropped: {:?}",
                    data.args()
                );
                assert!(matches!(&data.args()[0], Value::Atom(n) if n == "x"));
            }
            other => panic!("expected Value::Data, got {other:?}"),
        }
    }

    #[test]
    fn mk_right_builds_data_dropping_leading_type_args() {
        let v = eval_one("__right__(A, B, y)");
        match v {
            Value::Data(data) => {
                assert_eq!(data.ctor(), "__right__");
                assert_eq!(data.args().len(), 1);
                assert!(matches!(&data.args()[0], Value::Atom(n) if n == "y"));
            }
            other => panic!("expected Value::Data, got {other:?}"),
        }
    }

    #[test]
    fn mk_pair_builds_data_dropping_leading_type_args() {
        // `__pair__(A, B, x, y)` — two leading erased type-args, two
        // value components. Builds `Data { "__pair__", [x, y] }`.
        let v = eval_one("__pair__(A, B, x, y)");
        match v {
            Value::Data(data) => {
                assert_eq!(data.ctor(), "__pair__");
                assert_eq!(
                    data.args().len(),
                    2,
                    "exactly two components: {:?}",
                    data.args()
                );
                assert!(matches!(&data.args()[0], Value::Atom(n) if n == "x"));
                assert!(matches!(&data.args()[1], Value::Atom(n) if n == "y"));
            }
            other => panic!("expected Value::Data, got {other:?}"),
        }
    }

    #[test]
    fn either_over_data_left_with_type_args_selects_left() {
        // ι-LeftEither against the REAL injection shape: the scrutinee
        // is `__left__(A, B, x)` (with type-args), built to
        // `Value::Data`; `__either__(C, D, E, scrut, fl, fr)` selects
        // `fl(x)`. Both arms must reduce to `f(x)`.
        let m = parse_module(
            "module x; import __intrinsics__; \
             equiv il { \
               __either__(A, B, C, __left__(A, B, x), .(l) { f(l) }, .(r) { g(r) }); \
               f(x) }",
        );
        let ctx = EvalCtx::new();
        let v = eval_each(&equiv_terms(&m), &ctx);
        let (a, b) = first_two(&v);
        assert!(nf_eq(a, b, &ctx), "NFs were {a:?} vs {b:?}");
    }

