    #[test]
    fn apply_reflection_term_builtins_build_checked_terms() {
        let ctx = EvalCtx::new();
        let unit = || Type::Unit { meta: zero_meta() };

        // __term_type__ reflects a checked term's stored type.
        let term_type = apply(
            Value::Primitive(ComptimeBuiltin::TermType),
            vec![checked_term_value(
                Expr::Unit {
                    occurrence: Default::default(),
                    meta: zero_meta(),
                },
                unit(),
            )],
            &ctx,
        );
        assert!(
            matches!(as_refl_type_ref(&term_type), Some(Type::Unit { .. })),
            "{term_type:?}"
        );

        // __term_fn__(fn_type, body): a unit-domain function.
        let unit_ty = unit();
        let fn_ty = Type::Function {
            param: Box::new(unit_ty.clone()),
            ret: Box::new(unit_ty.clone()),
            meta: zero_meta(),
            abi_arity: Type::function_param_abi_slot_count(&unit_ty),
            caps: (),
        };
        let body = Value::EvalClosure {
            function: test_eval_function(&["packet"], EvalExpr::ReflTermUnit),
            captured: Vec::<Value>::new().into(),
        };
        let term_fn = apply(
            Value::Primitive(ComptimeBuiltin::TermFn),
            vec![refl_type_value(fn_ty), body],
            &ctx,
        );
        assert!(matches!(term_fn, Value::CheckedTerm(_)), "{term_fn:?}");

        // __term_type_fn__(arity, body).
        let type_body = Value::EvalClosure {
            function: test_eval_function(&["tv"], EvalExpr::ReflTermUnit),
            captured: Vec::<Value>::new().into(),
        };
        let term_type_fn = apply(
            Value::Primitive(ComptimeBuiltin::TermTypeFn),
            vec![Value::ReflTypeArity(0), type_body],
            &ctx,
        );
        let Value::CheckedTerm(term_type_fn) = term_type_fn else {
            panic!("expected checked type-function term: {term_type_fn:?}")
        };
        let Type::Forall {
            body: forall_body, ..
        } = term_type_fn.ty()
        else {
            panic!("type-function term stored a non-forall type")
        };
        assert!(matches!(forall_body.as_ref(), Type::Unit { .. }));
        let CheckedTermNode::TermCall {
            fn_value,
            params,
            arg_packet,
        } = term_type_fn.node.as_ref()
        else {
            panic!("type-function term was not materialized through its Unit call")
        };
        assert!(params.is_empty());
        assert!(matches!(arg_packet.ty(), Type::Unit { .. }));
        assert!(matches!(
            arg_packet.node.as_ref(),
            CheckedTermNode::Raw(Expr::Unit { .. })
        ));
        let CheckedTermNode::TermFn { sig, body } = fn_value.node.as_ref() else {
            panic!("type-function Unit call did not wrap a checked function")
        };
        assert_eq!(
            sig.groups,
            vec![
                crate::ast::SignatureGroupKind::Value { len: 0 },
                crate::ast::SignatureGroupKind::Type { len: 1 },
            ]
        );
        assert!(matches!(body.ty(), Type::Unit { .. }));
        let Type::Function {
            param,
            ret,
            abi_arity,
            ..
        } = fn_value.ty()
        else {
            panic!("type-function wrapper stored a non-function type")
        };
        assert_eq!(*abi_arity, 0);
        assert!(matches!(param.as_ref(), Type::Unit { .. }));
        assert_eq!(ret.as_ref(), term_type_fn.ty());

        // __term_type_app__: apply a forall-typed term to a type arg.
        let forall_ty = Type::Forall {
            param: TypeParam {
                name: "A".into(),
                span: zero_span(),
                kind: None,
            },
            body: Box::new(Type::synth_path(vec!["A".into()], Vec::new(), zero_span())),
            meta: zero_meta(),
        };
        let poly = checked_term_value(path_expr("f"), forall_ty);
        let term_type_app = apply(
            Value::Primitive(ComptimeBuiltin::TermTypeApp),
            vec![poly, refl_type_value(unit())],
            &ctx,
        );
        assert!(
            matches!(term_type_app, Value::CheckedTerm(_)),
            "{term_type_app:?}"
        );

        // __term_call__ over a product-domain function drives
        // split_function_params → split_product_prefix's Product arm.
        let product_ty = Type::Product {
            left: Box::new(unit()),
            right: Box::new(unit()),
            meta: zero_meta(),
        };
        let call_fn_ty = Type::Function {
            param: Box::new(product_ty.clone()),
            ret: Box::new(unit()),
            meta: zero_meta(),
            abi_arity: Type::function_param_abi_slot_count(&product_ty),
            caps: (),
        };
        let fn_value = checked_term_value(path_expr("g"), call_fn_ty.clone());
        let arg_packet = checked_term_value(
            Expr::Unit {
                occurrence: Default::default(),
                meta: zero_meta(),
            },
            product_ty,
        );
        let term_call = apply(
            Value::Primitive(ComptimeBuiltin::TermCall),
            vec![refl_type_value(call_fn_ty), fn_value, arg_packet],
            &ctx,
        );
        assert!(matches!(term_call, Value::CheckedTerm(_)), "{term_call:?}");
    }

    #[test]
    fn term_specialize_uses_shared_solver_and_instantiates_in_binder_order() {
        let ctx = EvalCtx::new();
        let param = TypeParam {
            name: "A".into(),
            span: zero_span(),
            kind: None,
        };
        let pattern = Type::synth_path(vec!["A".into()], Vec::new(), zero_span());
        let poly_type = Type::Forall {
            param,
            body: Box::new(pattern.clone()),
            meta: zero_meta(),
        };
        let result = apply(
            Value::Primitive(ComptimeBuiltin::TermSpecialize),
            vec![
                checked_term_value(path_expr("poly"), poly_type),
                refl_type_value(pattern),
                refl_type_value(Type::Unit { meta: zero_meta() }),
            ],
            &ctx,
        );
        let Value::Data(success) = result else {
            panic!("specialization did not return its success injection: {result:?}")
        };
        assert_eq!(success.ctor(), "__left__");
        let [Value::CheckedTerm(specialized)] = success.args() else {
            panic!("specialization success did not carry a checked term: {success:?}")
        };
        assert!(matches!(specialized.ty(), Type::Unit { .. }));
        assert!(matches!(
            specialized.node.as_ref(),
            CheckedTermNode::TermTypeApp {
                arg: Type::Unit { .. },
                ..
            }
        ));
    }

    #[test]
    fn projected_term_specialize_returns_an_authenticated_projected_recipe() {
        let ctx = EvalCtx::new();
        let (proof, fills, term) =
            crate::pass::typecheck_core::apply::fills::specialization_term_for_test();
        let original = term.clone();
        let (proof, _fills) = fills_capability_values(proof, fills);
        let result = apply(
            Value::Primitive(ComptimeBuiltin::TermSpecialize),
            vec![
                proof.clone(),
                projected_value(term),
                refl_type_value(Type::synth_path(
                    vec!["A".to_owned()],
                    Vec::new(),
                    zero_span(),
                )),
                refl_type_value(Type::Unit { meta: zero_meta() }),
            ],
            &ctx,
        );
        let Value::Data(success) = result else {
            panic!("projected specialization did not return a sum: {result:?}")
        };
        assert_eq!(success.ctor(), "__left__");
        let [Value::Projected(specialized)] = success.args() else {
            panic!("projected specialization success lost its recipe: {success:?}")
        };
        let proof_capability = marked_comptime_proof_from_value(&proof).unwrap();
        assert!(specialized.matches_proof(proof_capability));
        assert!(
            !specialized.same_snapshot(&original),
            "specialization must add the inferred type application to the recipe"
        );
        assert!(
            specialized.closed_term().is_none(),
            "projected specialization must not force its producer recipe closed"
        );
        assert!(
            crate::pass::typecheck_core::apply::fills::specialization_evidence_for_test(
                &original,
                specialized,
            ),
            "specialization must preserve exact scope, focus, and producer provenance"
        );

        let specialized_type = apply(
            Value::Primitive(ComptimeBuiltin::TermType),
            vec![proof.clone(), Value::Projected(specialized.clone())],
            &ctx,
        );
        assert!(
            matches!(specialized_type, Value::Projected(_)),
            "__term_type__ must retain the specialized projected type handle"
        );
        let view = apply(
            Value::Primitive(ComptimeBuiltin::TypeView),
            vec![proof, specialized_type],
            &ctx,
        );
        assert!(
            matches!(&view, Value::Data(unit) if unit.ctor() == "__left__" && matches!(unit.args(), [Value::Unit])),
            "__type_view__ must structurally reduce the projected specialized result: {view:?}"
        );
    }

    #[test]
    fn staged_reflection_reapplication_retains_a_marked_comptime_proof() {
        let ctx = EvalCtx::new();
        let (proof, fills, term) =
            crate::pass::typecheck_core::apply::fills::specialization_term_for_test();
        let (proof, _fills) = fills_capability_values(proof, fills);
        let proof_capability = marked_comptime_proof_from_value(&proof).unwrap();

        let partially_applied = apply(
            Value::Primitive(ComptimeBuiltin::TermType),
            vec![proof.clone()],
            &ctx,
        );
        let reflected = apply(partially_applied, vec![projected_value(term)], &ctx);
        let Value::Projected(reflected) = reflected else {
            panic!("staged __term_type__ lost its marked proof: {reflected:?}")
        };
        assert!(reflected.matches_proof(proof_capability));
        assert!(reflected.is_type());
    }

    #[test]
    fn multi_stage_reflection_reapplication_flattens_a_marked_proof_prefix() {
        let ctx = EvalCtx::new();
        let (proof, _fills) = fresh_fills_capability_values();
        let with_proof = apply(
            Value::Primitive(ComptimeBuiltin::TypeProduct),
            vec![proof],
            &ctx,
        );
        let with_left = apply(
            with_proof,
            vec![refl_type_value(Type::Unit { meta: zero_meta() })],
            &ctx,
        );
        let product = apply(
            with_left,
            vec![refl_type_value(Type::Bottom { meta: zero_meta() })],
            &ctx,
        );
        assert!(matches!(
            as_refl_type_ref(&product),
            Some(Type::Product { left, right, .. })
                if matches!(left.as_ref(), Type::Unit { .. })
                    && matches!(right.as_ref(), Type::Bottom { .. })
        ));
    }

    #[test]
    fn projected_type_constructor_batch_reduces_without_closing_the_operand() {
        use crate::pass::typecheck_core::apply::fills::{
            ProjectedTypeView, focused_type_for_test, projected_type_arguments, projected_type_view,
        };

        let ctx = EvalCtx::new();
        let (proof, _fills) = fresh_fills_capability_values();
        let proof_capability = marked_comptime_proof_from_value(&proof).unwrap();
        let projected = |ty| {
            projected_value(focused_type_for_test(
                proof_capability,
                ReflectedType::new_trusted(ty),
            ))
        };
        let unit = Type::Unit { meta: zero_meta() };
        let bottom = Type::Bottom { meta: zero_meta() };

        let product = apply(
            Value::Primitive(ComptimeBuiltin::TypeProduct),
            vec![
                proof.clone(),
                projected(unit.clone()),
                refl_type_value(bottom),
            ],
            &ctx,
        );
        let Value::Projected(product) = product else {
            panic!("projected __type_product__ did not retain a type handle: {product:?}")
        };
        assert!(matches!(
            projected_type_view(proof_capability, &product).unwrap(),
            ProjectedTypeView::Product { .. }
        ));

        let arrow = apply(
            Value::Primitive(ComptimeBuiltin::TypeArrow),
            vec![
                proof.clone(),
                projected(unit.clone()),
                Value::ReflTypeArity(1),
                refl_type_value(unit.clone()),
            ],
            &ctx,
        );
        let Value::Projected(arrow) = arrow else {
            panic!("projected __type_arrow__ did not retain a type handle: {arrow:?}")
        };
        assert!(matches!(
            projected_type_view(proof_capability, &arrow).unwrap(),
            ProjectedTypeView::Function { abi_arity: 1, .. }
        ));

        let head = Type::synth_path(vec!["F".to_owned()], Vec::new(), zero_span());
        let applied = apply(
            Value::Primitive(ComptimeBuiltin::TypeApply),
            vec![
                proof.clone(),
                projected(head),
                refl_type_value(unit.clone()),
            ],
            &ctx,
        );
        let Value::Projected(applied) = applied else {
            panic!("projected __type_apply__ did not retain a type handle: {applied:?}")
        };
        let arguments = projected_type_arguments(proof_capability, &applied)
            .unwrap()
            .expect("a known projected path must expose its arguments");
        assert_eq!(arguments.len(), 1);
        assert!(matches!(
            projected_type_view(proof_capability, &arguments[0]).unwrap(),
            ProjectedTypeView::Unit
        ));

        let scheme = Type::Forall {
            param: TypeParam {
                name: "A".to_owned(),
                span: zero_span(),
                kind: None,
            },
            body: Box::new(Type::synth_path(
                vec!["A".to_owned()],
                Vec::new(),
                zero_span(),
            )),
            meta: zero_meta(),
        };
        let instantiated = apply(
            Value::Primitive(ComptimeBuiltin::TypeInstantiate),
            vec![proof.clone(), projected(scheme), refl_type_value(unit)],
            &ctx,
        );
        let Value::Data(success) = instantiated else {
            panic!("projected __type_instantiate__ did not return its result sum: {instantiated:?}")
        };
        assert_eq!(success.ctor(), "__left__");
        let [Value::Projected(instantiated)] = success.args() else {
            panic!("projected instantiation success lost its type handle: {success:?}")
        };
        assert!(matches!(
            projected_type_view(proof_capability, instantiated).unwrap(),
            ProjectedTypeView::Unit
        ));
    }

    #[test]
    fn projected_remaining_type_and_term_constructor_callbacks_reduce() {
        use crate::pass::typecheck_core::apply::fills::{
            ProjectedTypeView, projected_term_let_evidence_for_test, projected_type_view,
        };

        let ctx = EvalCtx::new();
        let (raw_proof, fills, template) =
            crate::pass::typecheck_core::apply::fills::specialization_term_for_test();
        let (proof, _fills) = fills_capability_values(raw_proof, fills);
        let proof_capability = marked_comptime_proof_from_value(&proof).unwrap();
        let unit = Type::Unit { meta: zero_meta() };
        let specialized = apply(
            Value::Primitive(ComptimeBuiltin::TermSpecialize),
            vec![
                proof.clone(),
                projected_value(template.clone()),
                refl_type_value(Type::synth_path(
                    vec!["A".to_owned()],
                    Vec::new(),
                    zero_span(),
                )),
                refl_type_value(unit.clone()),
            ],
            &ctx,
        );
        let Value::Data(success) = specialized else {
            panic!("projected specialization did not return a sum: {specialized:?}")
        };
        let [Value::Projected(unit_recipe)] = success.args() else {
            panic!("projected specialization did not return a recipe: {success:?}")
        };
        let unit_recipe = Value::Projected(unit_recipe.clone());
        let unit_type = apply(
            Value::Primitive(ComptimeBuiltin::TermType),
            vec![proof.clone(), unit_recipe.clone()],
            &ctx,
        );
        let unary_returning = |value| Value::EvalClosure {
            function: test_eval_function(&["ignored"], EvalExpr::Local(0)),
            captured: vec![value].into(),
        };

        let forall = apply(
            Value::Primitive(ComptimeBuiltin::TypeForall),
            vec![
                proof.clone(),
                Value::ReflTypeArity(0),
                unary_returning(unit_type.clone()),
            ],
            &ctx,
        );
        let Value::Projected(forall) = forall else {
            panic!("callback-only projected __type_forall__ stayed residual: {forall:?}")
        };
        assert!(matches!(
            projected_type_view(proof_capability, &forall).unwrap(),
            ProjectedTypeView::Forall { arity: 0, .. }
        ));

        let type_application = apply(
            Value::Primitive(ComptimeBuiltin::TermTypeApp),
            vec![
                proof.clone(),
                projected_value(template),
                refl_type_value(unit.clone()),
            ],
            &ctx,
        );
        let Value::Projected(type_application) = type_application else {
            panic!("projected __term_type_app__ stayed residual: {type_application:?}")
        };
        let type_application_type = apply(
            Value::Primitive(ComptimeBuiltin::TermType),
            vec![proof.clone(), Value::Projected(type_application)],
            &ctx,
        );
        let Value::Projected(type_application_type) = type_application_type else {
            panic!("projected type application lost its result type")
        };
        assert!(matches!(
            projected_type_view(proof_capability, &type_application_type).unwrap(),
            ProjectedTypeView::Unit
        ));

        let identity = || Value::EvalClosure {
            function: test_eval_function(&["value"], EvalExpr::Local(0)),
            captured: Vec::<Value>::new().into(),
        };
        let direct_let = apply(
            Value::Primitive(ComptimeBuiltin::TermLet),
            vec![
                proof.clone(),
                unit_type.clone(),
                unit_recipe.clone(),
                identity(),
            ],
            &ctx,
        );
        assert!(
            matches!(direct_let, Value::Projected(_)),
            "projected __term_let__ stayed residual: {direct_let:?}"
        );
        let callback_only_let = apply(
            Value::Primitive(ComptimeBuiltin::TermLet),
            vec![
                proof.clone(),
                refl_type_value(unit.clone()),
                checked_term_value(
                    Expr::Unit {
                        occurrence: Default::default(),
                        meta: zero_meta(),
                    },
                    unit.clone(),
                ),
                unary_returning(unit_recipe.clone()),
            ],
            &ctx,
        );
        assert!(
            matches!(callback_only_let, Value::Projected(_)),
            "callback-only projected __term_let__ stayed residual: {callback_only_let:?}"
        );
        let closed_type_projected_value_let = apply(
            Value::Primitive(ComptimeBuiltin::TermLet),
            vec![
                proof.clone(),
                refl_type_value(unit.clone()),
                unit_recipe.clone(),
                identity(),
            ],
            &ctx,
        );
        let Value::Projected(closed_type_projected_value_let) = closed_type_projected_value_let
        else {
            panic!(
                "closed-type projected-value __term_let__ stayed residual: {closed_type_projected_value_let:?}"
            )
        };
        assert!(projected_term_let_evidence_for_test(
            proof_capability,
            &closed_type_projected_value_let,
        ));

        let function_type = apply(
            Value::Primitive(ComptimeBuiltin::TypeArrow),
            vec![
                proof.clone(),
                unit_type.clone(),
                Value::ReflTypeArity(1),
                unit_type.clone(),
            ],
            &ctx,
        );
        let direct_fn = apply(
            Value::Primitive(ComptimeBuiltin::TermFn),
            vec![proof.clone(), function_type, identity()],
            &ctx,
        );
        assert!(
            matches!(direct_fn, Value::Projected(_)),
            "projected __term_fn__ stayed residual: {direct_fn:?}"
        );
        let ordinary_function_type = Type::Function {
            param: Box::new(unit.clone()),
            ret: Box::new(unit.clone()),
            meta: zero_meta(),
            abi_arity: 1,
            caps: (),
        };
        let callback_only_fn = apply(
            Value::Primitive(ComptimeBuiltin::TermFn),
            vec![
                proof.clone(),
                refl_type_value(ordinary_function_type),
                unary_returning(unit_recipe.clone()),
            ],
            &ctx,
        );
        assert!(
            matches!(callback_only_fn, Value::Projected(_)),
            "callback-only projected __term_fn__ stayed residual: {callback_only_fn:?}"
        );

        let type_fn = apply(
            Value::Primitive(ComptimeBuiltin::TermTypeFn),
            vec![
                proof.clone(),
                Value::ReflTypeArity(0),
                unary_returning(unit_recipe),
            ],
            &ctx,
        );
        let Value::Projected(type_fn) = type_fn else {
            panic!("callback-only projected __term_type_fn__ stayed residual: {type_fn:?}")
        };
        let type_fn_type = apply(
            Value::Primitive(ComptimeBuiltin::TermType),
            vec![proof.clone(), Value::Projected(type_fn)],
            &ctx,
        );
        let Value::Projected(type_fn_type) = type_fn_type else {
            panic!("projected type function lost its reflected type")
        };
        assert!(matches!(
            projected_type_view(proof_capability, &type_fn_type).unwrap(),
            ProjectedTypeView::Forall { arity: 0, .. }
        ));
    }

    #[test]
    fn projected_remaining_injections_and_conditional_callbacks_reduce() {
        use crate::pass::typecheck_core::apply::fills::{ProjectedTypeView, projected_type_view};

        let ctx = EvalCtx::new();
        let (raw_proof, fills, template) =
            crate::pass::typecheck_core::apply::fills::specialization_term_for_test();
        let (proof, _fills) = fills_capability_values(raw_proof, fills);
        let proof_capability = marked_comptime_proof_from_value(&proof).unwrap();
        let unit = Type::Unit { meta: zero_meta() };
        let specialized = apply(
            Value::Primitive(ComptimeBuiltin::TermSpecialize),
            vec![
                proof.clone(),
                projected_value(template),
                refl_type_value(Type::synth_path(
                    vec!["A".to_owned()],
                    Vec::new(),
                    zero_span(),
                )),
                refl_type_value(unit.clone()),
            ],
            &ctx,
        );
        let Value::Data(success) = specialized else {
            panic!("projected specialization did not return a sum: {specialized:?}")
        };
        let [Value::Projected(unit_recipe)] = success.args() else {
            panic!("projected specialization did not return a recipe: {success:?}")
        };
        let unit_recipe = Value::Projected(unit_recipe.clone());
        let unit_type = apply(
            Value::Primitive(ComptimeBuiltin::TermType),
            vec![proof.clone(), unit_recipe.clone()],
            &ctx,
        );
        let sum_type = apply(
            Value::Primitive(ComptimeBuiltin::TypeSum),
            vec![proof.clone(), unit_type.clone(), unit_type.clone()],
            &ctx,
        );

        for builtin in [
            ComptimeBuiltin::IntrinsicLeft,
            ComptimeBuiltin::IntrinsicRight,
        ] {
            let injected = apply(
                Value::Primitive(builtin),
                vec![proof.clone(), sum_type.clone(), unit_recipe.clone()],
                &ctx,
            );
            let Value::Projected(injected) = injected else {
                panic!("projected {builtin:?} stayed residual: {injected:?}")
            };
            let injected_type = apply(
                Value::Primitive(ComptimeBuiltin::TermType),
                vec![proof.clone(), Value::Projected(injected)],
                &ctx,
            );
            let Value::Projected(injected_type) = injected_type else {
                panic!("projected injection lost its result type")
            };
            assert!(matches!(
                projected_type_view(proof_capability, &injected_type).unwrap(),
                ProjectedTypeView::Sum { .. }
            ));
        }

        let nullary_returning = |value| Value::EvalClosure {
            function: test_eval_function(&[], EvalExpr::Local(0)),
            captured: vec![value].into(),
        };
        let direct = apply(
            Value::Primitive(ComptimeBuiltin::IntrinsicIfThenElse),
            vec![
                proof.clone(),
                unit_type,
                unit_recipe.clone(),
                nullary_returning(unit_recipe.clone()),
                nullary_returning(unit_recipe.clone()),
            ],
            &ctx,
        );
        assert!(
            matches!(direct, Value::Projected(_)),
            "projected __intrinsic_if_then_else__ stayed residual: {direct:?}"
        );

        let callback_only = apply(
            Value::Primitive(ComptimeBuiltin::IntrinsicIfThenElse),
            vec![
                proof.clone(),
                refl_type_value(unit.clone()),
                checked_term_value(
                    Expr::Unit {
                        occurrence: Default::default(),
                        meta: zero_meta(),
                    },
                    unit,
                ),
                nullary_returning(unit_recipe.clone()),
                nullary_returning(unit_recipe),
            ],
            &ctx,
        );
        assert!(
            matches!(callback_only, Value::Projected(_)),
            "callback-only projected conditional stayed residual: {callback_only:?}"
        );
    }

    #[test]
    fn projected_product_spine_fold_visits_authenticated_exact_children() {
        let ctx = EvalCtx::new();
        let (proof, fills, term) =
            crate::pass::typecheck_core::apply::fills::specialization_term_for_test();
        let (proof, _fills) = fills_capability_values(proof, fills);
        let target = Type::Product {
            left: Box::new(Type::Unit { meta: zero_meta() }),
            right: Box::new(Type::Unit { meta: zero_meta() }),
            meta: zero_meta(),
        };
        let specialized = apply(
            Value::Primitive(ComptimeBuiltin::TermSpecialize),
            vec![
                proof.clone(),
                projected_value(term),
                refl_type_value(Type::synth_path(
                    vec!["A".to_owned()],
                    Vec::new(),
                    zero_span(),
                )),
                refl_type_value(target),
            ],
            &ctx,
        );
        let Value::Data(success) = specialized else {
            panic!("projected specialization did not return a sum")
        };
        let [Value::Projected(specialized)] = success.args() else {
            panic!("projected specialization did not return a recipe: {success:?}")
        };
        let projected_ty = apply(
            Value::Primitive(ComptimeBuiltin::TermType),
            vec![proof.clone(), Value::Projected(specialized.clone())],
            &ctx,
        );
        let folded = apply(
            Value::Primitive(ComptimeBuiltin::TypeProductSpineFold),
            vec![
                proof.clone(),
                projected_ty,
                Value::Unit,
                Value::Atom("projected_fold_step".to_owned()),
            ],
            &ctx,
        );
        let Value::Stuck(outer_step, outer_args) = folded else {
            panic!("projected product fold did not visit both children: {folded:?}")
        };
        assert!(matches!(outer_step.as_ref(), Value::Atom(name) if name == "projected_fold_step"));
        let [
            Value::Stuck(inner_step, inner_args),
            Value::Projected(right),
        ] = outer_args.as_slice()
        else {
            panic!("projected product fold lost its right child: {outer_args:?}")
        };
        assert!(matches!(inner_step.as_ref(), Value::Atom(name) if name == "projected_fold_step"));
        let [Value::Unit, Value::Projected(left)] = inner_args.as_slice() else {
            panic!("projected product fold lost its left child: {inner_args:?}")
        };
        let proof_capability = marked_comptime_proof_from_value(&proof).unwrap();
        assert!(left.matches_proof(proof_capability));
        assert!(right.matches_proof(proof_capability));
        assert!(
            !left.same_snapshot(right),
            "product children must retain their distinct exact focus paths"
        );
        for child in [left, right] {
            let view = crate::pass::typecheck_core::apply::fills::projected_type_view(
                proof_capability,
                child,
            )
            .unwrap();
            assert!(matches!(
                view,
                crate::pass::typecheck_core::apply::fills::ProjectedTypeView::Unit
            ));
        }
    }

    #[test]
    fn projected_fuel_measure_uses_the_authenticated_structural_carrier() {
        use crate::pass::typecheck_core::apply::fills::{
            ProjectedTypeView, open_function_reflection_for_test, projected_type_for_fuel_test,
            projected_type_fuel_evidence_for_test, projected_type_view,
            projected_type_with_proof_for_fuel_test, specialization_term_for_test,
        };

        let ctx = EvalCtx::new();
        let lowered_meta = || crate::ast::Meta::<crate::ast::Lowered>::new(zero_span());
        let goal: Type<crate::ast::Lowered> = Type::Goal {
            goal: crate::ast::TypeGoalRef::for_test(9, 0, 0),
            args: Vec::new(),
            meta: lowered_meta(),
            ext: (),
        };
        let infer: Type<crate::ast::Lowered> = Type::Infer {
            meta: lowered_meta(),
            ext: (),
        };
        let unit = Type::Unit {
            meta: lowered_meta(),
        };
        let projected = |ty: Type<crate::ast::Lowered>| {
            projected_value(projected_type_for_fuel_test(ty.clone(), ty))
        };

        assert_eq!(fuel_measure(&projected(goal.clone()), &ctx), None);
        assert_eq!(fuel_measure(&projected(infer.clone()), &ctx), None);
        assert_eq!(initial_fuel_measure(&projected(goal.clone()), &ctx), None);
        assert_eq!(initial_fuel_measure(&projected(infer.clone()), &ctx), None);
        let open_path = projected(Type::synth_path(
            vec!["Box".to_owned()],
            vec![goal.clone()],
            zero_span(),
        ));
        assert_eq!(fuel_measure(&open_path, &ctx), None);
        assert_eq!(initial_fuel_measure(&open_path, &ctx), Some(1));
        let open_product = projected(Type::Product {
            left: Box::new(unit.clone()),
            right: Box::new(infer.clone()),
            meta: lowered_meta(),
        });
        assert_eq!(fuel_measure(&open_product, &ctx), None);
        assert_eq!(initial_fuel_measure(&open_product, &ctx), Some(2));
        assert_eq!(
            fuel_measure(
                &data_value("fuel_wrapper", vec![projected(goal.clone())]),
                &ctx,
            ),
            None,
            "a constructor cannot make provisional projected fuel measurable"
        );
        assert_eq!(
            initial_fuel_measure(
                &data_value("fuel_wrapper", vec![projected(goal.clone())]),
                &ctx,
            ),
            None,
            "a constructor cannot hide an unresolved projected root"
        );

        let closed_product = projected(Type::Product {
            left: Box::new(unit.clone()),
            right: Box::new(unit.clone()),
            meta: lowered_meta(),
        });
        let wrapped_closed_product = data_value("fuel_wrapper", vec![closed_product.clone()]);
        assert_eq!(fuel_measure(&closed_product, &ctx), Some(3));
        assert_eq!(fuel_measure(&wrapped_closed_product, &ctx), Some(4));
        assert_eq!(initial_fuel_measure(&wrapped_closed_product, &ctx), Some(4));

        let dropped_goal_projected = projected_type_for_fuel_test(
            Type::synth_path(vec!["Drop".to_owned()], vec![goal.clone()], zero_span()),
            unit.clone(),
        );
        assert_eq!(
            projected_type_fuel_evidence_for_test(&dropped_goal_projected),
            (false, true, true, false),
            "dropping a goal from the fuel carrier must not close the handle or discard its authority evidence"
        );
        let dropped_goal = projected_value(dropped_goal_projected);
        assert_eq!(
            fuel_measure(&dropped_goal, &ctx),
            Some(1),
            "a transparent alias may definitionally drop an unresolved argument"
        );
        assert_eq!(initial_fuel_measure(&dropped_goal, &ctx), Some(1));
        let retained_goal = projected_value(projected_type_for_fuel_test(
            Type::synth_path(vec!["Keep".to_owned()], vec![goal.clone()], zero_span()),
            goal,
        ));
        assert_eq!(
            fuel_measure(&retained_goal, &ctx),
            None,
            "a transparent alias that retains a goal remains unmeasurable"
        );
        assert_eq!(initial_fuel_measure(&retained_goal, &ctx), None);

        let nominal = |name: &str| {
            Type::synth_path(
                vec![name.to_owned()],
                vec![unit.clone(), unit.clone()],
                zero_span(),
            )
        };
        let (crumb_proof, crumb_projected) = projected_type_with_proof_for_fuel_test(
            nominal("Crumb"),
            Type::Sum {
                left: Box::new(nominal("Step_left")),
                right: Box::new(nominal("Step_right")),
                meta: lowered_meta(),
            },
        );
        let ProjectedTypeView::Sum { left, right } =
            projected_type_view(&crumb_proof, &crumb_projected)
                .expect("the deep Crumb carrier must expose its sum")
        else {
            panic!("the deep Crumb carrier did not expose a sum")
        };
        assert_eq!(left.structural_measure(), Some(3));
        assert_eq!(right.structural_measure(), Some(3));
        let crumb = projected_value(crumb_projected);
        assert_eq!(
            fuel_measure(&crumb, &ctx),
            Some(7),
            "fuel must measure the authenticated alias-unfolded carrier"
        );

        let (proof, _foreign, open_function) =
            open_function_reflection_for_test(ReflectedType::new_trusted(Type::Unit {
                meta: zero_meta(),
            }));
        let ProjectedTypeView::Function { param, ret, .. } =
            projected_type_view(&proof, &open_function).expect("open function view")
        else {
            panic!("open projected function lost its stable outer shell")
        };
        assert_eq!(open_function.structural_measure(), None);
        assert_eq!(open_function.initial_structural_measure(), Some(2));
        assert_eq!(
            param.structural_measure(),
            Some(1),
            "a stable child remains measurable even when its parent is open"
        );
        assert_eq!(ret.structural_measure(), None);
        assert_eq!(ret.initial_structural_measure(), None);
        let wrapped_open_function =
            data_value("fuel_wrapper", vec![projected_value(open_function.clone())]);
        let (_reminted_proof, _reminted_foreign, reminted_open_function) =
            open_function_reflection_for_test(ReflectedType::new_trusted(Type::Unit {
                meta: zero_meta(),
            }));
        assert!(!open_function.same_snapshot(&reminted_open_function));
        let reminted_open_wrapper = data_value(
            "fuel_wrapper",
            vec![projected_value(reminted_open_function)],
        );
        assert_eq!(
            fuel_measure(&wrapped_open_function, &ctx),
            Some(3),
            "a known projected shell has the same stable rank inside recursive constructor fuel"
        );
        assert_eq!(
            initial_fuel_measure(&wrapped_open_function, &ctx),
            Some(3),
            "initial and recursive constructor ranks must agree for an open projected field"
        );
        let nested_open_function =
            data_value("outer_fuel_wrapper", vec![wrapped_open_function.clone()]);
        assert_eq!(fuel_measure(&nested_open_function, &ctx), Some(4));
        assert_eq!(initial_fuel_measure(&nested_open_function, &ctx), Some(4));

        let unwrap_closed = apply(
            Value::StructuralRecur {
                root_measure: 4,
                current_measure: 4,
                step: EvalRef::new(Value::Atom("unwrap_closed_projected_step".to_owned())),
            },
            vec![closed_product, Value::Unit],
            &ctx,
        );
        assert!(
            matches!(&unwrap_closed, Value::Stuck(callee, args)
                if matches!(callee.as_ref(), Value::Atom(name) if name == "unwrap_closed_projected_step")
                    && matches!(args.as_slice(), [Value::StructuralRecur { current_measure: 3, .. }, Value::Projected(_), Value::Unit])),
            "a closed projected field did not preserve its structural size when unwrapped: {unwrap_closed:?}"
        );

        let traverse_open_wrapper = apply(
            Value::StructuralRecur {
                root_measure: 4,
                current_measure: 4,
                step: EvalRef::new(Value::Atom("open_projected_wrapper_step".to_owned())),
            },
            vec![wrapped_open_function.clone(), Value::Unit],
            &ctx,
        );
        assert!(
            matches!(&traverse_open_wrapper, Value::Stuck(callee, args)
                if matches!(callee.as_ref(), Value::Atom(name) if name == "open_projected_wrapper_step")
                    && matches!(args.as_slice(), [Value::StructuralRecur { current_measure: 3, .. }, Value::Data(_), Value::Unit])),
            "a shrinking constructor spine with a known open projected field did not recurse: {traverse_open_wrapper:?}"
        );
        let repeat_open_wrapper = apply(
            Value::StructuralRecur {
                root_measure: 4,
                current_measure: 3,
                step: EvalRef::new(Value::Atom("repeat_open_projected_wrapper_step".to_owned())),
            },
            vec![reminted_open_wrapper, Value::Unit],
            &ctx,
        );
        assert!(
            matches!(&repeat_open_wrapper, Value::Stuck(callee, _)
                if matches!(callee.as_ref(), Value::StructuralRecur { .. })),
            "an equal recursive constructor rank with projected evidence was admitted: {repeat_open_wrapper:?}"
        );
        let increasing_open_wrapper = apply(
            Value::StructuralRecur {
                root_measure: 5,
                current_measure: 3,
                step: EvalRef::new(Value::Atom(
                    "increasing_open_projected_wrapper_step".to_owned(),
                )),
            },
            vec![
                data_value(
                    "outer_fuel_wrapper",
                    vec![data_value(
                        "fuel_wrapper",
                        vec![projected_value(open_function.clone())],
                    )],
                ),
                Value::Unit,
            ],
            &ctx,
        );
        assert!(
            matches!(&increasing_open_wrapper, Value::Stuck(callee, _)
                if matches!(callee.as_ref(), Value::StructuralRecur { .. })),
            "an increasing recursive constructor rank with projected evidence was admitted: {increasing_open_wrapper:?}"
        );

        let recursive = apply(
            Value::StructuralRecur {
                root_measure: 3,
                current_measure: 2,
                step: EvalRef::new(Value::Atom("open_projected_step".to_owned())),
            },
            vec![open_path.clone(), Value::Unit],
            &ctx,
        );
        assert!(
            matches!(recursive, Value::Stuck(callee, _)
                if matches!(callee.as_ref(), Value::StructuralRecur { .. })),
            "a projected nested goal became measurable on a recursive edge"
        );

        let unstable_site = structural_recur_site_for_test("open_projected_fuel_test");
        let open_function_value = projected_value(open_function.clone());
        let (initial_measure, active) = ctx
            .enter_structural_recur_site(&unstable_site, &open_function_value)
            .expect("known projected function shell must enter an inactive site");
        assert_eq!(initial_measure, 2);
        assert!(
            matches!(
                ctx.enter_structural_recur_site(&unstable_site, &open_path),
                Err(StructuralRecurSiteEntryError::NonDecreasingReentry { .. })
            ),
            "an unstable projected lower bound re-entered an active site as a decrease"
        );
        drop(active);

        let (_proof, _fills, checked_recipe) = specialization_term_for_test();
        let (_reminted_proof, _reminted_fills, reminted_checked_recipe) =
            specialization_term_for_test();
        assert_eq!(
            checked_recipe.structural_measure(),
            Some(1),
            "checked recipes remain atomic structural fuel"
        );
        assert_eq!(checked_recipe.initial_structural_measure(), Some(1));
        assert!(
            !checked_recipe.same_snapshot(&reminted_checked_recipe),
            "control recipes must come from distinct snapshots"
        );
        let equal_recipe = apply(
            Value::StructuralRecur {
                root_measure: 2,
                current_measure: 1,
                step: EvalRef::new(Value::Atom("equal_checked_recipe_step".to_owned())),
            },
            vec![projected_value(reminted_checked_recipe), Value::Unit],
            &ctx,
        );
        assert!(
            matches!(&equal_recipe, Value::Stuck(callee, _)
                if matches!(callee.as_ref(), Value::StructuralRecur { .. })),
            "fresh equal-measure checked recipe bypassed strict descent: {equal_recipe:?}"
        );
    }

    #[test]
    fn projected_recursive_fuel_requires_strict_measure_decrease() {
        use crate::pass::typecheck_core::apply::fills::{
            focused_type_for_test, projected_type_arguments,
        };

        let ctx = EvalCtx::new();
        let (proof, _fills) = fresh_fills_capability_values();
        let proof_capability = marked_comptime_proof_from_value(&proof).unwrap();
        let parent = focused_type_for_test(
            proof_capability,
            ReflectedType::new_trusted(Type::synth_path(
                vec!["Pair".to_owned()],
                vec![
                    Type::Unit { meta: zero_meta() },
                    Type::Unit { meta: zero_meta() },
                ],
                zero_span(),
            )),
        );
        let first_children = projected_type_arguments(proof_capability, &parent)
            .expect("same-proof projected parent")
            .expect("known path arguments");
        let second_children = projected_type_arguments(proof_capability, &parent)
            .expect("same-proof projected parent")
            .expect("known path arguments");
        let first = first_children[0].clone();
        let reminted = second_children[0].clone();
        assert_eq!(parent.structural_measure(), Some(3));
        assert_eq!(first.structural_measure(), Some(1));
        assert_eq!(reminted.structural_measure(), Some(1));
        assert!(
            !first.same_snapshot(&reminted),
            "repeated structural views must expose the fresh-snapshot counterexample"
        );

        let strict = apply(
            Value::StructuralRecur {
                root_measure: 3,
                current_measure: 3,
                step: EvalRef::new(Value::Atom("strict_projected_step".to_owned())),
            },
            vec![projected_value(first.clone()), Value::Unit],
            &ctx,
        );
        assert!(
            matches!(&strict, Value::Stuck(callee, args)
                if matches!(callee.as_ref(), Value::Atom(name) if name == "strict_projected_step")
                    && matches!(args.as_slice(), [Value::StructuralRecur { current_measure: 1, .. }, Value::Projected(_), Value::Unit])),
            "a strict projected 3 -> 1 edge was rejected: {strict:?}"
        );

        let equal = apply(
            Value::StructuralRecur {
                root_measure: 3,
                current_measure: 1,
                step: EvalRef::new(Value::Atom("equal_projected_step".to_owned())),
            },
            vec![projected_value(reminted.clone()), Value::Unit],
            &ctx,
        );
        assert!(
            matches!(&equal, Value::Stuck(callee, _)
                if matches!(callee.as_ref(), Value::StructuralRecur { .. })),
            "fresh equal-size projected fuel bypassed strict descent: {equal:?}"
        );

        let wrapped_first = data_value("fuel_wrapper", vec![projected_value(first.clone())]);
        let wrapped_reminted = data_value("fuel_wrapper", vec![projected_value(reminted.clone())]);
        assert_eq!(fuel_measure(&wrapped_first, &ctx), Some(2));
        assert_eq!(fuel_measure(&wrapped_reminted, &ctx), Some(2));
        let wrapped_equal = apply(
            Value::StructuralRecur {
                root_measure: 3,
                current_measure: 2,
                step: EvalRef::new(Value::Atom("wrapped_projected_step".to_owned())),
            },
            vec![wrapped_reminted, Value::Unit],
            &ctx,
        );
        assert!(
            matches!(&wrapped_equal, Value::Stuck(callee, _)
                if matches!(callee.as_ref(), Value::StructuralRecur { .. })),
            "a data wrapper hid fresh equal-size projected fuel: {wrapped_equal:?}"
        );

        let increasing = apply(
            Value::StructuralRecur {
                root_measure: 4,
                current_measure: 1,
                step: EvalRef::new(Value::Atom("increasing_projected_step".to_owned())),
            },
            vec![projected_value(parent.clone()), Value::Unit],
            &ctx,
        );
        assert!(
            matches!(&increasing, Value::Stuck(callee, _)
                if matches!(callee.as_ref(), Value::StructuralRecur { .. })),
            "increasing projected fuel bypassed strict current descent: {increasing:?}"
        );

        let ordinary = apply(
            Value::StructuralRecur {
                root_measure: 2,
                current_measure: 1,
                step: EvalRef::new(Value::Atom("ordinary_equal_step".to_owned())),
            },
            vec![Value::StrAtom("right".to_owned()), Value::Unit],
            &ctx,
        );
        assert!(
            matches!(&ordinary, Value::Stuck(callee, _)
                if matches!(callee.as_ref(), Value::StructuralRecur { .. })),
            "equal-measure ordinary fuel bypassed strict descent: {ordinary:?}"
        );

        let projected_site = structural_recur_site_for_test("projected_fuel_test");
        let parent_value = projected_value(parent);
        let first_value = projected_value(first);
        let reminted_value = projected_value(reminted);
        let (parent_measure, parent_guard) = ctx
            .enter_structural_recur_site(&projected_site, &parent_value)
            .expect("initial projected site entry");
        assert_eq!(parent_measure, 3);
        let (child_measure, child_guard) = ctx
            .enter_structural_recur_site(&projected_site, &first_value)
            .expect("strict projected site descent");
        assert_eq!(child_measure, 1);
        drop(child_guard);
        drop(parent_guard);
        let (first_measure, first_guard) = ctx
            .enter_structural_recur_site(&projected_site, &first_value)
            .expect("initial projected child entry");
        assert_eq!(first_measure, 1);
        assert!(
            matches!(
                ctx.enter_structural_recur_site(&projected_site, &reminted_value),
                Err(StructuralRecurSiteEntryError::NonDecreasingReentry { .. })
            ),
            "fresh equal-size projected fuel re-entered the same helper origin"
        );
        drop(first_guard);

        let ordinary_site = structural_recur_site_for_test("ordinary_fuel_test");
        let (ordinary_measure, ordinary_guard) = ctx
            .enter_structural_recur_site(&ordinary_site, &Value::StrAtom("left".to_owned()))
            .expect("initial ordinary site entry");
        assert_eq!(ordinary_measure, 1);
        assert!(
            matches!(
                ctx.enter_structural_recur_site(
                    &ordinary_site,
                    &Value::StrAtom("right".to_owned())
                ),
                Err(StructuralRecurSiteEntryError::NonDecreasingReentry { .. })
            ),
            "equal-measure ordinary fuel re-entered the same helper origin"
        );
        assert!(
            matches!(
                ctx.enter_structural_recur_site(
                    &ordinary_site,
                    &data_value("larger_fuel", vec![Value::Unit])
                ),
                Err(StructuralRecurSiteEntryError::NonDecreasingReentry { .. })
            ),
            "larger ordinary fuel re-entered the same helper origin"
        );
        drop(ordinary_guard);
    }

    #[test]
    fn projected_type_args_and_structural_recur_use_the_semantic_carrier() {
        let ctx = EvalCtx::new();
        let (proof, _fills) = fresh_fills_capability_values();
        let proof_capability = marked_comptime_proof_from_value(&proof).unwrap();
        let applied = Type::synth_path(
            vec!["Pair".to_owned()],
            vec![
                Type::Unit { meta: zero_meta() },
                Type::Unit { meta: zero_meta() },
            ],
            zero_span(),
        );
        let projected = projected_value(
            crate::pass::typecheck_core::apply::fills::focused_type_for_test(
                proof_capability,
                ReflectedType::new_trusted(applied),
            ),
        );
        assert_eq!(fuel_measure(&projected, &ctx), Some(3));

        let folded = apply(
            Value::Primitive(ComptimeBuiltin::TypeArgsFold),
            vec![
                proof.clone(),
                projected.clone(),
                Value::Unit,
                Value::Atom("projected_args_step".to_owned()),
            ],
            &ctx,
        );
        let Value::Stuck(_, outer_args) = folded else {
            panic!("projected type-argument fold did not visit both arguments: {folded:?}")
        };
        let [Value::Stuck(_, inner_args), Value::Projected(right)] = outer_args.as_slice() else {
            panic!("projected type-argument fold lost its right child: {outer_args:?}")
        };
        let [Value::Unit, Value::Projected(left)] = inner_args.as_slice() else {
            panic!("projected type-argument fold lost its left child: {inner_args:?}")
        };
        assert_eq!(left.structural_measure(), Some(1));
        assert_eq!(right.structural_measure(), Some(1));
        assert!(!left.same_snapshot(right));
        let recursive = apply(
            Value::StructuralRecur {
                root_measure: 3,
                current_measure: 3,
                step: EvalRef::new(Value::Atom("projected_child_step".to_owned())),
            },
            vec![Value::Projected(left.clone()), Value::Unit],
            &ctx,
        );
        assert!(
            matches!(&recursive, Value::Stuck(callee, args)
                if matches!(callee.as_ref(), Value::Atom(name) if name == "projected_child_step")
                    && matches!(args.as_slice(), [Value::StructuralRecur { root_measure: 3, current_measure: 1, .. }, Value::Projected(_), Value::Unit])),
            "a semantic projected child was not accepted as structurally smaller fuel: {recursive:?}"
        );

        let recur = apply(
            structural_recur_source_primitive_for_test("projected-semantic-carrier"),
            vec![
                proof,
                projected,
                Value::Unit,
                Value::Atom("projected_recur_step".to_owned()),
            ],
            &ctx,
        );
        assert!(
            matches!(&recur, Value::Stuck(callee, args)
                if matches!(callee.as_ref(), Value::Atom(name) if name == "projected_recur_step")
                    && matches!(args.as_slice(), [Value::StructuralRecur { root_measure: 3, current_measure: 3, .. }, Value::Projected(_), Value::Unit])),
            "projected structural fuel did not enter the recursion step: {recur:?}"
        );
    }

    #[test]
    fn projected_either_retains_open_branch_coherence_for_adoption() {
        let ctx = EvalCtx::new();
        let (proof, sum_type, result_type, scrutinee, left_body, right_body) =
            crate::pass::typecheck_core::apply::fills::open_either_reflection_for_test();
        let proof_value = Value::Data(EvalRef::new(DataValue::new_marked_comptime_proof(
            proof.clone(),
        )));
        let handler = |body| Value::EvalClosure {
            function: test_eval_function(&["_payload"], EvalExpr::Const(projected_value(body))),
            captured: Vec::<Value>::new().into(),
        };

        let either = apply(
            Value::Primitive(ComptimeBuiltin::IntrinsicEither),
            vec![
                proof_value,
                projected_value(sum_type),
                projected_value(result_type),
                projected_value(scrutinee),
                handler(left_body),
                handler(right_body),
            ],
            &ctx,
        );
        let Value::Projected(either) = either else {
            panic!("projected either rejected authenticated open branch results: {either:?}")
        };
        assert!(
            crate::pass::typecheck_core::apply::fills::deferred_either_evidence_for_test(
                &proof, &either,
            )
        );
    }

    #[test]
    fn projected_natural_match_type_sum_call_and_absurd_reduce() {
        let ctx = EvalCtx::new();
        let (raw_proof, fills, term) =
            crate::pass::typecheck_core::apply::fills::specialization_term_for_test();
        let (proof, _fills) = fills_capability_values(raw_proof, fills);
        let specialize = |target: Type<EvalPhase>| {
            let result = apply(
                Value::Primitive(ComptimeBuiltin::TermSpecialize),
                vec![
                    proof.clone(),
                    projected_value(term.clone()),
                    refl_type_value(Type::synth_path(
                        vec!["A".to_owned()],
                        Vec::new(),
                        zero_span(),
                    )),
                    refl_type_value(target),
                ],
                &ctx,
            );
            let Value::Data(success) = result else {
                panic!("projected specialization did not return a sum: {result:?}")
            };
            let [Value::Projected(recipe)] = success.args() else {
                panic!("projected specialization did not return a recipe: {success:?}")
            };
            recipe.clone()
        };
        let unit = Type::Unit { meta: zero_meta() };
        let function_ty = Type::Function {
            param: Box::new(unit.clone()),
            ret: Box::new(unit.clone()),
            meta: zero_meta(),
            abi_arity: 1,
            caps: (),
        };
        let sum_ty = Type::Sum {
            left: Box::new(unit.clone()),
            right: Box::new(unit.clone()),
            meta: zero_meta(),
        };
        let unit_recipe = specialize(unit.clone());
        let function_recipe = specialize(function_ty);
        let sum_recipe = specialize(sum_ty);
        let bottom_recipe = specialize(Type::Bottom { meta: zero_meta() });

        let unit_type = apply(
            Value::Primitive(ComptimeBuiltin::TermType),
            vec![proof.clone(), Value::Projected(unit_recipe.clone())],
            &ctx,
        );
        let function_type = apply(
            Value::Primitive(ComptimeBuiltin::TermType),
            vec![proof.clone(), Value::Projected(function_recipe.clone())],
            &ctx,
        );
        let sum = apply(
            Value::Primitive(ComptimeBuiltin::TypeSum),
            vec![proof.clone(), unit_type.clone(), unit_type.clone()],
            &ctx,
        );
        let Value::Projected(sum) = sum else {
            panic!("projected __type_sum__ did not retain a projected type: {sum:?}")
        };
        assert!(matches!(
            crate::pass::typecheck_core::apply::fills::projected_type_view(
                marked_comptime_proof_from_value(&proof).unwrap(),
                &sum,
            )
            .unwrap(),
            crate::pass::typecheck_core::apply::fills::ProjectedTypeView::Sum { .. }
        ));

        let pair = apply(
            Value::Primitive(ComptimeBuiltin::IntrinsicPair),
            vec![
                proof.clone(),
                Value::Projected(unit_recipe.clone()),
                Value::Projected(unit_recipe.clone()),
            ],
            &ctx,
        );
        let Value::Projected(pair) = pair else {
            panic!("projected __intrinsic_pair__ did not retain a recipe: {pair:?}")
        };
        let pair_type = apply(
            Value::Primitive(ComptimeBuiltin::TermType),
            vec![proof.clone(), Value::Projected(pair.clone())],
            &ctx,
        );
        for projection in [ComptimeBuiltin::IntrinsicFst, ComptimeBuiltin::IntrinsicSnd] {
            let child = apply(
                Value::Primitive(projection),
                vec![
                    proof.clone(),
                    pair_type.clone(),
                    Value::Projected(pair.clone()),
                ],
                &ctx,
            );
            let Value::Projected(child) = child else {
                panic!("projected {projection:?} did not retain a child recipe: {child:?}")
            };
            let child_type = apply(
                Value::Primitive(ComptimeBuiltin::TermType),
                vec![proof.clone(), Value::Projected(child)],
                &ctx,
            );
            assert!(matches!(
                apply(
                    Value::Primitive(ComptimeBuiltin::TypeView),
                    vec![proof.clone(), child_type],
                    &ctx,
                ),
                Value::Data(unit) if unit.ctor() == "__left__"
            ));
        }

        let identity_handler = || Value::EvalClosure {
            function: test_eval_function(&["payload"], EvalExpr::Local(0)),
            captured: Vec::<Value>::new().into(),
        };
        let either = apply(
            Value::Primitive(ComptimeBuiltin::IntrinsicEither),
            vec![
                proof.clone(),
                Value::Projected(sum.clone()),
                unit_type.clone(),
                Value::Projected(sum_recipe),
                identity_handler(),
                identity_handler(),
            ],
            &ctx,
        );
        let Value::Projected(either) = either else {
            panic!("projected __intrinsic_either__ did not retain a recipe: {either:?}")
        };
        assert!(either.closed_term().is_none());
        let either_type = apply(
            Value::Primitive(ComptimeBuiltin::TermType),
            vec![proof.clone(), Value::Projected(either)],
            &ctx,
        );
        assert!(matches!(
            apply(
                Value::Primitive(ComptimeBuiltin::TypeView),
                vec![proof.clone(), either_type],
                &ctx,
            ),
            Value::Data(unit) if unit.ctor() == "__left__"
        ));

        let call = apply(
            Value::Primitive(ComptimeBuiltin::TermCall),
            vec![
                proof.clone(),
                function_type,
                Value::Projected(function_recipe),
                Value::Projected(unit_recipe),
            ],
            &ctx,
        );
        let Value::Projected(call) = call else {
            panic!("projected __term_call__ did not retain a recipe: {call:?}")
        };
        assert!(call.closed_term().is_none());
        let call_type = apply(
            Value::Primitive(ComptimeBuiltin::TermType),
            vec![proof.clone(), Value::Projected(call)],
            &ctx,
        );
        assert!(matches!(
            apply(
                Value::Primitive(ComptimeBuiltin::TypeView),
                vec![proof.clone(), call_type],
                &ctx,
            ),
            Value::Data(unit) if unit.ctor() == "__left__"
        ));

        let absurd = apply(
            Value::Primitive(ComptimeBuiltin::IntrinsicAbsurd),
            vec![proof.clone(), Value::Projected(bottom_recipe), unit_type],
            &ctx,
        );
        let Value::Projected(absurd) = absurd else {
            panic!("projected __intrinsic_absurd__ did not retain a recipe: {absurd:?}")
        };
        assert!(absurd.closed_term().is_none());
        let absurd_type = apply(
            Value::Primitive(ComptimeBuiltin::TermType),
            vec![proof.clone(), Value::Projected(absurd)],
            &ctx,
        );
        assert!(matches!(
            apply(
                Value::Primitive(ComptimeBuiltin::TypeView),
                vec![proof, absurd_type],
                &ctx,
            ),
            Value::Data(unit) if unit.ctor() == "__left__"
        ));
    }

    #[test]
    fn projected_product_projection_replays_core_intrinsics() {
        let unit = Type::Unit { meta: zero_meta() };
        let product = Type::Product {
            left: Box::new(unit.clone()),
            right: Box::new(unit.clone()),
            meta: zero_meta(),
        };
        let value = EvalRef::new(CheckedTerm::new(
            Expr::Unit {
                occurrence: Default::default(),
                meta: zero_meta(),
            },
            product.clone(),
        ));
        for (left, expected) in [(true, "__fst__"), (false, "__snd__")] {
            let projected = CheckedTerm::from_projected(
                ProjectedTermConstruction::ProductProjection {
                    left_ty: unit.clone(),
                    right_ty: unit.clone(),
                    value: value.clone(),
                    left,
                },
                unit.clone(),
            );
            let Expr::Call { callee, .. } = projected.clone_expr() else {
                panic!("a projected product projection must replay as a core call")
            };
            assert!(
                matches!(callee.as_ref(), Expr::Path { segments, .. }
                    if matches!(segments.as_slice(), [segment] if segment.name == expected)),
                "projected product projection replayed the reflection helper instead of `{expected}`: {callee:?}"
            );
        }
    }

    #[test]
    fn projected_product_views_bind_one_shared_template_source() {
        let unit = Type::Unit { meta: zero_meta() };
        let product = Type::Product {
            left: Box::new(unit.clone()),
            right: Box::new(unit.clone()),
            meta: zero_meta(),
        };
        let source = EvalRef::new(CheckedTerm::template_value(0, product.clone()));
        let left = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::ProductProjection {
                left_ty: unit.clone(),
                right_ty: unit.clone(),
                value: source.clone(),
                left: true,
            },
            unit.clone(),
        ));
        let right = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::ProductProjection {
                left_ty: unit.clone(),
                right_ty: unit.clone(),
                value: source,
                left: false,
            },
            unit.clone(),
        ));
        let split = CheckedTerm::from_projected(
            ProjectedTermConstruction::Pair { left, right },
            product.clone(),
        );
        let adapted = split.adapt_template_values(&CheckedTermTemplateValueAdapter {
            sources: vec![CheckedTermTemplateSource {
                ty: product.clone(),
                force_if_unused: false,
            }],
            slots: vec![CheckedTermTemplateSlot {
                pieces: vec![CheckedTermTemplatePiece {
                    source_index: 0,
                    source_slot: 0,
                    source_slot_tys: vec![product],
                }],
            }],
        });
        let CheckedTermNode::TermLet { name, value, body } = adapted.node.as_ref() else {
            panic!("two views of one template source must replay through a let")
        };
        assert!(matches!(
            value.node.as_ref(),
            CheckedTermNode::TemplateValue { index: 0 }
        ));
        let CheckedTermNode::IntrinsicPair { left, right } = body.node.as_ref() else {
            panic!("the shared source let must retain both projected views")
        };
        for projection in [left, right] {
            let CheckedTermNode::IntrinsicProjection { value, .. } = projection.node.as_ref()
            else {
                panic!("the adapted split lost a product projection")
            };
            assert!(matches!(
                value.node.as_ref(),
                CheckedTermNode::Local { name: local } if local == name
            ));
        }
        assert_eq!(
            checked_term_template_value_counts(&adapted.node),
            HashMap::from([(0, 1)]),
            "the original source expression must replay exactly once"
        );

        let branch_counts = checked_term_template_value_counts(&EvalRef::new(
            CheckedTermNode::IntrinsicIfThenElse {
                result_ty: unit.clone(),
                condition: EvalRef::new(CheckedTerm::template_value(0, unit.clone())),
                true_body: EvalRef::new(CheckedTerm::template_value(1, unit.clone())),
                false_body: EvalRef::new(CheckedTerm::template_value(2, unit)),
            },
        ));
        assert_eq!(
            branch_counts,
            HashMap::from([(0, 1), (1, 1), (2, 1)]),
            "template occurrence counting must visit condition and each branch once"
        );
    }

    #[test]
    fn repeated_callable_template_source_replays_through_one_untyped_let_with_canonical_types() {
        let unit = Type::Unit { meta: zero_meta() };
        let product = Type::Product {
            left: Box::new(unit.clone()),
            right: Box::new(unit.clone()),
            meta: zero_meta(),
        };
        let nested_result = Type::Function {
            param: Box::new(unit.clone()),
            ret: Box::new(unit.clone()),
            meta: zero_meta(),
            abi_arity: 7,
            caps: (),
        };
        let source_ty = Type::Function {
            param: Box::new(product.clone()),
            ret: Box::new(nested_result.clone()),
            meta: zero_meta(),
            abi_arity: 2,
            caps: (),
        };
        let source = EvalRef::new(CheckedTerm::template_value(0, source_ty.clone()));
        let packet = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::Pair {
                left: EvalRef::new(CheckedTerm::new(
                    Expr::Unit {
                        occurrence: Default::default(),
                        meta: zero_meta(),
                    },
                    unit.clone(),
                )),
                right: EvalRef::new(CheckedTerm::new(
                    Expr::Unit {
                        occurrence: Default::default(),
                        meta: zero_meta(),
                    },
                    unit.clone(),
                )),
            },
            product,
        ));
        let call = || {
            EvalRef::new(CheckedTerm::from_projected(
                ProjectedTermConstruction::Call {
                    fn_value: source.clone(),
                    params: vec![unit.clone(), unit.clone()],
                    arg_packet: packet.clone(),
                },
                nested_result.clone(),
            ))
        };
        let result_ty = Type::Product {
            left: Box::new(nested_result.clone()),
            right: Box::new(nested_result.clone()),
            meta: zero_meta(),
        };
        let template = CheckedTerm::from_projected(
            ProjectedTermConstruction::Pair {
                left: call(),
                right: call(),
            },
            result_ty,
        );
        let adapted = template.adapt_template_values(&CheckedTermTemplateValueAdapter {
            sources: vec![CheckedTermTemplateSource {
                ty: source_ty.clone(),
                force_if_unused: false,
            }],
            slots: vec![CheckedTermTemplateSlot {
                pieces: vec![CheckedTermTemplatePiece {
                    source_index: 0,
                    source_slot: 0,
                    source_slot_tys: vec![source_ty],
                }],
            }],
        });

        let CheckedTermNode::TermLet { name, value, body } = adapted.node.as_ref() else {
            panic!("the repeated callable source must be staged exactly once")
        };
        assert!(matches!(
            value.ty(),
            Type::Function {
                abi_arity: 2,
                ret,
                ..
            } if matches!(ret.as_ref(), Type::Function { abi_arity: 7, .. })
        ));
        let CheckedTermNode::IntrinsicPair { left, right } = body.node.as_ref() else {
            panic!("both calls must remain in the staged template body")
        };
        for call in [left, right] {
            let CheckedTermNode::TermCall {
                fn_value, params, ..
            } = call.node.as_ref()
            else {
                panic!("the repeated source use must remain an authored call")
            };
            assert_eq!(
                params.len(),
                2,
                "both semantic arguments must survive replay"
            );
            assert!(matches!(
                fn_value.node.as_ref(),
                CheckedTermNode::Local { name: local } if local == name
            ));
        }
        assert_eq!(
            checked_term_template_value_counts(&adapted.node),
            HashMap::from([(0, 1)]),
            "the ABI-2 source must be materialized exactly once"
        );

        let mut raw_to_pre_prime = |expr: &Expr<EvalPhase>, _call_span: Span| {
            crate::ast::convert_expr::<EvalPhase, PrePrime>(expr)
        };
        let mut type_to_pre_prime =
            |ty: &Type<EvalPhase>| crate::ast::convert_type::<EvalPhase, PrePrime>(ty);
        let staged_source = path_expr_pre_prime("flat_source", zero_span());
        let replayed = adapted.instantiate_template_pre_prime(
            std::slice::from_ref(&staged_source),
            zero_span(),
            &mut raw_to_pre_prime,
            &mut type_to_pre_prime,
        );
        let Expr::Let {
            name: replayed_name,
            ty: None,
            value: replayed_value,
            body: replayed_body,
            ..
        } = replayed
        else {
            panic!("the persisted template must use one unannotated binding")
        };
        assert_eq!(replayed_name, name.as_str());
        assert_eq!(*replayed_value, staged_source);
        let Expr::Call { args, .. } = replayed_body.as_ref() else {
            panic!("the two staged calls must remain paired")
        };
        let persisted_types = args
            .iter()
            .filter_map(|arg| match arg {
                CallArg::Type(ty) => Some(ty),
                CallArg::Value(_) => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            persisted_types.len(),
            2,
            "the pair must persist both callable result types"
        );
        assert!(persisted_types.iter().all(|ty| {
            matches!(
                ty,
                Type::Function {
                    param,
                    abi_arity: 0,
                    ..
                } if matches!(param.as_ref(), Type::Unit { .. })
            )
        }));
        let calls = args
            .iter()
            .filter_map(|arg| match arg {
                CallArg::Value(Expr::Call { callee, args, .. })
                    if matches!(callee.as_ref(), Expr::Path { segments, .. }
                        if matches!(segments.as_slice(), [segment] if segment.name == replayed_name)) =>
                {
                    Some(args)
                }
                _ => None,
            })
            .collect::<Vec<_>>();
        assert_eq!(
            calls.len(),
            2,
            "both calls must use the one persisted binding"
        );
        assert!(calls.iter().all(|args| args.len() == 2));
    }

    fn assert_template_types(
        term: &CheckedTerm,
        expected: &EvalAstType,
        expected_occurrences: usize,
    ) {
        fn visit(term: &CheckedTerm, expected: &EvalAstType, occurrences: &mut usize) {
            match term.node.as_ref() {
                CheckedTermNode::TemplateValue { .. } => {
                    *occurrences += 1;
                    assert_eq!(term.ty(), expected);
                }
                CheckedTermNode::Raw(_)
                | CheckedTermNode::Local { .. }
                | CheckedTermNode::ElabError { .. } => {}
                CheckedTermNode::TermLet { value, body, .. } => {
                    visit(value, expected, occurrences);
                    visit(body, expected, occurrences);
                }
                CheckedTermNode::TermFn { body, .. }
                | CheckedTermNode::TermTypeApp { fn_value: body, .. }
                | CheckedTermNode::IntrinsicProjection { value: body, .. }
                | CheckedTermNode::IntrinsicInjection { value: body, .. }
                | CheckedTermNode::IntrinsicAbsurd {
                    bottom_value: body, ..
                } => visit(body, expected, occurrences),
                CheckedTermNode::TermCall {
                    fn_value,
                    arg_packet,
                    ..
                }
                | CheckedTermNode::IntrinsicPair {
                    left: fn_value,
                    right: arg_packet,
                } => {
                    visit(fn_value, expected, occurrences);
                    visit(arg_packet, expected, occurrences);
                }
                CheckedTermNode::IntrinsicEither {
                    value,
                    left_body,
                    right_body,
                    ..
                } => {
                    visit(value, expected, occurrences);
                    visit(left_body, expected, occurrences);
                    visit(right_body, expected, occurrences);
                }
                CheckedTermNode::IntrinsicIfThenElse {
                    condition,
                    true_body,
                    false_body,
                    ..
                } => {
                    visit(condition, expected, occurrences);
                    visit(true_body, expected, occurrences);
                    visit(false_body, expected, occurrences);
                }
            }
        }

        let mut occurrences = 0;
        visit(term, expected, &mut occurrences);
        assert_eq!(occurrences, expected_occurrences);
    }

    fn runtime_tail_for_test(runtime: &EvalAstType) -> EvalRef<CheckedTerm> {
        let Type::Sum { right, .. } = runtime else {
            panic!("sum runtime fixture")
        };
        EvalRef::new(CheckedTerm::new(
            path_expr("outer_continuation"),
            Type::Function {
                param: right.clone(),
                ret: Box::new(runtime.clone()),
                abi_arity: 1,
                meta: zero_meta(),
                caps: (),
            },
        ))
    }

    #[test]
    fn lifted_terminal_callback_adapter_retypes_every_opaque_child_family() {
        let unit = Type::Unit { meta: zero_meta() };
        let bottom = Type::Bottom { meta: zero_meta() };
        let boolean = type_path("BoolRole");
        let runtime_result = Type::Sum {
            left: Box::new(type_path("RecursiveState")),
            right: Box::new(unit.clone()),
            meta: zero_meta(),
        };
        let callback = |result| Type::Function {
            param: Box::new(unit.clone()),
            ret: Box::new(result),
            meta: zero_meta(),
            abi_arity: 1,
            caps: (),
        };
        let public_callback = callback(unit.clone());
        let runtime_callback = callback(runtime_result.clone());
        let raw = |name: &str, ty| EvalRef::new(CheckedTerm::new(path_expr(name), ty));
        let hidden = |body: EvalRef<CheckedTerm>| {
            EvalRef::new(CheckedTerm::from_projected(
                ProjectedTermConstruction::Let {
                    name: "unused_callback".to_owned(),
                    value: EvalRef::new(CheckedTerm::template_value(0, public_callback.clone())),
                    body: body.clone(),
                },
                body.clone_type(),
            ))
        };
        let terminal = || {
            EvalRef::new(CheckedTerm::from_projected(
                ProjectedTermConstruction::Call {
                    fn_value: EvalRef::new(CheckedTerm::template_value(0, public_callback.clone())),
                    params: vec![unit.clone()],
                    arg_packet: raw("unit_argument", unit.clone()),
                },
                unit.clone(),
            ))
        };
        let with_terminal = |opaque: EvalRef<CheckedTerm>| {
            CheckedTerm::from_projected(
                ProjectedTermConstruction::IfThenElse {
                    condition: raw("outer_condition", boolean.clone()),
                    true_body: terminal(),
                    false_body: opaque,
                },
                unit.clone(),
            )
        };

        let public_pair = Type::Product {
            left: Box::new(public_callback.clone()),
            right: Box::new(public_callback.clone()),
            meta: zero_meta(),
        };
        let callback_pair = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::Pair {
                left: EvalRef::new(CheckedTerm::template_value(0, public_callback.clone())),
                right: raw("ordinary_callback", public_callback.clone()),
            },
            public_pair.clone(),
        ));
        let selected_public_callback = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::ProductProjection {
                left_ty: public_callback.clone(),
                right_ty: public_callback.clone(),
                value: callback_pair,
                left: false,
            },
            public_callback.clone(),
        ));
        let consumer_type = Type::Function {
            param: Box::new(public_callback.clone()),
            ret: Box::new(unit.clone()),
            meta: zero_meta(),
            abi_arity: 1,
            caps: (),
        };
        let call_argument = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::Call {
                fn_value: raw("consume_callback", consumer_type),
                params: vec![public_callback.clone()],
                arg_packet: selected_public_callback,
            },
            unit.clone(),
        ));

        let sum_type = Type::Sum {
            left: Box::new(unit.clone()),
            right: Box::new(unit.clone()),
            meta: zero_meta(),
        };
        let either = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::Either {
                left_ty: unit.clone(),
                right_ty: unit.clone(),
                value: hidden(raw("scrutinee", sum_type)),
                left_name: "left".to_owned(),
                left_body: raw("left_body", unit.clone()),
                right_name: "right".to_owned(),
                right_body: raw("right_body", unit.clone()),
            },
            unit.clone(),
        ));
        let conditional = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::IfThenElse {
                condition: hidden(raw("condition", boolean.clone())),
                true_body: raw("true_body", unit.clone()),
                false_body: raw("false_body", unit.clone()),
            },
            unit.clone(),
        ));
        let absurd = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::Absurd {
                bottom_value: hidden(raw("bottom", bottom)),
            },
            unit.clone(),
        ));

        let function_type = Type::Function {
            param: Box::new(unit.clone()),
            ret: Box::new(unit.clone()),
            meta: zero_meta(),
            abi_arity: 1,
            caps: (),
        };
        let function = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::Fn {
                sig: Signature::from_parts(
                    vec![SignatureParam::Value(crate::ast::Param {
                        name: "parameter".to_owned(),
                        ty: Some(unit.clone()),
                        pattern: (),
                        meta: zero_meta(),
                    })],
                    vec![crate::ast::SignatureGroupKind::Value { len: 1 }],
                ),
                body: hidden(raw("fn_body", unit.clone())),
            },
            function_type.clone(),
        ));
        let function_call = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::Call {
                fn_value: function,
                params: vec![unit.clone()],
                arg_packet: raw("fn_argument", unit.clone()),
            },
            unit.clone(),
        ));

        let type_function = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::TypeFn {
                param: TypeParam {
                    name: "A".to_owned(),
                    span: zero_span(),
                    kind: None,
                },
                body: hidden(raw("type_fn_body", unit.clone())),
            },
            unit.clone(),
        ));
        let type_application = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::TypeApp {
                term: type_function,
                arg: unit.clone(),
            },
            unit.clone(),
        ));

        let injection = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::Injection {
                left_ty: unit.clone(),
                right_ty: unit.clone(),
                value: hidden(raw("injected", unit.clone())),
                left: true,
            },
            Type::Sum {
                left: Box::new(unit.clone()),
                right: Box::new(unit.clone()),
                meta: zero_meta(),
            },
        ));
        let discarded_injection = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::Let {
                name: "unused_injection".to_owned(),
                value: injection,
                body: raw("after_injection", unit.clone()),
            },
            unit.clone(),
        ));

        let fixtures = [
            ("call argument", call_argument),
            ("either scrutinee", either),
            ("if condition", conditional),
            ("absurd bottom", absurd),
            ("function body", function_call),
            ("type-function body", type_application),
            ("injection value", discarded_injection),
        ];
        for (label, opaque) in fixtures {
            let adapted = with_terminal(opaque).adapt_lifted_terminal_callbacks(
                &[Some(runtime_callback.clone())],
                runtime_result.clone(),
                runtime_tail_for_test(&runtime_result),
            );
            assert_eq!(adapted.ty(), &runtime_result, "{label}");
            assert_template_types(&adapted, &runtime_callback, 2);
        }
    }

    #[test]
    fn lifted_terminal_callback_adapter_covers_the_authorized_topology() {
        let unit = Type::Unit { meta: zero_meta() };
        let bottom = Type::Bottom { meta: zero_meta() };
        let state = type_path("RecursiveState");
        let runtime_result = Type::Sum {
            left: Box::new(state),
            right: Box::new(unit.clone()),
            meta: zero_meta(),
        };
        let public_callback = Type::Function {
            param: Box::new(unit.clone()),
            ret: Box::new(unit.clone()),
            meta: zero_meta(),
            abi_arity: 1,
            caps: (),
        };
        let runtime_callback = Type::Function {
            param: Box::new(unit.clone()),
            ret: Box::new(runtime_result.clone()),
            meta: zero_meta(),
            abi_arity: 1,
            caps: (),
        };
        let forall = |body| Type::Forall {
            param: TypeParam {
                name: "A".to_owned(),
                span: zero_span(),
                kind: None,
            },
            body: Box::new(body),
            meta: zero_meta(),
        };
        let public_source = forall(public_callback.clone());
        let runtime_source = forall(runtime_callback.clone());
        let specialized = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::TypeApp {
                term: EvalRef::new(CheckedTerm::template_value(0, public_source)),
                arg: unit.clone(),
            },
            public_callback.clone(),
        ));
        let ordinary_callback = EvalRef::new(CheckedTerm::new(
            path_expr("ordinary_callback"),
            public_callback.clone(),
        ));
        let public_pair = Type::Product {
            left: Box::new(public_callback.clone()),
            right: Box::new(public_callback.clone()),
            meta: zero_meta(),
        };
        let callbacks = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::Pair {
                left: specialized,
                right: ordinary_callback.clone(),
            },
            public_pair.clone(),
        ));
        let callback_call = |name: &str| {
            let callback = EvalRef::new(CheckedTerm::from_projected(
                ProjectedTermConstruction::ProductProjection {
                    left_ty: public_callback.clone(),
                    right_ty: public_callback.clone(),
                    value: EvalRef::new(CheckedTerm::local(name.to_owned(), public_pair.clone())),
                    left: true,
                },
                public_callback.clone(),
            ));
            EvalRef::new(CheckedTerm::from_projected(
                ProjectedTermConstruction::Call {
                    fn_value: callback,
                    params: vec![unit.clone()],
                    arg_packet: EvalRef::new(CheckedTerm::new(
                        Expr::Unit {
                            occurrence: Default::default(),
                            meta: zero_meta(),
                        },
                        unit.clone(),
                    )),
                },
                unit.clone(),
            ))
        };
        let shadowed_call = callback_call("callbacks");
        let lifted_call = callback_call("callbacks");
        let bottom_value = EvalRef::new(CheckedTerm::new(path_expr("bottom"), bottom));
        let absurd = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::Absurd {
                bottom_value: bottom_value.clone(),
            },
            unit.clone(),
        ));
        let condition = EvalRef::new(CheckedTerm::new(
            path_expr("condition"),
            type_path("BoolRole"),
        ));
        let right_body = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::IfThenElse {
                condition: condition.clone(),
                true_body: lifted_call,
                false_body: absurd,
            },
            unit.clone(),
        ));
        let scrutinee = EvalRef::new(CheckedTerm::new(
            path_expr("scrutinee"),
            Type::Sum {
                left: Box::new(public_pair.clone()),
                right: Box::new(unit.clone()),
                meta: zero_meta(),
            },
        ));
        let either = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::Either {
                left_ty: public_pair,
                right_ty: unit.clone(),
                value: scrutinee.clone(),
                left_name: "callbacks".to_owned(),
                left_body: shadowed_call,
                right_name: "ignored".to_owned(),
                right_body,
            },
            unit.clone(),
        ));
        let template = CheckedTerm::from_projected(
            ProjectedTermConstruction::Let {
                name: "callbacks".to_owned(),
                value: callbacks,
                body: either,
            },
            unit,
        );

        reset_runtime_callback_adapter_work();
        let outer_continuation = runtime_tail_for_test(&runtime_result);
        let adapted = template.adapt_lifted_terminal_callbacks(
            &[Some(runtime_source.clone())],
            runtime_result.clone(),
            outer_continuation.clone(),
        );

        assert_eq!(adapted.ty(), &runtime_result);
        let CheckedTermNode::TermLet { value, body, .. } = adapted.node.as_ref() else {
            panic!("the callback alias let was not preserved")
        };
        let CheckedTermNode::IntrinsicPair { left, right } = value.node.as_ref() else {
            panic!("the callback pair alias was not preserved")
        };
        assert!(EvalRef::ptr_eq(right, &ordinary_callback));
        assert!(matches!(
            left.node.as_ref(),
            CheckedTermNode::TermTypeApp { fn_value, .. }
                if matches!(fn_value.node.as_ref(), CheckedTermNode::TemplateValue { index: 0 })
                    && fn_value.ty() == &runtime_source
        ));
        let CheckedTermNode::IntrinsicEither {
            value: adapted_scrutinee,
            left_body,
            right_body,
            result_ty,
            ..
        } = body.node.as_ref()
        else {
            panic!("the terminal either was not preserved")
        };
        assert_eq!(result_ty, &runtime_result);
        assert!(EvalRef::ptr_eq(adapted_scrutinee, &scrutinee));
        assert!(matches!(
            left_body.node.as_ref(),
            CheckedTermNode::TermCall { fn_value, arg_packet, .. }
                if EvalRef::ptr_eq(fn_value, &outer_continuation)
                    && matches!(arg_packet.node.as_ref(), CheckedTermNode::TermCall { .. })
        ));
        let CheckedTermNode::IntrinsicIfThenElse {
            condition: adapted_condition,
            true_body,
            false_body,
            result_ty,
        } = right_body.node.as_ref()
        else {
            panic!("the terminal conditional was not preserved")
        };
        assert_eq!(result_ty, &runtime_result);
        assert!(EvalRef::ptr_eq(adapted_condition, &condition));
        assert!(matches!(
            true_body.node.as_ref(),
            CheckedTermNode::TermCall { fn_value, .. }
                if fn_value.ty() == &runtime_callback
                    && !EvalRef::ptr_eq(fn_value, &outer_continuation)
        ));
        assert!(matches!(
            false_body.node.as_ref(),
            CheckedTermNode::IntrinsicAbsurd { result_ty, bottom_value: adapted_bottom }
                if result_ty == &runtime_result && EvalRef::ptr_eq(adapted_bottom, &bottom_value)
        ));
        let (firings, reused, rebuilt) = runtime_callback_adapter_work();
        assert_eq!(firings, 1);
        assert_eq!(
            reused, 5,
            "the unaffected pair member and opaque control children must be reused"
        );
        assert!(
            rebuilt > reused,
            "the firing fixture must rebuild its typed spine"
        );
    }

