    fn lifted_terminal_callback_adapter_continues_an_unused_callee_alias() {
        let unit = Type::Unit { meta: zero_meta() };
        let runtime_result = Type::Sum {
            left: Box::new(type_path("RecursiveState")),
            right: Box::new(unit.clone()),
            meta: zero_meta(),
        };
        let callback = |result| Type::Function {
            param: Box::new(unit.clone()),
            ret: Box::new(result),
            meta: zero_meta(),
            abi_arity: 1,
            caps: (),
        };
        let public_callback = callback(unit.clone());
        let runtime_callback = callback(runtime_result.clone());
        let unused_alias = EvalRef::new(CheckedTerm::from_projected(
            ProjectedTermConstruction::Let {
                name: "unused".to_owned(),
                value: EvalRef::new(CheckedTerm::template_value(0, public_callback.clone())),
                body: EvalRef::new(CheckedTerm::new(
                    path_expr("ordinary_callback"),
                    public_callback.clone(),
                )),
            },
            public_callback.clone(),
        ));
        let template = CheckedTerm::from_projected(
            ProjectedTermConstruction::Call {
                fn_value: unused_alias,
                params: vec![unit.clone()],
                arg_packet: EvalRef::new(CheckedTerm::new(
                    Expr::Unit {
                        occurrence: Default::default(),
                        meta: zero_meta(),
                    },
                    unit.clone(),
                )),
            },
            unit.clone(),
        );

        let outer_continuation = runtime_tail_for_test(&runtime_result);
        let adapted = template.adapt_lifted_terminal_callbacks(
            &[Some(runtime_callback)],
            runtime_result.clone(),
            outer_continuation.clone(),
        );

        let CheckedTermNode::TermCall {
            fn_value: continuation,
            arg_packet: value,
            ..
        } = adapted.node.as_ref()
        else {
            panic!("the rebuilt public call did not apply its outer continuation")
        };
        assert!(EvalRef::ptr_eq(continuation, &outer_continuation));
        let CheckedTermNode::TermCall { fn_value, .. } = value.node.as_ref() else {
            panic!("the public branch lost its terminal call")
        };
        let CheckedTermNode::TermLet {
            value: unused_value,
            body,
            ..
        } = fn_value.node.as_ref()
        else {
            panic!("the public callee lost its unused alias")
        };
        assert_eq!(unused_value.ty(), &callback(runtime_result.clone()));
        assert!(matches!(
            body.node.as_ref(),
            CheckedTermNode::Raw(Expr::Path { segments, .. })
                if matches!(segments.as_slice(), [segment] if segment.name == "ordinary_callback")
        ));
        assert_eq!(fn_value.ty(), &public_callback);
    }

