    #[test]
    fn projected_call_and_absurd_replay_checked_core_nodes() {
        let unit = Type::Unit { meta: zero_meta() };
        let bottom = Type::Bottom { meta: zero_meta() };
        let fn_type = Type::Function {
            param: Box::new(unit.clone()),
            ret: Box::new(unit.clone()),
            meta: zero_meta(),
            abi_arity: 1,
            caps: (),
        };
        let call = CheckedTerm::from_projected(
            ProjectedTermConstruction::Call {
                fn_value: EvalRef::new(CheckedTerm::new(path_expr("projected_fn"), fn_type)),
                params: vec![unit.clone()],
                arg_packet: EvalRef::new(CheckedTerm::new(
                    Expr::Unit {
                        occurrence: Default::default(),
                        meta: zero_meta(),
                    },
                    unit.clone(),
                )),
            },
            unit.clone(),
        );
        assert!(
            matches!(call.node.as_ref(), CheckedTermNode::TermCall { params, .. } if params == &vec![unit.clone()])
        );
        assert!(matches!(call.clone_expr(), Expr::Call { .. }));

        let absurd = CheckedTerm::from_projected(
            ProjectedTermConstruction::Absurd {
                bottom_value: EvalRef::new(CheckedTerm::new(
                    Expr::Unit {
                        occurrence: Default::default(),
                        meta: zero_meta(),
                    },
                    bottom,
                )),
            },
            unit,
        );
        let Expr::Call { callee, .. } = absurd.clone_expr() else {
            panic!("projected absurd must replay as a core call")
        };
        assert!(matches!(
            callee.as_ref(),
            Expr::Path { segments, .. }
                if matches!(segments.as_slice(), [segment] if segment.name == "__absurd__")
        ));
    }

    #[test]
    fn term_specialize_distinguishes_structural_miss_from_diagnostic() {
        let ctx = EvalCtx::new();
        let params = ["A", "Unused"];
        let mut poly_type = Type::Unit { meta: zero_meta() };
        for name in params.into_iter().rev() {
            poly_type = Type::Forall {
                param: TypeParam {
                    name: name.into(),
                    span: zero_span(),
                    kind: None,
                },
                body: Box::new(poly_type),
                meta: zero_meta(),
            };
        }
        let underdetermined = apply(
            Value::Primitive(ComptimeBuiltin::TermSpecialize),
            vec![
                checked_term_value(path_expr("poly"), poly_type),
                refl_type_value(Type::synth_path(vec!["A".into()], Vec::new(), zero_span())),
                refl_type_value(Type::Unit { meta: zero_meta() }),
            ],
            &ctx,
        );
        assert!(
            matches!(&underdetermined, Value::Data(outer)
                if outer.ctor() == "__right__"
                    && matches!(outer.args(), [Value::Data(inner)]
                        if inner.ctor() == "__right__"
                            && matches!(inner.args(), [Value::DiagnosticText(message)] if message.contains("Unused")))),
            "underdetermined relation must use diagnostic branch: {underdetermined:?}"
        );

        let mismatch_pattern = Type::Product {
            left: Box::new(Type::Unit { meta: zero_meta() }),
            right: Box::new(Type::Unit { meta: zero_meta() }),
            meta: zero_meta(),
        };
        let mismatch_target = Type::Sum {
            left: Box::new(Type::Unit { meta: zero_meta() }),
            right: Box::new(Type::Unit { meta: zero_meta() }),
            meta: zero_meta(),
        };
        let miss = apply(
            Value::Primitive(ComptimeBuiltin::TermSpecialize),
            vec![
                checked_term_value(path_expr("mono"), mismatch_pattern.clone()),
                refl_type_value(mismatch_pattern),
                refl_type_value(mismatch_target),
            ],
            &ctx,
        );
        assert!(
            matches!(&miss, Value::Data(outer)
                if outer.ctor() == "__right__"
                    && matches!(outer.args(), [Value::Data(inner)]
                        if inner.ctor() == "__left__"
                            && matches!(inner.args(), [Value::Unit]))),
            "structural mismatch must use no-match branch: {miss:?}"
        );
    }

    #[test]
    fn apply_reflection_type_instantiate_arity_zero_binder() {
        let ctx = EvalCtx::new();
        let scheme = Type::Forall {
            param: TypeParam {
                name: "A".into(),
                span: zero_span(),
                kind: Some(crate::ast::Kind::arrow_chain(0)),
            },
            body: Box::new(Type::Unit { meta: zero_meta() }),
            meta: zero_meta(),
        };
        let instantiated = apply(
            Value::Primitive(ComptimeBuiltin::TypeInstantiate),
            vec![
                refl_type_value(scheme),
                refl_type_value(Type::Unit { meta: zero_meta() }),
            ],
            &ctx,
        );
        // Substituting a ground (non-path) arg for an arity-0 binder
        // succeeds → the ok (left) injection of the result sum.
        assert!(
            matches!(&instantiated, Value::Data(d) if d.ctor() == "__left__"),
            "{instantiated:?}"
        );
    }

    #[test]
    fn apply_reflection_runtime_args_strip_and_fold_arity() {
        let ctx = EvalCtx::new();

        // A `__Comptime__` receiver is stripped before the arm match.
        let stripped = apply(
            Value::Primitive(ComptimeBuiltin::TypeUnit),
            vec![Value::Primitive(ComptimeBuiltin::ComptimeProof)],
            &ctx,
        );
        assert!(
            matches!(as_refl_type_ref(&stripped), Some(Type::Unit { .. })),
            "{stripped:?}"
        );
        // A non-`__Comptime__` leading atom is NOT stripped → stays stuck.
        let unstripped = apply(
            Value::Primitive(ComptimeBuiltin::TypeUnit),
            vec![Value::Atom("not_comptime".into())],
            &ctx,
        );
        assert!(matches!(unstripped, Value::Stuck(..)), "{unstripped:?}");

        // __structural_recur__ with exactly its three operands reduces
        // through the step (no 6-arg strip fires).
        let recur = apply(
            structural_recur_primitive_for_test("runtime-args"),
            vec![Value::Unit, Value::Unit, Value::Atom("s".into())],
            &ctx,
        );
        assert!(
            matches!(&recur, Value::Stuck(c, _) if matches!(&**c, Value::Atom(n) if n == "s")),
            "{recur:?}"
        );

        // __type_args_fold__ with its three operands folds (no 4-arg strip).
        let pair_ty = Type::synth_path(
            vec!["Pair".into()],
            vec![
                Type::Unit { meta: zero_meta() },
                Type::Unit { meta: zero_meta() },
            ],
            zero_span(),
        );
        let folded = apply(
            Value::Primitive(ComptimeBuiltin::TypeArgsFold),
            vec![
                refl_type_value(pair_ty),
                Value::Unit,
                Value::Atom("f".into()),
            ],
            &ctx,
        );
        assert!(
            matches!(&folded, Value::Stuck(c, _) if matches!(&**c, Value::Atom(n) if n == "f")),
            "{folded:?}"
        );
    }

    #[test]
    fn marked_fill_capabilities_are_immutable_call_scoped_and_unmemoizable() {
        let ctx = EvalCtx::new();
        let (proof, empty) = fresh_fills_capability_values();
        let candidate = refl_type_value(Type::Unit { meta: zero_meta() });
        let destination = projected_value(
            crate::pass::typecheck_core::apply::fills::focused_type_for_test(
                marked_comptime_proof_from_value(&proof).unwrap(),
                ReflectedType::new_trusted(Type::Unit { meta: zero_meta() }),
            ),
        );
        let filled = apply(
            Value::Primitive(ComptimeBuiltin::Fill),
            vec![
                proof.clone(),
                empty.clone(),
                destination.clone(),
                candidate.clone(),
            ],
            &ctx,
        );
        assert_eq!(
            fill_context_from_value(&empty)
                .unwrap()
                .relations_in_source_order()
                .len(),
            0
        );
        assert_eq!(
            fill_context_from_value(&filled)
                .unwrap()
                .relations_in_source_order()
                .len(),
            1
        );
        assert!(!exact_call_memo_result_shareable(&proof));
        assert!(!exact_call_memo_result_shareable(&filled));
        assert!(!exact_call_memo_result_shareable(&destination));
        let mut memo_budget = EXACT_CALL_MEMO_KEY_BUDGET;
        assert!(value_memo_key(&destination, &mut memo_budget).is_none());
        assert_eq!(fuel_measure(&destination, &ctx), Some(1));

        let closed_view = apply(
            Value::Primitive(ComptimeBuiltin::TypeDisplay),
            vec![proof.clone(), destination.clone()],
            &ctx,
        );
        assert!(matches!(closed_view, Value::DiagnosticText(_)));

        let plain_destination = apply(
            Value::Primitive(ComptimeBuiltin::Fill),
            vec![
                proof.clone(),
                empty.clone(),
                candidate.clone(),
                candidate.clone(),
            ],
            &ctx,
        );
        assert!(
            matches!(plain_destination, Value::Stuck(..)),
            "{plain_destination:?}"
        );

        let (foreign_proof, _) = fresh_fills_capability_values();
        let foreign_view = apply(
            Value::Primitive(ComptimeBuiltin::TypeDisplay),
            vec![foreign_proof.clone(), destination.clone()],
            &ctx,
        );
        assert!(matches!(foreign_view, Value::Stuck(..)), "{foreign_view:?}");
        let rejected = apply(
            Value::Primitive(ComptimeBuiltin::Fill),
            vec![foreign_proof, filled, destination, candidate],
            &ctx,
        );
        assert!(matches!(rejected, Value::Stuck(..)), "{rejected:?}");

        let reflected = apply(
            Value::Primitive(ComptimeBuiltin::TypeUnit),
            vec![proof],
            &ctx,
        );
        assert!(matches!(
            as_refl_type_ref(&reflected),
            Some(Type::Unit { .. })
        ));
    }

    #[test]
    fn projected_type_args_fold_residualizes_only_an_unresolved_specialization_root() {
        use crate::pass::typecheck_core::apply::fills::{
            focused_type_for_test, projected_type_apply, projected_type_arguments,
            unresolved_type_reflections_for_test,
        };

        let ctx = EvalCtx::new();
        let (proof, foreign, goal, infer, alias_goal) = unresolved_type_reflections_for_test();
        let proof_value = Value::Data(EvalRef::new(DataValue::new_marked_comptime_proof(
            proof.clone(),
        )));
        let init = Value::Atom("unvisited_args".to_owned());
        let step = Value::Atom("visit_arg".to_owned());

        for unresolved in [&goal, &infer, &alias_goal] {
            assert!(
                projected_type_arguments(&proof, unresolved)
                    .expect("an authenticated unresolved type is not malformed")
                    .is_none(),
                "an unresolved canonical root fabricated an empty argument list"
            );
            assert!(
                projected_type_arguments(&foreign, unresolved).is_err(),
                "an unresolved root bypassed invocation authentication"
            );
            let folded = apply(
                Value::Primitive(ComptimeBuiltin::TypeArgsFold),
                vec![
                    proof_value.clone(),
                    projected_value((*unresolved).clone()),
                    init.clone(),
                    step.clone(),
                ],
                &ctx,
            );
            assert!(
                matches!(folded, Value::Stuck(..)),
                "an unresolved canonical root reduced to a concrete fold result: {folded:?}"
            );
        }

        let unit = Type::Unit { meta: zero_meta() };
        let non_path = focused_type_for_test(&proof, ReflectedType::new_trusted(unit.clone()));
        assert_eq!(
            projected_type_arguments(&proof, &non_path)
                .expect("a known unit type is authenticated")
                .expect("a known non-path root must reduce")
                .len(),
            0
        );
        let folded = apply(
            Value::Primitive(ComptimeBuiltin::TypeArgsFold),
            vec![
                proof_value.clone(),
                projected_value(non_path),
                init.clone(),
                step.clone(),
            ],
            &ctx,
        );
        assert!(
            matches!(&folded, Value::Atom(name) if name == "unvisited_args"),
            "a known non-path root stopped behaving as an empty argument list: {folded:?}"
        );

        let head = focused_type_for_test(
            &proof,
            ReflectedType::new_trusted(Type::synth_path(
                vec!["F".to_owned()],
                Vec::new(),
                zero_span(),
            )),
        );
        let nested = projected_type_apply(&proof, &projected_value(head), &projected_value(goal))
            .expect("a same-proof path application is authenticated")
            .expect("a known path root must reduce");
        let nested_arguments = projected_type_arguments(&proof, &nested)
            .expect("a same-proof path is authenticated")
            .expect("a known path with an open interior must expose its arguments");
        assert_eq!(nested_arguments.len(), 1);
        let folded = apply(
            Value::Primitive(ComptimeBuiltin::TypeArgsFold),
            vec![proof_value, projected_value(nested), Value::Unit, step],
            &ctx,
        );
        assert!(
            matches!(&folded, Value::Stuck(callee, args)
                if matches!(callee.as_ref(), Value::Atom(name) if name == "visit_arg")
                    && matches!(args.as_slice(), [Value::Unit, Value::Projected(_)])),
            "a known path with an open argument did not visit that argument: {folded:?}"
        );
    }

    #[test]
    fn projected_type_apply_residualizes_only_an_unresolved_specialization_head() {
        use crate::pass::typecheck_core::apply::fills::{
            focused_type_for_test, projected_type_apply, projected_type_arguments,
            unresolved_type_reflections_for_test,
        };

        let ctx = EvalCtx::new();
        let (proof, foreign, goal, infer, alias_goal) = unresolved_type_reflections_for_test();
        let (_, _, foreign_argument, _, _) = unresolved_type_reflections_for_test();
        let proof_value = Value::Data(EvalRef::new(DataValue::new_marked_comptime_proof(
            proof.clone(),
        )));
        let unit = Type::Unit { meta: zero_meta() };
        let unit_value = refl_type_value(unit.clone());

        assert!(
            projected_type_apply(
                &proof,
                &projected_value(goal.clone()),
                &projected_value(foreign_argument),
            )
            .is_err(),
            "an unresolved same-proof head residualized before authenticating its argument"
        );

        for unresolved in [&goal, &infer, &alias_goal] {
            assert!(
                projected_type_apply(&proof, &projected_value((*unresolved).clone()), &unit_value,)
                    .expect("an authenticated unresolved head is not malformed")
                    .is_none(),
                "an unresolved canonical head discarded its type argument"
            );
            assert!(
                projected_type_apply(
                    &foreign,
                    &projected_value((*unresolved).clone()),
                    &unit_value,
                )
                .is_err(),
                "an unresolved head bypassed invocation authentication"
            );
            let applied = apply(
                Value::Primitive(ComptimeBuiltin::TypeApply),
                vec![
                    proof_value.clone(),
                    projected_value((*unresolved).clone()),
                    unit_value.clone(),
                ],
                &ctx,
            );
            assert!(
                matches!(applied, Value::Stuck(..)),
                "an unresolved canonical head reduced after dropping its argument: {applied:?}"
            );
        }

        let non_path = focused_type_for_test(&proof, ReflectedType::new_trusted(unit.clone()));
        let unchanged =
            projected_type_apply(&proof, &projected_value(non_path.clone()), &unit_value)
                .expect("a known unit head is authenticated")
                .expect("a known non-path head must retain its existing no-op behavior");
        assert!(unchanged.same_snapshot(&non_path));

        let head = focused_type_for_test(
            &proof,
            ReflectedType::new_trusted(Type::synth_path(
                vec!["F".to_owned()],
                Vec::new(),
                zero_span(),
            )),
        );
        let nested = projected_type_apply(&proof, &projected_value(head), &projected_value(goal))
            .expect("a same-proof path application is authenticated")
            .expect("a known path root must reduce");
        let applied = projected_type_apply(&proof, &projected_value(nested), &unit_value)
            .expect("a same-proof nested path is authenticated")
            .expect("a known path with an open interior must remain applicable");
        assert_eq!(
            projected_type_arguments(&proof, &applied)
                .expect("the twice-applied path is authenticated")
                .expect("a known path root must expose its arguments")
                .len(),
            2
        );
    }

    #[test]
    fn projected_goal_free_child_closes_without_closing_its_open_parent() {
        use crate::pass::typecheck_core::apply::fills::{
            ProjectedTypeView, open_function_reflection_evidence_for_test,
            open_function_reflection_for_test, projected_type_view,
        };

        let ctx = EvalCtx::new();
        let unit = Type::Unit { meta: zero_meta() };
        let (proof, foreign_proof, parent) =
            open_function_reflection_for_test(ReflectedType::new_trusted(unit.clone()));
        crate::pass::typecheck_core::reset_deep_canonicalization_calls_for_test();
        let ProjectedTypeView::Function { param, ret, .. } =
            projected_type_view(&proof, &parent).expect("projected function view")
        else {
            panic!("an open projected function must retain its structural shell")
        };
        assert!(open_function_reflection_evidence_for_test(
            &parent, &param, &ret
        ));
        let ProjectedTypeView::Function {
            param: repeated_param,
            ret: repeated_ret,
            ..
        } = projected_type_view(&proof, &parent).expect("repeated projected function view")
        else {
            panic!("a repeated view lost the semantic function carrier")
        };
        assert!(open_function_reflection_evidence_for_test(
            &parent,
            &repeated_param,
            &repeated_ret,
        ));
        assert_eq!(
            param.structural_measure(),
            repeated_param.structural_measure()
        );
        assert_eq!(ret.structural_measure(), repeated_ret.structural_measure());
        assert!(matches!(
            projected_type_view(&proof, &param).expect("nested projected child view"),
            ProjectedTypeView::Unit
        ));
        assert_eq!(
            crate::pass::typecheck_core::deep_canonicalization_calls_for_test(),
            0,
            "repeated structural views re-canonicalized an already captured carrier"
        );

        let proof_value = Value::Data(EvalRef::new(DataValue::new_marked_comptime_proof(proof)));
        let foreign_proof_value = Value::Data(EvalRef::new(DataValue::new_marked_comptime_proof(
            foreign_proof,
        )));
        let reflected_unit = refl_type_value(unit);
        let param = projected_value(param);
        let ret = projected_value(ret);
        let parent = projected_value(parent);

        let equal = apply(
            Value::Primitive(ComptimeBuiltin::TypeEqual),
            vec![proof_value.clone(), param.clone(), reflected_unit.clone()],
            &ctx,
        );
        assert!(matches!(equal, Value::Bool(true)), "{equal:?}");
        for value in [parent, ret] {
            let equality = apply(
                Value::Primitive(ComptimeBuiltin::TypeEqual),
                vec![proof_value.clone(), value, reflected_unit.clone()],
                &ctx,
            );
            assert!(
                matches!(equality, Value::Stuck(..)),
                "an open parent or sibling was laundered into reflected evidence: {equality:?}"
            );
        }
        let foreign = apply(
            Value::Primitive(ComptimeBuiltin::TypeEqual),
            vec![foreign_proof_value, param.clone(), reflected_unit],
            &ctx,
        );
        assert!(
            matches!(foreign, Value::Stuck(..)),
            "a same-shaped foreign proof authenticated projected evidence: {foreign:?}"
        );
        for builtin in [ComptimeBuiltin::TypeDisplay, ComptimeBuiltin::TypeShortName] {
            let displayed = apply(
                Value::Primitive(builtin),
                vec![proof_value.clone(), param.clone()],
                &ctx,
            );
            assert!(
                matches!(&displayed, Value::DiagnosticText(text) if text == "."),
                "{displayed:?}"
            );
        }
    }

    #[test]
    fn projected_alias_child_uses_its_deep_carrier_and_exact_binder_scope() {
        use crate::pass::typecheck_core::apply::fills::{
            ProjectedTypeView, open_function_reflection_evidence_for_test,
            open_noncanonical_function_reflection_for_test, projected_type_view,
        };

        let artifact = lowered_package(&[(
            "consumer.kio",
            "module consumer; type Alias[T] = T; type A = .;",
        )]);
        let module_entry = artifact.module("consumer").expect("consumer module");
        let ctx = EvalCtx::for_module(&artifact, &module_entry.module, "consumer")
            .expect("consumer evaluator context");
        let (proof, foreign_proof, parent) = open_noncanonical_function_reflection_for_test();
        let ProjectedTypeView::Function { param, ret, .. } =
            projected_type_view(&proof, &parent).expect("projected noncanonical function view")
        else {
            panic!("an open noncanonical function must retain its structural shell")
        };
        assert!(open_function_reflection_evidence_for_test(
            &parent, &param, &ret
        ));

        let span = zero_span();
        let written = Type::synth_path(vec!["A".to_owned()], Vec::new(), span);
        let expected = crate::pass::resolve::exported_contract_type(
            &written,
            module_entry,
            &HashMap::from([("A".to_owned(), crate::ast::Kind::Star)]),
        );
        let expected_display = crate::pass::typecheck_core::display_type(&expected);
        assert_eq!(expected_display, "A", "rigid-binder protection was lost");

        let proof_value = Value::Data(EvalRef::new(DataValue::new_marked_comptime_proof(proof)));
        let foreign_proof_value = Value::Data(EvalRef::new(DataValue::new_marked_comptime_proof(
            foreign_proof,
        )));
        let param = projected_value(param);
        let equal = apply(
            Value::Primitive(ComptimeBuiltin::TypeEqual),
            vec![
                proof_value.clone(),
                param.clone(),
                refl_type_value(expected),
            ],
            &ctx,
        );
        assert!(matches!(equal, Value::Bool(true)), "{equal:?}");
        for builtin in [ComptimeBuiltin::TypeDisplay, ComptimeBuiltin::TypeShortName] {
            let displayed = apply(
                Value::Primitive(builtin),
                vec![proof_value.clone(), param.clone()],
                &ctx,
            );
            assert!(
                matches!(&displayed, Value::DiagnosticText(text) if text == &expected_display),
                "projected reflection did not expose the semantic alias child: {displayed:?}"
            );
        }

        let missing_module = apply(
            Value::Primitive(ComptimeBuiltin::TypeDisplay),
            vec![proof_value, param.clone()],
            &EvalCtx::new(),
        );
        assert!(
            matches!(&missing_module, Value::DiagnosticText(text) if text == "A"),
            "a canonical rigid child retained an unnecessary module dependency: {missing_module:?}"
        );
        let foreign = apply(
            Value::Primitive(ComptimeBuiltin::TypeDisplay),
            vec![foreign_proof_value, param],
            &ctx,
        );
        assert!(
            matches!(foreign, Value::Stuck(..)),
            "a foreign proof authenticated projected reflection evidence: {foreign:?}"
        );
    }

    #[test]
    fn projected_alias_path_arguments_follow_the_deep_carrier_order() {
        use crate::pass::typecheck_core::apply::fills::{
            ProjectedTypeView, closed_specialized_type_for_test, projected_type_arguments,
            projected_type_fuel_evidence_for_test, projected_type_view,
            projected_type_with_proof_for_fuel_test,
        };

        let span = zero_span();
        let unit = Type::Unit {
            meta: crate::ast::Meta::<crate::ast::Lowered>::new(span),
        };
        let bottom = Type::Bottom {
            meta: crate::ast::Meta::<crate::ast::Lowered>::new(span),
        };
        let path = |name: &str, args| Type::synth_path(vec![name.to_owned()], args, span);
        let (proof, swap) = projected_type_with_proof_for_fuel_test(
            path("Swap", vec![unit.clone(), bottom.clone()]),
            path("Pair", vec![bottom.clone(), unit.clone()]),
        );
        let args = projected_type_arguments(&proof, &swap)
            .expect("same-invocation type arguments")
            .expect("the deep path carrier must expose arguments");
        assert_eq!(args.len(), 2);
        assert!(matches!(
            projected_type_view(&proof, &args[0]).expect("first swapped argument"),
            ProjectedTypeView::Bottom
        ));
        assert!(matches!(
            projected_type_view(&proof, &args[1]).expect("second swapped argument"),
            ProjectedTypeView::Unit
        ));

        let (proof, foreign, closed_swap) = closed_specialized_type_for_test(
            path("Swap", vec![unit.clone(), bottom.clone()]),
            path("Pair", vec![bottom.clone(), unit.clone()]),
        );
        let closed_args = projected_type_arguments(&proof, &closed_swap)
            .expect("same-invocation closed type arguments")
            .expect("the closed deep path carrier must expose arguments");
        assert!(matches!(
            closed_args[0]
                .closed_reflected()
                .expect("the first semantic child remains closed")
                .as_type(),
            Type::Bottom { .. }
        ));
        assert!(matches!(
            closed_args[1]
                .closed_reflected()
                .expect("the second semantic child remains closed")
                .as_type(),
            Type::Unit { .. }
        ));
        for child in &closed_args {
            assert_eq!(
                projected_type_fuel_evidence_for_test(child),
                (true, true, true, false),
                "semantic children must preserve closure and invocation evidence"
            );
            assert!(child.authenticates_fill_destination(&proof));
        }
        assert!(
            projected_type_arguments(&foreign, &closed_swap).is_err(),
            "a foreign proof authenticated a closed semantic child"
        );

        let (proof, nested_alias) = projected_type_with_proof_for_fuel_test(
            path("Pair", vec![path("Alias", vec![unit.clone()])]),
            path("Pair", vec![unit]),
        );
        let args = projected_type_arguments(&proof, &nested_alias)
            .expect("same-invocation type arguments")
            .expect("the nominal carrier must expose its argument");
        assert!(matches!(
            projected_type_view(&proof, &args[0]).expect("deep nominal argument"),
            ProjectedTypeView::Unit
        ));
    }

    #[test]
    fn grouped_comptime_proof_application_reassociates_for_primitive() {
        let ctx = EvalCtx::new();
        let fuel = refl_type_value(Type::Unit { meta: zero_meta() });
        let input = Value::Unit;
        let step = Value::Atom("step".into());
        let primitive = structural_recur_source_primitive_for_test("grouped-proof");
        let direct = apply(
            primitive.clone(),
            vec![
                Value::Primitive(ComptimeBuiltin::ComptimeProof),
                fuel.clone(),
                input.clone(),
                step.clone(),
            ],
            &ctx,
        );
        let proof_group = apply(
            primitive,
            vec![Value::Primitive(ComptimeBuiltin::ComptimeProof)],
            &ctx,
        );
        let grouped = apply(proof_group, vec![fuel, input, step], &ctx);

        assert_eq!(value_to_string(&grouped), value_to_string(&direct));
        assert!(
            matches!(
                &grouped,
                Value::Stuck(callee, args)
                    if matches!(callee.as_ref(), Value::Atom(name) if name == "step")
                        && matches!(args.as_slice(), [Value::StructuralRecur { .. }, Value::ReflType(_), Value::Unit])
            ),
            "grouped Kio' application did not reach the recursion step: {grouped:?}"
        );
    }

    fn lowered_package(mods: &[(&str, &str)]) -> EvalArtifact {
        use std::path::PathBuf;
        let parsed: Vec<(PathBuf, _)> = mods
            .iter()
            .map(|(path, src)| {
                let surface = crate::pass::parser::parse(src).expect("parse");
                let desugared = crate::pass::desugar::desugar_module(surface).expect("desugar");
                (PathBuf::from(path), desugared)
            })
            .collect();
        let (lowered, _) =
            crate::pass::label_elab::elaborate_package(parsed, None).expect("label_elab");
        let package: crate::pass::resolve::Package<SourcePhase> =
            crate::pass::resolve::Package::build(std::path::Path::new(""), lowered, None)
                .expect("package build");
        package.resolve_imports().expect("resolve imports");
        let package = crate::pass::alpha_normalize::normalize_package(&package);
        crate::pass::substitute::substitute_package_for_eval(&package, &Elaborations::new())
            .expect("evaluator artifact")
    }

    #[test]
    fn checked_term_serialization_preserves_nested_type_binders() {
        use crate::pass::typecheck_core::PrimeTypeRequalifier;

        let unit = EvalRef::new(CheckedTerm::new(
            Expr::Unit {
                occurrence: Default::default(),
                meta: zero_meta(),
            },
            Type::Unit { meta: zero_meta() },
        ));
        let mut expr = EvalExpr::Const(Value::CheckedTerm(unit.clone()));
        for _ in 0..2 {
            let function = test_eval_function(&["type"], expr);
            expr = EvalExpr::ReflTermTypeFn {
                arity: EvalRef::new(EvalExpr::Const(Value::ReflTypeArity(0))),
                body: EvalRef::new(EvalExpr::FnRef {
                    cache_key: function.cache_key.clone(),
                    function,
                    share_closure: false,
                }),
            };
        }
        let generated =
            eval_compiled_expr(&expr, &mut EvalSlots::root(Vec::new()), &EvalCtx::new());
        let Value::CheckedTerm(generated) = generated else {
            panic!("type-function constructor lost its checked term");
        };
        let canonical = generated.canonicalize_generated_names();
        fn type_fn_parts(term: &CheckedTerm) -> (&TypeParam, &CheckedTerm) {
            let CheckedTermNode::TermCall { fn_value, .. } = term.node.as_ref() else {
                panic!("type-function constructor lost its Unit application");
            };
            let CheckedTermNode::TermFn { sig, body } = fn_value.node.as_ref() else {
                panic!("type-function constructor lost its function");
            };
            let [SignatureParam::Type(param)] = sig.params.as_slice() else {
                panic!("type-function constructor lost its type parameter");
            };
            (param, body)
        }
        let (outer, body) = type_fn_parts(&canonical);
        let (inner, _) = type_fn_parts(body);
        assert!(is_generated_checked_term_type_name(&outer.name));
        assert!(is_generated_checked_term_type_name(&inner.name));
        assert_ne!(outer.name, inner.name);
        assert_eq!(
            canonical.serialization_type_binders(),
            HashSet::from([outer.name.clone(), inner.name.clone()])
        );

        let type_fn = |name: &str, body| {
            EvalRef::new(checked_term_type_fn(
                TypeParam {
                    name: name.to_owned(),
                    span: zero_span(),
                    kind: None,
                },
                body,
            ))
        };
        let value_fn = EvalRef::new(CheckedTerm::from_node(
            CheckedTermNode::TermFn {
                sig: Signature::new(vec![value_param("value_only")]),
                body: unit.clone(),
            },
            Type::Function {
                param: Box::new(unit.clone_type()),
                ret: Box::new(unit.clone_type()),
                meta: zero_meta(),
                abi_arity: 1,
                caps: (),
            },
        ));
        let term = type_fn(
            "Local",
            checked_product_packet(&[type_fn("Remote", type_fn("Local", unit)), value_fn]),
        );
        let binders = term.serialization_type_binders();
        assert_eq!(
            binders,
            HashSet::from(["Local".to_owned(), "Remote".to_owned()])
        );

        let artifact = lowered_package(&[
            (
                "provider.kio",
                "module provider; pub newtype Remote : . { constructor remote; projector un_remote; };",
            ),
            (
                "caller.kio",
                "module caller; import provider(Remote); \
                 newtype Local : . { constructor local; projector un_local; }; \
                 newtype Other : . { constructor other; projector un_other; };",
            ),
        ]);
        let caller = &artifact.module("caller").expect("caller module").module;
        let mut requalifier = PrimeTypeRequalifier::new(caller);
        let nominal = |owner: &str, name: &str| -> Type<EvalPhase> {
            Type::synth_path(
                vec![owner.to_owned(), name.to_owned()],
                Vec::new(),
                zero_span(),
            )
        };
        let path_names = |ty: Type<EvalPhase>| {
            let Type::Path { segments, .. } = ty else {
                panic!("rewritten nominal lost its path");
            };
            segments
                .into_iter()
                .map(|segment| segment.name)
                .collect::<Vec<_>>()
        };
        let local = path_names(requalifier.rewrite(&nominal("caller", "Local"), &binders));
        let remote = path_names(requalifier.rewrite(&nominal("provider", "Remote"), &binders));
        let other = path_names(requalifier.rewrite(&nominal("caller", "Other"), &binders));
        let aliases = requalifier.take_local_aliases();
        assert_eq!(aliases.len(), 1);
        assert_eq!(aliases[0].nominal, "Local");
        assert!(aliases[0].params.is_empty());
        assert_eq!(local, [aliases[0].alias.clone()]);
        assert!(!binders.contains(&local[0]));
        let imports = requalifier.take_imports();
        assert_eq!(imports.len(), 1);
        let crate::ast::ImportKind::Qualified { path, alias } = &imports[0].kind else {
            panic!("shadowed selective import needs a qualified binding");
        };
        assert_eq!(
            path.segments
                .iter()
                .map(|segment| segment.as_str())
                .collect::<Vec<_>>(),
            ["provider"]
        );
        assert_eq!(remote, [alias.clone(), "Remote".to_owned()]);
        assert!(!binders.contains(alias));
        assert_eq!(other, ["Other"]);
    }

    #[test]
    fn type_short_name_uses_shortest_unambiguous_root_spelling() {
        let artifact = lowered_package(&[
            (
                "owner.kio",
                "module owner; pub type Box[A] = A; pub type Choice[A][B] = A & B; pub type Item = .;",
            ),
            ("tie_owner.kio", "module tie_owner; pub type Thing = .;"),
            ("unimported.kio", "module unimported; pub type Hidden = .;"),
            (
                "consumer.kio",
                "module consumer; \
                 import owner as verbose; import owner(Box); import owner as o; \
                 import tie_owner as aa; import tie_owner as bb; \
                 type Local = .; fn keep() -> . { () }",
            ),
        ]);
        let consumer = &artifact.module("consumer").expect("consumer module").module;
        let ctx = EvalCtx::for_module(&artifact, consumer, "consumer")
            .expect("consumer evaluator context");
        let nominal = |owner: &str, leaf: &str, args: Vec<Type<EvalPhase>>| {
            Type::synth_path(vec![owner.to_owned(), leaf.to_owned()], args, zero_span())
        };
        let unit = Type::Unit { meta: zero_meta() };

        let box_unit = nominal("owner", "Box", vec![unit.clone()]);
        assert_eq!(
            compact_refl_type_display(&box_unit, &ctx),
            "Box(.)",
            "a later selective import must beat an earlier qualified import without unfolding the alias head"
        );
        assert_eq!(
            compact_refl_type_display(&nominal("consumer", "Local", Vec::new()), &ctx),
            "Local",
            "a same-module nominal should use its bare leaf"
        );
        assert_eq!(
            compact_refl_type_display(&nominal("owner", "Item", Vec::new()), &ctx),
            "o.Item",
            "the shortest qualified alias should win independently of import order"
        );
        assert_eq!(
            compact_refl_type_display(&nominal("tie_owner", "Thing", Vec::new()), &ctx),
            "aa.Thing",
            "equal-length aliases should retain source order"
        );
        assert_eq!(
            compact_refl_type_display(&nominal("unimported", "Hidden", Vec::new()), &ctx),
            "unimported.Hidden",
            "an owner outside the lexical import scope must stay canonical"
        );

        let full = apply(
            Value::Primitive(ComptimeBuiltin::TypeDisplay),
            vec![refl_type_value(box_unit.clone())],
            &ctx,
        );
        let short = apply(
            Value::Primitive(ComptimeBuiltin::TypeShortName),
            vec![refl_type_value(box_unit)],
            &ctx,
        );
        assert!(
            matches!(&full, Value::DiagnosticText(text) if text == "owner.Box(.)"),
            "full reflected display changed while short display split away: {full:?}"
        );
        assert!(
            matches!(&short, Value::DiagnosticText(text) if text == "Box(.)"),
            "the short-name builtin did not use compact root spelling: {short:?}"
        );
    }

    #[test]
    fn reflected_type_display_uses_canonical_module_path_separators() {
        let ctx = EvalCtx::new();
        let path = |segments: &[&str], args| {
            Type::synth_path(
                segments
                    .iter()
                    .map(|segment| (*segment).to_owned())
                    .collect(),
                args,
                zero_span(),
            )
        };
        let reflected = Type::Product {
            left: Box::new(path(
                &["foo", "bar", "Box"],
                vec![path(&["m", "Item"], Vec::new())],
            )),
            right: Box::new(path(&["Local"], Vec::new())),
            meta: zero_meta(),
        };
        let display = apply(
            Value::Primitive(ComptimeBuiltin::TypeDisplay),
            vec![refl_type_value(reflected)],
            &ctx,
        );
        assert!(
            matches!(&display, Value::DiagnosticText(text) if text == "(foo/bar.Box(m.Item) & Local)"),
            "reflected nested/applied type did not retain canonical, alias, and local spelling: {display:?}"
        );
    }

    #[test]
    fn reflected_type_name_display_uses_canonical_module_path_separators() {
        let ctx = EvalCtx::new();
        for (segments, expected) in [
            (vec!["foo", "bar", "Item"], "foo/bar.Item"),
            (vec!["m", "Item"], "m.Item"),
            (vec!["Local"], "Local"),
        ] {
            let name_display = apply(
                Value::Primitive(ComptimeBuiltin::TypeNameDisplay),
                vec![Value::ReflTypeName {
                    segments: segments.into_iter().map(str::to_owned).collect(),
                    param_arities: Vec::new(),
                }],
                &ctx,
            );
            assert!(
                matches!(&name_display, Value::DiagnosticText(text) if text == expected),
                "reflected type-name display did not preserve the identity shape: {name_display:?}"
            );
        }
    }

    #[test]
    fn type_short_name_preserves_structure_and_exact_binder_scope() {
        let artifact = lowered_package(&[
            (
                "owner.kio",
                "module owner; pub type Box[A] = A; pub type Choice[A][B] = A & B; pub type Item = .;",
            ),
            ("missing.kio", "module missing; pub type Hidden = .;"),
            (
                "consumer.kio",
                "module consumer; \
                 import owner as verbose; import owner(Box); import owner as o; \
                 type Local = .; fn keep() -> . { () }",
            ),
        ]);
        let consumer = &artifact.module("consumer").expect("consumer module").module;
        let ctx = EvalCtx::for_module(&artifact, consumer, "consumer")
            .expect("consumer evaluator context");
        let nominal = |owner: &str, leaf: &str, args: Vec<Type<EvalPhase>>| {
            Type::synth_path(vec![owner.to_owned(), leaf.to_owned()], args, zero_span())
        };
        let bare = |name: &str| type_path(name);
        let unit = Type::Unit { meta: zero_meta() };
        let local = nominal("consumer", "Local", Vec::new());
        let nested_sum = Type::Sum {
            left: Box::new(local),
            right: Box::new(nominal("missing", "Hidden", Vec::new())),
            meta: zero_meta(),
        };
        let choice = nominal(
            "owner",
            "Choice",
            vec![nominal("owner", "Box", vec![unit]), nested_sum],
        );
        let structured = Type::synth_function(
            vec![choice],
            nominal("owner", "Item", Vec::new()),
            zero_span(),
        );
        assert_eq!(
            compact_refl_type_display(&structured, &ctx),
            "o.Choice(Box(.), (Local | missing.Hidden)) -> o.Item",
            "short spelling must preserve nested applications, sums, function structure, and alias heads"
        );

        let shadowed_leaf = Type::Forall {
            param: TypeParam {
                name: "Box".to_owned(),
                span: zero_span(),
                kind: None,
            },
            body: Box::new(nominal("owner", "Box", vec![bare("Box")])),
            meta: zero_meta(),
        };
        assert_eq!(
            compact_refl_type_display(&shadowed_leaf, &ctx),
            "[Box] o.Box(Box)",
            "a forall binder must keep a same-leaf selective import qualified"
        );

        let shadowed_alias = Type::Forall {
            param: TypeParam {
                name: "o".to_owned(),
                span: zero_span(),
                kind: None,
            },
            body: Box::new(nominal("owner", "Item", Vec::new())),
            meta: zero_meta(),
        };
        let alias_scope_boundary = Type::Product {
            left: Box::new(shadowed_alias),
            right: Box::new(nominal("owner", "Item", Vec::new())),
            meta: zero_meta(),
        };
        assert_eq!(
            compact_refl_type_display(&alias_scope_boundary, &ctx),
            "(([o] verbose.Item) & o.Item)",
            "a nested binder must make the shortest alias unavailable only in its lexical body, then release it"
        );

        let free_leaf_collision = Type::Product {
            left: Box::new(bare("Box")),
            right: Box::new(nominal("owner", "Box", Vec::new())),
            meta: zero_meta(),
        };
        assert_eq!(
            compact_refl_type_display(&free_leaf_collision, &ctx),
            "(Box & o.Box)",
            "a free bare head must protect the same spelling throughout one reflected type"
        );

        let canonical = nominal("owner", "Box", vec![bare("T")]);
        assert_eq!(
            compact_refl_type_display(&canonical, &EvalCtx::new()),
            crate::pass::typecheck_core::display_type(&canonical),
            "without an evaluator root, short display must exactly match full display"
        );

        let deep_canonical = Type::synth_path(
            vec!["foo".to_owned(), "bar".to_owned(), "Box".to_owned()],
            vec![nominal("owner", "Item", Vec::new())],
            zero_span(),
        );
        assert_eq!(
            compact_refl_type_display(&deep_canonical, &EvalCtx::new()),
            "foo/bar.Box(owner.Item)",
            "a canonical fallback must retain module-path separators throughout a nested application"
        );
    }

    #[test]
    fn projected_type_short_name_uses_authenticated_root_spelling() {
        use crate::pass::typecheck_core::apply::fills::closed_specialized_type_for_test;

        let artifact = lowered_package(&[
            ("owner.kio", "module owner; pub type Item = .;"),
            (
                "consumer.kio",
                "module consumer; import owner as verbose; import owner as o; fn keep() -> . { () }",
            ),
        ]);
        let consumer = &artifact.module("consumer").expect("consumer module").module;
        let ctx = EvalCtx::for_module(&artifact, consumer, "consumer")
            .expect("consumer evaluator context");
        let lowered_item = Type::synth_path(
            vec!["owner".to_owned(), "Item".to_owned()],
            Vec::new(),
            zero_span(),
        );
        let (proof, foreign, projected) =
            closed_specialized_type_for_test(lowered_item.clone(), lowered_item);
        let proof = Value::Data(EvalRef::new(DataValue::new_marked_comptime_proof(proof)));
        let foreign = Value::Data(EvalRef::new(DataValue::new_marked_comptime_proof(foreign)));
        let projected = projected_value(projected);

        let full = apply(
            Value::Primitive(ComptimeBuiltin::TypeDisplay),
            vec![proof.clone(), projected.clone()],
            &ctx,
        );
        let short = apply(
            Value::Primitive(ComptimeBuiltin::TypeShortName),
            vec![proof, projected.clone()],
            &ctx,
        );
        let rejected = apply(
            Value::Primitive(ComptimeBuiltin::TypeShortName),
            vec![foreign, projected],
            &ctx,
        );
        assert!(
            matches!(&full, Value::DiagnosticText(text) if text == "owner.Item"),
            "full projected display changed while short display split away: {full:?}"
        );
        assert!(
            matches!(&short, Value::DiagnosticText(text) if text == "o.Item"),
            "an authenticated closed projection did not use root compact spelling: {short:?}"
        );
        assert!(
            matches!(&rejected, Value::Stuck(..)),
            "a foreign proof authenticated projected short-name evidence: {rejected:?}"
        );
    }

    fn reserved_shadow_artifact() -> EvalArtifact {
        use std::path::PathBuf;

        let sources = [
            (
                "provider.kio",
                "module provider; import __comptime__; \
                 pub fn shadow(proof: .)(left: ., middle: ., right: .) -> . { left }",
            ),
            (
                "selective.kio",
                "module selective; import __comptime__; import provider(shadow); fn keep() -> . { () }",
            ),
            (
                "qualified.kio",
                "module qualified; import __comptime__; import provider as p; fn keep() -> . { () }",
            ),
            (
                "builtin.kio",
                "module builtin; import __comptime__; fn keep() -> . { () }",
            ),
        ];
        let parsed = sources
            .iter()
            .map(|(path, source)| {
                let surface = crate::pass::parser::parse(source).expect("parse shadow package");
                let desugared =
                    crate::pass::desugar::desugar_module(surface).expect("desugar shadow package");
                (PathBuf::from(path), desugared)
            })
            .collect();
        let (mut lowered, _) = crate::pass::label_elab::elaborate_package(parsed, None)
            .expect("label-elaborate shadow package");
        for (_, module) in &mut lowered {
            match module_path_string(module).as_str() {
                "provider" => {
                    let def = module
                        .items
                        .iter_mut()
                        .find_map(|item| match item {
                            Item::FnDef(def) if def.name == "shadow" => Some(def),
                            _ => None,
                        })
                        .expect("provider shadow definition");
                    def.name = "__structural_recur__".to_owned();
                }
                "selective" => {
                    let import_item = module
                        .imports
                        .iter_mut()
                        .find_map(|import_| match &mut import_.kind {
                            ImportKind::Selective { items, .. } => items.first_mut(),
                            _ => None,
                        })
                        .expect("selective shadow import");
                    let crate::ast::ImportItem::Name { name, .. } = import_item else {
                        panic!("ordinary selective shadow import")
                    };
                    *name = "__structural_recur__".to_owned();
                }
                _ => {}
            }
        }
        let package: crate::pass::resolve::Package<SourcePhase> =
            crate::pass::resolve::Package::build(std::path::Path::new(""), lowered, None)
                .expect("shadow package build");
        package.resolve_imports().expect("resolve shadow uses");
        let package = crate::pass::alpha_normalize::normalize_package(&package);
        crate::pass::substitute::substitute_package_for_eval(&package, &Elaborations::new())
            .expect("shadow evaluator artifact")
    }

    #[test]
    fn ordinary_resolution_precedes_structural_recur_authority_for_every_path_shape() {
        let artifact = reserved_shadow_artifact();
        let proof = Expr::Unit {
            occurrence: Default::default(),
            meta: zero_meta(),
        };
        let grouped_args = vec![
            CallArg::Value(Expr::Unit {
                occurrence: Default::default(),
                meta: zero_meta(),
            }),
            CallArg::Value(Expr::Unit {
                occurrence: Default::default(),
                meta: zero_meta(),
            }),
            CallArg::Value(Expr::Unit {
                occurrence: Default::default(),
                meta: zero_meta(),
            }),
        ];
        let path = |segments: &[&str]| Expr::Path {
            occurrence: Default::default(),
            segments: segments
                .iter()
                .map(|segment| PathSegment::new((*segment).to_owned(), zero_span()))
                .collect(),
            meta: zero_meta(),
            ext: (),
        };

        for (module_path, segments) in [
            ("provider", vec!["__structural_recur__"]),
            ("selective", vec!["__structural_recur__"]),
            ("qualified", vec!["p", "__structural_recur__"]),
        ] {
            let module = &artifact
                .module(module_path)
                .unwrap_or_else(|| panic!("{module_path} module"))
                .module;
            let ctx = AuthenticatedEvalCtx::for_module(&artifact, module, module_path)
                .expect("ordinary shadow context");
            let callee = path(&segments);
            let bare = eval_authenticated(&callee, &Env::new(), &ctx);
            assert!(
                matches!(&bare, Value::EvalClosure { .. }),
                "{module_path} bare value gained primitive authority: {bare:?}"
            );
            let indirect = apply(
                apply(bare, vec![Value::Unit], &ctx),
                vec![Value::Unit, Value::Unit, Value::Unit],
                &ctx,
            );
            assert!(matches!(indirect, Value::Unit));

            let grouped = Expr::synth_call(
                Expr::synth_call(callee, vec![CallArg::Value(proof.clone())], zero_span()),
                grouped_args.clone(),
                zero_span(),
            );
            assert!(matches!(
                eval_authenticated(&grouped, &Env::new(), &ctx),
                Value::Unit
            ));
        }

        let builtin_module = &artifact.module("builtin").expect("builtin module").module;
        let builtin_ctx = AuthenticatedEvalCtx::for_module(&artifact, builtin_module, "builtin")
            .expect("builtin context");
        let builtin =
            eval_authenticated(&path(&["__structural_recur__"]), &Env::new(), &builtin_ctx);
        assert!(structural_recur_primitive_site(&builtin).is_some());
    }

    #[test]
    fn evaluation_fn_tables_filter_ordinary_qualified_imports() {
        let pkg = lowered_package(&[
            (
                "provider.kio",
                "module provider; fn hidden() -> . { () } pub fn shown() -> . { () }",
            ),
            (
                "ordinary.kio",
                "module ordinary; import provider as p; fn keep() -> . { () }",
            ),
        ]);
        pkg.resolve_imports().expect("resolve imports");

        let ordinary = &pkg.module("ordinary").expect("ordinary module").module;
        let ordinary_env =
            crate::pass::typecheck_core::ModuleEnv::build(ordinary, None, None, Some(&pkg))
                .expect("ordinary env");
        let (_, ordinary_fns) = fn_tables_from_env(&ordinary_env);
        assert!(ordinary_fns.contains_key(&("p", "shown")));
        assert!(!ordinary_fns.contains_key(&("p", "hidden")));
    }

