    fn type_unit_call() -> Expr<EvalPhase> {
        Expr::synth_call(path_expr("__type_unit__"), Vec::new(), zero_span())
    }

    fn reflect_unit_call(callee: Expr<EvalPhase>) -> Expr<EvalPhase> {
        Expr::synth_call(
            callee,
            vec![
                CallArg::Value(Expr::Unit {
                    occurrence: Default::default(),
                    meta: zero_meta(),
                }),
                CallArg::Type(Type::Unit { meta: zero_meta() }),
            ],
            zero_span(),
        )
    }

    fn reflect_unit_call_with_proof(proof: Expr<EvalPhase>, grouped: bool) -> Expr<EvalPhase> {
        if grouped {
            let proof_group = Expr::synth_call(
                path_expr("__reflect_type__"),
                vec![CallArg::Value(proof)],
                zero_span(),
            );
            Expr::synth_call(
                proof_group,
                vec![CallArg::Type(Type::Unit { meta: zero_meta() })],
                zero_span(),
            )
        } else {
            Expr::synth_call(
                path_expr("__reflect_type__"),
                vec![
                    CallArg::Value(proof),
                    CallArg::Type(Type::Unit { meta: zero_meta() }),
                ],
                zero_span(),
            )
        }
    }

    #[test]
    fn evaluator_primitive_environment_round_trips_with_module_scope() {
        let artifact = lowered_package(&[
            (
                "enabled.kio",
                "module enabled; import __comptime__; fn keep() -> . { () }",
            ),
            ("disabled.kio", "module disabled; fn keep() -> . { () }"),
        ]);
        assert_eq!(
            artifact.primitives().resolve("enabled", "__type_unit__"),
            Some(ComptimeBuiltin::TypeUnit),
        );
        assert_eq!(
            artifact.primitives().resolve("disabled", "__type_unit__"),
            None,
        );

        let encoded = postcard::to_allocvec(artifact.primitives())
            .expect("serialize evaluator primitive environment");
        let decoded: EvalPrimitiveEnv =
            postcard::from_bytes(&encoded).expect("deserialize evaluator primitive environment");
        assert_eq!(&decoded, artifact.primitives());
    }

    #[test]
    fn raw_comptime_spellings_have_no_evaluator_authority() {
        let ctx = EvalCtx::new();
        let direct = eval(&type_unit_call(), &Env::new(), &ctx);
        assert!(matches!(direct, Value::Atom(name) if name == "__type_unit__"));

        let indirect = Expr::Let {
            occurrence: Default::default(),
            name: "f".to_owned(),
            name_span: zero_span(),
            ty: None,
            pattern: (),
            value: Box::new(path_expr("__type_unit__")),
            body: Box::new(Expr::synth_call(path_expr("f"), Vec::new(), zero_span())),
            meta: zero_meta(),
        };
        let indirect = eval(&indirect, &Env::new(), &ctx);
        assert!(matches!(indirect, Value::Atom(name) if name == "__type_unit__"));

        let reflected = eval(
            &reflect_unit_call(path_expr("__reflect_type__")),
            &Env::new(),
            &ctx,
        );
        assert!(matches!(reflected, Value::Stuck(callee, _)
            if matches!(callee.as_ref(), Value::Atom(name) if name == "__reflect_type__")));

        let authorized = test_primitive_ctx(&[ComptimeBuiltin::ReflectType]);
        let qualified = Expr::Path {
            occurrence: Default::default(),
            segments: vec![
                PathSegment::new("fake", zero_span()),
                PathSegment::new("__reflect_type__", zero_span()),
            ],
            meta: zero_meta(),
            ext: (),
        };
        let qualified = eval(&reflect_unit_call(qualified), &Env::new(), &authorized);
        assert!(matches!(qualified, Value::Stuck(callee, _)
            if matches!(callee.as_ref(), Value::Atom(name)
                if name == "fake.__reflect_type__")));
    }

