    #[test]
    fn grouped_reflect_type_application_reflects_the_type_group() {
        let ctx = test_primitive_ctx(&[ComptimeBuiltin::ReflectType]);
        let proof_group = Expr::synth_call(
            path_expr("__reflect_type__"),
            vec![CallArg::Value(path_expr("ct"))],
            zero_span(),
        );
        let grouped = Expr::synth_call(
            proof_group.clone(),
            vec![CallArg::Type(Type::Unit { meta: zero_meta() })],
            zero_span(),
        );

        let reflected = eval(&grouped, &Env::new(), &ctx);
        assert!(
            matches!(as_refl_type_ref(&reflected), Some(Type::Unit { .. })),
            "grouped reflection must reflect the type argument, not the proof: {reflected:?}"
        );

        let value_shaped = Expr::synth_call(
            proof_group,
            vec![CallArg::Value(path_expr("Named"))],
            zero_span(),
        );
        let reflected = eval(&value_shaped, &Env::new(), &ctx);
        assert!(
            matches!(
                as_refl_type_ref(&reflected),
                Some(Type::Path { segments, .. })
                    if matches!(segments.as_slice(), [name] if name.as_str() == "Named")
            ),
            "grouped reflection must admit a value-shaped type name: {reflected:?}"
        );

        let invalid = [
            Expr::synth_call(
                path_expr("__reflect_type__"),
                vec![CallArg::Type(Type::Unit { meta: zero_meta() })],
                zero_span(),
            ),
            Expr::synth_call(
                Expr::synth_call(path_expr("__reflect_type__"), Vec::new(), zero_span()),
                vec![CallArg::Type(Type::Unit { meta: zero_meta() })],
                zero_span(),
            ),
            Expr::synth_call(
                Expr::synth_call(
                    path_expr("__reflect_type__"),
                    vec![
                        CallArg::Value(path_expr("ct")),
                        CallArg::Value(path_expr("extra")),
                    ],
                    zero_span(),
                ),
                vec![CallArg::Type(Type::Unit { meta: zero_meta() })],
                zero_span(),
            ),
            Expr::synth_call(
                Expr::synth_call(
                    path_expr("__reflect_type__"),
                    vec![CallArg::Value(path_expr("ct"))],
                    zero_span(),
                ),
                vec![
                    CallArg::Type(Type::Unit { meta: zero_meta() }),
                    CallArg::Type(Type::Unit { meta: zero_meta() }),
                ],
                zero_span(),
            ),
        ];
        for call in invalid {
            let result = eval(&call, &Env::new(), &ctx);
            assert!(
                as_refl_type_ref(&result).is_none(),
                "malformed reflection application must remain stuck: {result:?}"
            );
        }
    }

    #[test]
    fn reflected_type_constant_fold_evaluates_computed_proof_once_direct_and_grouped() {
        let module = parse_module(
            "module x; fn computed(proof: .) -> . { (); proof } equiv keep { (); () }",
        );
        for grouped in [false, true] {
            let metrics = Arc::new(EvalMetrics::default());
            let ctx = test_primitive_ctx_for("x", &[ComptimeBuiltin::ReflectType])
                .with_root_module(&module)
                .with_fn_defs(fn_def_map(&module))
                .with_metrics(metrics.clone());
            let proof = Expr::synth_call(
                path_expr("computed"),
                vec![CallArg::Value(Expr::Unit {
                    occurrence: Default::default(),
                    meta: zero_meta(),
                })],
                zero_span(),
            );

            let reflected = eval(
                &reflect_unit_call_with_proof(proof, grouped),
                &Env::new(),
                &ctx,
            );

            assert!(
                matches!(as_refl_type_ref(&reflected), Some(Type::Unit { .. })),
                "computed proof lost the reflected type (grouped={grouped}): {reflected:?}"
            );
            let snapshot = metrics.snapshot();
            assert_eq!(
                snapshot.apply_fn_calls, 1,
                "grouped={grouped}: {snapshot:?}"
            );
        }
    }

    #[test]
    fn reflected_type_constant_fold_cannot_discard_a_structural_fault_direct_or_grouped() {
        let module = parse_module(
            "module x; import __comptime__; \
             fn reject(proof: .) -> . { \
               __structural_recur__(proof, __type_unit__(), (), \
                 .(recur, fuel, input) { recur(fuel, input) }) \
             } \
             equiv keep { (); () }",
        );
        for grouped in [false, true] {
            let ctx = test_primitive_ctx_for(
                "x",
                &[
                    ComptimeBuiltin::ReflectType,
                    ComptimeBuiltin::StructuralRecur,
                    ComptimeBuiltin::TypeUnit,
                ],
            )
            .with_root_module(&module)
            .with_fn_defs(fn_def_map(&module));
            let proof = Expr::synth_call(
                path_expr("reject"),
                vec![CallArg::Value(Expr::Unit {
                    occurrence: Default::default(),
                    meta: zero_meta(),
                })],
                zero_span(),
            );

            let fault = eval(
                &reflect_unit_call_with_proof(proof, grouped),
                &Env::new(),
                &ctx,
            );

            assert_eq!(
                structural_recur_stuck_message(&fault, &ctx),
                Some(
                    "`__structural_recur__` got stuck because a recursive call did not descend from the current fuel measure (root=1, current=1, next=1)"
                        .to_string()
                ),
                "grouped={grouped}: {fault:?}"
            );
        }
    }

    #[test]
    fn artifact_reflection_preserves_exact_paths_and_caller_binders() {
        let pkg = lowered_package(&[
            ("types.kio", "module types; host type Actual role(i64);"),
            ("other.kio", "module other; host type Actual role(i32);"),
            (
                "reflect_helper.kio",
                "module reflect_helper; import types as local_alias; host type String role(i64); type Local = local_alias.Actual;",
            ),
            (
                "main.kio",
                "module main; import other as types; import types as real; host type String role(i32); newtype T : . { constructor mk_t; projector un_t; };",
            ),
        ]);
        pkg.resolve_imports().expect("resolve imports");
        let ctx = EvalCtx::new().with_package(Some(&pkg));

        let canonical_owner_type = Type::synth_path(
            vec!["types".to_owned(), "Actual".to_owned()],
            Vec::new(),
            zero_span(),
        );
        let canonical_other_type = Type::synth_path(
            vec!["other".to_owned(), "Actual".to_owned()],
            Vec::new(),
            zero_span(),
        );
        let checked = CheckedTerm::new(
            Expr::Unit {
                occurrence: Default::default(),
                meta: zero_meta(),
            },
            canonical_owner_type,
        );
        assert!(
            !checked_type_equiv(&checked, &canonical_other_type, &ctx),
            "an artifact type keeps its exact declaring-module identity"
        );
        let reflected = ReflectedType::new(checked.clone_type(), "reflected artifact type")
            .expect("reflected artifact type");
        assert_eq!(reflected.as_type(), checked.ty());

        let main_module = &pkg.module("main").expect("main module").module;
        let source_written = Type::synth_path(
            vec!["types".to_owned(), "Actual".to_owned()],
            Vec::new(),
            zero_span(),
        );
        let Type::Path { segments, .. } =
            crate::pass::typecheck_core::source_type_spelling(&source_written, main_module, false)
        else {
            panic!("expected source-written path")
        };
        assert_eq!(
            segments.iter().map(PathSegment::as_str).collect::<Vec<_>>(),
            vec!["types", "Actual"],
            "source spelling must not be reinterpreted as a canonical owner path"
        );
        let Type::Path { segments, .. } = crate::pass::typecheck_core::source_type_spelling(
            &Type::synth_path(
                vec!["types".to_owned(), "Actual".to_owned()],
                Vec::new(),
                zero_span(),
            ),
            main_module,
            true,
        ) else {
            panic!("expected canonical path")
        };
        assert_eq!(
            segments.iter().map(PathSegment::as_str).collect::<Vec<_>>(),
            vec!["real", "Actual"],
            "canonical identity should use the consumer's correct source alias"
        );
        let Type::Path { segments, .. } =
            crate::pass::typecheck_core::source_type_spelling_with_bound(
                &Type::synth_path(
                    vec!["main".to_owned(), "String".to_owned()],
                    Vec::new(),
                    zero_span(),
                ),
                main_module,
                true,
                &HashSet::from(["String".to_owned()]),
            )
        else {
            panic!("expected binder-aware canonical path")
        };
        assert_eq!(
            segments.iter().map(PathSegment::as_str).collect::<Vec<_>>(),
            vec!["main", "String"],
            "a same-named binder must prevent ambiguous local respelling"
        );

        let reflected_alias = Value::ReflType(
            ReflectedType::new(
                Type::synth_path(
                    vec!["types".to_owned(), "Actual".to_owned()],
                    Vec::new(),
                    zero_span(),
                ),
                "reflected alias",
            )
            .expect("reflected alias"),
        );
        let Type::Path { segments, .. } =
            canonical_refl_type(&reflected_alias, &ctx).expect("canonical alias")
        else {
            panic!("expected canonical alias path")
        };
        assert_eq!(
            segments.iter().map(PathSegment::as_str).collect::<Vec<_>>(),
            vec!["types", "Actual"],
            "the caller's `types` alias must not reinterpret an owner-qualified path"
        );

        for (path, expected) in [
            (
                vec!["reflect_helper".to_owned(), "String".to_owned()],
                vec!["reflect_helper", "String"],
            ),
            (
                vec!["types".to_owned(), "Actual".to_owned()],
                vec!["types", "Actual"],
            ),
        ] {
            let reflected = Value::ReflType(
                ReflectedType::new(
                    Type::synth_path(path, Vec::new(), zero_span()),
                    "reflected owner type",
                )
                .expect("reflected owner type"),
            );
            let Type::Path { segments, .. } =
                canonical_refl_type(&reflected, &ctx).expect("canonical owner type")
            else {
                panic!("expected canonical owner path")
            };
            assert_eq!(
                segments.iter().map(PathSegment::as_str).collect::<Vec<_>>(),
                expected,
                "the consumer must not reinterpret an owner's bare nominal or alias"
            );
        }

        let reflected_binder = Value::ReflType(
            ReflectedType::new(type_path("T"), "reflected binder").expect("reflected binder"),
        );
        let Type::Path { segments, .. } =
            canonical_refl_type(&reflected_binder, &ctx).expect("canonical binder")
        else {
            panic!("expected canonical binder path")
        };
        assert_eq!(
            segments.iter().map(PathSegment::as_str).collect::<Vec<_>>(),
            vec!["T"],
            "the caller's same-named nominal must not capture a reflected binder"
        );

        let nested_binder = Type::Forall {
            param: TypeParam {
                name: "T".to_owned(),
                span: zero_span(),
                kind: None,
            },
            body: Box::new(type_path("T")),
            meta: zero_meta(),
        };
        let Type::Forall { body, .. } =
            qualify_explicit_reflected_paths(&nested_binder, main_module, &HashMap::new())
        else {
            panic!("expected nested reflected binder")
        };
        assert!(
            matches!(body.as_ref(), Type::Path { segments, args, .. }
                if segments.len() == 1 && segments[0].as_str() == "T" && args.is_empty()),
            "a nested reflected forall binder must not resolve to the owner's same-named nominal: {body:?}"
        );
    }

    #[test]
    fn eval_fn_tables_collects_module_and_qualified_fns() {
        let pkg = lowered_package(&[
            ("a.kio", "module a; pub fn unit_a() -> . { () }"),
            (
                "c.kio",
                "module c; import a as ax; equiv q { ax.unit_a(); () }",
            ),
        ]);
        pkg.resolve_imports().expect("resolve imports");
        // Same-module fn table: module a's own fn must be present.
        let module_a = &pkg.module("a").expect("module a").module;
        let (fn_defs, _) = eval_fn_tables(&pkg, module_a).expect("tables for a");
        assert!(
            fn_defs.contains_key("unit_a"),
            "module a's own fn must populate the fn table, got {:?}",
            fn_defs.keys().collect::<Vec<_>>()
        );

        // Qualified import table: `import a as ax;` exposes (ax, unit_a).
        let module_c = &pkg.module("c").expect("module c").module;
        let (_, qualified) = eval_fn_tables(&pkg, module_c).expect("tables for c");
        assert!(
            qualified.contains_key(&("ax", "unit_a")),
            "qualified import must expose the target's fns, got {:?}",
            qualified.keys().collect::<Vec<_>>()
        );
    }

    #[test]
    fn artifact_newtype_registry_uses_exact_declaration_spelling() {
        let pkg = lowered_package(&[(
            "a.kio",
            "module a; rec { \
               newtype Wrap : Peer { pub constructor mk; pub projector get; }; \
               newtype Peer : Wrap { constructor make_peer; projector un_peer; }; \
             }",
        )]);
        let registry = newtype_registry_for_package(&pkg);
        assert_eq!(
            registry.proj_ctor.get("a::Wrap.get").map(String::as_str),
            Some("a::Wrap.mk"),
            "cache fingerprint input must preserve declaration-site identity"
        );
        assert!(!registry.proj_ctor.contains_key("Wrap.get"));
        assert!(!registry.proj_ctor.contains_key("get"));
        assert_eq!(
            registry
                .proj_ctor
                .get("a::Peer.un_peer")
                .map(String::as_str),
            Some("a::Peer.make_peer")
        );
    }

    #[test]
    fn unimported_newtype_cannot_change_local_iota_reduction() {
        let pkg = lowered_package(&[
            (
                "a.kio",
                "module a; \
                 newtype Wrap[A] : A { pub constructor mk; pub projector get; }; \
                 fn unwrap[A](x: A) -> A { Wrap.get(A, Wrap.mk(A, x)) }",
            ),
            (
                "unrelated.kio",
                "module unrelated; \
                 newtype Wrap[A] : A { pub constructor make; pub projector get; };",
            ),
        ]);
        let module = &pkg.module("a").expect("module a").module;
        let unwrap = find_module_fn(module, "unwrap").expect("unwrap fn");
        let ctx = EvalCtx::for_module(&pkg, module, "a").expect("evaluation context");
        let mut env = Env::new();
        env.insert("x".to_owned(), Value::Atom("payload".to_owned()));

        let value = eval(&unwrap.body, &env, &ctx);
        assert!(
            matches!(&value, Value::Atom(name) if name == "payload"),
            "an unimported declaration changed `Wrap.get(Wrap.mk(x))`: {value:?}"
        );
    }

