    #[test]
    fn reflected_repeated_formal_uses_of_one_higher_kinded_alias_all_expand() {
        let pkg = lowered_package(&[(
            "owner.kio",
            "module owner; \
             host type String; \
             host type N; \
             host type Either[E][A]; \
             type Unary[E] = Either(E); \
             type Twice[*F][A] = F(F(A));",
        )]);
        pkg.resolve_imports().expect("resolve imports");
        let ctx = EvalCtx::new().with_package(Some(&pkg));
        let nominal = |name: &str, args: Vec<Type<EvalPhase>>| {
            Type::synth_path(vec!["owner".to_owned(), name.to_owned()], args, zero_span())
        };
        let string = nominal("String", Vec::new());
        let terminal = nominal("N", Vec::new());
        let unary = nominal("Unary", vec![string.clone()]);
        let source = nominal("Twice", vec![unary, terminal.clone()]);
        let inner = nominal("Either", vec![string.clone(), terminal]);
        let expected = nominal("Either", vec![string, inner]);

        let expanded = expand_eval_canonical_alias_refs(&source, &ctx);
        assert_eq!(
            crate::pass::typecheck_core::display_type(&expanded),
            crate::pass::typecheck_core::display_type(&expected),
            "both formal uses of `Unary(String)` must expand without making source spans part of the semantic assertion"
        );
        assert!(canonical_refl_type_equiv(&source, &expected, &ctx));
    }

