    #[test]
    fn reflected_generic_alias_keeps_caller_and_owner_identities_distinct() {
        let pkg = lowered_package(&[(
            "owner.kio",
            "module owner; \
             newtype A : . { constructor mk_a; projector un_a; }; \
             pub type Pair[T] = T & A; \
             type Inner[T] = T & A; \
             pub type Outer[A] = Inner(A);",
        )]);
        pkg.resolve_imports().expect("resolve imports");
        let ctx = EvalCtx::new().with_package(Some(&pkg));

        for alias_name in ["Pair", "Outer"] {
            let caller_name = if alias_name == "Pair" { "A" } else { "B" };
            let alias = Type::synth_path(
                vec!["owner".to_owned(), alias_name.to_owned()],
                vec![type_path(caller_name)],
                zero_span(),
            );
            let expanded = expand_eval_canonical_alias_refs(&alias, &ctx);
            let Type::Product { left, right, .. } = expanded else {
                panic!("expected {alias_name}[{caller_name}] to expand to a product");
            };
            assert!(
                matches!(left.as_ref(), Type::Path { segments, args, .. }
                    if segments.len() == 1
                        && segments[0].as_str() == caller_name
                        && args.is_empty()),
                "caller binder must remain bare: {left:?}"
            );
            assert!(
                matches!(right.as_ref(), Type::Path { segments, args, .. }
                    if segments.iter().map(|segment| segment.as_str()).eq(["owner", "A"])
                        && args.is_empty()),
                "owner nominal must retain its exact identity: {right:?}"
            );
        }
    }

